def _set_dark_title_bar(window):
    if sys_platform.system() != "Windows":
        return
    try:
        dwmapi = ctypes.WinDLL("dwmapi", use_last_error=True)
    except OSError as exc:
        _dbg(f"Could not load Windows DWM API for dark title bar: {exc}")
        return
    set_attribute = dwmapi.DwmSetWindowAttribute
    set_attribute.argtypes = [
        ctypes.c_void_p, ctypes.c_uint, ctypes.c_void_p, ctypes.c_uint,
    ]
    set_attribute.restype = ctypes.c_long
    enabled = ctypes.c_int(1)
    hwnd = ctypes.c_void_p(int(window.winId()))
    for attribute in (20, 19):
        result = set_attribute(
            hwnd, attribute, ctypes.byref(enabled), ctypes.sizeof(enabled))
        if result == 0:
            return
    _dbg(f"Windows rejected the dark title bar setting (HRESULT {result:#x})")


# simplecad_debug.txt output; overridden by the "debug_enabled" user setting (Edit → Settings → Debug).
DEBUG_ENABLED = True
_LOG_DIR = os.path.dirname(os.path.abspath(__file__))
_DBG_LOG = os.path.join(_LOG_DIR, "simplecad_debug.txt")
_ERROR_LOG = os.path.join(_LOG_DIR, "simplecad_error.txt")
_CRASH_LOG = os.path.join(_LOG_DIR, "simplecad_crash.txt")

def _trace(msg):
    with open(_ERROR_LOG, "a", encoding="utf-8") as f:
        import datetime
        f.write(f"{datetime.datetime.now()}: {msg}\n")
        f.flush()

def _dbg(msg):
    if not DEBUG_ENABLED:
        return
    with open(_DBG_LOG, "a", encoding="utf-8") as _f:
        _f.write(str(msg) + "\n")
        _f.flush()

def _json_default(obj):
    """JSON encoder default for NumPy arrays and scalars."""
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    if isinstance(obj, (np.floating, np.integer)):
        return float(obj)
    return float(obj)

