# ── data model ────────────────────────────────────────────────────────────────
class Vertex:
    def __init__(self, x, y, locked=False):
        self.x = float(x); self.y = float(y)
        self.locked = locked      # excluded from solving (reference geometry or rigid text)
    def xy(self): return (self.x, self.y)

class Segment:
    def __init__(self, v0, v1, construction=False, reference=False):
        self.v0 = v0; self.v1 = v1
        self.construction = construction or reference   # support geometry: never extruded
        self.reference = reference                      # projected edge of the sketch face
    def length(self):
        return math.hypot(self.v1.x-self.v0.x, self.v1.y-self.v0.y)
    def midpoint(self):
        return ((self.v0.x+self.v1.x)/2, (self.v0.y+self.v1.y)/2)
    def midpoint_of(self, P):
        (ax, ay), (bx, by) = P(self.v0), P(self.v1)
        return ((ax+bx)/2, (ay+by)/2)
    def axis(self):
        if abs(self.v1.y-self.v0.y) < AXIS_TOL: return 'H'
        if abs(self.v1.x-self.v0.x) < AXIS_TOL: return 'V'
        return 'D'

class SketchText:
    """Rigid outline geometry; only whole-label moves and uniform scaling change its vertices."""
    def __init__(self, label, segments, *, box_vertices=None, font_family="Arial",
                 font_size=12.0, bold=False, italic=False, underline=False, align="left"):
        self.label = label
        self.segments = list(segments)
        self.box_vertices = list(box_vertices or [])
        self.font_family = str(font_family or "Arial")
        self.font_size = float(font_size)
        self.bold = bool(bold)
        self.italic = bool(italic)
        self.underline = bool(underline)
        self.align = align if align in ("left", "center", "right") else "left"
        for v in self.vertices(): v.locked = True

    def vertices(self):
        verts = {v for s in self.segments for v in (s.v0, s.v1)}
        verts.update(self.box_vertices)
        return verts

    def bounds(self):
        verts = self.vertices()
        return (min(v.x for v in verts), min(v.y for v in verts),
                max(v.x for v in verts), max(v.y for v in verts))

    def corners(self):
        if len(self.box_vertices) >= 4:
            return [v.xy() for v in self.box_vertices[:4]]
        x0, y0, x1, y1 = self.bounds()
        return [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]

    def constraint_points(self):
        if len(self.box_vertices) >= 9:
            return [v.xy() for v in self.box_vertices[:9]]
        corners = self.corners()
        (x0, y0), (x1, _), (_, y1), _ = corners
        xm, ym = (x0 + x1)/2, (y0 + y1)/2
        return corners + [(xm, y0), (x1, ym), (xm, y1), (x0, ym), (xm, ym)]

class Circle:
    def __init__(self, center, radius=10.0, construction=False, reference=False):
        self.center = center; self.radius = radius
        self.construction = construction or reference
        self.reference = reference
        self.locked = reference   # radius is not a solver variable

class Arc:
    """Partial circle running CCW from v_start to v_end around center.
    Radius is |center→v_start|; an implicit equation keeps v_end on that radius."""
    def __init__(self, center, v_start, v_end, construction=False, reference=False):
        self.center = center; self.v_start = v_start; self.v_end = v_end
        self.construction = construction or reference
        self.reference = reference
    def radius(self):
        return math.hypot(self.v_start.x-self.center.x, self.v_start.y-self.center.y)
    def angles(self):
        """(start angle, CCW sweep) in radians."""
        a0 = math.atan2(self.v_start.y-self.center.y, self.v_start.x-self.center.x)
        a1 = math.atan2(self.v_end.y-self.center.y, self.v_end.x-self.center.x)
        sweep = (a1-a0) % (2*math.pi)
        if sweep < 1e-9: sweep = 2*math.pi
        return a0, sweep
    def mid_angle(self):
        a0, sw = self.angles(); return a0 + sw/2
    def tess(self):
        a0, sw = self.angles(); r = self.radius()
        n = curve_segments(r, sw)
        cx, cy = self.center.x, self.center.y
        pts = [(cx+r*math.cos(a0+sw*i/n), cy+r*math.sin(a0+sw*i/n)) for i in range(n+1)]
        pts[0] = self.v_start.xy(); pts[-1] = self.v_end.xy()
        return pts

class Ellipse:
    """Smooth ellipse defined by four endpoints of two centered perpendicular diameters."""
    def __init__(self, major_start, major_end, minor_start, minor_end,
                 construction=False, reference=False):
        self.major_start = major_start; self.major_end = major_end
        self.minor_start = minor_start; self.minor_end = minor_end
        self.construction = construction or reference
        self.reference = reference

    def vertices(self):
        return (self.major_start, self.major_end, self.minor_start, self.minor_end)

    def axes(self):
        major_start, major_end, minor_start, minor_end = (v.xy() for v in self.vertices())
        center = tuple((major_start[i] + major_end[i] + minor_start[i] + minor_end[i]) / 4
                       for i in range(2))
        major = ((major_end[0]-major_start[0])/2, (major_end[1]-major_start[1])/2)
        minor = ((minor_end[0]-minor_start[0])/2, (minor_end[1]-minor_start[1])/2)
        return center, major, minor

    def tess(self):
        center, major, minor = self.axes()
        count = curve_segments(max(math.hypot(*major), math.hypot(*minor)))
        return [(center[0] + major[0]*math.cos(2*math.pi*i/count) +
                 minor[0]*math.sin(2*math.pi*i/count),
                 center[1] + major[1]*math.cos(2*math.pi*i/count) +
                 minor[1]*math.sin(2*math.pi*i/count)) for i in range(count)]

class PlanetaryRatioSpinBox(QDoubleSpinBox):
    """Step across valid planetary tooth-count ratios rather than arbitrary decimals."""
    def __init__(self, parent=None):
        super().__init__(parent)
        self._planetary_steps = None

    def set_planetary_steps(self, values):
        self._planetary_steps = sorted(set(float(value) for value in values)) if values else None

    def stepBy(self, steps):
        if not self._planetary_steps:
            return super().stepBy(steps)
        values = self._planetary_steps
        current_index = min(range(len(values)), key=lambda index: abs(values[index] - self.value()))
        target_index = min(max(current_index + int(steps), 0), len(values) - 1)
        self.setValue(values[target_index])

# ── constraints ───────────────────────────────────────────────────────────────
# Every constraint is an equation system solved by SketchSystem (Newton / least squares).
class CFixed:
    """Fixes a vertex at the position it had when the constraint was created."""
    kind = "fixed"
    def __init__(self, vertex):
        self.vertex = vertex; self.x0 = vertex.x; self.y0 = vertex.y

class CDimension:
    """Driving dimension. target: Segment (length) | (Vertex,Vertex) (H/V/aligned distance)
    | Circle (diameter or radius, see dim_mode) | Arc (radius)."""
    kind = "dim"
    def __init__(self, target, value, orient=None):
        self.target   = target
        self.value    = value
        self.orient   = orient        # "H"/"V"/"D" for vertex-pair dimensions
        self.dim_mode = "diameter"    # circles only
        self.sign     = 1.0           # direction of H/V pair dimensions
        if isinstance(target, tuple) and orient in ("H", "V"):
            a, b = target
            d = (b.x-a.x) if orient == "H" else (b.y-a.y)
            self.sign = 1.0 if d >= 0 else -1.0
        # drawing placement (user-draggable); None = automatic
        self.off_mm = None; self.side = None; self.t_frac = 0.5; self.angle = None
    def label(self): return f"{self.value:.1f}"

class CPerpendicular:
    """Two segments are perpendicular."""
    kind = "perp"
    def __init__(self, seg_a, seg_b):
        self.seg_a = seg_a; self.seg_b = seg_b

class CCoincident:
    """vertex_move lies on vertex_target."""
    kind = "coincident"
    def __init__(self, vertex_move, vertex_target):
        self.vertex_move   = vertex_move
        self.vertex_target = vertex_target

class CPointOnLine:
    """Vertex lies on the (infinite) line through a segment."""
    kind = "ptline"
    def __init__(self, vertex, seg):
        self.vertex = vertex; self.seg = seg

class CHorizontal:
    """Segment is horizontal."""
    kind = "horiz"
    def __init__(self, seg): self.seg = seg

class CVertical:
    """Segment is vertical."""
    kind = "vert"
    def __init__(self, seg): self.seg = seg

class CPointOnCurve:
    """Vertex lies on a circle / arc (on its full circle)."""
    kind = "ptcurve"
    def __init__(self, vertex, curve):
        self.vertex = vertex; self.curve = curve

class CEqual:
    """Two segments have equal length or two circles have equal radius."""
    kind = "equal"
    def __init__(self, seg_a, seg_b):
        self.seg_a = seg_a; self.seg_b = seg_b

class CParallel:
    """Two segments are parallel."""
    kind = "parallel"
    def __init__(self, seg_a, seg_b):
        self.seg_a = seg_a; self.seg_b = seg_b

class CCollinear:
    """Two segments lie on the same infinite line."""
    kind = "collinear"
    def __init__(self, seg_a, seg_b):
        self.seg_a = seg_a; self.seg_b = seg_b

class CSymmetric:
    """Two segments or two vertices are symmetric about a center line or center point.
    center: Segment (axis of symmetry) or Vertex (center point)."""
    kind = "symmetric"
    def __init__(self, seg_a, seg_b, center):
        self.seg_a = seg_a; self.seg_b = seg_b; self.center = center

class CMirrorPoint:
    """A point and its mirror about a sketch axis or a segment."""
    kind = "mirror"
    def __init__(self, vertex_move, vertex_target, axis):
        self.vertex_move = vertex_move
        self.vertex_target = vertex_target
        self.axis = axis

class CTangential:
    """A line and curve, or two curves, are tangent in their current branch."""
    kind = "tangent"
    def __init__(self, entity_a, entity_b):
        self.entity_a = entity_a; self.entity_b = entity_b
        if isinstance(entity_a, Segment) or isinstance(entity_b, Segment):
            line = entity_a if isinstance(entity_a, Segment) else entity_b
            curve = entity_b if line is entity_a else entity_a
            self.side = 1.0 if _signed_line_dist(
                line.v0.xy(), line.v1.xy(), curve.center.xy()) >= 0.0 else -1.0
            self.external = True
        else:
            def radius(curve):
                return curve.radius if isinstance(curve, Circle) else math.dist(
                    curve.center.xy(), curve.v_start.xy())
            distance = math.dist(entity_a.center.xy(), entity_b.center.xy())
            ra, rb = radius(entity_a), radius(entity_b)
            self.external = abs(distance - (ra + rb)) <= abs(distance - abs(ra - rb))
            self.side = 1.0 if ra >= rb else -1.0


def _constraint_pts(e):
    """Vertex → its point; Segment → (start, end) points."""
    return e.xy() if isinstance(e, Vertex) else (e.v0.xy(), e.v1.xy())

def _signed_line_dist(a, b, p):
    """Signed distance of point p from the infinite line a→b (left = positive)."""
    dx, dy = b[0]-a[0], b[1]-a[1]; L = math.hypot(dx, dy)
    return 0.0 if L < 1e-12 else (dx*(p[1]-a[1]) - dy*(p[0]-a[0]))/L

def _line_angle(a0, a1, b0, b1):
    """Signed angle (rad) from direction a0→a1 to direction b0→b1."""
    ax, ay = a1[0]-a0[0], a1[1]-a0[1]; bx, by = b1[0]-b0[0], b1[1]-b0[1]
    return math.atan2(ax*by - ay*bx, ax*bx + ay*by)

def _angle_ray_sides(line_a, line_b, point_a, point_b):
    """Return endpoint-direction signs for the clicked rays at the lines' intersection."""
    ax, ay = line_a.v0.xy(); adx = line_a.v1.x-ax; ady = line_a.v1.y-ay
    bx, by = line_b.v0.xy(); bdx = line_b.v1.x-bx; bdy = line_b.v1.y-by
    denominator = adx*bdy - ady*bdx
    if abs(denominator) < 1e-12:
        return None
    t = ((bx-ax)*bdy - (by-ay)*bdx) / denominator
    ix, iy = ax+t*adx, ay+t*ady
    side_a = 1.0 if (point_a[0]-ix)*adx + (point_a[1]-iy)*ady >= 0 else -1.0
    side_b = 1.0 if (point_b[0]-ix)*bdx + (point_b[1]-iy)*bdy >= 0 else -1.0
    return side_a, side_b

class CDistance:
    """Distance between two entities: point–point, point–line, line–line or circle–circle.
    Line–line becomes parallel at the given distance; circle–circle measures center distance,
    or the difference between radii when the circles are concentric. Circle–line measures
    clearance from the circumference.
    Line–line may instead use mode "angle" (degrees).
    driving=False → information only (support-geometry mode): no equation, just displayed."""
    kind = "dist"
    def __init__(self, a, b, value=None, mode="distance", driving=True, orient="D",
                 angle_sides=None):
        if isinstance(a, Segment) and isinstance(b, Vertex): a, b = b, a   # point first
        if isinstance(a, Segment) and isinstance(b, Circle): a, b = b, a   # circle first
        self.a = a; self.b = b; self.mode = mode; self.driving = driving
        self.angle_sides = tuple(angle_sides) if angle_sides is not None else None
        self.orient = orient if isinstance(a, Vertex) and isinstance(b, Vertex) else "D"
        self.dim_mode = None
        self.circle_relation = None
        self.circle_outer = None
        self.circle_side = None
        if isinstance(a, Circle) and isinstance(b, Segment):
            side = _signed_line_dist(b.v0.xy(), b.v1.xy(), a.center.xy())
            self.circle_side = 1.0 if side >= 0.0 else -1.0
        if isinstance(a, Circle) and isinstance(b, Circle):
            center_distance = math.hypot(a.center.x - b.center.x, a.center.y - b.center.y)
            if center_distance <= 1e-9:
                self.circle_relation = "concentric"
                self.circle_outer = a if a.radius >= b.radius else b
            else:
                self.circle_relation = "center"
        m = self.measure_signed()
        self.sign = 1.0 if m >= 0 else -1.0
        self.value = abs(m) if value is None else value
        self.off_mm = None; self.side = None; self.t_frac = 0.5; self.angle = None

    @property
    def pair(self):
        kind = lambda entity: "v" if isinstance(entity, Vertex) else \
                              "s" if isinstance(entity, Segment) else \
                              "c" if isinstance(entity, Circle) else "a"
        return kind(self.a) + kind(self.b)

    def measure_signed(self, P=None):
        """Current signed value (mm, or degrees in angle mode). P maps vertex → (x,y)."""
        P = P or (lambda v: v.xy())
        a, b = self.a, self.b
        if self.pair == "vv":
            (ax, ay), (bx, by) = P(a), P(b)
            orient = getattr(self, "orient", "D")
            if orient == "H": return bx - ax          # horizontal distance (signed)
            if orient == "V": return by - ay          # vertical distance (signed)
            return math.hypot(bx-ax, by-ay)
        if self.pair == "cc":
            center_distance = math.hypot(
                P(a.center)[0] - P(b.center)[0],
                P(a.center)[1] - P(b.center)[1])
            if self.circle_relation == "center":
                return center_distance
            if self.circle_relation == "concentric":
                inner = b if self.circle_outer is a else a
                return self.circle_outer.radius - inner.radius
            if self.circle_relation == "nested":
                inner = b if self.circle_outer is a else a
                return self.circle_outer.radius - inner.radius - center_distance
            return center_distance - a.radius - b.radius
        if isinstance(a, Segment) and isinstance(b, Vertex):
            return _signed_line_dist(P(a.v0), P(a.v1), P(b))
        if isinstance(a, Vertex) and isinstance(b, Segment):
            return _signed_line_dist(P(b.v0), P(b.v1), P(a))
        if isinstance(a, Circle) and isinstance(b, Segment):
            return abs(_signed_line_dist(P(b.v0), P(b.v1), P(a.center))) - a.radius
        if self.mode == "angle":
            sides = getattr(self, "angle_sides", None)
            if sides is not None:
                ax, ay = P(a.v1)[0]-P(a.v0)[0], P(a.v1)[1]-P(a.v0)[1]
                bx, by = P(b.v1)[0]-P(b.v0)[0], P(b.v1)[1]-P(b.v0)[1]
                return math.degrees(_line_angle((0.0, 0.0),
                                                (ax*sides[0], ay*sides[0]),
                                                (0.0, 0.0), (bx*sides[1], by*sides[1])))
            return math.degrees(_line_angle(P(a.v0), P(a.v1), P(b.v0), P(b.v1)) % math.pi)
        return _signed_line_dist(P(a.v0), P(a.v1), b.midpoint_of(P))

    def measure(self):
        return abs(self.measure_signed())

    def label(self):
        v = self.value if self.driving else self.measure()
        txt = f"{v:.1f}°" if self.mode == "angle" else f"{v:.1f}"
        return txt if self.driving else f"({txt})"

def constraint_refs(c):
    """Geometry objects (vertices/segments/circles/arcs) referenced by a constraint."""
    if isinstance(c, CFixed):         return {c.vertex}
    if isinstance(c, CDimension):
        return set(c.target) if isinstance(c.target, tuple) else {c.target}
    if isinstance(c, CPerpendicular): return {c.seg_a, c.seg_b}
    if isinstance(c, CCoincident):    return {c.vertex_move, c.vertex_target}
    if isinstance(c, CPointOnLine):   return {c.vertex, c.seg}
    if isinstance(c, CPointOnCurve):  return {c.vertex, c.curve}
    if isinstance(c, (CHorizontal, CVertical)): return {c.seg}
    if isinstance(c, CDistance):      return {c.a, c.b}
    if isinstance(c, CEqual):         return {c.seg_a, c.seg_b}
    if isinstance(c, CParallel):      return {c.seg_a, c.seg_b}
    if isinstance(c, CCollinear):     return {c.seg_a, c.seg_b}
    if isinstance(c, CSymmetric):     return {c.seg_a, c.seg_b, c.center}
    if isinstance(c, CMirrorPoint):
        refs = {c.vertex_move, c.vertex_target}
        if isinstance(c.axis, Segment): refs.add(c.axis)
        return refs
    if isinstance(c, CTangential):    return {c.entity_a, c.entity_b}
    return set()

def describe_constraint(sk, c):
    """Human-readable one-liner for the constraint list."""
    def P(v): return f"P{sk.vertices.index(v)}" if v in sk.vertices else "P?"
    def L(s): return f"L{sk.segments.index(s)}" if s in sk.segments else "L?"
    if isinstance(c, CFixed):
        at = " at origin" if (c.x0, c.y0) == (0.0, 0.0) else ""
        return f"📌 Fixed  {P(c.vertex)}{at}"
    if isinstance(c, CPerpendicular): return f"⊾ Perpendicular  {L(c.seg_a)} ⟂ {L(c.seg_b)}"
    if isinstance(c, CCoincident):    return f"● Coincident  {P(c.vertex_move)} → {P(c.vertex_target)}"
    if isinstance(c, CPointOnLine):   return f"⊸ Point on line  {P(c.vertex)} on {L(c.seg)}"
    if isinstance(c, CPointOnCurve):
        cu = c.curve
        if isinstance(cu, Circle):
            name = f"circle C{sk.circles.index(cu)}" if cu in sk.circles else "circle C?"
        else:
            name = f"arc A{sk.arcs.index(cu)}" if cu in sk.arcs else "arc A?"
        return f"◌ Point on curve  {P(c.vertex)} on {name}"
    if isinstance(c, CHorizontal):    return f"― Horizontal  {L(c.seg)}"
    if isinstance(c, CVertical):      return f"| Vertical  {L(c.seg)}"
    if isinstance(c, CEqual):
        if isinstance(c.seg_a, Circle) and isinstance(c.seg_b, Circle):
            a = f"C{sk.circles.index(c.seg_a)}" if c.seg_a in sk.circles else "C?"
            b = f"C{sk.circles.index(c.seg_b)}" if c.seg_b in sk.circles else "C?"
            return f"= Equal diameter  {a} = {b}"
        return f"= Equal length  {L(c.seg_a)} = {L(c.seg_b)}"
    if isinstance(c, CParallel):      return f"∥ Parallel  {L(c.seg_a)} ∥ {L(c.seg_b)}"
    if isinstance(c, CCollinear):    return f"↔ Collinear  {L(c.seg_a)}, {L(c.seg_b)}"
    if isinstance(c, CSymmetric):
        ctr = L(c.center) if isinstance(c.center, Segment) else P(c.center)
        first = P(c.seg_a) if isinstance(c.seg_a, Vertex) else L(c.seg_a)
        second = P(c.seg_b) if isinstance(c.seg_b, Vertex) else L(c.seg_b)
        return f"⇔ Symmetric  {first}, {second} about {ctr}"
    if isinstance(c, CMirrorPoint):
        axis = L(c.axis) if isinstance(c.axis, Segment) else c.axis + " axis"
        return f"⇔ Mirror  {P(c.vertex_move)}, {P(c.vertex_target)} about {axis}"
    if isinstance(c, CTangential):
        def E(entity):
            if isinstance(entity, Segment): return L(entity)
            if isinstance(entity, Circle):
                return f"C{sk.circles.index(entity)}" if entity in sk.circles else "C?"
            return f"A{sk.arcs.index(entity)}" if entity in sk.arcs else "A?"
        return f"⌒ Tangential  {E(c.entity_a)} to {E(c.entity_b)}"
    if isinstance(c, CDistance):
        def E(entity):
            if isinstance(entity, Vertex): return P(entity)
            if isinstance(entity, Segment): return L(entity)
            if isinstance(entity, Circle):
                return f"C{sk.circles.index(entity)}" if entity in sk.circles else "C?"
            return f"A{sk.arcs.index(entity)}" if entity in sk.arcs else "A?"
        if c.mode == "angle":
            head = f"∠ Angle {c.value:.1f}°" if c.driving else f"ⓘ Angle ({c.measure():.1f}°)"
        else:
            name = {"H": "Horiz. length", "V": "Vert. length"}.get(
                getattr(c, "orient", "D"), "Clearance" if c.pair in ("cc", "cs") else "Length")
            head = f"↔ {name} {c.value:.2f}" if c.driving else f"ⓘ {name} ({c.measure():.2f})"
        sep = {"vv": "–", "vs": " to ", "ss": " ∥ " if c.mode == "distance" else ", ",
               "cc": " ↔ ", "cs": " to "}[c.pair]
        return f"{head}  {E(c.a)}{sep}{E(c.b)}"
    if isinstance(c, CDimension):
        t = c.target
        if isinstance(t, Segment): return f"📏 Length {c.value:.2f}  {L(t)}"
        if isinstance(t, tuple):
            kind = {"H": "Horiz. dist", "V": "Vert. dist"}.get(c.orient, "Distance")
            return f"📏 {kind} {c.value:.2f}  {P(t[0])}–{P(t[1])}"
        if isinstance(t, Circle):
            i = sk.circles.index(t) if t in sk.circles else "?"
            sym = "⌀" if c.dim_mode == "diameter" else "R"
            return f"📏 {sym}{c.value:.2f}  Circle C{i}"
        if isinstance(t, Arc):
            i = sk.arcs.index(t) if t in sk.arcs else "?"
            return f"📏 R{c.value:.2f}  Arc A{i}"
    return type(c).__name__

# ── constraint solver ─────────────────────────────────────────────────────────
class SketchSystem:
    """Equation system of a sketch. Unknowns: x,y of every used, non-locked vertex and the
    radius of every non-locked circle. Solved with damped Gauss-Newton (minimum-norm steps,
    so geometry moves as little as possible). DOF = unknowns − rank(Jacobian)."""
    FD_H = 1e-6

    def __init__(self, sk):
        self.sk = sk
        used = self.sk.used_vertices()
        self.order = [v for v in sk.vertices if v in used]
        self.order += [v for v in used if v not in self.order]
        self.text_vertex_group = {v: group for group in sk.text_groups for v in group.vertices()}
        self.vix, self.rix, n = {}, {}, 0
        for v in self.order:
            if not v.locked and v not in self.text_vertex_group:
                self.vix[v] = n; n += 2
        self.tix = {}
        for group in sk.text_groups:
            if group.vertices():
                self.tix[group] = n; n += 2
        for c in sk.circles:
            if not c.locked: self.rix[c] = n; n += 1
        self.n = n
        self.eqs = []          # (owner, row0, nrows, var indices, func)
        self.m = 0
        X0 = self.pack()
        for c in sk.constraints:
            eq = self._equations(c)
            if eq: self._add(c, *eq, X0=X0)
        for a in sk.arcs:      # implicit: both arc ends on the same radius
            def f(X, a=a):
                cx, cy = self.P(a.center, X); sx, sy = self.P(a.v_start, X)
                ex, ey = self.P(a.v_end, X)
                return [math.hypot(ex-cx, ey-cy) - math.hypot(sx-cx, sy-cy)]
            self._add(a, [a.center, a.v_start, a.v_end], [], f, X0=X0)
        for ellipse in sk.ellipses:
            def f(X, ellipse=ellipse):
                a0, a1, b0, b1 = ellipse.vertices()
                (x0, y0), (x1, y1), (u0, v0), (u1, v1) = (
                    self.P(vertex, X) for vertex in (a0, a1, b0, b1))
                cx_a, cy_a = (x0+x1)/2, (y0+y1)/2
                cx_b, cy_b = (u0+u1)/2, (v0+v1)/2
                ax, ay = x1-x0, y1-y0
                bx, by = u1-u0, v1-v0
                scale = math.hypot(ax, ay)*math.hypot(bx, by)
                perpendicular = (ax*bx+ay*by)/scale if scale > 1e-18 else 0.0
                return [cx_a-cx_b, cy_a-cy_b, perpendicular]
            self._add(ellipse, ellipse.vertices(), [], f, X0=X0)

    def _add(self, owner, verts, circles, f, X0):
        idx = []
        for v in verts:
            i = self.vix.get(v)
            if i is None:
                group = self.text_vertex_group.get(v)
                i = self.tix.get(group)
            if i is not None and i not in idx: idx += [i, i+1]
        for c in circles:
            i = self.rix.get(c)
            if i is not None: idx.append(i)
        nrows = len(f(X0))
        self.eqs.append((owner, self.m, nrows, idx, f)); self.m += nrows

    def P(self, v, X):
        i = self.vix.get(v)
        if i is not None:
            return X[i], X[i+1]
        group = self.text_vertex_group.get(v)
        if group is not None:
            i = self.tix[group]
            return v.x + X[i], v.y + X[i+1]
        return v.x, v.y

    def R(self, c, X):
        i = self.rix.get(c)
        return X[i] if i is not None else c.radius

    def _equations(self, c):
        P, R = self.P, self.R
        if isinstance(c, CFixed):
            v = c.vertex
            def f(X):
                x, y = P(v, X); return [x-c.x0, y-c.y0]
            return [v], [], f
        if isinstance(c, CCoincident):
            a, b = c.vertex_move, c.vertex_target
            def f(X):
                (ax, ay), (bx, by) = P(a, X), P(b, X); return [ax-bx, ay-by]
            return [a, b], [], f
        if isinstance(c, (CHorizontal, CVertical)):
            a, b = c.seg.v0, c.seg.v1; k = 1 if isinstance(c, CHorizontal) else 0
            def f(X):
                return [P(b, X)[k] - P(a, X)[k]]
            return [a, b], [], f
        if isinstance(c, CPerpendicular):
            a0, a1, b0, b1 = c.seg_a.v0, c.seg_a.v1, c.seg_b.v0, c.seg_b.v1
            def f(X):
                (p, q), (r, s) = P(a0, X), P(a1, X); (t, u), (w, z) = P(b0, X), P(b1, X)
                dax, day, dbx, dby = r-p, s-q, w-t, z-u
                la, lb = math.hypot(dax, day), math.hypot(dbx, dby)
                if la < 1e-9 or lb < 1e-9: return [0.0]
                return [(dax*dbx + day*dby)/(la*lb)]
            return [a0, a1, b0, b1], [], f
        if isinstance(c, CPointOnLine):
            a, b, v = c.seg.v0, c.seg.v1, c.vertex
            def f(X):
                (ax, ay), (bx, by), (px, py) = P(a, X), P(b, X), P(v, X)
                dx, dy = bx-ax, by-ay; L = math.hypot(dx, dy)
                if L < 1e-9: return [0.0]
                return [(dx*(py-ay) - dy*(px-ax))/L]
            return [a, b, v], [], f
        if isinstance(c, CPointOnCurve):
            v, cu = c.vertex, c.curve
            if isinstance(cu, Circle):
                def f(X):
                    (cx, cy), (px, py) = P(cu.center, X), P(v, X)
                    return [math.hypot(px-cx, py-cy) - R(cu, X)]
                return [cu.center, v], [cu], f
            def f(X):
                (cx, cy), (sx, sy), (px, py) = P(cu.center, X), P(cu.v_start, X), P(v, X)
                return [math.hypot(px-cx, py-cy) - math.hypot(sx-cx, sy-cy)]
            return [cu.center, cu.v_start, v], [], f
        if isinstance(c, CDimension):
            t = c.target
            if isinstance(t, Segment) or isinstance(t, tuple):
                a, b = (t.v0, t.v1) if isinstance(t, Segment) else t
                orient = c.orient if isinstance(t, tuple) else None
                def f(X):
                    (ax, ay), (bx, by) = P(a, X), P(b, X)
                    if orient == "H": return [(bx-ax)*c.sign - c.value]
                    if orient == "V": return [(by-ay)*c.sign - c.value]
                    return [math.hypot(bx-ax, by-ay) - c.value]
                return [a, b], [], f
            if isinstance(t, Circle):
                def f(X):
                    target = c.value/2 if c.dim_mode == "diameter" else c.value
                    return [R(t, X) - target]
                return [], [t], f
            if isinstance(t, Arc):
                def f(X):
                    (cx, cy), (sx, sy) = P(t.center, X), P(t.v_start, X)
                    return [math.hypot(sx-cx, sy-cy) - c.value]
                return [t.center, t.v_start], [], f
        if isinstance(c, CDistance):
            if not c.driving: return None
            a, b = c.a, c.b
            if c.pair == "cc":
                if c.circle_relation == "concentric":
                    inner = b if c.circle_outer is a else a
                    def f(X):
                        return [R(c.circle_outer, X) - R(inner, X) - c.value*c.sign]
                    return [], [a, b], f
                def f(X):
                    (ax, ay), (bx, by) = P(a.center, X), P(b.center, X)
                    center_distance = math.sqrt((bx-ax)**2 + (by-ay)**2 + 1e-18)
                    if c.circle_relation == "center":
                        return [center_distance - c.value*c.sign]
                    if c.circle_relation == "nested":
                        inner = b if c.circle_outer is a else a
                        return [R(c.circle_outer, X) - R(inner, X) -
                                center_distance - c.value*c.sign]
                    return [center_distance - R(a, X) - R(b, X) - c.value*c.sign]
                return [a.center, b.center], [] if c.circle_relation == "center" else [a, b], f
            if c.pair == "cs":
                def f(X):
                    distance = _signed_line_dist(P(b.v0, X), P(b.v1, X), P(a.center, X))
                    return [distance*c.circle_side - R(a, X) - c.value*c.sign]
                return [a.center, b.v0, b.v1], [a], f
            verts = [a] if isinstance(a, Vertex) else [a.v0, a.v1]
            verts += [b] if isinstance(b, Vertex) else [b.v0, b.v1]
            if c.pair == "ss" and c.mode == "distance":
                    def f(X):
                        Pv = lambda v: P(v, X)
                        a0, a1, b0, b1 = Pv(a.v0), Pv(a.v1), Pv(b.v0), Pv(b.v1)
                        ang = _line_angle(a0, a1, b0, b1)
                        return [math.sin(ang),                       # parallel (or anti-parallel)
                                _signed_line_dist(a0, a1, b.midpoint_of(Pv))*c.sign - c.value]
                    return verts, [], f
            if c.pair == "ss":
                    def f(X):
                        Pv = lambda v: P(v, X)
                        sides = getattr(c, "angle_sides", None)
                        if sides is not None:
                            ax, ay = Pv(a.v1)[0]-Pv(a.v0)[0], Pv(a.v1)[1]-Pv(a.v0)[1]
                            bx, by = Pv(b.v1)[0]-Pv(b.v0)[0], Pv(b.v1)[1]-Pv(b.v0)[1]
                            angle = _line_angle((0.0, 0.0), (ax*sides[0], ay*sides[0]),
                                                (0.0, 0.0), (bx*sides[1], by*sides[1]))
                            d = angle - math.radians(c.value)*c.sign
                            return [math.atan2(math.sin(d), math.cos(d))]
                        d = _line_angle(Pv(a.v0), Pv(a.v1), Pv(b.v0), Pv(b.v1)) \
                            - math.radians(c.value)
                        return [0.5*math.atan2(math.sin(2*d), math.cos(2*d))]
                    return verts, [], f
            def f(X):
                    m = c.measure_signed(lambda v: P(v, X))
                    return [m*c.sign - c.value]
            return verts, [], f
        if isinstance(c, CEqual):
            if isinstance(c.seg_a, Circle) and isinstance(c.seg_b, Circle):
                def f(X):
                    return [R(c.seg_a, X) - R(c.seg_b, X)]
                return [], [c.seg_a, c.seg_b], f
            a0, a1, b0, b1 = c.seg_a.v0, c.seg_a.v1, c.seg_b.v0, c.seg_b.v1
            def f(X):
                (ax, ay), (bx, by) = P(a0, X), P(a1, X)
                (cx, cy), (dx, dy) = P(b0, X), P(b1, X)
                return [math.hypot(bx-ax, by-ay) - math.hypot(dx-cx, dy-cy)]
            return [a0, a1, b0, b1], [], f
        if isinstance(c, CParallel):
            a0, a1, b0, b1 = c.seg_a.v0, c.seg_a.v1, c.seg_b.v0, c.seg_b.v1
            def f(X):
                (ax, ay), (bx, by) = P(a0, X), P(a1, X)
                (cx, cy), (dx, dy) = P(b0, X), P(b1, X)
                return [(bx-ax)*(dy-cy) - (by-ay)*(dx-cx)]
            return [a0, a1, b0, b1], [], f
        if isinstance(c, CCollinear):
            a0, a1, b0, b1 = c.seg_a.v0, c.seg_a.v1, c.seg_b.v0, c.seg_b.v1
            def f(X):
                (ax, ay), (bx, by) = P(a0, X), P(a1, X)
                (cx, cy), (dx, dy) = P(b0, X), P(b1, X)
                ux, uy = bx-ax, by-ay
                vx, vy = dx-cx, dy-cy
                length = math.hypot(ux, uy)
                other_length = math.hypot(vx, vy)
                if length < 1e-9 or other_length < 1e-9: return [0.0, 0.0]
                return [(ux*vy-uy*vx)/(length*other_length),
                        (ux*(cy-ay)-uy*(cx-ax))/length]
            return [a0, a1, b0, b1], [], f
        if isinstance(c, CTangential):
            a, b = c.entity_a, c.entity_b
            if isinstance(a, Segment) or isinstance(b, Segment):
                line = a if isinstance(a, Segment) else b
                curve = b if line is a else a
                if isinstance(curve, Segment): return None
                def radius(X):
                    if isinstance(curve, Circle): return R(curve, X)
                    (cx, cy), (sx, sy) = P(curve.center, X), P(curve.v_start, X)
                    return math.hypot(sx-cx, sy-cy)
                def f(X):
                    center = P(curve.center, X)
                    distance = _signed_line_dist(P(line.v0, X), P(line.v1, X), center)
                    return [distance - c.side*radius(X)]
                verts = [line.v0, line.v1, curve.center]
                circles = [curve] if isinstance(curve, Circle) else []
                if isinstance(curve, Arc): verts.append(curve.v_start)
                return verts, circles, f
            def radius(curve, X):
                if isinstance(curve, Circle): return R(curve, X)
                (cx, cy), (sx, sy) = P(curve.center, X), P(curve.v_start, X)
                return math.hypot(sx-cx, sy-cy)
            def f(X):
                (ax, ay), (bx, by) = P(a.center, X), P(b.center, X)
                distance = math.sqrt((bx-ax)**2 + (by-ay)**2 + 1e-18)
                ra, rb = radius(a, X), radius(b, X)
                target = ra + rb if c.external else c.side*(ra-rb)
                return [distance-target]
            verts = [a.center, b.center]
            circles = []
            for curve in (a, b):
                if isinstance(curve, Circle): circles.append(curve)
                else: verts.append(curve.v_start)
            return verts, circles, f
        if isinstance(c, CSymmetric):
            a0, a1 = (c.seg_a, c.seg_a) if isinstance(c.seg_a, Vertex) else (c.seg_a.v0, c.seg_a.v1)
            b0, b1 = (c.seg_b, c.seg_b) if isinstance(c.seg_b, Vertex) else (c.seg_b.v0, c.seg_b.v1)
            if isinstance(c.center, Segment):
                cv0, cv1 = c.center.v0, c.center.v1
                def f(X):
                    ma = ((P(a0,X)[0]+P(a1,X)[0])/2, (P(a0,X)[1]+P(a1,X)[1])/2)
                    mb = ((P(b0,X)[0]+P(b1,X)[0])/2, (P(b0,X)[1]+P(b1,X)[1])/2)
                    da = _signed_line_dist(P(cv0,X), P(cv1,X), ma)
                    db = _signed_line_dist(P(cv0,X), P(cv1,X), mb)
                    (lx,ly),(rx,ry) = P(cv0,X), P(cv1,X)
                    dx2,dy2 = rx-lx, ry-ly; L2 = dx2*dx2+dy2*dy2 or 1e-12
                    ta = ((ma[0]-lx)*dx2+(ma[1]-ly)*dy2)/L2
                    tb = ((mb[0]-lx)*dx2+(mb[1]-ly)*dy2)/L2
                    return [da + db, ta - tb]
                return [a0, a1, b0, b1, cv0, cv1], [], f
            else:
                cv = c.center
                def f(X):
                    ma = ((P(a0,X)[0]+P(a1,X)[0])/2, (P(a0,X)[1]+P(a1,X)[1])/2)
                    mb = ((P(b0,X)[0]+P(b1,X)[0])/2, (P(b0,X)[1]+P(b1,X)[1])/2)
                    cx2, cy2 = P(cv, X)
                    return [(ma[0]+mb[0])/2 - cx2, (ma[1]+mb[1])/2 - cy2]
                return [a0, a1, b0, b1, cv], [], f
        if isinstance(c, CMirrorPoint):
            source, mirror = c.vertex_move, c.vertex_target
            if isinstance(c.axis, Segment):
                a, b = c.axis.v0, c.axis.v1
                def f(X):
                    (x, y), (mx, my) = P(source, X), P(mirror, X)
                    (ax, ay), (bx, by) = P(a, X), P(b, X)
                    dx, dy = bx-ax, by-ay
                    length2 = dx*dx + dy*dy
                    if length2 < 1e-18:
                        return [1.0, 1.0]
                    t = ((x-ax)*dx + (y-ay)*dy) / length2
                    return [mx - (2*(ax+t*dx)-x), my - (2*(ay+t*dy)-y)]
                return [source, mirror, a, b], [], f
            def f(X):
                (x, y), (mx, my) = P(source, X), P(mirror, X)
                return [mx-x, my+y] if c.axis == "horizontal" else [mx+x, my-y]
            return [source, mirror], [], f
        return None

    # ── state vector ─────────────────────────────────────────────────────────
    def pack(self):
        X = [0.0]*self.n
        for v, i in self.vix.items(): X[i] = v.x; X[i+1] = v.y
        for c, i in self.rix.items(): X[i] = c.radius
        return X

    def unpack(self, X):
        for v, i in self.vix.items(): v.x = float(X[i]); v.y = float(X[i+1])
        for group, i in self.tix.items():
            dx, dy = float(X[i]), float(X[i+1])
            if dx or dy:
                for v in group.vertices():
                    v.x += dx; v.y += dy
        for c, i in self.rix.items(): c.radius = float(X[i])

    def indices_of(self, verts):
        idx = []
        for v in verts:
            i = self.vix.get(v)
            if i is None:
                i = self.tix.get(self.text_vertex_group.get(v))
            if i is not None and i not in idx: idx += [i, i+1]
        return idx

    def rows_of(self, owner):
        return [r for o, r0, nr, _, _ in self.eqs if o is owner for r in range(r0, r0+nr)]

    # ── numerics ─────────────────────────────────────────────────────────────
    def residuals(self, X):
        r = []
        for _, _, _, _, f in self.eqs: r += f(X)
        return np.array(r, dtype=float)

    def jacobian(self, X):
        X = list(X); h = self.FD_H
        J = np.zeros((self.m, self.n))
        for _, r0, nr, idx, f in self.eqs:
            for j in idx:
                old = X[j]
                X[j] = old + h; fp = f(X)
                X[j] = old - h; fm = f(X)
                X[j] = old
                for k in range(nr): J[r0+k, j] = (fp[k]-fm[k])/(2*h)
        return J

    @staticmethod
    def _rank_tol(S):
        return 1e-5*max(1.0, float(S[0])) if len(S) else 1.0

    def rank(self, J=None):
        if J is None: J = self.jacobian(self.pack())
        if J.size == 0: return 0
        S = np.linalg.svd(J, compute_uv=False)
        return int((S > self._rank_tol(S)).sum())

    def solve(self, X, lock=(), heavy=()):
        """Gauss-Newton with backtracking. Variables in `lock` stay put; variables in `heavy`
        are weighted so they move as little as possible. Returns (ok, X)."""
        X = list(X)
        if self.m == 0: return True, X
        lockset, heavyset = set(lock), set(heavy)
        free = [j for j in range(self.n) if j not in lockset]
        wts = np.array([1e3 if j in heavyset else 1.0 for j in free])
        r = self.residuals(X)
        for _ in range(60):
            if np.abs(r).max() < 1e-9: return True, X
            if not free: break
            J = self.jacobian(X)[:, free] / wts
            dx = np.linalg.lstsq(J, -r, rcond=None)[0] / wts
            nr = np.linalg.norm(r); step = 1.0; improved = False
            for _ in range(12):
                Xn = list(X)
                for k, j in enumerate(free): Xn[j] += step*dx[k]
                rn = self.residuals(Xn)
                if np.linalg.norm(rn) < nr:
                    X, r, improved = Xn, rn, True; break
                step *= 0.5
            if not improved: break
        return bool(np.abs(r).max() < 1e-6), X

    def analyse(self):
        """DOF and which vertices / circles are fully determined."""
        locked = {v for v in self.order if v.locked}
        if self.n == 0:
            return {"dof": 0, "dof_all": 0, "det_v": set(self.order), "det_c": set(self.sk.circles)}
        J = self.jacobian(self.pack())
        if J.shape[0]:
            _, S, Vt = np.linalg.svd(J)
            rank = int((S > self._rank_tol(S)).sum())
            N = Vt[rank:]
        else:
            rank, N = 0, np.eye(self.n)
        def det(cols):
            return N.shape[0] == 0 or float(np.abs(N[:, cols]).max()) < 1e-4
        det_v = set(locked)
        for v, i in self.vix.items():
            if det([i, i+1]): det_v.add(v)
        det_c = set()
        for c in self.sk.circles:
            i = self.rix.get(c)
            if c.center in det_v and (i is None or det([i])): det_c.add(c)
        # only profile geometry must be constrained; support geometry and points are optional
        mand = set()
        for s in self.sk.segments:
            if not s.construction: mand |= {s.v0, s.v1}
        for a in self.sk.arcs:
            if not a.construction: mand |= {a.center, a.v_start, a.v_end}
        for ellipse in self.sk.ellipses:
            if not ellipse.construction: mand.update(ellipse.vertices())
        cols = []
        for c in self.sk.circles:
            if not c.construction:
                mand.add(c.center)
                if c in self.rix: cols.append(self.rix[c])
        for v in mand:
            if v in self.vix: cols += [self.vix[v], self.vix[v]+1]
        if cols and N.shape[0]:
            sub = N[:, sorted(cols)]
            Ss = np.linalg.svd(sub, compute_uv=False)
            dof_req = int((Ss > 1e-6).sum())
        else:
            dof_req = 0
        return {"dof": dof_req, "dof_all": self.n - rank, "det_v": det_v, "det_c": det_c}

def solve_sketch(sk):
    """Solve all constraints in place. Returns True when every equation is satisfied."""
    return sk.solve()

# ── sketch ────────────────────────────────────────────────────────────────────
def plane_frame(plane):
    """(origin, u, v, w) — sketch x/y axes and extrusion direction of a base plane."""
    e = np.eye(3); ax, ay, az = PLANE_AXES[plane]
    return (np.zeros(3), e[ax].copy(), e[ay].copy(), e[az].copy())

def rotated_face_frame(frame, rotation):
    origin, u, v, normal = (np.asarray(a, float) for a in frame)
    cosine, sine = rotation
    return origin, cosine*u+sine*v, -sine*u+cosine*v, normal

def face_reference_sketch(face, frame):
    """Create fixed face outlines with stable links to their boundary primitives."""
    sk = Sketch("Face", frame=frame)
    origin, u, v, normal = sk.frame
    def vertex(point):
        delta = np.asarray(point, dtype=float) - origin
        xy = (float(delta @ u), float(delta @ v))
        existing = next((item for item in sk.vertices if math.dist(item.xy(), xy) < 1e-6),
                        None)
        if existing is None:
            existing = Vertex(*xy, locked=True)
            sk.vertices.append(existing)
        return existing
    for index, primitive in enumerate(face.get("boundary", [])):
        if primitive[0] == "line":
            a, b = vertex(primitive[1]), vertex(primitive[2])
            if a is b:
                continue
            element = Segment(a, b, reference=True)
            sk.segments.append(element)
        elif primitive[0] == "circle":
            element = Circle(vertex(primitive[1]), primitive[2], reference=True)
            sk.circles.append(element)
        elif primitive[0] == "arc":
            _, center, start, end, axis = primitive
            if float(np.dot(axis, normal)) < 0:
                start, end = end, start
            element = Arc(vertex(center), vertex(start), vertex(end), reference=True)
            sk.arcs.append(element)
        else:
            continue
        element.reference_boundary = index
    return sk

def project_sketch_segments(source, target):
    """Add source sketch lines to a face sketch as fixed reference segments."""
    origin, axis_u, axis_v, _ = (np.asarray(axis, float) for axis in target.frame)
    def project(vertex):
        point = np.asarray(source.to3d(vertex.xy()), dtype=float) - origin
        return float(point @ axis_u), float(point @ axis_v)

    boundary = [segment for segment in target.segments if segment.reference]
    boundary_a = np.asarray([segment.v0.xy() for segment in boundary], dtype=float).reshape(-1, 2)
    boundary_b = np.asarray([segment.v1.xy() for segment in boundary], dtype=float).reshape(-1, 2)
    mapped_vertices = {}
    for segment in source.segments:
        if segment.reference:
            continue
        a, b = project(segment.v0), project(segment.v1)
        if math.dist(a, b) < 1e-6:
            continue
        samples = [((1.0 - t) * np.asarray(a) + t * np.asarray(b))
                   for t in (0.0, 0.25, 0.5, 0.75, 1.0)]
        if boundary and all(min_seg_dist(point, boundary_a, boundary_b) < 1e-5
                            for point in samples):
            continue
        va = mapped_vertices.get(segment.v0)
        if va is None:
            va = Vertex(*a, locked=True)
            mapped_vertices[segment.v0] = va
            target.vertices.append(va)
        vb = mapped_vertices.get(segment.v1)
        if vb is None:
            vb = Vertex(*b, locked=True)
            mapped_vertices[segment.v1] = vb
            target.vertices.append(vb)
        if va is not vb:
            target.segments.append(Segment(va, vb, reference=True))

def project_sketch_points(source, target):
    """Project standalone source points into a face sketch as fixed reference points."""
    origin, axis_u, axis_v, _ = (np.asarray(axis, float) for axis in target.frame)
    projected = 0
    for point in source.points_free:
        if point.locked:
            continue
        delta = np.asarray(source.to3d(point.xy()), dtype=float) - origin
        xy = (float(delta @ axis_u), float(delta @ axis_v))
        existing = next((vertex for vertex in target.vertices
                         if vertex.locked and math.dist(vertex.xy(), xy) < 1e-6), None)
        if existing is not None:
            if existing not in target.points_free:
                target.points_free.append(existing)
                projected += 1
            continue
        vertex = Vertex(*xy, locked=True)
        target.vertices.append(vertex)
        target.points_free.append(vertex)
        projected += 1
    return projected

def project_sketch_circles(source, target):
    """Project parallel source-sketch circles into a face sketch as fixed references."""
    source_normal = np.asarray(source.frame[3], dtype=float)
    target_origin, axis_u, axis_v, target_normal = (
        np.asarray(axis, dtype=float) for axis in target.frame)
    if abs(float(source_normal @ target_normal)) < 1.0 - 1e-6:
        return
    for circle in source.circles:
        if circle.reference:
            continue
        center = np.asarray(source.to3d(circle.center.xy()), dtype=float) - target_origin
        xy = (float(center @ axis_u), float(center @ axis_v))
        if any(existing.reference and
               math.dist(existing.center.xy(), xy) < 1e-5 and
               abs(existing.radius - circle.radius) < 1e-5
               for existing in target.circles):
            continue
        vertex = next((v for v in target.vertices
                       if v.locked and math.dist(v.xy(), xy) < 1e-6), None)
        if vertex is None:
            vertex = Vertex(*xy, locked=True)
            target.vertices.append(vertex)
        target.circles.append(Circle(vertex, circle.radius, reference=True))

def project_sketch_curves(source, target):
    """Project source arcs and non-parallel circles as fixed polylines."""
    origin, axis_u, axis_v, target_normal = (
        np.asarray(axis, dtype=float) for axis in target.frame)
    source_normal = np.asarray(source.frame[3], dtype=float)
    parallel_planes = abs(float(source_normal @ target_normal)) >= 1.0 - 1e-6

    def project(points):
        world = source.to3d_many(points)
        relative = world - origin
        return np.column_stack((relative @ axis_u, relative @ axis_v))

    mapped_vertices = {}

    def vertex(xy):
        key = (round(float(xy[0]), 8), round(float(xy[1]), 8))
        result = mapped_vertices.get(key)
        if result is None:
            result = Vertex(*key, locked=True)
            mapped_vertices[key] = result
            target.vertices.append(result)
        return result

    curves = [(arc.tess(), False) for arc in source.arcs if not arc.reference]
    curves.extend((ellipse.tess(), True) for ellipse in source.ellipses
                  if not ellipse.reference)
    if not parallel_planes:
        curves.extend((circle_pts(circle.center.x, circle.center.y, circle.radius), True)
                      for circle in source.circles if not circle.reference)
    added = 0
    for points, closed in curves:
        projected = project(points)
        if len(projected) < 2:
            continue
        pairs = zip(projected, np.roll(projected, -1, axis=0)) if closed else \
            zip(projected[:-1], projected[1:])
        for start, end in pairs:
            if float(np.linalg.norm(end - start)) < 1e-6:
                continue
            a, b = vertex(start), vertex(end)
            if a is b or any(
                    (math.dist(existing.v0.xy(), a.xy()) < 1e-6 and
                     math.dist(existing.v1.xy(), b.xy()) < 1e-6) or
                    (math.dist(existing.v0.xy(), b.xy()) < 1e-6 and
                     math.dist(existing.v1.xy(), a.xy()) < 1e-6)
                    for existing in target.segments):
                continue
            target.segments.append(Segment(a, b, reference=True))
            added += 1
    return added

def datum_surface_frame(base_frame, offset, rotation):
    """Apply local XYZ offsets and X-then-Y-then-Z rotations to a reference frame."""
    origin, u, v, normal = (np.asarray(axis, float) for axis in base_frame)
    basis = np.column_stack((u, v, normal))
    x, y, z = np.radians(np.asarray(rotation, dtype=float))
    cx, sx = math.cos(x), math.sin(x)
    cy, sy = math.cos(y), math.sin(y)
    cz, sz = math.cos(z), math.sin(z)
    rx = np.array([[1, 0, 0], [0, cx, -sx], [0, sx, cx]])
    ry = np.array([[cy, 0, sy], [0, 1, 0], [-sy, 0, cy]])
    rz = np.array([[cz, -sz, 0], [sz, cz, 0], [0, 0, 1]])
    transformed = basis @ (rz @ ry @ rx)
    placed_origin = origin + basis @ np.asarray(offset, dtype=float)
    return (placed_origin, transformed[:, 0], transformed[:, 1], transformed[:, 2])

def tangent_face_frame(entry, face_index):
    """Build an automatic tangent frame at the highest vertex of a curved mesh face."""
    faces = entry.get("faces", [])
    if not isinstance(face_index, int) or not 0 <= face_index < len(faces):
        raise ValueError("The curved reference face is no longer available.")
    face = faces[face_index]
    if face.get("planar") or not face.get("tris"):
        raise ValueError("Choose a curved face for automatic tangent placement.")
    solid = entry.get("solid")
    if not isinstance(solid, (tuple, list)) or len(solid) != 2:
        raise ValueError("The curved reference face has no usable mesh.")
    vertices, triangles = solid
    points = np.asarray(vertices, dtype=float)
    tris = np.asarray(triangles, dtype=int).reshape(-1, 3)
    face_triangle_ids = np.asarray(face["tris"], dtype=int)
    if not len(points) or not len(face_triangle_ids) or \
            np.any(face_triangle_ids < 0) or np.any(face_triangle_ids >= len(tris)):
        raise ValueError("The curved reference face has no usable mesh.")
    face_triangles = tris[face_triangle_ids]
    if np.any(face_triangles < 0) or np.any(face_triangles >= len(points)) or \
            not np.isfinite(points).all():
        raise ValueError("The curved reference face has no usable mesh.")

    face_vertex_ids = np.unique(face_triangles)
    highest_z = float(points[face_vertex_ids, 2].max())
    tolerance = max(1e-8, float(np.ptp(points[face_vertex_ids, 2])) * 1e-8)
    candidates = face_vertex_ids[
        points[face_vertex_ids, 2] >= highest_z - tolerance]
    mesh_center = points.mean(axis=0)
    triangle_normals = np.cross(
        points[face_triangles[:, 1]] - points[face_triangles[:, 0]],
        points[face_triangles[:, 2]] - points[face_triangles[:, 0]])
    triangle_centers = points[face_triangles].mean(axis=1)
    inward = np.einsum("ij,ij->i", triangle_normals, triangle_centers-mesh_center) < 0
    triangle_normals[inward] *= -1

    candidates_with_normals = []
    for vertex_id in candidates:
        incident = np.any(face_triangles == vertex_id, axis=1)
        normal = triangle_normals[incident].sum(axis=0)
        length = float(np.linalg.norm(normal))
        if length > 1e-12:
            normal /= length
            candidates_with_normals.append((vertex_id, normal))
    if not candidates_with_normals:
        raise ValueError("Could not determine a tangent direction for the curved face.")
    vertex_id, normal = max(
        candidates_with_normals,
        key=lambda item: (float(item[1][2]), -int(item[0])))
    origin = points[vertex_id]

    reference = np.array([0.0, 0.0, 1.0])
    if abs(float(reference @ normal)) > 0.95:
        reference = np.array([0.0, 1.0, 0.0])
    axis_u = _unit(np.cross(reference, normal))
    axis_v = _unit(np.cross(normal, axis_u))
    return origin, axis_u, axis_v, normal

def _fit_curved_surface(entry, face_index):
    if not isinstance(entry, dict):
        return None
    faces = entry.get("faces", [])
    if not isinstance(face_index, int) or not 0 <= face_index < len(faces):
        return None
    face = faces[face_index]
    solid = entry.get("solid")
    if face.get("planar") or not face.get("tris") or \
            not isinstance(solid, (tuple, list)) or len(solid) != 2:
        return None
    vertices, triangles = solid
    points = np.asarray(vertices, dtype=float)
    tris = np.asarray(triangles, dtype=int).reshape(-1, 3)
    tri_ids = np.asarray(face["tris"], dtype=int)
    if not len(tri_ids) or np.any(tri_ids < 0) or np.any(tri_ids >= len(tris)):
        return None
    face_tris = tris[tri_ids]
    if np.any(face_tris < 0) or np.any(face_tris >= len(points)) or \
            not np.isfinite(points).all():
        return None
    face_points = points[np.unique(face_tris)]
    if len(face_points) < 6:
        return None
    triangle_points = points[face_tris]
    normals = np.cross(triangle_points[:, 1] - triangle_points[:, 0],
                       triangle_points[:, 2] - triangle_points[:, 0])
    normal_lengths = np.linalg.norm(normals, axis=1)
    normals = normals[normal_lengths > 1e-12] / normal_lengths[normal_lengths > 1e-12, None]
    cylinder_axis = None
    if len(normals) >= 3:
        normal_eigenvalues, normal_eigenvectors = np.linalg.eigh(
            normals.T @ normals / len(normals))
        if normal_eigenvalues[-1] > 1e-9 and \
                normal_eigenvalues[0] / normal_eigenvalues[-1] <= 0.08:
            cylinder_axis = normal_eigenvectors[:, 0]

    surface_type = str(face.get("surface_type", "")).upper()
    # A least-squares sphere fit makes the controls independent of mesh orientation.
    sphere_matrix = np.column_stack((2.0 * face_points, np.ones(len(face_points))))
    sphere_rhs = np.einsum("ij,ij->i", face_points, face_points)
    sphere_fit, _, sphere_rank, _ = np.linalg.lstsq(sphere_matrix, sphere_rhs, rcond=None)
    if sphere_rank == 4:
        sphere_center = sphere_fit[:3]
        sphere_radius = math.sqrt(max(0.0, float(sphere_fit[3] + sphere_center @ sphere_center)))
        sphere_error = float(np.sqrt(np.mean(
            (np.linalg.norm(face_points - sphere_center, axis=1) - sphere_radius) ** 2)))
        if (surface_type == "SPHERE" or
                (surface_type != "CYLINDER" and cylinder_axis is None)) and \
                sphere_radius > 1e-9 and \
                sphere_error <= max(1e-5, sphere_radius * 0.01):
            return "sphere", sphere_center, sphere_radius

    # Cylinder normals share one zero-variance direction: the cylinder axis.
    if cylinder_axis is None:
        return None
    axis = cylinder_axis
    major = int(np.argmax(np.abs(axis)))
    if axis[major] < 0:
        axis = -axis
    reference = np.array((0.0, 0.0, 1.0))
    radial_u = reference - float(reference @ axis) * axis
    if float(np.linalg.norm(radial_u)) < 1e-8:
        reference = np.array((1.0, 0.0, 0.0))
        radial_u = reference - float(reference @ axis) * axis
    radial_u = _unit(radial_u)
    radial_v = _unit(np.cross(axis, radial_u))
    x, y = face_points @ radial_u, face_points @ radial_v
    circle_matrix = np.column_stack((2.0 * x, 2.0 * y, np.ones(len(x))))
    circle_fit, _, circle_rank, _ = np.linalg.lstsq(
        circle_matrix, x * x + y * y, rcond=None)
    if circle_rank < 3:
        return None
    center_u, center_v, constant = circle_fit
    radius = math.sqrt(max(0.0, float(constant + center_u**2 + center_v**2)))
    radial_error = float(np.sqrt(np.mean(
        (np.hypot(x - center_u, y - center_v) - radius) ** 2)))
    if radius <= 1e-9 or radial_error > max(1e-5, radius * 0.02):
        return None
    face_axial = face_points @ axis
    solid_axial = points @ axis
    axial_center = float((solid_axial.min() + solid_axial.max()) / 2.0)
    axial_limits = (float(face_axial.min() - axial_center),
                    float(face_axial.max() - axial_center))
    center = center_u * radial_u + center_v * radial_v + axial_center * axis
    axial_default = axial_limits[1] if axis[2] > 1e-8 else \
        axial_limits[0] if axis[2] < -1e-8 else 0.0
    return ("cylinder", center, axis, radial_u, radial_v, radius,
            axial_limits, (0.0, axial_default))

def curved_surface_frame(entry, face_index, position=None):
    """Return a positioned tangent frame and shape metadata for spherical/cylindrical mesh faces."""
    if not isinstance(entry, dict):
        return None
    faces = entry.get("faces", [])
    solid = entry.get("solid")
    if not isinstance(face_index, int) or not 0 <= face_index < len(faces) or \
            not isinstance(solid, (tuple, list)) or len(solid) != 2:
        return None
    cache = entry.setdefault("_curved_surface_cache", {})
    cached = cache.get(face_index)
    face = faces[face_index]
    if cached is not None and cached[0] is solid[0] and \
            cached[1] is solid[1] and cached[2] is face:
        definition = cached[3]
    else:
        definition = _fit_curved_surface(entry, face_index)
        cache[face_index] = (solid[0], solid[1], face, definition)
    if definition is None:
        return None

    if position is not None:
        position = np.asarray(position, dtype=float)
        if position.shape != (2,) or not np.isfinite(position).all():
            raise ValueError("Tangent position values must be finite numbers.")
    shape = definition[0]
    if shape == "sphere":
        _, center, radius = definition
        limits, default_position = (-90.0, 90.0), (0.0, 90.0)
        azimuth, elevation = np.radians(default_position if position is None else position)
        normal = np.array((math.cos(elevation) * math.cos(azimuth),
                           math.cos(elevation) * math.sin(azimuth),
                           math.sin(elevation)))
        axis_u = np.array((-math.sin(azimuth), math.cos(azimuth), 0.0))
        axis_v = _unit(np.cross(normal, axis_u))
        frame = (center + radius * normal, axis_u, axis_v, normal)
        return frame, shape, limits, default_position
    _, center, axis, radial_u, radial_v, radius, limits, default_position = definition
    _, center, axis, radial_u, radial_v, radius, limits, default_position = definition
    if position is None:
        position = default_position
    angle = math.radians(float(position[0]))
    axial_position = float(position[1])
    normal = math.cos(angle) * radial_u + math.sin(angle) * radial_v
    axis_u = axis
    axis_v = _unit(np.cross(normal, axis_u))
    frame = (center + axial_position * axis + radius * normal,
             axis_u, axis_v, normal)
    return frame, shape, limits, default_position

class Sketch:
    _ctr = [0]
    def __init__(self, plane, name=None, frame=None):
        Sketch._ctr[0] += 1
        self.name        = name or f"sketch{Sketch._ctr[0]:02d}"
        self.plane       = plane          # "XY"/"XZ"/"YZ", "Face" or a datum "Surface"
        self.frame       = tuple(np.asarray(a, float) for a in frame) if frame is not None \
                           else plane_frame(plane)
        self.face_rotation = (1.0, 0.0)
        self.vertices    = []
        self.segments    = []
        self.circles     = []
        self.arcs        = []
        self.ellipses    = []
        self.points_free = []   # standalone sketch points (e.g. created by Point-on-Line)
        self.reference_generated_levels = []
        self.legacy_reference_levels = False
        self.text_groups = []
        self.constraints = []
        self._an_key = None; self._an = None

    def _make_text_box_vertices(self, segments):
        """Create locked virtual points on a text bounding box: corners, edge mids, center."""
        if not segments:
            return []
        verts = {v for s in segments for v in (s.v0, s.v1)}
        x0 = min(v.x for v in verts); y0 = min(v.y for v in verts)
        x1 = max(v.x for v in verts); y1 = max(v.y for v in verts)
        xm, ym = (x0+x1)/2.0, (y0+y1)/2.0
        points = [(x0, y0), (x1, y0), (x1, y1), (x0, y1),
                  (xm, y0), (x1, ym), (xm, y1), (x0, ym), (xm, ym)]
        made = []
        for x, y in points:
            v = Vertex(x, y, locked=True)
            self.vertices.append(v)
            made.append(v)
        return made

    # ── placement ────────────────────────────────────────────────────────────
    def to3d(self, xy, z=0.0):
        O, u, v, w = self.frame
        return tuple(float(c) for c in O + xy[0]*u + xy[1]*v + z*w)

    def to3d_many(self, pts):
        O, u, v, _ = self.frame
        P = np.asarray(pts, dtype=float).reshape(-1, 2)
        return O + P[:, :1]*u + P[:, 1:2]*v

    def get_or_merge(self, x, y, snap):
        independent_vertices = self.text_vertices() | self.reference_vertices()
        for v in self.vertices:
            if v in independent_vertices: continue
            if hasattr(v, "reference_level"): continue
            if math.hypot(v.x-x, v.y-y) <= snap: return v
        v = Vertex(x, y); self.vertices.append(v); return v

    def text_vertices(self):
        return {v for group in self.text_groups for v in group.vertices()}

    def reference_vertices(self):
        vertices = {v for s in self.segments if s.reference for v in (s.v0, s.v1)}
        vertices.update(c.center for c in self.circles if c.reference)
        vertices.update(v for a in self.arcs if a.reference
                        for v in (a.center, a.v_start, a.v_end))
        vertices.update(v for ellipse in self.ellipses if ellipse.reference
                for v in ellipse.vertices())
        vertices.update(v for v in self.points_free if v.locked)
        return vertices

    def text_group_for(self, element):
        return next((group for group in self.text_groups
                     if element in group.segments or
                     (isinstance(element, Vertex) and element in group.vertices())), None)

    def expand_text_selection(self, segs):
        segs = set(segs)
        for group in self.text_groups:
            if segs.intersection(group.segments): segs.update(group.segments)
        return segs

    def add_svg_contours(self, contours, text_groups=()):
        """Insert ordinary SVG geometry and independently owned, rigid text outlines."""
        owners = {i: group for group in text_groups for i in group["contours"]}
        made = {id(group): [] for group in text_groups}
        added = 0
        for i, contour in enumerate(contours):
            group = owners.get(i)
            if group is None:
                vertices = [self.get_or_merge(x, y, MERGE_TOL) for x, y in contour]
            else:
                # Close each glyph contour locally, never merging it with other sketch geometry.
                vertices = []
                for x, y in contour:
                    v = next((v for v in vertices if math.hypot(v.x-x, v.y-y) <= MERGE_TOL), None)
                    if v is None:
                        v = Vertex(x, y, locked=True); self.vertices.append(v)
                    vertices.append(v)
                if len(vertices) > 2 and vertices[-1] is not vertices[0]:
                    vertices.append(vertices[0])
            segments = [Segment(a, b) for a, b in zip(vertices, vertices[1:]) if a is not b]
            self.segments.extend(segments); added += len(segments)
            if group is not None: made[id(group)].extend(segments)
        for group in text_groups:
            segs = made[id(group)]
            if not segs:
                continue
            self.text_groups.append(SketchText(
                group.get("label", ""), segs,
                box_vertices=self._make_text_box_vertices(segs),
                font_family=group.get("font_family", "Arial"),
                font_size=group.get("font_size", 12.0),
                bold=group.get("bold", False),
                italic=group.get("italic", False),
                underline=group.get("underline", False),
                align=group.get("align", "left"),
            ))
        self._an_key = None
        return added

    def add_text_label(self, at_xy, label, style):
        """Add a rigid text outline at sketch position at_xy (mm)."""
        contours = text_contours(str(label or ""),
                                 font_family=style.get("font_family", "Arial"),
                                 font_size=style.get("font_size", 12.0),
                                 bold=style.get("bold", False),
                                 italic=style.get("italic", False),
                                 underline=style.get("underline", False),
                                 align=style.get("align", "left"))
        if not contours:
            return None, 0
        ox, oy = float(at_xy[0]), float(at_xy[1])
        segs = []
        for contour in contours:
            vertices = []
            for x, y in contour:
                v = next((v for v in vertices
                          if math.hypot(v.x-(ox+x), v.y-(oy+y)) <= MERGE_TOL), None)
                if v is None:
                    v = Vertex(ox+x, oy+y, locked=True)
                    self.vertices.append(v)
                vertices.append(v)
            made = [Segment(a, b) for a, b in zip(vertices, vertices[1:]) if a is not b]
            self.segments.extend(made)
            segs.extend(made)
        if not segs:
            return None, 0
        group = SketchText(str(label), segs,
                           box_vertices=self._make_text_box_vertices(segs),
                           font_family=style.get("font_family", "Arial"),
                           font_size=float(style.get("font_size", 12.0)),
                           bold=bool(style.get("bold", False)),
                           italic=bool(style.get("italic", False)),
                           underline=bool(style.get("underline", False)),
                           align=style.get("align", "left"))
        self.text_groups.append(group)
        self._an_key = None
        return group, len(segs)

    def transform_text(self, group, original, scale=1.0, center=(0.0, 0.0), offset=(0.0, 0.0)):
        """Transform a complete label from a drag-start snapshot; reject conflicting constraints."""
        if group not in self.text_groups or set(original) != group.vertices():
            raise ValueError("A text transform must contain every vertex of an existing text group")
        if not all(math.isfinite(value) for value in (scale, *center, *offset)) or scale <= 0:
            return False
        positions = {v: (v.x, v.y) for v in self.vertices}
        radii = {c: c.radius for c in self.circles}
        for v, (x, y) in original.items():
            v.x = center[0] + (x-center[0])*scale + offset[0]
            v.y = center[1] + (y-center[1])*scale + offset[1]
        if self.solve():
            self._an_key = None
            return True
        for v, (x, y) in positions.items(): v.x, v.y = x, y
        for c, r in radii.items(): c.radius = r
        return False

    # ── topology ─────────────────────────────────────────────────────────────
    def used_vertices(self):
        used = set(self.points_free)
        for s in self.segments: used |= {s.v0, s.v1}
        for a in self.arcs:     used |= {a.center, a.v_start, a.v_end}
        for c in self.circles:  used.add(c.center)
        for ellipse in self.ellipses: used.update(ellipse.vertices())
        for group in self.text_groups: used |= group.vertices()
        return used

    def _edge_records(self):
        recs = [{"kind": "line", "a": s.v0, "b": s.v1, "pts": [s.v0.xy(), s.v1.xy()]}
                for s in self.segments if not s.construction]
        recs += [{"kind": "arc", "a": a.v_start, "b": a.v_end, "pts": a.tess(),
                  "center": a.center.xy(), "start": a.v_start.xy(), "end": a.v_end.xy()}
                 for a in self.arcs if not a.construction]
        return recs

    def profile_closed(self):
        """True when non-construction profile edges form closed loops."""
        edges = self._edge_records()
        has_closed_curve = (any(not c.construction for c in self.circles) or
                    any(not ellipse.construction for ellipse in self.ellipses))
        if not edges and not has_closed_curve: return bool(self.text_groups)
        deg = {}
        for e in edges:
            if e["a"] is e["b"]: return False
            deg[e["a"]] = deg.get(e["a"], 0) + 1; deg[e["b"]] = deg.get(e["b"], 0) + 1
        return all(d == 2 for d in deg.values())

    @property
    def closed(self): return self.profile_closed()

    def profile_loop_edges(self):
        """Closed profile loops as lists of edge records whose pts run along the loop
        (support geometry excluded). Full circles form single-edge loops."""
        loops = []
        edges = self._edge_records()
        unused = list(range(len(edges)))
        while unused:
            e0 = edges[unused.pop(0)]
            v_first, v_cur = e0["a"], e0["b"]
            loop = [dict(e0)]
            while v_cur is not v_first:
                nxt = next((j for j in unused
                            if edges[j]["a"] is v_cur or edges[j]["b"] is v_cur), None)
                if nxt is None: break
                unused.remove(nxt)
                e = dict(edges[nxt])
                if e["a"] is v_cur: v_cur = e["b"]
                else:               e["pts"] = e["pts"][::-1]; v_cur = e["a"]
                loop.append(e)
            if v_cur is v_first and sum(len(e["pts"])-1 for e in loop) >= 3:
                loops.append(loop)
        for c in self.circles:
            if not c.construction:
                pts = circle_pts(c.center.x, c.center.y, c.radius)
                loops.append([{"kind": "circle", "pts": pts + [pts[0]],
                               "center": c.center.xy(), "radius": c.radius}])
        for ellipse in self.ellipses:
            if not ellipse.construction:
                pts = ellipse.tess()
                loops.append([{"kind": "line", "pts": [a, b]}
                              for a, b in zip(pts, pts[1:] + pts[:1])])
        return loops

    def profile_loops(self):
        """Closed profile loops as lists of (x,y) mm points."""
        return [[p for e in loop for p in e["pts"][:-1]] for loop in self.profile_loop_edges()]

    def replace_vertex(self, old, new):
        """Redirect every reference of vertex old to vertex new and drop old."""
        if old is new: return
        if self.text_group_for(old) is not None or self.text_group_for(new) is not None:
            raise ValueError("Rigid text vertices cannot be merged with other geometry")
        for s in self.segments:
            if s.v0 is old: s.v0 = new
            if s.v1 is old: s.v1 = new
        for a in self.arcs:
            if a.center is old:  a.center = new
            if a.v_start is old: a.v_start = new
            if a.v_end is old:   a.v_end = new
        for c in self.circles:
            if c.center is old: c.center = new
        for ellipse in self.ellipses:
            for attr in ("major_start", "major_end", "minor_start", "minor_end"):
                if getattr(ellipse, attr) is old: setattr(ellipse, attr, new)
        pts = []
        for v in self.points_free:
            v = new if v is old else v
            if v not in pts: pts.append(v)
        self.points_free = pts
        for c in self.constraints:
            for attr in ("vertex", "vertex_move", "vertex_target", "a", "b"):
                if getattr(c, attr, None) is old: setattr(c, attr, new)
            if isinstance(c, CDimension) and isinstance(c.target, tuple):
                c.target = tuple(new if v is old else v for v in c.target)
        # a coincidence between two now-identical vertices is meaningless
        self.constraints = [c for c in self.constraints if not (
            isinstance(c, CCoincident) and c.vertex_move is c.vertex_target)]
        if old in self.vertices: self.vertices.remove(old)

    def remove_geometry(self, segs=(), circles=(), arcs=(), points=(), ellipses=()):
        """Remove editable geometry and its constraints; projected reference geometry survives."""
        segs = {s for s in segs if not s.reference}
        circles = {c for c in circles if not c.reference}
        arcs = {a for a in arcs if not a.reference}
        points = {v for v in points if not v.locked}
        ellipses = {ellipse for ellipse in ellipses if not ellipse.reference}
        ellipses.update(ellipse for ellipse in self.ellipses
                if set(ellipse.vertices()) & points)
        segs = self.expand_text_selection(segs)
        self.text_groups = [group for group in self.text_groups
                            if not segs.intersection(group.segments)]
        before = self.used_vertices()
        self.segments    = [s for s in self.segments if s not in segs]
        self.circles     = [c for c in self.circles if c not in circles]
        self.arcs        = [a for a in self.arcs if a not in arcs]
        self.ellipses    = [ellipse for ellipse in self.ellipses if ellipse not in ellipses]
        self.points_free = [v for v in self.points_free if v not in points]
        after   = self.used_vertices()
        orphans = (before - after) | (points - after)
        self.vertices = [v for v in self.vertices if v not in orphans]
        gone = segs | circles | arcs | ellipses | orphans
        self.constraints = [c for c in self.constraints if not (constraint_refs(c) & gone)]

    # ── scissor (trim) ───────────────────────────────────────────────────────
    def _trim_cuts(self, target):
        """Cut positions on target: crossings with every other element (incl. support and
        reference geometry) plus existing points lying on it.
        → (curve, [[param, point, vertex|None, [cutting elements]], …] sorted by param)."""
        cv = curve_of(target)
        own = ({target.v0, target.v1} if isinstance(target, Segment) else
               {target.center} if isinstance(target, Circle) else
               {target.center, target.v_start, target.v_end})
        cand = []
        for other in self.segments + self.circles + self.arcs:
            if other is target: continue
            for P in curve_intersections(cv, curve_of(other)):
                cand.append((curve_param(cv, P), P, None, other))
        independent_vertices = self.text_vertices() | self.reference_vertices()
        for v in self.used_vertices():
            if v not in own and dist_to_curve(cv, v.xy()) < TRIM_TOL:
                cand.append((curve_param(cv, v.xy()), v.xy(),
                             None if v in independent_vertices else v, None))
        end = curve_end(cv)
        closed = cv[0] == "circle" and cv[3] is None
        eps = TRIM_TOL if cv[0] == "line" else TRIM_TOL/max(cv[2], 1e-9)
        cuts = []
        for s, P, v, other in sorted(cand, key=lambda k: k[0]):
            if closed: s %= 2*math.pi
            elif s <= eps or s >= end - eps: continue
            dup = next((c for c in cuts if abs(c[0]-s) < eps or
                        (closed and abs(abs(c[0]-s) - 2*math.pi) < eps)), None)
            if dup is None:
                cuts.append([s, P, v, [other] if other is not None else []])
            else:
                if dup[2] is None and v is not None: dup[1], dup[2] = P, v
                if other is not None: dup[3].append(other)
        return cv, cuts

    def trim_range(self, target, click):
        """Part of target removed by a scissor click at `click` (mm).
        → (curve, cuts, lo, hi): lo / hi index the cut before / after the click (None = start /
        end of the element). lo = hi = None: the whole element goes (no cut points, or a full
        circle with fewer than two)."""
        cv, cuts = self._trim_cuts(target)
        sc, end = curve_param(cv, click), curve_end(cv)
        if cv[0] == "circle" and cv[3] is None:
            n = len(cuts)
            if n < 2: return cv, cuts, None, None
            for k in range(n):
                a, b = cuts[k][0], cuts[(k+1) % n][0] + (2*math.pi if k == n-1 else 0.0)
                s = sc if sc >= a else sc + 2*math.pi
                if a <= s <= b: return cv, cuts, k, (k+1) % n
            return cv, cuts, n-1, 0
        if not cuts: return cv, cuts, None, None
        if cv[0] == "line": sc = min(max(sc, 0.0), end)
        elif sc > end:  sc = end if sc - end < 2*math.pi - sc else 0.0
        lo = hi = None
        for k, c in enumerate(cuts):
            if c[0] <= sc: lo = k
            elif hi is None: hi = k
        return cv, cuts, lo, hi

    def trim_preview(self, target, click):
        """Polyline (mm) of the part a scissor click would remove."""
        cv, cuts, lo, hi = self.trim_range(target, click)
        end = curve_end(cv)
        a = cuts[lo][0] if lo is not None else 0.0
        b = cuts[hi][0] if hi is not None else end
        if lo is not None and hi is not None and b < a: b += 2*math.pi   # circle wrap-around
        if cv[0] == "line": return [curve_point(cv, a), curve_point(cv, b)]
        n = max(2, int(abs(b-a)/(2*math.pi)*64) + 1)
        return [curve_point(cv, a + (b-a)*i/n) for i in range(n+1)]

    def trim(self, target, click):
        """Scissor: remove the part of target between the two cut points around click.
        New end points stay attached to the cutting geometry (Point on Line / on Curve).
        Returns (ok, message)."""
        if target.reference: return False, "reference geometry cannot be cut"
        if self.text_group_for(target) is not None:
            return False, "text is rigid; move or resize the whole label in Select mode"
        cv, cuts, lo, hi = self.trim_range(target, click)
        if lo is None and hi is None:
            self.remove_geometry(segs=[target] if isinstance(target, Segment) else (),
                                 circles=[target] if isinstance(target, Circle) else (),
                                 arcs=[target] if isinstance(target, Arc) else ())
            return True, "whole element removed (no cut points)"
        extra = []
        def vert(k):
            c = cuts[k]
            if c[2] is None:
                v = Vertex(*c[1]); self.vertices.append(v); c[2] = v
                for o in c[3]:
                    if o.reference: continue
                    extra.append(CPointOnLine(v, o) if isinstance(o, Segment) else CPointOnCurve(v, o))
            return c[2]
        con = target.construction
        if isinstance(target, Segment):
            pieces = ([Segment(target.v0, vert(lo), con)] if lo is not None else []) + \
                     ([Segment(vert(hi), target.v1, con)] if hi is not None else [])
        elif isinstance(target, Circle):
            pieces = [Arc(target.center, vert(hi), vert(lo), con)]
        else:
            pieces = ([Arc(target.center, target.v_start, vert(lo), con)] if lo is not None else []) + \
                     ([Arc(target.center, vert(hi), target.v_end, con)] if hi is not None else [])
        self._replace_element(target, pieces, extra)
        return True, f"cut — {len(pieces)} piece(s) left"

    @staticmethod
    def _trivial(c):
        """Point-on constraints whose point is an end point of the element itself."""
        if isinstance(c, CPointOnLine):  return c.vertex in (c.seg.v0, c.seg.v1)
        if isinstance(c, CPointOnCurve): return isinstance(c.curve, Arc) and \
                                                c.vertex in (c.curve.v_start, c.curve.v_end)
        return False

    def _replace_element(self, target, pieces, extra=()):
        """Swap target for its trimmed pieces and carry its constraints over."""
        before = self.used_vertices()
        first = pieces[0] if pieces else None
        if isinstance(target, Segment):
            i = self.segments.index(target); self.segments[i:i+1] = pieces
        elif isinstance(target, Circle):
            self.circles.remove(target); self.arcs += pieces
        else:
            i = self.arcs.index(target); self.arcs[i:i+1] = pieces
        add, keep = list(extra), []
        for c in self.constraints:
            if target not in constraint_refs(c): keep.append(c); continue
            if isinstance(c, (CHorizontal, CVertical)):
                add += [type(c)(p) for p in pieces]; continue
            if isinstance(c, CDimension):
                if isinstance(target, Circle) and first is not None:
                    add.append(CDimension(first, c.value/2 if c.dim_mode == "diameter" else c.value))
                elif isinstance(target, Arc) and first is not None:
                    c.target = first; keep.append(c)
                continue        # a line's length does not apply to its pieces
            if first is None: continue
            for attr in ("seg", "seg_a", "seg_b", "curve", "a", "b"):
                if getattr(c, attr, None) is target: setattr(c, attr, first)
            keep.append(c)
        if len(pieces) == 2:    # pieces of a line stay collinear, pieces of an arc concentric
            p0, p1 = pieces
            add += [CPointOnLine(p1.v0, p0), CPointOnLine(p1.v1, p0)] if isinstance(p0, Segment) \
                   else [CPointOnCurve(p1.v_start, p0)]
        orphans = before - self.used_vertices()
        self.vertices = [v for v in self.vertices if v not in orphans]
        self.constraints = [c for c in keep
                            if not (constraint_refs(c) & orphans) and not self._trivial(c)]
        for c in add:
            if not (constraint_refs(c) & orphans) and not self._trivial(c):
                self.try_add_constraint(c)

    # ── support geometry switch / clipboard ──────────────────────────────────
    @staticmethod
    def set_construction(elements, on):
        """Switch elements between profile and support geometry. Returns the count changed."""
        n = 0
        for e in elements:
            if getattr(e, "reference", False) or e.construction == on: continue
            e.construction = on; n += 1
        return n

    def mirror_geometry(self, segments, circles, arcs, ellipses, points, axis):
        segments, circles, arcs = set(segments), set(circles), set(arcs)
        ellipses, points = set(ellipses), set(points)
        elements = segments | circles | arcs | ellipses
        if not (elements or points):
            raise ValueError("Select geometry to mirror")
        if any(getattr(element, "reference", False) for element in elements) or \
                any(point.locked for point in points):
            raise ValueError("Reference geometry cannot be mirrored")
        if any(self.text_group_for(element) is not None for element in segments | points):
            raise ValueError("Text cannot be mirrored")
        if isinstance(axis, Segment):
            if axis in segments:
                raise ValueError("Choose an axis outside the selected geometry")
            ax, ay = axis.v0.xy()
            dx, dy = axis.v1.x-ax, axis.v1.y-ay
            length2 = dx*dx + dy*dy
            if length2 < 1e-18:
                raise ValueError("The mirror axis has zero length")
            def reflect(x, y):
                t = ((x-ax)*dx + (y-ay)*dy) / length2
                return 2*(ax+t*dx)-x, 2*(ay+t*dy)-y
        elif axis == "horizontal":
            def reflect(x, y): return x, -y
        elif axis == "vertical":
            def reflect(x, y): return -x, y
        else:
            raise ValueError("Choose a horizontal or vertical mirror axis")
        vertices = set(points)
        for segment in segments: vertices.update((segment.v0, segment.v1))
        for circle in circles: vertices.add(circle.center)
        for arc in arcs: vertices.update((arc.center, arc.v_start, arc.v_end))
        for ellipse in ellipses: vertices.update(ellipse.vertices())
        if vertices & self.text_vertices():
            raise ValueError("Text cannot be mirrored")
        mapping = {vertex: Vertex(*reflect(vertex.x, vertex.y))
                   for vertex in self.vertices if vertex in vertices}
        if len(mapping) != len(vertices):
            raise ValueError("Selected geometry contains a missing vertex")
        new_segments = [Segment(mapping[s.v0], mapping[s.v1], s.construction)
                        for s in self.segments if s in segments]
        pairs = [(circle, Circle(mapping[circle.center], circle.radius, circle.construction))
                 for circle in self.circles if circle in circles]
        new_arcs = [Arc(mapping[a.center], mapping[a.v_end], mapping[a.v_start], a.construction)
                    for a in self.arcs if a in arcs]
        new_ellipses = [Ellipse(*(mapping[vertex] for vertex in ellipse.vertices()),
                                construction=ellipse.construction)
                        for ellipse in self.ellipses if ellipse in ellipses]
        new_points = [mapping[point] for point in self.points_free if point in points]
        constraints = [CMirrorPoint(source, mirror, axis) for source, mirror in mapping.items()]
        constraints.extend(CEqual(source, mirror) for source, mirror in pairs)
        self.vertices.extend(mapping.values())
        self.segments.extend(new_segments)
        self.circles.extend(mirror for _, mirror in pairs)
        self.arcs.extend(new_arcs)
        self.ellipses.extend(new_ellipses)
        self.points_free.extend(new_points)
        self.constraints.extend(constraints)
        self._an_key = None
        return len(new_segments) + len(pairs) + len(new_arcs) + len(new_ellipses) + len(new_points)

    def extract(self, segs=(), circles=(), arcs=(), points=()):
        """Independent copy of elements plus the constraints among them (Fix constraints and
        reference geometry are left out). Used by Copy / Cut."""
        segs = self.expand_text_selection(segs)
        segs    = [s for s in self.segments if s in segs and not s.reference]
        circles = [c for c in self.circles if c in circles and not c.reference]
        arcs    = [a for a in self.arcs if a in arcs and not a.reference]
        points  = [v for v in self.points_free if v in points]
        text_groups = [group for group in self.text_groups
                       if any(segment in segs for segment in group.segments)]
        if not (segs or circles or arcs or points):
            return None
        verts = set(points)
        for s in segs:    verts |= {s.v0, s.v1}
        for c in circles: verts.add(c.center)
        for arc in arcs:  verts.update((arc.center, arc.v_start, arc.v_end))
        for group in text_groups: verts.update(group.vertices())
        ordered_verts = [v for v in self.vertices if v in verts]
        ordered_verts.extend(v for v in verts if v not in self.vertices)
        vertex_map = {v: Vertex(v.x, v.y, v.locked) for v in ordered_verts}
        data = {
            "vertices": list(vertex_map.values()),
            "segments": [Segment(vertex_map[s.v0], vertex_map[s.v1], s.construction)
                         for s in segs],
            "circles": [Circle(vertex_map[c.center], c.radius, c.construction) for c in circles],
            "arcs": [Arc(vertex_map[a.center], vertex_map[a.v_start], vertex_map[a.v_end],
                         a.construction) for a in arcs],
            "points": [vertex_map[v] for v in points],
            "text_groups": [],
            "constraints": [],
        }
        object_map = dict(vertex_map)
        object_map.update(zip(segs, data["segments"]))
        object_map.update(zip(circles, data["circles"]))
        object_map.update(zip(arcs, data["arcs"]))
        for group in text_groups:
            data["text_groups"].append(SketchText(
                group.label, [object_map[s] for s in group.segments],
                box_vertices=[vertex_map[v] for v in group.box_vertices],
                font_family=group.font_family, font_size=group.font_size,
                bold=group.bold, italic=group.italic, underline=group.underline,
                align=group.align))
        allowed = set(segs) | set(circles) | set(arcs) | verts
        for constraint in self.constraints:
            refs = constraint_refs(constraint)
            if isinstance(constraint, CFixed) or \
                    (isinstance(constraint, CMirrorPoint) and not isinstance(constraint.axis, Segment)) or \
                    not refs or not refs <= allowed:
                continue
            copied = type(constraint).__new__(type(constraint))
            for name, value in constraint.__dict__.items():
                setattr(copied, name, self._remap_clip_value(value, object_map))
            data["constraints"].append(copied)
        return data

    @staticmethod
    def _remap_clip_value(value, object_map):
        if isinstance(value, tuple):
            return tuple(Sketch._remap_clip_value(item, object_map) for item in value)
        if isinstance(value, (Vertex, Segment, Circle, Arc)):
            return object_map.get(value, value)
        return value

    @staticmethod
    def clip_vertices(data):
        return data["vertices"]

    @staticmethod
    def mirror_clipboard(data, axis):
        if axis not in ("x", "y"):
            raise ValueError("Clipboard mirror axis must be 'x' or 'y'")
        vertices = data["vertices"]
        if not vertices:
            return
        x0, x1 = min(v.x for v in vertices), max(v.x for v in vertices)
        y0, y1 = min(v.y for v in vertices), max(v.y for v in vertices)
        cx, cy = (x0+x1)/2, (y0+y1)/2
        for vertex in vertices:
            if axis == "x":
                vertex.y = 2*cy - vertex.y
            else:
                vertex.x = 2*cx - vertex.x
        for arc in data["arcs"]:
            arc.v_start, arc.v_end = arc.v_end, arc.v_start
        for constraint in data["constraints"]:
            if isinstance(constraint, CDimension) and isinstance(constraint.target, tuple):
                if (axis == "x" and constraint.orient == "V") or \
                        (axis == "y" and constraint.orient == "H"):
                    constraint.sign *= -1
            elif isinstance(constraint, CDistance):
                if constraint.pair == "vv":
                    if (axis == "x" and constraint.orient == "V") or \
                            (axis == "y" and constraint.orient == "H"):
                        constraint.sign *= -1
                elif constraint.pair == "vs" or \
                        (constraint.pair == "ss" and constraint.mode == "distance"):
                    constraint.sign *= -1
                elif constraint.pair == "cs":
                    constraint.circle_side *= -1
                elif constraint.pair == "ss" and constraint.mode == "angle":
                    if constraint.angle_sides is not None:
                        constraint.sign *= -1
                    else:
                        constraint.value = 180.0 - constraint.value
            elif isinstance(constraint, CTangential) and (
                    isinstance(constraint.entity_a, Segment) or
                    isinstance(constraint.entity_b, Segment)):
                constraint.side *= -1

    def insert(self, data, dx=0.0, dy=0.0):
        """Insert an extracted clipboard snapshot, offsetting it by (dx, dy)."""
        vertex_map = {v: Vertex(v.x + dx, v.y + dy, v.locked) for v in data["vertices"]}
        inserted = {
            "vertices": list(vertex_map.values()),
            "segments": [Segment(vertex_map[s.v0], vertex_map[s.v1], s.construction)
                         for s in data["segments"]],
            "circles": [Circle(vertex_map[c.center], c.radius, c.construction)
                        for c in data["circles"]],
            "arcs": [Arc(vertex_map[a.center], vertex_map[a.v_start], vertex_map[a.v_end],
                         a.construction) for a in data["arcs"]],
            "points": [vertex_map[v] for v in data["points"]],
            "text_groups": [],
            "constraints": [],
        }
        object_map = dict(vertex_map)
        object_map.update(zip(data["segments"], inserted["segments"]))
        object_map.update(zip(data["circles"], inserted["circles"]))
        object_map.update(zip(data["arcs"], inserted["arcs"]))
        for group in data["text_groups"]:
            inserted["text_groups"].append(SketchText(
                group.label, [object_map[s] for s in group.segments],
                box_vertices=[vertex_map[v] for v in group.box_vertices],
                font_family=group.font_family, font_size=group.font_size,
                bold=group.bold, italic=group.italic, underline=group.underline,
                align=group.align))
        for constraint in data["constraints"]:
            copied = type(constraint).__new__(type(constraint))
            for name, value in constraint.__dict__.items():
                setattr(copied, name, self._remap_clip_value(value, object_map))
            inserted["constraints"].append(copied)
        self.vertices.extend(inserted["vertices"])
        self.segments.extend(inserted["segments"])
        self.circles.extend(inserted["circles"])
        self.arcs.extend(inserted["arcs"])
        self.points_free.extend(inserted["points"])
        self.text_groups.extend(inserted["text_groups"])
        self.constraints.extend(inserted["constraints"])
        self._an_key = None; self._an = None
        return inserted

    def _solve_with(self, system, prefer_lock=()):
        X = system.pack()
        if prefer_lock:
            idx = system.indices_of(prefer_lock)
            if idx:
                ok, X2 = system.solve(X, heavy=idx)
                if ok:
                    # Preserve variables that barely moved, then solve with them held.
                    still = [j for j in idx if abs(X2[j] - X[j]) < 1e-3]
                    if still:
                        X3 = list(X2)
                        for j in still:
                            X3[j] = X[j]
                        ok3, X3 = system.solve(X3, still)
                        if ok3:
                            X2 = X3
                if ok:
                    system.unpack(X2)
                    return True
        ok, X2 = system.solve(X)
        if ok:
            system.unpack(X2)
        return ok

    def solve(self, prefer_lock=()):
        return self._solve_with(SketchSystem(self), prefer_lock)

    def try_add_constraint(self, c, prefer_lock=()):
        """Add c only if it removes at least one DOF (i.e. is not redundant / dependent on
        existing constraints) and can be satisfied. Returns (ok, message)."""
        if isinstance(c, CDistance) and not c.driving:
            self.constraints.append(c)            # information only: never constrains
            return True, "information only"
        r0 = SketchSystem(self).rank()
        self.constraints.append(c)
        system = SketchSystem(self)
        r1 = system.rank()
        if r1 <= r0:
            self.constraints.remove(c)
            return False, "redundant — already defined by other constraints (over-constrained)"
        if not self._solve_with(system, prefer_lock):
            self.constraints.remove(c)
            return False, "conflicts with existing constraints"
        rows = len(system.rows_of(c))
        return True, ("partially redundant" if r1 - r0 < rows else "")

    def remove_constraint(self, c):
        if c in self.constraints: self.constraints.remove(c)

    def set_dimension_value(self, c, value, dim_mode=None):
        """Change a driving dimension; reverts and returns False if it cannot be satisfied."""
        old = (c.value, c.dim_mode)
        c.value = value
        if dim_mode: c.dim_mode = dim_mode
        prefer_lock = (c.a.v0, c.a.v1) if isinstance(c, CDistance) and c.mode == "angle" \
            and c.pair == "ss" else ()
        if self.solve(prefer_lock=prefer_lock): return True
        c.value, c.dim_mode = old
        return False

    def drag(self, moves):
        """Move vertices toward targets {vertex: (x,y)} while honouring all constraints.
        First the dragged vertices are held at their targets and the rest follows; if that
        is impossible, the nearest valid configuration is used (vertex slides / stays)."""
        snap = {v: (v.x, v.y) for v in self.vertices}
        rad  = {c: c.radius for c in self.circles}
        for v, (x, y) in moves.items():
            if not v.locked: v.x, v.y = x, y
        system = SketchSystem(self); X = system.pack()
        ok, X2 = system.solve(X, system.indices_of(moves.keys()))
        if not ok: ok, X2 = system.solve(X)
        if ok:
            system.unpack(X2); return True
        for v, (x, y) in snap.items(): v.x, v.y = x, y
        for c, r in rad.items(): c.radius = r
        return False

    def analysis(self):
        key = (tuple((id(v), v.x, v.y) for v in self.vertices),
               tuple((id(c), id(c.center), c.radius, c.construction) for c in self.circles),
               tuple((id(s.v0), id(s.v1), s.construction) for s in self.segments),
               tuple((id(a.center), id(a.v_start), id(a.v_end), a.construction)
                     for a in self.arcs),
               tuple((tuple(id(v) for v in ellipse.vertices()), ellipse.construction)
                   for ellipse in self.ellipses),
               tuple((id(c), getattr(c, "value", None), getattr(c, "dim_mode", None),
                      getattr(c, "mode", None)) for c in self.constraints),
               tuple(id(p) for p in self.points_free))
        if key != self._an_key:
            self._an = SketchSystem(self).analyse(); self._an_key = key
        return self._an

    # ── status ───────────────────────────────────────────────────────────────
    def total_dof(self):
        """Remaining DOF of the profile geometry (support geometry and points are optional)."""
        return self.analysis()["dof"]

    def optional_dof(self):
        """Remaining DOF that only affect support geometry / points (informational)."""
        an = self.analysis(); return max(0, an["dof_all"] - an["dof"])

    def blocking_issues(self):
        """Issues that prevent accepting the sketch."""
        return [] if self.profile_closed() else ["Profile not closed"]

    def open_issues(self):
        issues = self.blocking_issues()
        dof = self.total_dof()
        if dof > 0:
            issues.append(f"{dof} DOF remaining (accept still allowed)")
            if not any(isinstance(c, CFixed) for c in self.constraints) and \
               not any(v.locked for v in self.vertices):
                issues.append("Tip: fix one vertex to anchor position")
        return issues

    def points(self):
        return [s.v0.xy() for s in self.segments]

# ── geometry helpers ──────────────────────────────────────────────────────────
CURVE_CHORD_TOL = 0.005    # mm — max. deviation of a tessellated circle / arc from the true curve

def curve_segments(r, sweep=2*math.pi, lo=32, hi=256):
    """Segment count keeping the chord error below CURVE_CHORD_TOL (scaled to the sweep)."""
    frac = sweep/(2*math.pi)
    if r <= CURVE_CHORD_TOL: return max(4, int(math.ceil(lo*frac)))
    n = math.ceil(math.pi/math.acos(1.0 - CURVE_CHORD_TOL/r))
    return max(4, int(math.ceil(min(max(n, lo), hi)*frac)))

def circle_pts(cx, cy, r, n=None):
    if n is None: n = curve_segments(r)
    return [(cx+r*math.cos(2*math.pi*i/n), cy+r*math.sin(2*math.pi*i/n)) for i in range(n)]

def poly_area(pts):
    return 0.5*sum(pts[i][0]*pts[(i+1)%len(pts)][1]-pts[(i+1)%len(pts)][0]*pts[i][1]
                   for i in range(len(pts)))

def triangulate_polygon(pts):
    """Ear clipping for a simple CCW polygon; returns index triples."""
    def cross(o, a, b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    idx = list(range(len(pts))); tris = []
    while len(idx) > 3:
        m = len(idx)
        reflex = [idx[k] for k in range(m)
                  if cross(pts[idx[k-1]], pts[idx[k]], pts[idx[(k+1)%m]]) < 0]
        for k in range(m):
            i0, i1, i2 = idx[k-1], idx[k], idx[(k+1)%m]
            a, b, c = pts[i0], pts[i1], pts[i2]
            cr = cross(a, b, c)
            if abs(cr) < 1e-12:            # collinear / duplicate vertex: drop it
                idx.pop(k); break
            if cr < 0: continue
            if any(j not in (i0, i1, i2) and cross(a, b, pts[j]) >= 0 and
                   cross(b, c, pts[j]) >= 0 and cross(c, a, pts[j]) >= 0 for j in reflex):
                continue
            tris.append((i0, i1, i2)); idx.pop(k); break
        else:
            # no ear found (self-intersecting input) → fan the remainder
            tris += [(idx[0], idx[k], idx[k+1]) for k in range(1, len(idx)-1)]
            return tris
    if len(idx) == 3: tris.append(tuple(idx))
    return tris

def _face_boundary_loop(entry, face_index):
    """Return the vertex ids around the single closed boundary of a triangulated face."""
    face = entry["faces"][face_index]
    triangles = entry["solid"][1]
    edge_counts = {}
    for tri_index in face.get("tris", []):
        a, b, c = triangles[tri_index]
        for start, end in ((a, b), (b, c), (c, a)):
            edge = (min(start, end), max(start, end))
            edge_counts[edge] = edge_counts.get(edge, 0) + 1
    boundary = [edge for edge, count in edge_counts.items() if count == 1]
    if not boundary:
        return []
    adjacent = {}
    for a, b in boundary:
        adjacent.setdefault(a, []).append(b)
        adjacent.setdefault(b, []).append(a)
    if len(boundary) < 3 or any(len(neighbors) != 2 for neighbors in adjacent.values()):
        raise ValueError("Each selected face must have one simple closed boundary.")
    if not adjacent:
        raise ValueError("The selected face has no boundary.")
    loop = [min(adjacent)]
    previous = None
    while True:
        current = loop[-1]
        next_vertex = next(vertex for vertex in adjacent[current] if vertex != previous)
        if next_vertex == loop[0]:
            break
        if next_vertex in loop:
            raise ValueError("Each selected face must have one simple closed boundary.")
        loop.append(next_vertex)
        previous, current = current, next_vertex
    if len(loop) != len(adjacent):
        raise ValueError("Faces with holes or multiple boundaries cannot be bridged.")
    return loop

def _bridge_face_frame(entry, face_index, loop):
    """Estimate an outward frame and boundary vertex normals for a planar or curved face."""
    face = entry["faces"][face_index]
    if face.get("planar") and "frame" in face:
        origin, u, v, normal = (np.asarray(axis, dtype=float) for axis in face["frame"])
        normal = _unit(normal)
        u = _unit(u)
        v = _unit(np.cross(normal, u))
        if float(v @ np.asarray(face["frame"][2], dtype=float)) < 0:
            v = -v
        return origin, u, v, normal, [normal.copy() for _ in loop]

    vertices = np.asarray(entry["solid"][0], dtype=float)
    triangles = np.asarray(entry["solid"][1], dtype=int)
    face_triangles = np.asarray(face.get("tris", []), dtype=int)
    if not len(face_triangles):
        raise ValueError("The selected curved face has no triangles.")
    selected = triangles[face_triangles]
    tri_points = vertices[selected]
    tri_normals = np.cross(tri_points[:, 1] - tri_points[:, 0],
                           tri_points[:, 2] - tri_points[:, 0])
    face_normal = _unit(np.sum(tri_normals, axis=0))
    if np.linalg.norm(face_normal) < 1e-9:
        raise ValueError("Could not determine the selected curved face normal.")
    center = tri_points.reshape(-1, 3).mean(axis=0)
    reference = np.array((1.0, 0.0, 0.0)) if abs(face_normal[0]) < 0.9 \
        else np.array((0.0, 1.0, 0.0))
    u = _unit(np.cross(reference, face_normal))
    v = _unit(np.cross(face_normal, u))

    vertex_normals = {}
    for tri, tri_normal in zip(selected, tri_normals):
        for vertex_id in tri:
            vertex_normals[vertex_id] = vertex_normals.get(vertex_id, np.zeros(3)) + tri_normal
    normals = []
    for vertex_id in loop:
        normal = _unit(vertex_normals.get(vertex_id, face_normal))
        if float(normal @ face_normal) < 0:
            normal = -normal
        normals.append(normal)
    return center, u, v, face_normal, normals

def _resample_bridge_loop(points, normals, count):
    """Resample a closed face outline evenly while interpolating its local normals."""
    lengths = [float(np.linalg.norm(points[(i + 1) % len(points)] - points[i]))
               for i in range(len(points))]
    perimeter = sum(lengths)
    if perimeter < 1e-9:
        raise ValueError("A selected face boundary has zero length.")
    cumulative = np.cumsum([0.0] + lengths)
    sampled_points, sampled_normals = [], []
    for distance in np.linspace(0.0, perimeter, count, endpoint=False):
        edge = min(int(np.searchsorted(cumulative, distance, side="right") - 1),
                   len(points) - 1)
        fraction = (distance - cumulative[edge]) / max(lengths[edge], 1e-12)
        next_index = (edge + 1) % len(points)
        sampled_points.append(points[edge] * (1 - fraction) + points[next_index] * fraction)
        normal = normals[edge] * (1 - fraction) + normals[next_index] * fraction
        sampled_normals.append(_unit(normal))
    return sampled_points, sampled_normals

def _simplify_bridge_loop(vertices, ids):
    """Drop boundary vertices lying on a straight run (e.g. the extra vertices the fusing of
    bodies inserts into face edges), so the corners of a face stay corners when the boundary
    is resampled."""
    ids = list(ids)
    changed = True
    while changed and len(ids) > 3:
        changed = False
        for position in range(len(ids)):
            before = np.asarray(vertices[ids[position - 1]], dtype=float)
            here = np.asarray(vertices[ids[position]], dtype=float)
            after = np.asarray(vertices[ids[(position + 1) % len(ids)]], dtype=float)
            incoming, outgoing = here - before, after - here
            lengths = float(np.linalg.norm(incoming) * np.linalg.norm(outgoing))
            if lengths < 1e-12:
                straight = True
            else:
                straight = float(np.linalg.norm(np.cross(incoming, outgoing))) / lengths < 1e-4 \
                    and float(incoming @ outgoing) > 0
            if straight:
                del ids[position]
                changed = True
                break
    return ids

def _bridge_faces(entry_a, face_index_a, entry_b, face_index_b):
    """Build a closed bridge between two facing face boundaries."""
    if entry_a is entry_b and face_index_a == face_index_b:
        raise ValueError("Select two different faces.")
    try:
        ids_a = _simplify_bridge_loop(entry_a["solid"][0], _face_boundary_loop(entry_a, face_index_a))
    except ValueError:
        ids_a = []
    try:
        ids_b = _simplify_bridge_loop(entry_b["solid"][0], _face_boundary_loop(entry_b, face_index_b))
    except ValueError:
        ids_b = []
    if not ids_a and ids_b:
        entry_a, entry_b = entry_b, entry_a
        face_index_a, face_index_b = face_index_b, face_index_a
        ids_a, ids_b = ids_b, ids_a
    if not ids_a:
        raise ValueError("At least one selected face needs a simple closed boundary.")
    if len(ids_a) < 3 or (ids_b and len(ids_b) < 3):
        raise ValueError("The selected faces need at least three boundary points.")
    if not ids_b:       # projected bridge: keep every outline vertex so face A's triangles fit
        ids_a = _face_boundary_loop(entry_a, face_index_a)

    points_a = [np.asarray(entry_a["solid"][0][index], dtype=float) for index in ids_a]
    frame_a = _bridge_face_frame(entry_a, face_index_a, ids_a)
    center_a = np.mean(points_a, axis=0)
    normal_a = frame_a[3]
    if ids_b:
        points_b = [np.asarray(entry_b["solid"][0][index], dtype=float) for index in ids_b]
        frame_b = _bridge_face_frame(entry_b, face_index_b, ids_b)
        normals_b = frame_b[4]
    else:
        target_face = entry_b["faces"][face_index_b]
        target_triangles = np.asarray(entry_b["solid"][1], dtype=int)[
            np.asarray(target_face.get("tris", []), dtype=int)]
        if not len(target_triangles):
            raise ValueError("The selected target face has no triangles.")
        target_vertices = np.asarray(entry_b["solid"][0], dtype=float)
        target_center = target_vertices[np.unique(target_triangles)].mean(axis=0)
        target_direction = _unit(normal_a)
        hit_distance = _ray_nearest(points_a, target_direction, target_vertices, target_triangles)
        if not np.isfinite(hit_distance).all():
            reverse_direction = -target_direction
            reverse_hits = _ray_nearest(
                points_a, reverse_direction, target_vertices, target_triangles)
            if np.isfinite(reverse_hits).all() and \
                    float(reverse_direction @ (target_center - center_a)) > \
                    float(target_direction @ (target_center - center_a)):
                target_direction, hit_distance = reverse_direction, reverse_hits
        if not np.isfinite(hit_distance).all():
            raise ValueError("The boundary does not reach the selected closed surface.")
        points_b = [point + target_direction * distance
                    for point, distance in zip(points_a, hit_distance)]
        normal_b = -target_direction
        reference = np.array((1.0, 0.0, 0.0)) if abs(normal_b[0]) < 0.9 \
            else np.array((0.0, 1.0, 0.0))
        target_u = _unit(np.cross(reference, normal_b))
        target_v = _unit(np.cross(normal_b, target_u))
        frame_b = (np.mean(points_b, axis=0), target_u, target_v, normal_b,
                   [normal_b.copy() for _ in points_b])
        normals_b = frame_b[4]
    center_b = np.mean(points_b, axis=0)
    normal_b = frame_b[3]
    direction = center_b - center_a
    distance = float(np.linalg.norm(direction))
    if distance < 1e-4:
        raise ValueError("The selected face centers are too close to bridge.")
    direction /= distance
    if float(normal_a @ normal_b) > -0.8 or \
            float(normal_a @ direction) < 0.2 or float(-normal_b @ direction) < 0.2:
        raise ValueError("Select two faces that face each other across the gap.")

    projected = not ids_b
    if projected:
        # the target loop is the projection of the source loop: keep the exact face outline,
        # resampling would leave slivers of the source face exposed around the bridge
        count = len(points_a)
        normals_a = [np.asarray(normal, dtype=float) for normal in frame_a[4]]
        normals_b = list(normals_b)
    else:
        count = min(max(len(points_a), len(points_b)), 256)
        points_a, normals_a = _resample_bridge_loop(points_a, frame_a[4], count)
        points_b, normals_b = _resample_bridge_loop(points_b, normals_b, count)

        best = None
        for reverse in (False, True):
            candidate = points_b if not reverse else list(reversed(points_b))
            for shift in range(len(candidate)):
                aligned = candidate[shift:] + candidate[:shift]
                score = sum(float(np.dot(a - b, a - b)) for a, b in zip(points_a, aligned))
                if best is None or score < best[0]:
                    best = (score, aligned, reverse, shift)
        _, points_b, reverse, shift = best
        if reverse:
            normals_b.reverse()
        normals_b = normals_b[shift:] + normals_b[:shift]
    frame_u, frame_v = frame_a[1], frame_a[2]
    projected_a = [((point - center_a) @ frame_u, (point - center_a) @ frame_v)
                   for point in points_a]
    if poly_area(projected_a) * float(np.cross(frame_u, frame_v) @ normal_a) < 0:
        ids_a = list(reversed(ids_a))
        points_a.reverse()
        points_b.reverse()
        normals_a.reverse()
        normals_b.reverse()

    inset = min(0.02, distance * 0.01)
    # a projected bridge starts flush on face A (an inset would poke out of curved bodies)
    loop_a = list(points_a) if projected else \
        [point - normal * inset for point, normal in zip(points_a, normals_a)]
    loop_b = [point - normal * inset for point, normal in zip(points_b, normals_b)]
    vertices = [point.tolist() for point in loop_a + loop_b]
    triangles = []
    faces = []

    def add_face(kind, indices, boundary_indices, normal, frame, planar=True):
        start = len(triangles)
        for tri in indices:
            a, b, c = (np.asarray(vertices[index], dtype=float) for index in tri)
            if float(np.cross(b - a, c - a) @ normal) < 0:
                tri = (tri[0], tri[2], tri[1])
            triangles.append(tuple(tri))
        boundary_points = [vertices[index] for index in boundary_indices]
        boundary = [["line", boundary_points[i], boundary_points[(i + 1) % len(boundary_points)]]
                    for i in range(len(boundary_points))]
        record = {"kind": kind, "tris": list(range(start, len(triangles))),
                  "planar": planar}
        if planar:
            record["frame"] = [np.asarray(axis, dtype=float).tolist() for axis in frame]
            record["boundary"] = boundary
        faces.append(record)

    def cap_triangles(points, frame, offset):
        origin, u, v, _ = (np.asarray(axis, dtype=float) for axis in frame)
        projected = [((point - origin) @ u, (point - origin) @ v) for point in points]
        if poly_area(projected) < 0:
            projected.reverse()
            mapped = list(reversed(range(len(points))))
        else:
            mapped = list(range(len(points)))
        return [tuple(offset + mapped[index] for index in tri)
                for tri in triangulate_polygon(projected)]

    desired_a, desired_b = -direction, direction
    face_frame_a = [frame_a[0], frame_a[1], frame_a[2], frame_a[3]]
    face_frame_b = [frame_b[0], frame_b[1], frame_b[2], frame_b[3]]
    bridge_frame_a = [loop_a[0], frame_a[1], _unit(np.cross(desired_a, frame_a[1])), desired_a]
    bridge_frame_b = [loop_b[0], frame_b[1], _unit(np.cross(desired_b, frame_b[1])), desired_b]
    if projected:
        # face A's own triangles (reversed by add_face) cancel exactly against face A in the union
        index_of = {vertex_id: position for position, vertex_id in enumerate(ids_a)}
        source_vertices = entry_a["solid"][0]
        cap_a = []
        for tri in np.asarray(entry_a["solid"][1], dtype=int)[
                np.asarray(entry_a["faces"][face_index_a]["tris"], dtype=int)].tolist():
            for vertex_id in tri:
                if vertex_id not in index_of:
                    index_of[vertex_id] = len(vertices)
                    vertices.append([float(x) for x in source_vertices[vertex_id]])
            cap_a.append(tuple(index_of[vertex_id] for vertex_id in tri))
    else:
        cap_a = cap_triangles(loop_a, face_frame_a, 0)
    add_face("bridge end", cap_a, list(range(count)), desired_a, bridge_frame_a)
    add_face("bridge end", cap_triangles(loop_b, face_frame_b, count),
             list(range(count, 2 * count)), desired_b, bridge_frame_b)

    quads = []
    for index in range(count):
        following = (index + 1) % count
        quad = (index, following, count + following, count + index)
        side_tris = [(quad[0], quad[1], quad[2]), (quad[0], quad[2], quad[3])]
        points = [np.asarray(vertices[i], dtype=float) for i in quad]
        side_normal = np.cross(points[1] - points[0], points[2] - points[0])
        sweep = ((points[3] - points[0]) + (points[2] - points[1])) / 2.0
        expected_normal = np.cross(points[1] - points[0], sweep)
        if float(side_normal @ expected_normal) < 0:
            side_tris = [(a, c, b) for a, b, c in side_tris]
            side_normal = -side_normal
        side_normal = _unit(side_normal)
        planar = abs(float((points[3] - points[0]) @ side_normal)) < 1e-5
        quads.append((side_tris, side_normal, planar))

    # one side face per smooth run of quads (a round bridge gets one curved face, no seams)
    smooth = math.cos(math.radians(30.0))
    creases = [i for i in range(count) if float(quads[i - 1][1] @ quads[i][1]) < smooth]
    groups = [[(c + k) % count for k in range((creases[(j + 1) % len(creases)] - c) % count or count)]
              for j, c in enumerate(creases)] if creases else [list(range(count))]
    for group in groups:
        normal = quads[group[0]][1]
        flat = len(group) < count and all(quads[i][2] and float(normal @ quads[i][1]) > 1 - 1e-9
                                          for i in group)
        start = len(triangles)
        for i in group:
            triangles.extend(tuple(tri) for tri in quads[i][0])
        record = {"kind": "bridge side", "tris": list(range(start, len(triangles))), "planar": flat}
        if flat:
            last = (group[-1] + 1) % count
            ids = group + [last, count + last] + [count + i for i in reversed(group)]
            corner = np.asarray(vertices[group[0]], dtype=float)
            side_u = _unit(np.asarray(vertices[last], dtype=float) - corner)
            record["frame"] = [corner.tolist(), side_u.tolist(),
                               np.cross(normal, side_u).tolist(), normal.tolist()]
            record["boundary"] = [["line", vertices[ids[i]], vertices[ids[(i + 1) % len(ids)]]]
                                  for i in range(len(ids))]
        faces.append(record)

    if not _mesh_is_closed(triangles) or abs(mesh_volume(vertices, triangles)) < 1e-9:
        raise ValueError("The selected face boundaries do not form a valid bridge.")
    return vertices, triangles, faces

def _opposing_bridge_face_pairs(entry_a, entry_b):
    """Return boundary-to-opposing or boundary-to-surface pairs, nearest first."""
    faces_a = []
    for face_index, face in enumerate(entry_a.get("faces", [])):
        if not face.get("tris"):
            continue
        try:
            loop = _face_boundary_loop(entry_a, face_index)
            if len(loop) < 3:
                continue
            points = np.asarray([entry_a["solid"][0][index] for index in loop], dtype=float)
            frame = _bridge_face_frame(entry_a, face_index, loop)
            faces_a.append((face_index, points.mean(axis=0), frame[3]))
        except (ValueError, IndexError):
            continue

    faces_b = []
    for face_index, face in enumerate(entry_b.get("faces", [])):
        if not face.get("tris"):
            continue
        try:
            loop = _face_boundary_loop(entry_b, face_index)
            if len(loop) >= 3:
                points = np.asarray([entry_b["solid"][0][index] for index in loop], dtype=float)
                frame = _bridge_face_frame(entry_b, face_index, loop)
                faces_b.append((face_index, points.mean(axis=0), frame[3], True))
                continue
        except (ValueError, IndexError):
            pass
        triangles = np.asarray(entry_b["solid"][1], dtype=int)[
            np.asarray(face.get("tris", []), dtype=int)]
        if not len(triangles):
            continue
        vertices = np.asarray(entry_b["solid"][0], dtype=float)
        points = vertices[np.unique(triangles)]
        faces_b.append((face_index, points.mean(axis=0), None, False))

    pairs = []
    for face_a, center_a, normal_a in faces_a:
        for face_b, center_b, normal_b, has_boundary in faces_b:
            direction = center_b - center_a
            distance = float(np.linalg.norm(direction))
            if distance < 1e-4:
                continue
            direction /= distance
            faces_opposed = has_boundary and float(normal_a @ normal_b) <= -0.8 and \
                float(-normal_b @ direction) >= 0.2
            faces_toward_target = not has_boundary and float(normal_a @ direction) >= 0.2
            if float(normal_a @ direction) >= 0.2 and (faces_opposed or faces_toward_target):
                pairs.append((distance, face_a, face_b))
    return [(face_a, face_b) for _, face_a, face_b in sorted(pairs)]

def _pt_in_poly(pt, poly):
    """Ray-cast point-in-polygon test (2-D)."""
    x, y = pt; n = len(poly); inside = False
    j = n - 1
    for i in range(n):
        xi, yi = poly[i]; xj, yj = poly[j]
        if ((yi > y) != (yj > y)) and (x < (xj-xi)*(y-yi)/(yj-yi+1e-12) + xi):
            inside = not inside
        j = i
    return inside

def _bridge_hole(outer, hole):
    """Merge a CW hole into a CCW outer polygon via a bridge edge.
    Finds the rightmost hole vertex and the visible outer vertex to its right.
    Returns a single merged polygon (list of pts) with duplicated bridge vertices."""
    # find rightmost hole vertex
    hi = max(range(len(hole)), key=lambda i: hole[i][0])
    M = hole[hi]
    # find the outer vertex that is visible from M (rightmost intersection)
    best_x, best_oi = -math.inf, 0
    for oi in range(len(outer)):
        a, b = outer[oi], outer[(oi+1) % len(outer)]
        # does the ray M→+x cross edge a→b?
        if abs(b[1]-a[1]) < 1e-12: continue
        t = (M[1]-a[1])/(b[1]-a[1])
        if not (0.0 <= t <= 1.0): continue
        ix = a[0] + t*(b[0]-a[0])
        if ix >= M[0] and ix > best_x:
            best_x = ix; best_oi = oi
    # pick the vertex at best_oi or best_oi+1 that is more to the right
    oi1 = (best_oi+1) % len(outer)
    oi = oi1 if outer[oi1][0] > outer[best_oi][0] else best_oi
    # build merged polygon: outer[0..oi] + bridge + hole[hi..] + hole[..hi] + bridge back
    merged = list(outer[:oi+1])
    merged += [hole[(hi+k) % len(hole)] for k in range(len(hole))]
    merged += [hole[hi], outer[oi]]
    merged += list(outer[oi+1:])
    return merged

class _EcNode:
    __slots__ = ("i", "x", "y", "prev", "next", "steiner")
    def __init__(self, i, x, y):
        self.i = i; self.x = x; self.y = y; self.prev = self.next = None; self.steiner = False

def _ec_area(p, q, r): return (q.y - p.y)*(r.x - q.x) - (q.x - p.x)*(r.y - q.y)
def _ec_eq(a, b): return a.x == b.x and a.y == b.y
def _ec_pit(ax, ay, bx, by, cx, cy, px, py):
    return ((cx-px)*(ay-py) >= (ax-px)*(cy-py) and (ax-px)*(by-py) >= (bx-px)*(ay-py)
            and (bx-px)*(cy-py) >= (cx-px)*(by-py))
def _ec_remove(p): p.next.prev = p.prev; p.prev.next = p.next
def _ec_sign(v): return (v > 0) - (v < 0)
def _ec_on_seg(p, q, r):
    return min(p.x, r.x) <= q.x <= max(p.x, r.x) and min(p.y, r.y) <= q.y <= max(p.y, r.y)
def _ec_intersects(p1, q1, p2, q2):
    o1 = _ec_sign(_ec_area(p1, q1, p2)); o2 = _ec_sign(_ec_area(p1, q1, q2))
    o3 = _ec_sign(_ec_area(p2, q2, p1)); o4 = _ec_sign(_ec_area(p2, q2, q1))
    if o1 != o2 and o3 != o4: return True
    return ((o1 == 0 and _ec_on_seg(p1, p2, q1)) or (o2 == 0 and _ec_on_seg(p1, q2, q1)) or
            (o3 == 0 and _ec_on_seg(p2, p1, q2)) or (o4 == 0 and _ec_on_seg(p2, q1, q2)))
def _ec_local_inside(a, b):
    if _ec_area(a.prev, a, a.next) < 0:
        return _ec_area(a, b, a.next) >= 0 and _ec_area(a, a.prev, b) >= 0
    return _ec_area(a, b, a.prev) < 0 or _ec_area(a, a.next, b) < 0
def _ec_middle_inside(a, b):
    p = a; inside = False; px = (a.x + b.x)/2; py = (a.y + b.y)/2
    while True:
        if ((p.y > py) != (p.next.y > py)) and p.next.y != p.y and \
           px < (p.next.x - p.x)*(py - p.y)/(p.next.y - p.y) + p.x:
            inside = not inside
        p = p.next
        if p is a: return inside
def _ec_intersects_poly(a, b):
    p = a
    while True:
        if p.i != a.i and p.next.i != a.i and p.i != b.i and p.next.i != b.i and \
           _ec_intersects(p, p.next, a, b): return True
        p = p.next
        if p is a: return False
def _ec_valid_diagonal(a, b):
    return (a.next.i != b.i and a.prev.i != b.i and not _ec_intersects_poly(a, b) and
            ((_ec_local_inside(a, b) and _ec_local_inside(b, a) and _ec_middle_inside(a, b) and
              (_ec_area(a.prev, a, b.prev) != 0 or _ec_area(a, b.prev, b) != 0)) or
             (_ec_eq(a, b) and _ec_area(a.prev, a, a.next) > 0 and _ec_area(b.prev, b, b.next) > 0)))
def _ec_split(a, b):
    a2 = _EcNode(a.i, a.x, a.y); b2 = _EcNode(b.i, b.x, b.y)
    an = a.next; bp = b.prev
    a.next = b; b.prev = a; a2.next = an; an.prev = a2
    b2.next = a2; a2.prev = b2; bp.next = b2; b2.prev = bp
    return b2
def _ec_filter(start, end=None):
    if start is None: return None
    if end is None: end = start
    p = start
    while True:
        again = False
        if not p.steiner and (_ec_eq(p, p.next) or _ec_area(p.prev, p, p.next) == 0):
            _ec_remove(p); p = end = p.prev
            if p is p.next: break
            again = True
        else:
            p = p.next
        if not again and p is end: break
    return end
def _ec_is_ear(ear):
    a, b, c = ear.prev, ear, ear.next
    if _ec_area(a, b, c) >= 0: return False
    min_x = min(a.x, b.x, c.x); max_x = max(a.x, b.x, c.x)
    min_y = min(a.y, b.y, c.y); max_y = max(a.y, b.y, c.y)
    p = c.next
    while p is not a:
        if min_x <= p.x <= max_x and min_y <= p.y <= max_y and \
           _ec_pit(a.x, a.y, b.x, b.y, c.x, c.y, p.x, p.y) and \
           _ec_area(p.prev, p, p.next) >= 0:
            return False
        p = p.next
    return True
def _ec_cure(start, out):
    p = start
    while True:
        a = p.prev; b = p.next.next
        if not _ec_eq(a, b) and _ec_intersects(a, p, p.next, b) and \
           _ec_local_inside(a, b) and _ec_local_inside(b, a):
            out.append((a.i, p.i, b.i)); _ec_remove(p); _ec_remove(p.next); p = start = b
        p = p.next
        if p is start: return _ec_filter(p)
def _ec_split_earcut(start, out):
    a = start
    while True:
        b = a.next.next
        while b is not a.prev:
            if a.i != b.i and _ec_valid_diagonal(a, b):
                c = _ec_split(a, b)
                a = _ec_filter(a, a.next); c = _ec_filter(c, c.next)
                _ec_linked(a, out, 0); _ec_linked(c, out, 0)
                return
            b = b.next
        a = a.next
        if a is start: return
def _ec_linked(ear, out, pas):
    if ear is None: return
    stop = ear
    while ear.prev is not ear.next:
        prev, nxt = ear.prev, ear.next
        if _ec_is_ear(ear):
            out.append((prev.i, ear.i, nxt.i)); _ec_remove(ear)
            ear = stop = nxt.next; continue
        ear = nxt
        if ear is stop:
            if pas == 0: _ec_linked(_ec_filter(ear), out, 1)
            elif pas == 1:
                ear = _ec_cure(_ec_filter(ear), out); _ec_linked(ear, out, 2)
            else: _ec_split_earcut(ear, out)
            break
def _ec_ring(pts, base):
    """Circular doubly linked list of the points (outer ring CCW, holes CW for y up)."""
    last = None; first = None
    for k in range(len(pts)):
        n = _EcNode(base + k, pts[k][0], pts[k][1])
        if last is None: first = n
        else: n.prev = last; last.next = n
        last = n
    last.next = first; first.prev = last
    if _ec_eq(first, first.prev): _ec_remove(first); first = first.next
    return first
def _ec_bridge(hole, outer):
    p = outer; hx, hy = hole.x, hole.y; qx = -math.inf; m = None
    if _ec_eq(hole, p): return p
    while True:
        if _ec_eq(hole, p.next): return p.next
        if hy <= p.y and hy >= p.next.y and p.next.y != p.y:
            x = p.x + (hy - p.y)*(p.next.x - p.x)/(p.next.y - p.y)
            if x <= hx and x > qx:
                qx = x; m = p if p.x < p.next.x else p.next
                if x == hx: return m
        p = p.next
        if p is outer: break
    if m is None: return None
    stop = m; mx, my = m.x, m.y; tan_min = math.inf; p = m
    while True:
        if hx >= p.x >= mx and hx != p.x and _ec_pit(hx if hy < my else qx, hy, mx, my,
                                                      qx if hy < my else hx, hy, p.x, p.y):
            tn = abs(hy - p.y)/(hx - p.x)
            if _ec_local_inside(p, hole) and (tn < tan_min or (tn == tan_min and (
                    p.x > m.x or (p.x == m.x and _ec_area(m.prev, m, p.prev) < 0 and
                                  _ec_area(p.next, m, m.next) < 0)))):
                m = p; tan_min = tn
        p = p.next
        if p is stop: return m

@lru_cache(maxsize=16)
def _triangulate_profile_cached(outer, holes):
    if not holes:
        return tuple(triangulate_polygon(outer)), outer
    pts = list(outer); starts = []
    for h in holes: starts.append(len(pts)); pts += list(h)
    outer_node = _ec_ring(outer, 0)
    queue = []
    for s, h in zip(starts, holes):
        ring = _ec_ring(h, s)
        if ring is ring.next: ring.steiner = True
        left = ring; p = ring.next
        while p is not ring:
            if p.x < left.x or (p.x == left.x and p.y < left.y): left = p
            p = p.next
        queue.append(left)
    queue.sort(key=lambda n: n.x)
    for hole in queue:
        bridge = _ec_bridge(hole, outer_node)
        if bridge is None: continue
        rev = _ec_split(bridge, hole)
        _ec_filter(rev, rev.next)
        outer_node = _ec_filter(bridge, bridge.next)
    out = []
    _ec_linked(_ec_filter(outer_node), out, 0)
    return tuple(out), tuple(pts)

def triangulate_with_holes(outer, holes):
    """Triangulate a CCW outer polygon with zero or more CW hole polygons (earcut).
    Returns (tris, pts): CCW index triples into pts (= the outer points followed by the
    hole points). Results are cached by profile coordinates for repeated extrusions."""
    outer_key = tuple((float(p[0]), float(p[1])) for p in outer)
    holes_key = tuple(tuple((float(p[0]), float(p[1])) for p in hole) for hole in holes)
    tris, pts = _triangulate_profile_cached(outer_key, holes_key)
    return list(tris), list(pts)

def _unit(a):
    a = np.asarray(a, float); n = np.linalg.norm(a)
    return a/n if n > 1e-12 else a

def standard_gear_outline(module, teeth, pressure_angle=20.0, samples_per_tooth=24):
    """Sample a standard full-depth external spur-gear outline in polar coordinates."""
    module = float(module); pressure_angle = float(pressure_angle)
    if not math.isfinite(module) or module <= 0:
        raise ValueError("Gear module must be a finite positive number.")
    if not isinstance(teeth, int) or teeth < 6:
        raise ValueError("An external spur gear requires at least 6 teeth.")
    if not math.isfinite(pressure_angle) or not 10.0 <= pressure_angle <= 45.0:
        raise ValueError("Pressure angle must be between 10° and 45°.")

    pitch_radius = module * teeth / 2.0
    base_radius = pitch_radius * math.cos(math.radians(pressure_angle))
    root_radius = pitch_radius - 1.25 * module
    outer_radius = pitch_radius + module
    if root_radius <= 0:
        raise ValueError("The gear root diameter must be positive.")
    pitch_angle = 2.0 * math.pi / teeth
    inv_pitch = math.tan(math.radians(pressure_angle)) - math.radians(pressure_angle)
    start_radius = max(root_radius, base_radius)

    def half_tooth_angle(radius):
        alpha = math.acos(min(1.0, base_radius / radius))
        return math.pi / (2.0 * teeth) + inv_pitch - (math.tan(alpha) - alpha)

    outer_half_angle = half_tooth_angle(outer_radius)
    start_half_angle = half_tooth_angle(start_radius)
    points = []
    for index in range(teeth * samples_per_tooth):
        angle = (index / samples_per_tooth - 0.5) * pitch_angle
        relative = (angle + 0.5 * pitch_angle) % pitch_angle - 0.5 * pitch_angle
        side_angle = abs(relative)
        if side_angle <= outer_half_angle:
            radius = outer_radius
        elif side_angle < start_half_angle:
            low, high = start_radius, outer_radius
            for _ in range(24):
                middle = (low + high) / 2.0
                if half_tooth_angle(middle) > side_angle:
                    low = middle
                else:
                    high = middle
            radius = (low + high) / 2.0
        else:
            radius = root_radius
        points.append((radius * math.cos(angle), radius * math.sin(angle)))
    return points, root_radius

def make_gear_sketch(name, parameters, frame=None):
    """Build the editable XY profile for a standard external gear."""
    teeth = int(parameters["teeth"])
    module = float(parameters["outside_diameter"]) / (teeth + 2)
    outline, root_radius = standard_gear_outline(
        module, teeth, float(parameters.get("pressure_angle", 20.0)))
    bore = float(parameters.get("bore_diameter", 0.0))
    if not math.isfinite(bore) or bore < 0 or bore >= 2.0 * root_radius:
        raise ValueError("Bore diameter must be zero or smaller than the gear root diameter.")
    sketch = Sketch("XY", name=name, frame=frame)
    vertices = [Vertex(x, y) for x, y in outline]
    sketch.vertices.extend(vertices)
    sketch.segments.extend(
        Segment(vertices[i], vertices[(i + 1) % len(vertices)])
        for i in range(len(vertices)))
    centerpoint = Vertex(0.0, 0.0, locked=True)
    sketch.vertices.append(centerpoint)
    sketch.points_free.append(centerpoint)
    if bore:
        sketch.circles.append(Circle(Vertex(0.0, 0.0), bore / 2.0))
    return sketch

def make_internal_gear_sketch(name, parameters, frame=None):
    """Build an annular ring gear with inward-facing involute teeth."""
    teeth = int(parameters["teeth"])
    outside_diameter = float(parameters["outside_diameter"])
    module = float(parameters.get("module", outside_diameter / (teeth + 7.5)))
    pressure_angle = float(parameters.get("pressure_angle", 20.0))
    if not math.isfinite(outside_diameter) or outside_diameter <= 0:
        raise ValueError("Ring outside diameter must be finite and positive.")
    if not math.isfinite(module) or module <= 0:
        raise ValueError("Ring gear module must be finite and positive.")
    external_outline, _ = standard_gear_outline(module, teeth, pressure_angle)
    pitch_radius = module * teeth / 2.0
    inner_outline = []
    for x, y in external_outline:
        radius = math.hypot(x, y)
        angle = math.atan2(y, x)
        internal_radius = 2.0 * pitch_radius - radius
        if internal_radius <= 0:
            raise ValueError("The ring gear tooth count is too small for this module.")
        inner_outline.append((internal_radius * math.cos(angle),
                              internal_radius * math.sin(angle)))
    outer_radius = outside_diameter / 2.0
    if outer_radius <= max(math.hypot(x, y) for x, y in inner_outline):
        raise ValueError("Ring outside diameter leaves no material behind its teeth.")

    sketch = Sketch("XY", name=name, frame=frame)
    sketch.circles.append(Circle(Vertex(0.0, 0.0), outer_radius))
    vertices = [Vertex(x, y) for x, y in inner_outline]
    sketch.vertices.extend(vertices)
    sketch.segments.extend(
        Segment(vertices[index], vertices[(index + 1) % len(vertices)])
        for index in range(len(vertices)))
    centerpoint = Vertex(0.0, 0.0, locked=True)
    sketch.vertices.append(centerpoint)
    sketch.points_free.append(centerpoint)
    return sketch

def make_rack_sketch(name, parameters, frame=None):
    """Build a straight-sided involute-rack approximation with the given module."""
    module = float(parameters["module"])
    teeth = int(parameters["teeth"])
    pressure_angle = float(parameters.get("pressure_angle", 20.0))
    if not math.isfinite(module) or module <= 0:
        raise ValueError("Rack module must be a finite positive number.")
    if teeth < 1:
        raise ValueError("A rack must have at least one tooth.")
    if not math.isfinite(pressure_angle) or not 10.0 <= pressure_angle <= 45.0:
        raise ValueError("Pressure angle must be between 10° and 45°.")

    backlash_factor = float(parameters.get("backlash", 0.1))
    if not math.isfinite(backlash_factor) or backlash_factor < 0:
        raise ValueError("Rack backlash must be a finite nonnegative module fraction.")
    tooth_radius = float(parameters.get("tooth_radius", 0.0))
    if not math.isfinite(tooth_radius) or tooth_radius < 0:
        raise ValueError("Rack tooth radius must be finite and nonnegative.")
    pitch = math.pi * module
    half_pitch_tooth = pitch / 4.0 - module * backlash_factor / 2.0
    tip_half_width = half_pitch_tooth - module * math.tan(math.radians(pressure_angle))
    root_half_width = half_pitch_tooth + 1.25 * module * math.tan(math.radians(pressure_angle))
    if tip_half_width <= 0 or root_half_width >= pitch / 2.0:
        raise ValueError("The rack tooth proportions are invalid for this pressure angle.")
    length = teeth * pitch
    base_y = -2.5 * module
    points = [(length / 2.0, base_y)]
    tip_corners = []
    for index in reversed(range(teeth)):
        center = (index + 0.5 - teeth / 2.0) * pitch
        first = len(points)
        points.extend(((center + root_half_width, -1.25 * module),
                       (center + tip_half_width, module),
                       (center - tip_half_width, module),
                       (center - root_half_width, -1.25 * module)))
        tip_corners.extend((first + 1, first + 2))
    points.append((-length / 2.0, base_y))

    sketch = Sketch("XY", name=name, frame=frame)
    rounded = {}
    trims = {}
    if tooth_radius > 0 and parameters.get("round_tips", False):
        for index in tip_corners:
            previous = np.asarray(points[index - 1], float)
            point = np.asarray(points[index], float)
            following = np.asarray(points[index + 1], float)
            incoming = _unit(point - previous)
            outgoing = _unit(following - point)
            toward_previous = _unit(previous - point)
            toward_following = _unit(following - point)
            interior_angle = math.acos(float(np.clip(
                np.dot(toward_previous, toward_following), -1.0, 1.0)))
            turn = incoming[0] * outgoing[1] - incoming[1] * outgoing[0]
            if turn <= 0 or interior_angle <= 0:
                raise ValueError("Rack tooth corners cannot be rounded with this profile.")
            trim = tooth_radius / math.tan(interior_angle / 2.0)
            trims[index] = trim
            center = point + _unit(toward_previous + toward_following) * \
                     (tooth_radius / math.sin(interior_angle / 2.0))
            rounded[index] = (point + toward_previous * trim,
                              point + toward_following * trim, center)
        for index in range(len(points)):
            following = (index + 1) % len(points)
            if trims.get(index, 0.0) + trims.get(following, 0.0) >= \
                    math.dist(points[index], points[following]) - 1e-9:
                raise ValueError("Rack tooth radius is too large; adjacent rounded corners overlap.")

    vertices = {index: Vertex(x, y) for index, (x, y) in enumerate(points)
                if index not in rounded}
    arcs = {}
    for index, (start, end, center) in rounded.items():
        arcs[index] = (Vertex(*start), Vertex(*end), Vertex(*center))
    for index in range(len(points)):
        following = (index + 1) % len(points)
        start = arcs[index][1] if index in arcs else vertices[index]
        end = arcs[following][0] if following in arcs else vertices[following]
        sketch.segments.append(Segment(start, end))
    sketch.arcs.extend(Arc(center, start, end) for start, end, center in arcs.values())
    sketch.vertices.extend(vertices.values())
    sketch.vertices.extend(vertex for arc in arcs.values() for vertex in arc)
    centerpoint = Vertex(0.0, 0.0, locked=True)
    sketch.vertices.append(centerpoint)
    sketch.points_free.append(centerpoint)
    return sketch

def matching_gear_parameters(parameters, ratio, bore_diameter=0.0):
    """Return the spur-gear parameters for a mate at mate/primary tooth ratio."""
    ratio = float(ratio)
    if not math.isfinite(ratio) or ratio <= 0:
        raise ValueError("The matching gear ratio must be a finite positive number.")
    module = float(parameters["module"])
    teeth = int(round(int(parameters["teeth"]) * ratio))
    if not 6 <= teeth <= 200:
        raise ValueError("The ratio must produce a matching spur gear with 6 to 200 teeth.")
    return {
        "kind": "spur",
        "outside_diameter": module * (teeth + 2),
        "module": module,
        "teeth": teeth,
        "pressure_angle": float(parameters.get("pressure_angle", 20.0)),
        "thickness": float(parameters["thickness"]),
        "bore_diameter": float(bore_diameter),
    }


THREAD_METRIC_COARSE = {2: 0.4, 2.5: 0.45, 3: 0.5, 4: 0.7, 5: 0.8, 6: 1.0,
                        8: 1.25, 10: 1.5, 12: 1.75, 14: 2.0, 16: 2.0, 18: 2.5,
                        20: 2.5, 22: 2.5, 24: 3.0, 27: 3.0, 30: 3.5}
THREAD_UNIFIED = (
    ("#4-40 UNC", 0.112, 40, "UNC"), ("#6-32 UNC", 0.138, 32, "UNC"),
    ("#8-32 UNC", 0.164, 32, "UNC"), ("#10-24 UNC", 0.190, 24, "UNC"),
    ("#10-32 UNF", 0.190, 32, "UNF"), ("#12-24 UNC", 0.216, 24, "UNC"),
    ("1/4-20 UNC", 0.250, 20, "UNC"), ("1/4-28 UNF", 0.250, 28, "UNF"),
    ("5/16-18 UNC", 0.3125, 18, "UNC"), ("5/16-24 UNF", 0.3125, 24, "UNF"),
    ("3/8-16 UNC", 0.375, 16, "UNC"), ("3/8-24 UNF", 0.375, 24, "UNF"),
    ("7/16-14 UNC", 0.4375, 14, "UNC"), ("7/16-20 UNF", 0.4375, 20, "UNF"),
    ("1/2-13 UNC", 0.500, 13, "UNC"), ("1/2-20 UNF", 0.500, 20, "UNF"),
    ("5/8-11 UNC", 0.625, 11, "UNC"), ("5/8-18 UNF", 0.625, 18, "UNF"),
    ("3/4-10 UNC", 0.750, 10, "UNC"), ("3/4-16 UNF", 0.750, 16, "UNF"),
    ("1-8 UNC", 1.000, 8, "UNC"), ("1-12 UNF", 1.000, 12, "UNF"),
)
THREAD_SIZES = [
    (f"M{nominal:g} × {pitch:g}", nominal, pitch, "ISO")
    for nominal, pitch in THREAD_METRIC_COARSE.items()
] + [
    (label, diameter_in * 25.4, 25.4 / tpi, standard)
    for label, diameter_in, tpi, standard in THREAD_UNIFIED
]


def thread_size_label(nominal, pitch, standard="ISO"):
    for label, size, thread_pitch, family in THREAD_SIZES:
        if family == standard and abs(size - nominal) < 1e-6 and abs(thread_pitch - pitch) < 1e-6:
            return label
    return f"M{nominal:g} × {pitch:g}"


THREAD_PHASES = ((1 / 16, 0.0), (6 / 16, 1.0), (10 / 16, 1.0), (15 / 16, 0.0))   # (phase / pitch, depth fraction)

def thread_depth(kind, pitch, fit):
    """Radial depth of the printable ISO profile below the nominal cylinder surface."""
    clearance = 0.15 if fit == "6" else 0.25
    return 0.61343 * pitch + clearance / 2 if kind == "external" else 0.54127 * pitch - clearance / 2

def thread_available(start, low, high):
    """Cylinder length a thread starting at `start` can use; it runs toward the far end."""
    return max(high - start, start - low)

def _thread_fraction(distance, pitch):
    crest, root = pitch / 16, pitch * 3 / 8
    return 0.0 if distance <= crest else 1.0 if distance >= root else (distance - crest) / (root - crest)

def cylinder_face_thread_kind(entry, face_index, center, axis):
    """Classify a cylinder as external or internal from its outward face normals."""
    vertices, triangles = entry["solid"]
    face = entry["faces"][face_index]
    tri_ids = np.asarray(face.get("tris", ()), dtype=int)
    tris = np.asarray(triangles, dtype=int)[tri_ids]
    points = np.asarray(vertices, dtype=float)[tris]
    normals = np.cross(points[:, 1] - points[:, 0], points[:, 2] - points[:, 0])
    centers = points.mean(axis=1)
    axis = _unit(axis)
    offsets = centers - np.asarray(center, dtype=float)
    radial = offsets - np.outer(offsets @ axis, axis)
    score = float(np.einsum("ij,ij->i", normals, radial).sum())
    if abs(score) < 1e-10:
        raise ValueError("Could not determine whether the cylindrical face is inside or outside")
    return "external" if score > 0 else "internal"


def match_cylinder_face(mesh, axis, point, radius):
    """(face index, fitted cylinder definition) of the mesh face lying on the given axis line, else None."""
    verts, tris, faces = mesh
    temp = {"solid": (verts, tris), "faces": faces}
    axis, point = _unit(axis), np.asarray(point, float)
    tolerance = max(1e-3, float(radius) * 0.01)
    for index, face in enumerate(faces):
        if face.get("planar") or not face.get("tris"): continue
        definition = _fit_curved_surface(temp, index)
        if definition is None or definition[0] != "cylinder": continue
        _, center, face_axis, _, _, face_radius, _, _ = definition
        offset = point - center
        if abs(float(face_axis @ axis)) > 1 - 1e-6 and abs(face_radius - radius) <= tolerance and \
                float(np.linalg.norm(offset - (offset @ face_axis) * face_axis)) <= tolerance:
            return index, definition
    return None


def apply_thread_feature(mesh, feat):
    """Replace a plain cylinder face by a helical ISO thread surface built directly on its end rings."""
    if not feat.get("visible", True): return mesh
    verts, tris, faces = mesh
    match = match_cylinder_face(mesh, feat["axis"], feat["point"], feat["radius"])
    if match is None:
        raise ValueError("the threaded cylindrical face no longer exists")
    face_index, (_, center, axis, radial_u, radial_v, radius, (low, high), _) = match
    start = float((np.asarray(feat["point"], float) - center) @ axis)
    start = low if start - low < 1e-3 else high if high - start < 1e-3 else min(max(start, low), high)
    sign = 1 if high - start >= start - low else -1        # always toward the far end
    A, U, V = axis * sign, radial_u, radial_v * sign          # right-handed frame along the thread
    t_lo, t_hi = (low, high) if sign > 0 else (-high, -low)
    t0 = sign * start
    pitch = float(feat["pitch"])
    t1 = t_hi if feat.get("whole") else min(t0 + float(feat["length"]), t_hi)
    if t_hi - t1 < 1e-3: t1 = t_hi
    if t1 - t0 < pitch - 1e-9:
        raise ValueError("less than one pitch of the cylinder remains after the start point")

    V3 = np.asarray(verts, float); T3 = np.asarray(tris, int).reshape(-1, 3)
    face_tris = np.asarray(faces[face_index]["tris"], int)
    kind = cylinder_face_thread_kind({"solid": (verts, tris), "faces": faces}, face_index, center, axis)
    if kind != feat["kind"]:
        raise ValueError("the cylindrical face changed from inside to outside")
    depth = float(feat.get("depth", thread_depth(kind, pitch, feat["fit"])))
    if not math.isfinite(depth) or depth <= 0:
        raise ValueError("the thread depth must be a finite positive number")
    if radius <= depth + 0.1:
        raise ValueError("the cylinder is too small for this thread")

    ids = np.unique(T3[face_tris])
    rel = V3[ids] - center
    along = sign * (rel @ axis)
    theta = np.arctan2(rel @ V, rel @ U) % (2 * math.pi)
    at_lo, at_hi = abs(along - t_lo) < 1e-3, abs(along - t_hi) < 1e-3
    level = np.zeros(len(V3), int); level[ids[at_lo]] = 1; level[ids[at_hi]] = 2
    face_edges = np.sort(T3[face_tris][:, [0, 1, 1, 2, 2, 0]].reshape(-1, 2), axis=1)
    edges, count = np.unique(face_edges, axis=0, return_counts=True)
    rim = edges[count == 1]                                  # cuts through the wall add vertices between the rings
    if int(at_lo.sum()) < 8 or int(at_hi.sum()) < 8 or not len(rim) or \
            ((level[rim[:, 0]] != level[rim[:, 1]]) | (level[rim[:, 0]] == 0)).any():
        raise ValueError("threads need a full cylindrical face that no other feature cuts into")
    order = np.argsort(theta[at_lo]); lo_ids, lo_angles = ids[at_lo][order], theta[at_lo][order]
    order = np.argsort(theta[at_hi]); hi_ids, hi_angles = ids[at_hi][order], theta[at_hi][order]
    # Rings re-triangulated by a cut differ top and bottom; the thread then gets regular columns and narrow bands to the rings.
    spread = np.abs((hi_angles[None, :] - lo_angles[:, None] + math.pi) % (2 * math.pi) - math.pi)
    pair = spread.argmin(axis=1)
    clean = len(lo_ids) == len(hi_ids) and spread[np.arange(len(lo_ids)), pair].max() < 1e-3 and \
            len(set(pair.tolist())) == len(lo_ids) and np.diff(np.r_[lo_angles, lo_angles[0] + 2 * math.pi]).min() > 0.01
    if clean:
        angles, ring_lo, ring_hi = lo_angles, lo_ids.tolist(), hi_ids[pair].tolist()
    else:
        columns_n = int(min(144, max(48, math.ceil(2 * math.pi * radius / (pitch / 2)))))
        angles = np.arange(columns_n) * 2 * math.pi / columns_n
        ring_lo, ring_hi = lo_ids.tolist(), hi_ids.tolist()
    n = len(angles)
    attach0, attach1 = clean and t0 - t_lo < 1e-3, clean and t_hi - t1 < 1e-3
    if not attach0 and t0 - t_lo < pitch / 10: t0 = t_lo + pitch / 10
    if not attach1 and t_hi - t1 < pitch / 10: t1 = t_hi - pitch / 10
    if t1 - t0 < pitch - 1e-9:
        raise ValueError("less than one pitch of the cylinder remains after the start point")
    if kind == "external":
        # End caps only ever lose area to the groove; walls of other faces (a bore) must stay clear of it.
        wall = np.zeros(len(V3), bool)
        for other, face in enumerate(faces):
            if other == face_index or not len(face["tris"]): continue
            if face.get("planar") and "frame" in face and abs(float(np.asarray(face["frame"][3], float) @ axis)) > 0.999:
                continue
            wall[np.unique(T3[np.asarray(face["tris"], int)])] = True
        rel_all = V3 - center; axial = rel_all @ axis
        rho = np.linalg.norm(rel_all - np.outer(axial, axis), axis=1)
        inside = wall & (sign * axial > t0 - 1e-3) & (sign * axial < t1 + 1e-3) & \
                 (rho < radius - 1e-3) & (rho > radius - depth - 0.02)
        inside[ids] = False
        if inside.any():
            raise ValueError("the thread groove would cut into other geometry (wall too thin)")

    new_verts = []
    def add(angle, t, r):
        new_verts.append(tuple(center + t * A + r * (math.cos(angle) * U + math.sin(angle) * V)))
        return len(V3) + len(new_verts) - 1

    # Thread depth tapers to zero over `ramp` at both ends so the end rings stay on the original surface.
    ramp = min(pitch / 2, (t1 - t0) / 2)
    def radius_at(angle, t):
        phase = (t - t0 - pitch * angle / (2 * math.pi)) % pitch
        weight = min(1.0, (t - t0) / ramp, (t1 - t) / ramp)
        return radius - depth * _thread_fraction(min(phase, pitch - phase), pitch) * max(weight, 0.0)

    ring0 = ring_lo if attach0 else [add(a, t0, radius) for a in angles]
    ring1 = ring_hi if attach1 else [add(a, t1, radius) for a in angles]
    out = []                                                 # (a, b, c) counter-clockwise from outside
    def band(lower, upper):
        """Triangles between two closed rings (ids, angles) of any vertex counts; lower is at the smaller t."""
        (low_ids, low_angles), (up_ids, up_angles) = lower, upper
        low_angles, up_angles = np.asarray(low_angles, float), np.asarray(up_angles, float)
        shift = int(np.argmin(np.abs((up_angles - low_angles[0] + math.pi) % (2 * math.pi) - math.pi)))
        up_ids = list(up_ids[shift:]) + list(up_ids[:shift]); up_angles = np.r_[up_angles[shift:], up_angles[:shift]]
        rl = np.r_[(low_angles - low_angles[0]) % (2 * math.pi), 2 * math.pi]
        ru = np.r_[(up_angles - up_angles[0]) % (2 * math.pi), 2 * math.pi]
        nl, nu, i, j = len(low_ids), len(up_ids), 0, 0
        while i < nl or j < nu:
            if j == nu or (i < nl and rl[i + 1] <= ru[j + 1]):
                out.append((low_ids[i], low_ids[(i + 1) % nl], up_ids[j % nu])); i += 1
            else:
                out.append((low_ids[i % nl], up_ids[(j + 1) % nu], up_ids[j])); j += 1
    if not attach0: band((ring_lo, lo_angles), (ring0, angles))
    if not attach1: band((ring1, angles), (ring_hi, angles if clean else hi_angles))
    plain = len(out)

    eps = pitch * 2e-3
    columns = []
    for j, angle in enumerate(angles):
        marks = {t0 + ramp, t1 - ramp}
        origin = t0 + pitch * angle / (2 * math.pi)
        first = math.floor((t0 - origin) / pitch) - 1
        for k in range(first, first + int((t1 - t0) / pitch) + 3):
            marks.update(origin + (k + phase) * pitch for phase, _ in THREAD_PHASES)
        column, last = [(t0, ring0[j])], t0
        for t in sorted(marks):
            if t > last + eps and t < t1 - eps:
                column.append((t, add(angle, t, radius_at(angle, t)))); last = t
        columns.append(column + [(t1, ring1[j])])
    for j in range(n):
        left, right = columns[j], columns[(j + 1) % n]
        i = k = 0
        while i < len(left) - 1 or k < len(right) - 1:
            if i == len(left) - 1 or (k < len(right) - 1 and right[k + 1][0] < left[i + 1][0]):
                out.append((left[i][1], right[k][1], right[k + 1][1])); k += 1
            else:
                out.append((left[i][1], right[k][1], left[i + 1][1])); i += 1

    if kind == "internal": out = [(a, c, b) for a, b, c in out]
    keep = np.ones(len(T3), bool); keep[face_tris] = False
    remap = np.cumsum(keep) - 1
    new_tris = [tuple(t) for t in T3[keep].tolist()]
    base = len(new_tris)
    new_faces = [dict(f, tris=[int(remap[k]) for k in f["tris"] if keep[k]]) for f in faces]
    new_faces[face_index]["tris"] += range(base, base + plain)
    new_tris += out
    new_faces.append({"kind": "thread", "planar": False, "tris": list(range(base + plain, len(new_tris)))})
    result = (list(verts) + new_verts, new_tris, new_faces)
    if not _mesh_is_closed(new_tris):
        raise ValueError("the thread surface could not be joined to the cylinder")
    return result

def _flatten_loop(lp):
    pts, owner = [], []
    for ei, e in enumerate(lp):
        pts += e["pts"][:-1]; owner += [ei]*(len(e["pts"])-1)
    return pts, owner

def _profile_groups(loops):
    """Orient all profile loops counter-clockwise and detect nesting. Returns (loop_pts,
    groups): loop_pts[i] = (loop edges, polygon points); groups maps the index of every outer
    loop (or island) to the indices of the loops that are holes in it."""
    loop_pts = []
    for loop in loops:
        pts, _ = _flatten_loop(loop)
        if poly_area(pts) < 0:
            loop = [dict(e, pts=e["pts"][::-1]) for e in reversed(loop)]
            pts, _ = _flatten_loop(loop)
        loop_pts.append((loop, pts))

    # a loop is a hole if a boundary vertex of it lies inside an odd number of other loops
    # (a boundary vertex is used: the centroid of a ring-shaped loop may lie inside another loop)
    n_loops = len(loop_pts)
    depth = [0]*n_loops
    for i in range(n_loops):
        c = loop_pts[i][1][0]
        for j in range(n_loops):
            if i != j and _pt_in_poly(c, loop_pts[j][1]):
                depth[i] += 1

    # depth 0 = outer shell, depth 1 = hole, depth 2 = island inside hole, etc.
    # group holes with their immediate parent (the shallowest loop that contains them)
    groups = {}   # outer_index -> [hole_indices]
    for i in range(n_loops):
        if depth[i] % 2 == 0:   # outer or island
            groups[i] = []
    for i in range(n_loops):
        if depth[i] % 2 == 1:   # hole
            c = loop_pts[i][1][0]
            parent = min(
                (j for j in groups if _pt_in_poly(c, loop_pts[j][1])),
                key=lambda j: depth[j], default=None)
            if parent is not None:
                groups[parent].append(i)
    return loop_pts, groups

def extrude_profile(loops, h, frame, z0=0.0):
    """Prism(s) from profile loops (see Sketch.profile_loop_edges) along frame w, from
    z0 to z0+h (h > 0). Returns (verts, tris, faces). Triangles are wound with outward normals.
    faces: [{"kind","tris","planar", "frame":(O,u,v,n), "boundary":[prims]}] where boundary
    prims are ("line",A,B) | ("arc",C,S,E,axis) | ("circle",C,r) in world coordinates.
    Loops nested inside another loop are treated as holes (material removed)."""
    O, u, v, w = (np.asarray(a, float) for a in frame)
    z1 = z0 + h
    hand  = 1 if np.dot(np.cross(u, v), w) > 0 else -1
    axis2 = _unit(np.cross(u, v))             # CCW rotation axis of sketch coordinates
    def P(p, z): return O + p[0]*u + p[1]*v + z*w
    flatten = _flatten_loop
    loop_pts, groups = _profile_groups(loops)

    verts, tris, faces = [], [], []

    for outer_i, hole_indices in groups.items():
        outer_loop, outer_pts = loop_pts[outer_i]
        hole_loops  = [loop_pts[hi][0] for hi in hole_indices]
        hole_pts_list = []
        for hi in hole_indices:
            hp = loop_pts[hi][1]
            # holes must be CW for the bridge algorithm
            if poly_area(hp) > 0:
                hp = hp[::-1]
            hole_pts_list.append(hp)

        base = len(verts)
        # vertices: outer bottom, outer top, then each hole bottom+top
        all_loops_pts = [outer_pts] + hole_pts_list
        loop_base = []   # base vertex index for each loop
        for lp in all_loops_pts:
            loop_base.append(len(verts) - base)
            n = len(lp)
            verts += [tuple(float(c) for c in P(p, z0)) for p in lp]
            verts += [tuple(float(c) for c in P(p, z1)) for p in lp]

        def add(tl):
            ids = []
            for a, b, c in tl:
                ids.append(len(tris))
                tris.append((base+a, base+b, base+c) if hand > 0 else (base+a, base+c, base+b))
            return ids

        # --- caps (top and bottom) with holes ---
        # build flat index -> vertex offset maps (bottom and top layers)
        flat_to_v = []
        flat_to_v_top = []
        for li, lp in enumerate(all_loops_pts):
            lb = loop_base[li]; n = len(lp)
            flat_to_v     += [lb + k     for k in range(n)]
            flat_to_v_top += [lb + n + k for k in range(n)]
        all_verts_2d = [p for lp in all_loops_pts for p in lp]
        cap_tris, merged_pts = triangulate_with_holes(outer_pts, hole_pts_list)
        # map each merged point back to its vertex index (merged points are the loop points)
        pt_flat = {}
        for k, p in enumerate(all_verts_2d): pt_flat.setdefault((p[0], p[1]), k)
        def cap_ids(tri_list, flat_map):
            out = []
            for a, b, c in tri_list:
                ia, ib, ic = (flat_map[pt_flat[(merged_pts[k][0], merged_pts[k][1])]] for k in (a, b, c))
                if ia != ib and ib != ic and ia != ic: out.append((ia, ib, ic))   # drop slit triangles
            return out
        bot = add([(a, c, b) for a, b, c in cap_ids(cap_tris, flat_to_v)])
        top = add(cap_ids(cap_tris, flat_to_v_top))

        def lift(e, z):
            if e["kind"] == "line":  return ("line", P(e["pts"][0], z), P(e["pts"][-1], z))
            if e["kind"] == "arc":   return ("arc", P(e["center"], z), P(e["start"], z),
                                             P(e["end"], z), axis2)
            return ("circle", P(e["center"], z), e["radius"])
        def cap_face(kind, ids, z, nrm, all_loops):
            nrm = _unit(nrm); uu = _unit(u)
            boundary = [lift(e, z) for loop in all_loops for e in loop]
            return {"kind": kind, "tris": ids, "planar": True,
                    "frame": (P((0, 0), z), uu, np.cross(nrm, uu), nrm),
                    "boundary": boundary}
        all_cap_loops = [outer_loop] + hole_loops
        faces.append(cap_face("bottom", bot, z0, -w, all_cap_loops))
        faces.append(cap_face("top",    top, z1,  w, all_cap_loops))

        # --- side walls for every loop (outer + holes) ---
        for li, (loop, lp) in enumerate(zip([outer_loop]+hole_loops, all_loops_pts)):
            lb = loop_base[li]; n = len(lp)
            _, owner = flatten(loop)
            side = {}
            for i in range(n):
                j = (i+1) % n
                side.setdefault(owner[i], []).extend(
                    add([(lb+i, lb+j, lb+n+j), (lb+i, lb+n+j, lb+n+i)]))
            for ei, e in enumerate(loop):
                ids = side.get(ei, [])
                if e["kind"] == "line":
                    a2, b2 = e["pts"][0], e["pts"][-1]
                    A0, B0 = P(a2, z0), P(b2, z0)
                    nrm = _unit((b2[1]-a2[1])*u - (b2[0]-a2[0])*v)
                    if li > 0: nrm = -nrm   # hole walls: normal points inward
                    uu = _unit(P(b2, 0) - P(a2, 0))
                    faces.append({"kind": "side", "tris": ids, "planar": True,
                                  "frame": (A0, uu, np.cross(nrm, uu), nrm),
                                  "boundary": [("line", A0, B0),
                                               ("line", B0, B0+h*w),
                                               ("line", B0+h*w, A0+h*w),
                                               ("line", A0+h*w, A0)]})
                else:
                    faces.append({"kind": "side", "tris": ids, "planar": False})

    return verts, tris, faces

def draft_extrusion_mesh(mesh, pivot, axis, angle, selected_faces=None, circular=False):
    """Draft an extrusion's side faces about a pivot, preserving its section at the pivot plane."""
    vertices, triangles, faces = mesh
    V = np.asarray(vertices, dtype=float)
    T = np.asarray(triangles, dtype=int).reshape(-1, 3)
    pivot = np.asarray(pivot, dtype=float)
    axis = _unit(np.asarray(axis, dtype=float))
    angle = float(angle)
    if V.ndim != 2 or V.shape[1] != 3 or pivot.shape != (3,) or \
            not np.isfinite(V).all() or not np.isfinite(pivot).all() or \
            not np.isfinite(angle) or float(np.linalg.norm(axis)) < 1e-12:
        raise ValueError("The pivot, extrusion axis, and angle must be finite.")
    if abs(angle) >= 89.0:
        raise ValueError("The draft angle must be between -89 and 89 degrees.")
    if not T.size or not faces:
        raise ValueError("The extrusion has no faces to draft.")
    face_indices = set(range(len(faces))) if circular else set(selected_faces or ())
    sides = {index for index in face_indices if 0 <= index < len(faces) and
             faces[index].get("kind") not in ("top", "bottom")}
    if not sides:
        raise ValueError("Select at least one side surface to draft.")

    tangent = math.tan(math.radians(angle))
    incident = [[] for _ in range(len(V))]
    for face_index in sides:
        face = faces[face_index]
        tri_ids = np.asarray(face.get("tris", []), dtype=int)
        tri_ids = tri_ids[(tri_ids >= 0) & (tri_ids < len(T))]
        if not len(tri_ids):
            continue
        vertex_ids = np.unique(T[tri_ids].ravel())
        center = V[vertex_ids].mean(axis=0)
        normal = None
        if face.get("planar") and len(face.get("frame", ())) >= 4:
            toward_pivot = pivot - center
            toward_pivot -= axis * float(toward_pivot @ axis)
            if float(np.linalg.norm(toward_pivot)) > 1e-10:
                normal = _unit(toward_pivot)
            else:
                normal = -np.asarray(face["frame"][3], dtype=float)
                normal -= axis * float(normal @ axis)
                if float(np.linalg.norm(normal)) > 1e-10:
                    normal = _unit(normal)
        elif not circular:
            normals = np.zeros_like(V)
            face_triangles = T[tri_ids]
            crosses = np.cross(V[face_triangles[:, 1]] - V[face_triangles[:, 0]],
                               V[face_triangles[:, 2]] - V[face_triangles[:, 0]])
            for corner in range(3):
                np.add.at(normals, face_triangles[:, corner], crosses)
        for vertex_id in vertex_ids:
            point = V[vertex_id]
            if circular:
                radial = point - pivot
                radial -= axis * float(radial @ axis)
                direction = -_unit(radial) if float(np.linalg.norm(radial)) > 1e-10 else None
            elif normal is None:
                toward_pivot = pivot - point
                toward_pivot -= axis * float(toward_pivot @ axis)
                direction = _unit(toward_pivot) if float(np.linalg.norm(toward_pivot)) > 1e-10 \
                    else -_unit(normals[vertex_id]) \
                    if float(np.linalg.norm(normals[vertex_id])) > 1e-10 else None
            else:
                direction = normal
            if direction is not None:
                incident[vertex_id].append(direction)

    moved = V.copy()
    for vertex_id, directions in enumerate(incident):
        if not directions:
            continue
        point = V[vertex_id]
        travel = abs(float((point - pivot) @ axis))
        bisector = _unit(np.sum(directions, axis=0))
        alignment = min(float(bisector @ direction) for direction in directions)
        if alignment <= 1e-6:
            raise ValueError("The selected draft faces meet at an invalid corner.")
        moved[vertex_id] += bisector * (travel * tangent / alignment)

    old_cross = np.cross(V[T[:, 1]] - V[T[:, 0]], V[T[:, 2]] - V[T[:, 0]])
    new_cross = np.cross(moved[T[:, 1]] - moved[T[:, 0]], moved[T[:, 2]] - moved[T[:, 0]])
    if np.any(np.linalg.norm(new_cross, axis=1) < 1e-10) or \
            np.any(np.einsum("ij,ij->i", old_cross, new_cross) <= 0.0):
        raise ValueError("The draft angle collapses or inverts the extrusion.")

    updated_faces = []
    vertex_lookup = {tuple(point): index for index, point in enumerate(V)}

    def moved_boundary_point(point):
        point = np.asarray(point, dtype=float)
        vertex_id = vertex_lookup.get(tuple(point))
        if vertex_id is None:
            distances = np.linalg.norm(V - point, axis=1)
            nearest = int(np.argmin(distances))
            if distances[nearest] > 1e-7:
                return point
            vertex_id = nearest
        return moved[vertex_id]

    for face in faces:
        record = dict(face)
        tri_ids = np.asarray(face.get("tris", []), dtype=int)
        tri_ids = tri_ids[(tri_ids >= 0) & (tri_ids < len(T))]
        if "boundary" in face:
            boundary = []
            for primitive in face["boundary"]:
                if primitive[0] == "line":
                    boundary.append(("line", moved_boundary_point(primitive[1]),
                                     moved_boundary_point(primitive[2])))
                elif primitive[0] == "arc":
                    boundary.append(("arc", primitive[1], moved_boundary_point(primitive[2]),
                                     moved_boundary_point(primitive[3]), primitive[4]))
                else:
                    center = np.asarray(primitive[1], dtype=float)
                    relative = V - center
                    axial_distance = np.abs(relative @ axis)
                    radial_distance = np.linalg.norm(relative - (relative @ axis)[:, None] * axis,
                                                     axis=1)
                    candidates = np.flatnonzero((axial_distance < 1e-7) &
                        (np.abs(radial_distance - float(primitive[2])) < 1e-5))
                    radius = float(np.mean(np.linalg.norm(
                        moved[candidates] - center -
                        ((moved[candidates] - center) @ axis)[:, None] * axis, axis=1))) \
                        if len(candidates) else float(primitive[2])
                    boundary.append(("circle", center, radius))
            record["boundary"] = boundary
        if face.get("planar") and len(tri_ids):
            face_tris = T[tri_ids]
            points = moved[face_tris]
            crosses = np.cross(points[:, 1] - points[:, 0], points[:, 2] - points[:, 0])
            normal = _unit(crosses.sum(axis=0))
            old_frame = face.get("frame")
            if old_frame is not None and float(normal @ np.asarray(old_frame[3])) < 0.0:
                normal = -normal
            u = np.asarray(old_frame[1], dtype=float) if old_frame is not None else \
                points[0, 1] - points[0, 0]
            u -= normal * float(u @ normal)
            if float(np.linalg.norm(u)) < 1e-10:
                u = points[0, 1] - points[0, 0]
                u -= normal * float(u @ normal)
            u = _unit(u)
            v = _unit(np.cross(normal, u))
            record["frame"] = (points.reshape(-1, 3).mean(axis=0), u, v, normal)
        updated_faces.append(record)
    return moved.tolist(), triangles, updated_faces

def bevel_gear_extrusion(loops, h, frame, module, teeth, angle, z0=0.0):
    """Taper an involute prism toward its top face to form a straight bevel gear."""
    module, angle = float(module), float(angle)
    if not math.isfinite(module) or module <= 0 or not math.isfinite(angle) or \
            not 1.0 <= angle <= 75.0 or not math.isfinite(h) or h <= 0:
        raise ValueError("Bevel gear module, thickness, or cone angle is invalid.")
    pitch_radius = module * int(teeth) / 2.0
    top_scale = 1.0 - h * math.tan(math.radians(angle)) / pitch_radius
    if top_scale <= 0.1:
        raise ValueError("Bevel angle is too steep for this gear thickness.")

    vertices, triangles, faces = extrude_profile(loops, h, frame, z0)
    origin, axis_u, axis_v, axis_w = (np.asarray(axis, float) for axis in frame)

    def transform(point):
        delta = np.asarray(point, float) - origin
        x, y, z = float(delta @ axis_u), float(delta @ axis_v), float(delta @ axis_w)
        factor = 1.0 - (1.0 - top_scale) * (z - z0) / h
        return origin + factor * x * axis_u + factor * y * axis_v + z * axis_w

    vertices = [tuple(transform(vertex)) for vertex in vertices]
    transformed_faces = []
    for face in faces:
        record = dict(face)
        boundary = []
        for primitive in face.get("boundary", []):
            kind = primitive[0]
            if kind == "line":
                boundary.append((kind, transform(primitive[1]), transform(primitive[2])))
            elif kind == "arc":
                boundary.append((kind, transform(primitive[1]), transform(primitive[2]),
                                 transform(primitive[3]), primitive[4]))
            else:
                center = transform(primitive[1])
                delta = np.asarray(primitive[1], float) - origin
                z = float(delta @ axis_w)
                factor = 1.0 - (1.0 - top_scale) * (z - z0) / h
                boundary.append((kind, center, primitive[2] * factor))
        if "boundary" in face:
            record["boundary"] = boundary
        if face.get("kind") in ("bottom", "top"):
            frame_origin, u, v, normal = face["frame"]
            record["frame"] = (transform(frame_origin), u, v, normal)
        elif face.get("planar") and len(boundary) >= 4:
            corners = [boundary[0][1], boundary[0][2],
                       boundary[1][2], boundary[2][2]]
            side_u = _unit(corners[1] - corners[0])
            normal = _unit(np.cross(side_u, corners[3] - corners[0]))
            old_normal = np.asarray(face["frame"][3], float)
            if float(normal @ old_normal) < 0:
                normal = -normal
            record["frame"] = (corners[0], side_u, np.cross(normal, side_u), normal)
        transformed_faces.append(record)
    if not _mesh_is_closed(triangles):
        raise ValueError("The bevel gear taper produced an open mesh.")
    return vertices, triangles, transformed_faces

def helical_gear_extrusion(loops, h, frame, module, teeth, angle, z0=0.0):
    """Sweep an involute gear profile through an axial twist set by its helix angle."""
    module, angle = float(module), float(angle)
    if not math.isfinite(module) or module <= 0 or not math.isfinite(angle) or \
            abs(angle) > 45.0 or not math.isfinite(h) or h <= 0:
        raise ValueError("Helical gear module, thickness, or helix angle is invalid.")
    if abs(angle) < 1e-8:
        return extrude_profile(loops, h, frame, z0)

    pitch_radius = module * int(teeth) / 2.0
    if not math.isfinite(pitch_radius) or pitch_radius <= 0:
        raise ValueError("Helical gear pitch radius must be positive.")
    total_twist = h * math.tan(math.radians(angle)) / pitch_radius
    layer_count = max(1, int(math.ceil(abs(total_twist) / math.radians(3.0))))
    if layer_count > 128:
        raise ValueError("Helix is too long or steep; reduce the thickness or helix angle.")

    origin, u, v, w = (np.asarray(axis, float) for axis in frame)
    hand = 1 if np.dot(np.cross(u, v), w) > 0 else -1
    axis2 = _unit(np.cross(u, v))
    loop_pts, groups = _profile_groups(loops)
    vertices, triangles, faces = [], [], []

    def transform(point, z):
        theta = total_twist * (z - z0) / h
        cosine, sine = math.cos(theta), math.sin(theta)
        x = cosine * point[0] - sine * point[1]
        y = sine * point[0] + cosine * point[1]
        return origin + x * u + y * v + z * w

    def add(local_triangles, vertex_map, reverse=False):
        ids = []
        for a, b, c in local_triangles:
            if reverse:
                b, c = c, b
            if hand < 0:
                b, c = c, b
            ids.append(len(triangles))
            triangles.append((vertex_map[a], vertex_map[b], vertex_map[c]))
        return ids

    def cap_boundary(loop, z):
        boundary = []
        for edge in loop:
            if edge["kind"] == "line":
                boundary.append(("line", transform(edge["pts"][0], z),
                                 transform(edge["pts"][-1], z)))
            elif edge["kind"] == "arc":
                boundary.append(("arc", transform(edge["center"], z),
                                 transform(edge["start"], z), transform(edge["end"], z), axis2))
            else:
                boundary.append(("circle", transform(edge["center"], z), edge["radius"]))
        return boundary

    for outer_index, hole_indices in groups.items():
        outer_loop, outer_points = loop_pts[outer_index]
        all_loops = [outer_loop]
        all_points = [outer_points]
        for hole_index in hole_indices:
            hole_loop, hole_points = loop_pts[hole_index]
            hole_loop = [dict(edge, pts=edge["pts"][::-1]) for edge in reversed(hole_loop)]
            hole_points, _ = _flatten_loop(hole_loop)
            all_loops.append(hole_loop)
            all_points.append(hole_points)

        cap_triangles, merged_points = triangulate_with_holes(outer_points, all_points[1:])
        point_indices = {}
        for index, point in enumerate(point for loop in all_points for point in loop):
            point_indices.setdefault((point[0], point[1]), index)
        cap_local = [tuple(point_indices[(merged_points[index][0], merged_points[index][1])]
                           for index in triangle) for triangle in cap_triangles]
        flat_points = [point for loop in all_points for point in loop]
        layer_maps = []
        for layer in range(layer_count + 1):
            z = z0 + h * layer / layer_count
            vertex_map = []
            for point in flat_points:
                vertex_map.append(len(vertices))
                vertices.append(tuple(float(value) for value in transform(point, z)))
            layer_maps.append(vertex_map)

        bottom_ids = add(cap_local, layer_maps[0], reverse=True)
        top_ids = add(cap_local, layer_maps[-1])

        def cap_face(kind, ids, z, normal):
            theta = total_twist * (z - z0) / h
            cosine, sine = math.cos(theta), math.sin(theta)
            tangent_u = _unit(cosine * u + sine * v)
            normal = _unit(normal)
            return {"kind": kind, "tris": ids, "planar": True,
                    "frame": (origin + z * w, tangent_u, np.cross(normal, tangent_u), normal),
                    "boundary": [primitive for loop in all_loops
                                 for primitive in cap_boundary(loop, z)]}

        faces.append(cap_face("bottom", bottom_ids, z0, -w))
        faces.append(cap_face("top", top_ids, z0 + h, w))

        flat_offset = 0
        section_point_count = len(flat_points)
        for loop_index, (loop, points) in enumerate(zip(all_loops, all_points)):
            _, owners = _flatten_loop(loop)
            edge_triangles = [[] for _ in loop]
            point_count = len(points)
            for layer in range(layer_count):
                lower, upper = layer_maps[layer], layer_maps[layer + 1]
                for index in range(point_count):
                    following = (index + 1) % point_count
                    local = ((flat_offset + index, flat_offset + following,
                              section_point_count + flat_offset + following),
                             (flat_offset + index, section_point_count + flat_offset + following,
                              section_point_count + flat_offset + index))
                    edge_triangles[owners[index]].extend(add(local, lower + upper))
            faces.extend({"kind": "side", "tris": ids, "planar": False}
                         for ids in edge_triangles)
            flat_offset += point_count

    if not _mesh_is_closed(triangles):
        raise ValueError("The helical gear sweep produced an open mesh.")
    return vertices, triangles, faces

# ── ring extrusion: profile swept around an axis in the sketch plane (donut, ring, …) ──
RING_AXES = ("u", "v", "-u", "-v")
RING_REFS = ("center", "outer", "inner")

def ring_profile_extent(loops, axis="u"):
    """(centre, half width) of the profile perpendicular to a ring axis parallel to the
    sketch's X ("u") or Y ("v") axis."""
    pts = np.array([p for lp in loops for e in lp for p in e["pts"]], float)
    c = pts[:, 0] if axis in ("v", "-v") else pts[:, 1]
    return float(c.min() + c.max())/2, float(c.max() - c.min())/2

def ring_axis(loops, frame, axis="u", radius=10.0, ref="center"):
    """Axis of a ring extrusion: parallel to the sketch's own X ("u") or Y ("v") axis. The
    radius is measured from the axis to the centre of the profile ("center"), to its farthest
    edge ("outer") or to its nearest edge ("inner"). A positive radius puts the axis on the
    positive side of the profile (+Y of the sketch for the X axis, +X for the Y axis), a
    negative one on the other side. The selected axis key determines the axis direction, and
    positive angles follow the right-hand rule. Returns (point on the axis, axis direction,
    distance of the axis from the profile centre, axis key).
    Raises ValueError if the profile touches or crosses the axis."""
    O, u, v, w = (np.asarray(a, float) for a in frame)
    key = axis if axis in RING_AXES else "u"
    horizontal = key in ("u", "-u")
    e, side = (u, v) if horizontal else (v, u)           # axis direction, in-plane perpendicular
    if key.startswith("-"):
        e = -e
    mid, half = ring_profile_extent(loops, key)
    m = abs(radius); sgn = 1.0 if radius >= 0 else -1.0
    rc = m + half if ref == "inner" else m - half if ref == "outer" else m   # axis to profile centre
    if rc - half < 1e-4:
        raise ValueError("the profile touches or crosses the ring axis — use a larger radius "
                         "(a negative radius puts the axis on the other side)")
    centre = np.zeros(2); centre[1 if horizontal else 0] = mid + sgn*rc
    C = O + centre[0]*u + centre[1]*v
    return C, _unit(e), rc, key

def _rotate_about(pts, C, axis, ang):
    """Rotate points (or vectors, with C = 0) about the axis through C (Rodrigues)."""
    r = np.atleast_2d(np.asarray(pts, float) - C)
    c, s = math.cos(ang), math.sin(ang)
    return C + r*c + np.cross(axis, r)*s + np.outer(r @ axis, axis)*(1 - c)

def revolve_profile(loops, frame, C, axis, a0, a1, height=0.0):
    """Solid(s) swept by the profile loops about the axis (point C, direction `axis`) from angle
    a0 to a1 (rad, a1 > a0). Positive angles follow the right-hand rule about the supplied axis;
    use ring_axis to get an oriented sketch-local axis. A sweep of 360° gives a closed ring
    without end faces. Loops nested in another loop are holes. Returns (verts, tris, faces) like
    extrude_profile.
    Raises ValueError if the profile touches or crosses the axis."""
    O, u, v, w = (np.asarray(a, float) for a in frame)
    axis = _unit(axis)
    hand = 1 if np.dot(np.cross(u, v), w) > 0 else -1
    axis2 = _unit(np.cross(u, v))
    sweep = a1 - a0
    full = (sweep >= 2*math.pi - 1e-6 and sweep <= 2*math.pi + 1e-6 and
            abs(height) < 1e-9)
    n_a = max(3 if full else 1, int(math.ceil(sweep/math.radians(6.0) - 1e-9)))
    nr = n_a if full else n_a + 1
    angs = a0 + sweep*np.arange(nr)/n_a
    def P2(p): return O + p[0]*u + p[1]*v
    def at(p, ang): return _rotate_about(p, C, axis, ang)[0]
    def rotv(x, ang): return _rotate_about(x, 0.0, axis, ang)[0]
    loop_pts, groups = _profile_groups(loops)
    profile_points = np.asarray([p for _, pts in loop_pts for p in pts], dtype=float)
    profile_center = P2((profile_points.min(axis=0) + profile_points.max(axis=0)) / 2.0)
    toward_axis = C - profile_center
    toward_axis -= axis * float(toward_axis @ axis)
    toward_length = float(np.linalg.norm(toward_axis))
    if toward_length < 1e-9:
        raise ValueError("the profile touches or crosses the ring axis — use a larger radius")
    toward_axis /= toward_length
    if any(float((C - P2(p)) @ toward_axis) < 1e-4 for _, pts in loop_pts for p in pts):
        raise ValueError("the profile touches or crosses the ring axis — use a larger radius")
    verts, tris, faces = [], [], []

    def add(tl):
        ids = []
        for a, b, c in tl:
            ids.append(len(tris)); tris.append((a, b, c) if hand > 0 else (a, c, b))
        return ids

    for outer_i, hole_indices in groups.items():
        outer_loop, outer_pts = loop_pts[outer_i]
        hole_loops = [loop_pts[hi][0] for hi in hole_indices]
        hole_pts_list = [(hp[::-1] if poly_area(hp) > 0 else hp) for hp in (loop_pts[hi][1] for hi in hole_indices)]
        loops_here = [outer_loop] + hole_loops
        pts_here = [outer_pts] + hole_pts_list
        vbase = []
        for lp in pts_here:
            vbase.append(len(verts)); W = np.array([P2(p) for p in lp], float)
            for ring_index, ang in enumerate(angs):
                axial_offset = height * ring_index / max(nr - 1, 1)
                rotated = _rotate_about(W, C, axis, ang) + axial_offset * axis
                verts += [tuple(float(c) for c in q) for q in rotated]
        for li, (loop, lp) in enumerate(zip(loops_here, pts_here)):
            n = len(lp); _, owner = _flatten_loop(loop)
            if li > 0: owner = [owner[(n - 2 - k) % n] for k in range(n)]   # points were reversed
            side = {}
            for k in range(n_a):
                k2 = (k + 1) % nr
                for i in range(n):
                    j = (i + 1) % n
                    a_, b_ = vbase[li] + k*n + i, vbase[li] + k*n + j
                    c_, d_ = vbase[li] + k2*n + j, vbase[li] + k2*n + i
                    side.setdefault(owner[i], []).extend(add([(a_, b_, c_), (a_, c_, d_)]))
            for ei in range(len(loop)):
                faces.append({"kind": "side", "tris": side.get(ei, []), "planar": False})
        if full: continue

        # end caps: the profile at the first and at the last ring
        flat_loop = []
        flat_off = []
        for li, lp in enumerate(pts_here):
            for i in range(len(lp)): flat_loop.append(li); flat_off.append(i)
        all_2d = [p for lp in pts_here for p in lp]
        cap_tris, merged = triangulate_with_holes(outer_pts, hole_pts_list)
        pt_flat = {}
        for k, p in enumerate(all_2d): pt_flat.setdefault((p[0], p[1]), k)
        def cap_ids(ring):
            out = []
            for tri in cap_tris:
                ids = []
                for m in tri:
                    f = pt_flat[(merged[m][0], merged[m][1])]
                    ids.append(vbase[flat_loop[f]] + ring*len(pts_here[flat_loop[f]]) + flat_off[f])
                if len(set(ids)) == 3: out.append(tuple(ids))
            return out
        def cap_face(kind, ids, ang, sgn):
            nrm = _unit(sgn*rotv(w, ang)); uu = _unit(rotv(u, ang))
            def lift(e):
                if e["kind"] == "line":  return ("line", at(P2(e["pts"][0]), ang), at(P2(e["pts"][-1]), ang))
                if e["kind"] == "arc":   return ("arc", at(P2(e["center"]), ang), at(P2(e["start"]), ang),
                                                 at(P2(e["end"]), ang), rotv(axis2, ang))
                return ("circle", at(P2(e["center"]), ang), e["radius"])
            return {"kind": kind, "tris": ids, "planar": True,
                    "frame": (at(P2((0, 0)), ang), uu, np.cross(nrm, uu), nrm),
                    "boundary": [lift(e) for lp in loops_here for e in lp]}
        bot = add([(a, c, b) for a, b, c in cap_ids(0)])
        top = add(cap_ids(nr - 1))
        faces.append(cap_face("bottom", bot, angs[0], -1.0))
        faces.append(cap_face("top", top, angs[-1], 1.0))
    if mesh_volume(verts, tris) < 0.0:
        tris = [(a, c, b) for a, b, c in tris]
    return verts, tris, faces

# ── CSG: BSP-tree boolean subtraction ("remove material" extrusions) ──────────
CSG_EPS = 1e-5
_COPLANAR, _FRONT, _BACK, _SPANNING = 0, 1, 2, 3

class _CsgPoly:
    """Convex planar polygon. pts: [(x,y,z)…]; plane: (nx,ny,nz,w) or None if degenerate;
    tag: (source, face index) — which face of which mesh it came from."""
    __slots__ = ("pts", "plane", "tag")
    def __init__(self, pts, tag, plane=None):
        self.pts = pts; self.tag = tag
        if plane is None:
            nx = ny = nz = 0.0; n = len(pts)            # Newell normal (robust for slivers)
            for i in range(n):
                x0, y0, z0 = pts[i]; x1, y1, z1 = pts[(i+1) % n]
                nx += (y0-y1)*(z0+z1); ny += (z0-z1)*(x0+x1); nz += (x0-x1)*(y0+y1)
            L = math.sqrt(nx*nx + ny*ny + nz*nz)
            if L < 1e-12:
                plane = None
            else:
                nx, ny, nz = nx/L, ny/L, nz/L
                w = sum(nx*x + ny*y + nz*z for x, y, z in pts)/n
                plane = (nx, ny, nz, w)
        self.plane = plane
    def flipped(self):
        nx, ny, nz, w = self.plane
        return _CsgPoly(self.pts[::-1], self.tag, (-nx, -ny, -nz, -w))

def _csg_split(plane, poly, cop_front, cop_back, front, back):
    nx, ny, nz, w = plane
    ds = [nx*x + ny*y + nz*z - w for x, y, z in poly.pts]
    lo = min(ds); hi = max(ds)
    if lo >= -CSG_EPS:
        if hi <= CSG_EPS:
            px, py, pz, _ = poly.plane
            (cop_front if nx*px + ny*py + nz*pz > 0 else cop_back).append(poly)
        else:
            front.append(poly)
    elif hi <= CSG_EPS:
        back.append(poly)
    else:
        types = [_BACK if t < -CSG_EPS else _FRONT if t > CSG_EPS else _COPLANAR for t in ds]
        f, b = [], []; pts = poly.pts; n = len(pts)
        for i in range(n):
            j = (i+1) % n; ti, tj = types[i], types[j]; vi, vj = pts[i], pts[j]
            if ti != _BACK:  f.append(vi)
            if ti != _FRONT: b.append(vi)
            if (ti | tj) == _SPANNING:
                di = nx*vi[0] + ny*vi[1] + nz*vi[2]; dj = nx*vj[0] + ny*vj[1] + nz*vj[2]
                t = (w - di)/(dj - di)
                p = (vi[0] + (vj[0]-vi[0])*t, vi[1] + (vj[1]-vi[1])*t, vi[2] + (vj[2]-vi[2])*t)
                f.append(p); b.append(p)
        if len(f) >= 3: front.append(_CsgPoly(f, poly.tag, poly.plane))
        if len(b) >= 3: back.append(_CsgPoly(b, poly.tag, poly.plane))

class _CsgNode:
    """BSP tree node (iterative algorithms — no recursion limits)."""
    __slots__ = ("plane", "front", "back", "polys")
    def __init__(self, polys=None):
        self.plane = None; self.front = None; self.back = None; self.polys = []
        if polys: self.build(polys)
    def nodes(self):
        stack, out = [self], []
        while stack:
            nd = stack.pop(); out.append(nd)
            if nd.front is not None: stack.append(nd.front)
            if nd.back is not None:  stack.append(nd.back)
        return out
    def invert(self):
        for nd in self.nodes():
            nd.polys = [p.flipped() for p in nd.polys]
            if nd.plane is not None: nd.plane = tuple(-c for c in nd.plane)
            nd.front, nd.back = nd.back, nd.front
    def clip_polygons(self, polys):
        """Remove the parts of polys inside this BSP's solid."""
        out = []
        for p in polys: out.extend(self._clip_poly(p))
        return out
    def _clip_poly(self, poly):
        """Clip one polygon. A polygon that is split by a node plane but whose pieces are
        all kept is returned whole (limits the fragmentation caused by far-off planes)."""
        res, stack = [], [(0, self, poly)]
        while stack:
            op, a, b = stack.pop()
            if op == 1: res.append(a); continue            # finished result
            if op == 2:                                    # join the two halves of a split
                rb = res.pop(); rf = res.pop(); f0, b0 = b
                if len(rf) == 1 and rf[0] is f0 and len(rb) == 1 and rb[0] is b0:
                    res.append([a])
                else:
                    res.append(rf + rb)
                continue
            nd, p = a, b
            if nd.plane is None: res.append([p]); continue
            f, bk = [], []
            _csg_split(nd.plane, p, f, bk, f, bk)
            if f and bk:
                stack.append((2, p, (f[0], bk[0])))
                stack.append((0, nd.back, bk[0]) if nd.back is not None else (1, [], None))
                stack.append((0, nd.front, f[0]) if nd.front is not None else (1, [f[0]], None))
            elif f:
                stack.append((0, nd.front, f[0]) if nd.front is not None else (1, [f[0]], None))
            elif bk:
                stack.append((0, nd.back, bk[0]) if nd.back is not None else (1, [], None))
            else:
                res.append([])
        return res[0]
    def clip_to(self, bsp):
        for nd in self.nodes(): nd.polys = bsp.clip_polygons(nd.polys)
    def all_polygons(self):
        return [p for nd in self.nodes() for p in nd.polys]
    def build(self, polys):
        stack = [(self, polys)]
        while stack:
            nd, ps = stack.pop()
            if not ps: continue
            if nd.plane is None: nd.plane = _csg_pick_plane(ps)
            f, b = [], []
            for p in ps: _csg_split(nd.plane, p, nd.polys, nd.polys, f, b)
            if f:
                if nd.front is None: nd.front = _CsgNode()
                stack.append((nd.front, f))
            if b:
                if nd.back is None: nd.back = _CsgNode()
                stack.append((nd.back, b))

def _csg_pick_plane(ps, samples=6):
    """Splitting plane for a BSP node: among a few candidate polygons the one that cuts the
    fewest other polygons and divides the rest evenly (a plain "first polygon" choice
    fragments the model heavily)."""
    if len(ps) < 6: return ps[0].plane
    step = max(1, len(ps)//samples)
    cands = ps[::step][:samples]
    pts = np.array([q for p in ps for q in p.pts], float)
    cnt = np.fromiter((len(p.pts) for p in ps), int, len(ps))
    starts = np.cumsum(cnt) - cnt
    best, best_score = None, None
    for cp in cands:
        nx, ny, nz, w = cp.plane
        d = pts @ np.array([nx, ny, nz]) - w
        mx = np.maximum.reduceat(d, starts); mn = np.minimum.reduceat(d, starts)
        span = int(np.count_nonzero((mx > CSG_EPS) & (mn < -CSG_EPS)))
        nf = int(np.count_nonzero((mn >= -CSG_EPS) & (mx > CSG_EPS)))
        nb = int(np.count_nonzero((mx <= CSG_EPS) & (mn < -CSG_EPS)))
        score = 8*span + abs(nf - nb)
        if best_score is None or score < best_score: best, best_score = cp.plane, score
    return best

def csg_subtract_polys(A, B):
    """Solid A minus solid B (lists of _CsgPoly with outward orientation)."""
    a, b = _CsgNode(A), _CsgNode(B)
    a.invert(); a.clip_to(b); b.clip_to(a); b.invert(); b.clip_to(a); b.invert()
    # same polygons as a.build(b.all_polygons()); a.invert(), without splitting b by a's planes
    return [p.flipped() for p in a.all_polygons()] + [p.flipped() for p in b.all_polygons()]

def csg_union_polys(A, B):
    """Solid A plus solid B (lists of _CsgPoly with outward orientation)."""
    a, b = _CsgNode(A), _CsgNode(B)
    a.clip_to(b); b.clip_to(a); b.invert(); b.clip_to(a); b.invert()
    return a.all_polygons() + b.all_polygons()

def mesh_to_polys(verts, tris, faces, src):
    tri_face = {}
    for fi, f in enumerate(faces):
        for k in f["tris"]: tri_face[k] = fi
    out = []
    for k, (a, b, c) in enumerate(tris):
        p = _CsgPoly([tuple(verts[a]), tuple(verts[b]), tuple(verts[c])], (src, tri_face.get(k, -1)))
        if p.plane is not None: out.append(p)
    return out

def polys_to_mesh(polys, far=None):
    """Weld vertices, insert vertices lying on polygon edges (no T-junctions, so every edge
    has two triangles) and fan-triangulate each polygon (from a corner if it got no inserted
    vertices, otherwise around its centroid, so no slivers).
    far = (verts array, tris array, tags): triangles the CSG did not touch; they are kept as
    they are (only the ones next to the CSG result get the T-junction treatment).
    Returns (verts, tris, tag per triangle)."""
    key2i, V = {}, []
    fmap = {}
    if far is not None:
        FV, FT, ftags = far
        for i in np.unique(FT).tolist():
            q = FV[i]; k = (round(float(q[0]), 5), round(float(q[1]), 5), round(float(q[2]), 5))
            j = key2i.get(k)
            if j is None: j = key2i[k] = len(V); V.append((float(q[0]), float(q[1]), float(q[2])))
            fmap[i] = j
    loops = []
    for p in polys:
        ids = []
        for q in p.pts:
            k = (round(q[0], 5), round(q[1], 5), round(q[2], 5))
            i = key2i.get(k)
            if i is None: i = key2i[k] = len(V); V.append(q)
            if not ids or ids[-1] != i: ids.append(i)
        if len(ids) > 1 and ids[0] == ids[-1]: ids.pop()
        if len(ids) >= 3: loops.append((ids, p.tag))
    if not loops and far is None: return [], [], []
    A = np.asarray(V, float).reshape(-1, 3)
    cand = np.unique(np.fromiter((i for ids, _ in loops for i in ids), int))   # CSG vertices
    verts = [tuple(float(x) for x in v) for v in A]; tris, tags = [], []
    polys_ids = [(ids, tag) for ids, tag in loops]
    if far is not None and len(FT):
        lut = np.full(len(FV), -1, int)
        for i, j in fmap.items(): lut[i] = j
        FTm = lut[FT]
        touch = np.isin(FTm, cand).any(axis=1)
        for k in np.nonzero(~touch)[0].tolist():
            tris.append(tuple(FTm[k].tolist())); tags.append(ftags[k])
        polys_ids += [(FTm[k].tolist(), ftags[k]) for k in np.nonzero(touch)[0].tolist()]
    hits = _edge_vertex_hits(A, cand, polys_ids)
    for ids, tag in polys_ids:
        full = []; n = len(ids)
        for e in range(n):
            i, j = ids[e], ids[(e+1) % n]
            full.append(i)
            h = hits.get((i, j) if i < j else (j, i))
            if h: full.extend(h if i < j else h[::-1])
        if len(full) == 3:
            tris.append(tuple(full)); tags.append(tag); continue
        if len(full) == n:                       # BSP pieces are convex: fan from a corner
            P = A[full]
            fan = np.cross(P[1:-1] - P[0], P[2:] - P[0])
            ln = np.sqrt(np.einsum("ij,ij->i", fan, fan))
            if ln.min() > 1e-9*max(1.0, float(ln.max())) and np.all(fan @ fan[0] > 0):
                for e in range(1, n - 1):
                    tris.append((full[0], full[e], full[e + 1])); tags.append(tag)
                continue
        ci = len(verts); verts.append(tuple(float(x) for x in A[full].mean(axis=0)))
        for e in range(len(full)):
            tris.append((ci, full[e], full[(e+1) % len(full)])); tags.append(tag)
    if not tris: return [], [], []
    T = np.asarray(tris, int); used = np.unique(T)
    remap = np.full(len(verts), -1, int); remap[used] = np.arange(len(used))
    return [verts[i] for i in used.tolist()], [tuple(t) for t in remap[T].tolist()], tags

def _edge_vertex_hits(A, cand, polys_ids, chunk=1500000):
    """{(i, j): [vertex ids lying inside edge i→j ordered from i to j]} for the (i < j) edges of
    the polygons, looking only at the vertices cand. Vectorised: candidates per edge come from
    a sweep along the longest axis of the model."""
    E = set()
    for ids, _ in polys_ids:
        n = len(ids)
        for e in range(n):
            i, j = ids[e], ids[(e+1) % n]
            E.add((i, j) if i < j else (j, i))
    if not E or not len(cand): return {}
    E = np.array(sorted(E), int)
    P = A[cand]
    ax = int(np.argmax(P.max(0) - P.min(0)))
    order = np.argsort(P[:, ax], kind="stable")
    cand_s = cand[order]; xs = P[order, ax]
    a = A[E[:, 0]]; d = A[E[:, 1]] - a
    L2 = np.einsum("ij,ij->i", d, d)
    keep = L2 > 1e-18
    E, a, d, L2 = E[keep], a[keep], d[keep], L2[keep]
    pad = 2e-5
    ex0 = np.minimum(a[:, ax], a[:, ax] + d[:, ax]) - pad
    ex1 = np.maximum(a[:, ax], a[:, ax] + d[:, ax]) + pad
    lo = np.searchsorted(xs, ex0, "left"); hi = np.searchsorted(xs, ex1, "right")
    cnt = hi - lo
    out = {}
    start = 0
    while start < len(E):
        csum = np.cumsum(cnt[start:])
        end = start + max(1, int(np.searchsorted(csum, chunk, "right")))
        c = cnt[start:end]; tot = int(c.sum())
        if tot:
            ei = np.repeat(np.arange(start, end), c)
            off = np.arange(tot) - np.repeat(np.cumsum(c) - c, c)
            vi = cand_s[lo[ei] + off]
            w = A[vi] - a[ei]
            t = np.einsum("ij,ij->i", w, d[ei]) / L2[ei]
            ok = (t > 1e-7) & (t < 1 - 1e-7)
            ei, vi, t, w = ei[ok], vi[ok], t[ok], w[ok]
            dist = np.linalg.norm(w - t[:, None]*d[ei], axis=1)
            ok = dist < 1e-8
            ei, vi, t = ei[ok], vi[ok], t[ok]
            for k in np.lexsort((t, ei)).tolist():
                out.setdefault((int(E[ei[k], 0]), int(E[ei[k], 1])), []).append(int(vi[k]))
        start = end
    return out

def _bbox(verts):
    V = np.asarray(verts, float)
    return V.min(0), V.max(0)

def _cut_component_bounds(entry):
    """Cache bounds per connected solid so distant islands do not trigger booleans."""
    mesh = entry["base"]
    cached = entry.get("_cut_component_bounds")
    if cached is not None and cached[0] is mesh:
        return cached[1]
    vertices = np.asarray(mesh[0], dtype=float)
    triangles = np.asarray(mesh[1], dtype=int).reshape(-1, 3)
    parents = list(range(len(vertices)))
    def root(index):
        while parents[index] != index:
            parents[index] = parents[parents[index]]
            index = parents[index]
        return index
    for a, b, c in triangles:
        leader = root(a)
        parents[root(b)] = leader
        parents[root(c)] = leader
    groups = {}
    for index in np.unique(triangles):
        groups.setdefault(root(index), []).append(index)
    bounds = np.asarray([_bbox(vertices[indices]) for indices in groups.values()],
                        dtype=float).reshape(-1, 2, 3)
    entry["_cut_component_bounds"] = (mesh, bounds)
    return bounds

def _cut_overlaps(body, cutter):
    a, b = _cut_component_bounds(body), _cut_component_bounds(cutter)
    if not len(a) or not len(b):
        return False
    overlap = np.minimum(a[:, None, 1], b[None, :, 1]) - \
        np.maximum(a[:, None, 0], b[None, :, 0])
    return bool(np.any(np.all(overlap > CSG_EPS, axis=2)))

def _mesh_is_closed(tris):
    """True if no edge is open (every edge is used by an even number of triangles)."""
    T = np.asarray(tris, np.int64).reshape(-1, 3)
    if not len(T): return False
    E = np.concatenate([T[:, [0, 1]], T[:, [1, 2]], T[:, [2, 0]]])
    E.sort(axis=1)
    _, cnt = np.unique(E[:, 0]*(int(T.max()) + 1) + E[:, 1], return_counts=True)
    return bool(np.all(cnt % 2 == 0))

try:
    import manifold3d as _m3
except ImportError:
    _m3 = None

def _manifold_csg(V, T, tri_face, cutters, cutter_ids, union):
    """Boolean with the optional manifold3d library (native, much faster than the BSP).
    Returns (verts, tris, tags) like _csg_run, or None if it is unavailable or fails."""
    if _m3 is None: return None

    def solid(verts, tris, src, faces_of_tri):
        codes = (np.uint64(src + 1) << np.uint64(20)) + (np.asarray(faces_of_tri, np.int64) + 1).astype(np.uint64)
        mesh = _m3.Mesh64(np.array(verts, dtype=np.float64, order="C").reshape(-1, 3),
                          np.array(tris, dtype=np.uint64, order="C").reshape(-1, 3),
                          face_id=np.ascontiguousarray(codes, dtype=np.uint64))
        mesh.merge()
        body = _m3.Manifold(mesh)
        return body if body.status() == _m3.Error.NoError and not body.is_empty() else None

    try:
        bodies = [solid(V, T, -1, tri_face)]
        for ci in cutter_ids:
            cv, ct, cf = cutters[ci]
            ctf = np.full(len(ct), -1, np.int64)
            for fi, f in enumerate(cf):
                if f["tris"]: ctf[np.asarray(f["tris"], int)] = fi
            bodies.append(solid(cv, ct, ci, ctf))
        if any(body is None for body in bodies): return None
        result = _m3.Manifold.batch_boolean(
            bodies, _m3.OpType.Add if union else _m3.OpType.Subtract).to_mesh64()
    except Exception as ex:
        _dbg(f"manifold3d boolean failed, using BSP: {ex}")
        return None
    verts = np.asarray(result.vert_properties, float)[:, :3]
    tris = np.asarray(result.tri_verts, np.int64).reshape(-1, 3)
    codes = np.asarray(result.face_id, np.int64)
    if not len(tris) or len(codes) != len(tris): return None
    srcs = ((codes >> 20) - 1).tolist(); fis = ((codes & 0xFFFFF) - 1).tolist()
    return ([tuple(v) for v in verts.tolist()], [tuple(t) for t in tris.tolist()],
            list(zip(srcs, fis)))

def csg_subtract(base, cutters, label="cut ", union=False):
    """base / cutters: (verts, tris, faces) meshes. Returns base minus every cutter as
    (verts, tris, faces). Faces of base keep their indices (they may become empty); surfaces
    created by a cutter are appended as new faces (orientation flipped, kind = label + the
    cutter face kind).
    Only the triangles near a cutter go through the BSP; the rest of the body is left as it is
    (fast, and no fragmentation of far-away faces). If that gives no closed mesh, the whole
    body is processed. union=True adds the bodies instead of subtracting them."""
    verts, tris, faces = base
    if not tris: return base
    V = np.asarray(verts, float); T = np.asarray(tris, int).reshape(-1, 3)
    lo, hi = V.min(0), V.max(0)
    live = []
    for ci, (cv, ct, cf) in enumerate(cutters):
        if not ct: continue
        clo, chi = _bbox(cv)
        if not union and (np.any(clo > hi + CSG_EPS) or np.any(chi < lo - CSG_EPS)):
            continue   # no overlap: nothing to cut (a separate body is still added by a union)
        live.append((ci, clo, chi))
    if not live: return base
    TV = V[T]; tlo = TV.min(axis=1); thi = TV.max(axis=1)
    near = np.zeros(len(T), bool)
    for _, clo, chi in live:
        near |= np.all((tlo <= chi + 1e-3) & (thi >= clo - 1e-3), axis=1)
    cross = np.cross(TV[:, 1] - TV[:, 0], TV[:, 2] - TV[:, 0])
    far = np.nonzero(~near & (np.linalg.norm(cross, axis=1) >= 1e-12))[0]
    tri_face = np.full(len(T), -1, int)
    for fi, f in enumerate(faces):
        if f["tris"]: tri_face[np.asarray(f["tris"], int)] = fi
    res = None
    ids = [ci for ci, _, _ in live]
    v0 = mesh_volume(verts, tris)

    def valid(r):
        v1 = mesh_volume(r[0], r[1])
        vol_ok = v1 >= v0*(1 - 1e-6) if union else 0 < v1 <= v0*(1 + 1e-6)
        return _mesh_is_closed(r[1]) and vol_ok

    res = _manifold_csg(V, T, tri_face, cutters, ids, union)
    if res is not None and not valid(res): res = None
    if res is None and len(far):
        res = _csg_run(base, cutters, ids, np.nonzero(near)[0], tri_face,
                       (V, T[far], [(-1, int(tri_face[k])) for k in far]), union=union)
        if not valid(res): res = None
    if res is None:
        res = _csg_run(base, cutters, ids, np.arange(len(T)), tri_face, None, local=False, union=union)
    V2, T2, tags = res
    out = [dict(f, tris=[]) for f in faces]
    extra = {}

    def host_face(src, fi, k):
        """Union: a filler end cap lying in a planar face of the base belongs to that face."""
        a, b, c = (np.asarray(V2[i], float) for i in T2[k])
        nrm = np.cross(b - a, c - a); ln = np.linalg.norm(nrm)
        if ln < 1e-12: return None
        nrm /= ln; cen = (a + b + c)/3
        for hi, f in enumerate(faces):
            if f.get("planar") and "frame" in f:
                O, _, _, n = f["frame"]; n = np.asarray(n, float)
                if n @ nrm > 0.999 and abs((cen - np.asarray(O, float)) @ n) < 1e-4: return hi
        return None

    for k, (src, fi) in enumerate(tags):
        if src == -1 and fi >= 0:
            out[fi]["tris"].append(k); continue
        if union and src >= 0 and fi >= 0 and (src, fi) not in extra:
            if cutters[src][2][fi]["kind"].endswith((" end", " tool")):
                hi = host_face(src, fi, k)
                if hi is not None: extra[(src, fi)] = hi
        if (src, fi) not in extra:
            cf = cutters[src][2][fi] if src >= 0 and fi >= 0 else {"kind": "?", "planar": False}
            nf = {"kind": label + cf["kind"], "tris": [], "planar": bool(cf.get("planar"))}
            if cf.get("concave"): nf["concave"] = True
            if nf["planar"]:
                O, u, v, n = cf["frame"]; n2 = np.asarray(n, float) if union else -np.asarray(n, float)
                nf["frame"] = (O, u, np.cross(n2, u), n2); nf["boundary"] = cf["boundary"]
            extra[(src, fi)] = len(out); out.append(nf)
        out[extra[(src, fi)]]["tris"].append(k)
    return V2, T2, out

def _csg_run(base, cutters, cutter_ids, tri_ids, tri_face, far, local=True, union=False):
    """Subtract (or add) the cutters from the given triangles of base. Returns (verts, tris, tags).
    local: per cutter only the polygons near it go through the BSP."""
    verts, tris, faces = base
    polys = []
    for k in tri_ids.tolist():
        a, b, c = tris[k]
        p = _CsgPoly([tuple(verts[a]), tuple(verts[b]), tuple(verts[c])], (-1, int(tri_face[k])))
        if p.plane is not None: polys.append(p)
    for ci in cutter_ids:
        cv, ct, cf = cutters[ci]
        B = mesh_to_polys(cv, ct, cf, ci)
        op = csg_union_polys if union else csg_subtract_polys
        if local and len(polys) > 16:             # only polygons near this cutter take part
            clo, chi = _bbox(cv)
            pts = np.array([q for p in polys for q in p.pts], float)
            cnt = np.fromiter((len(p.pts) for p in polys), int, len(polys))
            starts = np.cumsum(cnt) - cnt
            plo = np.minimum.reduceat(pts, starts, axis=0); phi = np.maximum.reduceat(pts, starts, axis=0)
            hit = np.all((plo <= chi + 1e-3) & (phi >= clo - 1e-3), axis=1)
            rest = [p for p, h in zip(polys, hit.tolist()) if not h]
            polys = rest + op([p for p, h in zip(polys, hit.tolist()) if h], B)
        else:
            polys = op(polys, B)
    return polys_to_mesh(polys, far)

def mesh_volume(verts, tris):
    """Signed volume of a closed triangle mesh (positive for outward orientation)."""
    if not tris: return 0.0
    V = np.asarray(verts, float); T = np.asarray(tris, int)
    a, b, c = V[T[:, 0]], V[T[:, 1]], V[T[:, 2]]
    return float(np.einsum("ij,ij->i", a, np.cross(b, c)).sum()/6.0)

def mesh_surface_area(verts, tris):
    """Surface area of a triangle mesh."""
    if not tris: return 0.0
    V = np.asarray(verts, float); T = np.asarray(tris, int)
    a, b, c = V[T[:, 0]], V[T[:, 1]], V[T[:, 2]]
    return float(np.linalg.norm(np.cross(b - a, c - a), axis=1).sum()/2.0)

# ── chamfer / fillet: feature edges + cutter bodies (applied with csg_subtract) ──
FEATURE_TYPES   = ("chamfer", "fillet", "thread")
FEATURE_DEFAULTS = {"mode": "sym", "length": 2.0, "length2": 2.0, "angle": 45.0, "flip": False,
                    "radius": 2.0}

def chamfer_other_values(th, d, mode, length2=None, angle=None):
    """Derived chamfer values for two faces meeting at angle th (rad), with `d` on the first
    face: returns (second length, angle in degrees at the end of the first length)."""
    if mode == "angle" and angle is not None:
        a = math.radians(angle)
        if 0 < a < math.pi - th - 1e-3:
            return d*math.sin(a)/math.sin(th + a), angle
        return None, angle
    d2 = d if mode != "dist" or length2 is None else length2
    return d2, math.degrees(math.atan2(d2*math.sin(th), d - d2*math.cos(th)))
EDGE_SMOOTH_DOT = math.cos(math.radians(5.0))   # flatter creases are no edges
_PROBE_DIR = np.array([0.5772, 0.5781, 0.5766])

def is_feature(entry):
    return entry is not None and entry.get("type") in FEATURE_TYPES

def feature_signature(f):
    """Everything that influences the geometry of a chamfer / fillet / thread (cache key)."""
    if f["type"] == "thread": return json.dumps(f, sort_keys=True, default=_json_default)
    return json.dumps({"t": f["type"], "e": f.get("edges", []), "v": f.get("visible", True),
                       "auto": bool(f.get("auto_material", False)),
                       "p": {k: f.get(k, v) for k, v in FEATURE_DEFAULTS.items()}},
                      sort_keys=True, default=_json_default)

def mesh_edge_chains(verts, tris, faces):
    """Sharp edges of a body grouped into chains: connected mesh edges between the same two
    faces. Returns [{"faces": (f1, f2), "P": (m,3) points along the chain (closed chains
    repeat the first point), "closed", "convex", "frames": per unique point
    (t, n1, n2, u1, u2) — tangent, outward normals of both faces and the in-face directions
    pointing away from the edge —, "mid", "length"}]."""
    V = np.asarray(verts, float); T = np.asarray(tris, int).reshape(-1, 3)
    if not len(T): return []
    tri_face = np.full(len(T), -1, int)
    for fi, f in enumerate(faces):
        if f["tris"]: tri_face[np.asarray(f["tris"], int)] = fi
    N = np.cross(V[T[:, 1]] - V[T[:, 0]], V[T[:, 2]] - V[T[:, 0]])
    N /= np.maximum(np.linalg.norm(N, axis=1), 1e-30)[:, None]
    C = V[T].mean(axis=1)
    emap = {}
    for k, (a, b, c) in enumerate(T.tolist()):
        for x, y in ((a, b), (b, c), (c, a)):
            emap.setdefault((x, y) if x < y else (y, x), []).append(k)
    groups = {}
    for (a, b), ks in emap.items():
        if len(ks) != 2: continue
        k1, k2 = ks; f1, f2 = int(tri_face[k1]), int(tri_face[k2])
        if f1 == f2 or f1 < 0 or f2 < 0 or N[k1] @ N[k2] > EDGE_SMOOTH_DOT: continue
        if f1 > f2: f1, f2, k1, k2 = f2, f1, k2, k1
        groups.setdefault((f1, f2), []).append((a, b, k1, k2))
    chains = []
    for key, segs in groups.items():
        adj = {}
        for si, (a, b, _, _) in enumerate(segs):
            adj.setdefault(a, []).append(si); adj.setdefault(b, []).append(si)
        used = [False]*len(segs)
        for v0 in [v for v, l in adj.items() if len(l) != 2] + list(adj):   # open ends first
            for si0 in adj[v0]:
                if used[si0]: continue
                path, sl, v, si = [v0], [], v0, si0
                while si is not None and not used[si]:
                    used[si] = True; a, b, _, _ = segs[si]
                    v = b if a == v else a; path.append(v); sl.append(si)
                    nxt = [s for s in adj[v] if not used[s]]
                    si = nxt[0] if len(adj[v]) == 2 and nxt else None
                chains.append(_chain_data(key, path, [segs[s] for s in sl], V, N, C))
    return chains

def _chain_data(key, path, segs, V, N, C):
    P = V[path]; closed = len(path) > 2 and path[0] == path[-1]
    seg_fr = []; convex = 0
    for j, (a, b, k1, k2) in enumerate(segs):
        A, B = P[j], P[j+1]; s = _unit(B - A)
        n1, n2 = N[k1], N[k2]
        u1 = _unit(np.cross(s, n1)); u1 = u1 if (C[k1] - A) @ u1 > 0 else -u1
        u2 = _unit(np.cross(s, n2)); u2 = u2 if (C[k2] - A) @ u2 > 0 else -u2
        convex += 1 if u1 @ n2 < 0 else -1
        seg_fr.append((s, n1, n2, u1, u2))
    m = len(P) - 1 if closed else len(P); ns = len(segs)
    frames = []
    for j in range(m):
        adj = [k for k in ((j - 1) % ns if closed else j - 1, j if j < ns else -1) if k >= 0]
        t, n1, n2, u1, u2 = (_unit(sum(seg_fr[k][i] for k in adj)) for i in range(5))
        u1 = _unit(u1 - (u1 @ t)*t); u2 = _unit(u2 - (u2 @ t)*t)
        frames.append((t, n1, n2, u1, u2))
    L = np.linalg.norm(P[1:] - P[:-1], axis=1); tot = float(L.sum())
    mid = ((P[1:] + P[:-1])/2*L[:, None]).sum(0)/tot if tot > 0 else P.mean(0)
    return {"faces": key, "P": P, "closed": closed, "convex": convex > 0, "frames": frames,
            "mid": mid, "length": tot}

def chain_corners(chains):
    """Corner vertices (open chain ends): [(point, [chain indices])]."""
    out = {}
    for ci, c in enumerate(chains):
        if c["closed"]: continue
        for P in (c["P"][0], c["P"][-1]):
            k = tuple(np.round(P, 5))
            out.setdefault(k, (P, []))[1].append(ci)
    return list(out.values())

def match_edge_ref(ref, chains):
    """The chain a stored edge reference ({faces, mid}) refers to (None if gone)."""
    key = tuple(sorted(int(f) for f in ref["faces"]))
    mid = np.asarray(ref["mid"], float)
    cands = [c for c in chains if c["faces"] == key]
    normals = ref.get("normals")
    if normals is not None:
        compatible = []
        for chain in cands:
            frame = chain["frames"][len(chain["frames"]) // 2]
            if chain["closed"] == ref.get("closed") and all(
                    float(np.asarray(normal, float) @ frame[index + 1]) > EDGE_SMOOTH_DOT
                    for index, normal in enumerate(normals)):
                compatible.append(chain)
        if len(compatible) == 1:
            return compatible[0]
    if not cands:
        cands = chains
    if not cands: return None
    best = min(cands, key=lambda c: float(np.linalg.norm(c["mid"] - mid)))
    if cands is not chains and float(np.linalg.norm(best["mid"] - mid)) > 10.0:
        # Face indices can be reused for a different edge after a parametric rebuild.
        best = min(chains, key=lambda c: float(np.linalg.norm(c["mid"] - mid)))
    # only accept if midpoint is within a reasonable distance (10 mm)
    if float(np.linalg.norm(best["mid"] - mid)) > 10.0: return None
    return best

def ray_hit_count(o, d, v0, e1, e2):
    h = np.cross(d, e2); a = np.einsum('ij,ij->i', e1, h)
    ok = np.abs(a) > 1e-12
    f = np.where(ok, 1.0/np.where(ok, a, 1.0), 0.0)
    s = o - v0; u = f*np.einsum('ij,ij->i', s, h)
    q = np.cross(s, e1); v = f*(q @ d); t = f*np.einsum('ij,ij->i', e2, q)
    return int(np.count_nonzero(ok & (u >= 0) & (u <= 1) & (v >= 0) & (u+v <= 1) & (t > 1e-9)))

def _section(fr, P, feat):
    """Cross-section of the material removed at one chain point: profile points from face 1
    to face 2 (chamfer: 2 points, fillet: arc) → (points, d1, d2, L, b)."""
    t, n1, n2, u1, u2 = fr
    th = math.acos(max(-1.0, min(1.0, float(u1 @ u2))))      # angle between the two faces
    if th < 0.02 or th > math.pi - 0.02:
        raise ValueError("the faces at this edge are (almost) flat — nothing to chamfer / round")
    bis = u1 + u2; b = -_unit(bis)                             # points away from the material
    if feat["type"] == "chamfer":
        d = float(feat.get("length", 2.0))
        if d <= 0: raise ValueError("the chamfer length must be > 0")
        mode = feat.get("mode")
        if mode == "angle":
            a = math.radians(float(feat.get("angle", 45.0)))
            if not 0 < a < math.pi - th - 1e-3:
                raise ValueError(f"angle must be between 0° and {math.degrees(math.pi - th):.1f}° "
                                 "for this edge")
            da, db = d, d*math.sin(a)/math.sin(th + a)
        elif mode == "dist":
            db = float(feat.get("length2", d))
            if db <= 0: raise ValueError("the second chamfer length must be > 0")
            da = d
        else:
            da = db = d
        # "length" lies on face 1 (face 2 when flipped); the angle is measured at that end
        d1, d2 = (db, da) if feat.get("flip") else (da, db)
        pts = [P + d1*u1, P + d2*u2]
    else:
        r = float(feat.get("radius", 2.0))
        if r <= 0: raise ValueError("the fillet radius must be > 0")
        d1 = d2 = r/math.tan(th/2)
        Cc = P + _unit(bis)*(r/math.sin(th/2))
        T1, T2 = P + d1*u1, P + d2*u2
        e1 = _unit(T1 - Cc); w = T2 - Cc; e2 = _unit(w - (w @ e1)*e1)
        phi = math.pi - th
        n = curve_segments(r, phi, hi=1024)
        pts = [Cc + r*(math.cos(phi*s/n)*e1 + math.sin(phi*s/n)*e2) for s in range(n + 1)]
        pts[0], pts[-1] = T1, T2
    L = max(2.2*max(d1, d2)*math.cos(th/2), 0.05*max(d1, d2))
    return pts, d1, d2, L, b

def _surface_arrays(verts, tris):
    """(v0, e1, e2, unit normals) of a triangle mesh, for _snap_offset."""
    V = np.asarray(verts, float); T = np.asarray(tris, int).reshape(-1, 3)
    v0 = V[T[:, 0]]; e1 = V[T[:, 1]] - v0; e2 = V[T[:, 2]] - v0
    N = np.cross(e1, e2); N /= np.maximum(np.linalg.norm(N, axis=1), 1e-30)[:, None]
    return v0, e1, e2, N

def _snap_offset(q, n, smax, surface):
    """Signed distance s (|s| <= smax) from point q along the unit direction n to the nearest
    body surface whose outward normal points the same way as n, or None. A chamfer / fillet
    section is built on the tangent lines of the two faces; on a curved face those lines leave
    the surface, so the section ends are moved back onto it (the part then follows the curve
    instead of ending in a straight block)."""
    v0, e1, e2, N = surface
    use = np.nonzero(N @ n > EDGE_SMOOTH_DOT)[0]
    if not len(use): return None
    a, b, c = v0[use], e1[use], e2[use]
    h = np.cross(n, c); det = np.einsum('ij,ij->i', b, h)
    ok = np.abs(det) > 1e-12
    inv = np.where(ok, 1.0/np.where(ok, det, 1.0), 0.0)
    s = q - a; u = inv*np.einsum('ij,ij->i', s, h)
    w = np.cross(s, b); v = inv*(w @ n); t = inv*np.einsum('ij,ij->i', c, w)
    hit = ok & (u >= -1e-9) & (v >= -1e-9) & (u + v <= 1 + 1e-9) & (np.abs(t) <= smax)
    if not hit.any(): return None
    ts = t[hit]
    return float(ts[np.argmin(np.abs(ts))])

def _snap_section(sec, frame, filler, surface):
    """Move the end points of one cross-section onto the real surfaces of its two faces (see
    _snap_offset); the points between them follow smoothly. A face that is only continued as a
    plane (outer fillers) has no surface to snap to."""
    pts, d1, d2, L, b = sec
    t, n1, n2, u1, u2 = frame
    ends = ((0, n1, d1, filler != "outer1"), (len(pts) - 1, n2, d2, filler != "outer2"))
    shift = []
    for idx, n, d, real in ends:
        s = _snap_offset(np.asarray(pts[idx], float), _unit(np.asarray(n, float)),
                         0.5*d, surface) if real else None
        shift.append(np.zeros(3) if not s else s*_unit(np.asarray(n, float)))
    if not (shift[0].any() or shift[1].any()): return sec
    m = len(pts) - 1
    return ([np.asarray(p, float) + (1 - i/m)*shift[0] + (i/m)*shift[1] for i, p in enumerate(pts)],
            d1, d2, L, b)

def _simplify_closed_chain(chain, tol=1e-8):
    if not chain["closed"]:
        return chain
    points = chain["P"][:-1]
    count = len(points)
    keep = []
    for i in range(count):
        incoming = points[i] - points[(i - 1) % count]
        outgoing = points[(i + 1) % count] - points[i]
        scale = np.linalg.norm(incoming) * np.linalg.norm(outgoing)
        collinear = (scale > 1e-15 and incoming @ outgoing > 0 and
                     np.linalg.norm(np.cross(incoming, outgoing)) <= tol*scale)
        if not collinear:
            keep.append(i)
    if len(keep) < 3 or len(keep) == count:
        return chain
    P = points[keep]
    return dict(chain, P=np.vstack((P, P[0])), frames=[chain["frames"][i] for i in keep])

def edge_cutter(chain, feat, probe, filler=False, surface=None):
    """Closed tool body removing the chamfer / fillet material along one convex edge chain.
    filler: the body is added to the part instead — True for an inner (concave) chain,
    "outer1" / "outer2" for a convex chain whose corner is filled on the outside, with face 1 /
    face 2 only continued as a plane (e.g. the surface of the body below). Where another edge
    meets in a corner, chain["_miter"] = {end index: (point, normal)} ends the body on the
    mitre plane.
    probe(point) → True if the point is inside the body (decides whether the cutter may run
    past an open chain end). Returns (verts, tris, faces)."""
    chain = _simplify_closed_chain(chain)
    m = len(chain["frames"]); closed = chain["closed"]; P = chain["P"]
    frames = chain["frames"]
    if filler == "outer1":      # face 1 is only a plane extended past the edge (a body below it)
        frames = [(t, -n1, n2, -u1, u2) for t, n1, n2, u1, u2 in frames]
    elif filler == "outer2":
        frames = [(t, n1, -n2, u1, -u2) for t, n1, n2, u1, u2 in frames]
    secs = [_section(frames[j], P[j], feat) for j in range(m)]
    K0 = max(len(s[0]) for s in secs)
    if any(len(s[0]) != K0 for s in secs):         # keep the same point count on every ring
        n = K0 - 1; f2 = dict(feat, type="fillet")
        secs = [s if len(s[0]) == K0 else s for s in secs]
        if feat["type"] == "fillet":
            secs = []
            for j in range(m):
                pts, d1, d2, L, b = _section(frames[j], P[j], f2)
                if len(pts) != K0:
                    Cc = None
                    T1, T2 = pts[0], pts[-1]
                    # resample the arc polyline to K0 points
                    seg = np.asarray(pts); acc = np.r_[0, np.cumsum(np.linalg.norm(np.diff(seg, axis=0), axis=1))]
                    tt = np.linspace(0, acc[-1], n + 1)
                    pts = [np.array([np.interp(x, acc, seg[:, i]) for i in range(3)]) for x in tt]
                    pts[0], pts[-1] = T1, T2
                secs.append((pts, d1, d2, L, b))
    if surface is not None:
        secs = [_snap_section(sec, chain["frames"][j], filler, surface) for j, sec in enumerate(secs)]
    if feat["type"] == "chamfer" and not filler:
        for j in range(m if closed else m - 1):
            nxt = (j + 1) % m
            step = P[nxt] - P[j]
            for end in (0, -1):
                offset_step = np.asarray(secs[nxt][0][end]) - np.asarray(secs[j][0][end])
                if float(offset_step @ step) <= 1e-8*float(step @ step):
                    raise ValueError("the chamfer length reaches or exceeds the local radius of "
                                     "this edge; reduce the length or angle")
    rings = []
    for j, (pts, d1, d2, L, b) in enumerate(secs):
        Qa, Qb = pts[0], pts[-1]
        if filler:
            fr = frames[j]; n1, n2 = fr[1], fr[2]; u1, u2 = fr[3], fr[4]
            k = max(0.25*min(d1, d2), 0.05)
            if filler == "outer1":     # real face 2: sink into it; the base plane stays flush
                rings.append(list(pts) + [Qb - k*n2, P[j] - k*n2 + k*u2, P[j]])
            elif filler == "outer2":
                rings.append(list(pts) + [P[j], P[j] - k*n1 + k*u1, Qa - k*n1])
            else:      # inner corner: sink into the material below both faces
                rings.append(list(pts) + [Qb - k*n2, P[j] - k*(n1 + n2), Qa - k*n1])
        else:
            n1, n2 = frames[j][1:3]
            k = min(0.05*min(d1, d2), 0.05)
            if closed:
                k = min(k, 0.05*float(np.linalg.norm(P[(j + 1) % m] - P[j])))
            rings.append(list(pts) + [Qb + k*n2, P[j] + k*(n1 + n2), Qa + k*n1])
    K = len(rings[0]); M = K - 2                     # fan centre index of every ring
    if filler == "outer1": M = K - 1                 # fan from the edge point (sees the whole arc)
    elif filler == "outer2": M = K - 3
    if not closed and not filler:                    # run past free chain ends
        for j, sgn in ((0, -1.0), (m - 1, 1.0)):
            t, n1, n2, u1, u2 = chain["frames"][j]
            pts, d1, d2, L, b = secs[j]
            dmin, dmax = min(d1, d2), max(d1, d2, L)
            to = sgn*t
            if not probe(P[j] + to*0.02*dmin + _unit(u1 + u2)*0.3*dmin):
                rings[j] = [q + to*1.2*dmax for q in rings[j]]
    elif not closed and filler in ("outer1", "outer2"):
        miters = chain.get("_miter") or {}
        for j, sgn in ((0, -1.0), (m - 1, 1.0)):
            t = chain["frames"][j][0]
            if j in miters:       # corner shared with another edge: end on the mitre plane
                Pc, nm = miters[j]
                den = float(t @ nm)
                if abs(den) > 1e-6:
                    rings[j] = [q + t*(((Pc - q) @ nm - 1e-2)/den) for q in rings[j]]
                    continue
            rings[j] = [q - sgn*1e-3*t for q in rings[j]]   # a hair short of the end face
    verts = [tuple(float(x) for x in q) for ring in rings for q in ring]
    tris, kinds = [], []
    nprof = K0 - 1                                   # profile edges (chamfer: 1, fillet: arc)
    for j in range(m if closed else m - 1):
        a0, b0 = j*K, ((j + 1) % m)*K
        for i in range(K):
            i2 = (i + 1) % K
            tris += [(a0+i, a0+i2, b0+i2), (a0+i, b0+i2, b0+i)]
            kinds += ["main" if i < nprof else "tool"]*2
    if not closed:
        for a0, rev in ((0, True), ((m - 1)*K, False)):
            for i in range(K):
                i2 = (i + 1) % K
                if M in (i, i2): continue
                tris.append((a0+M, a0+i2, a0+i) if rev else (a0+M, a0+i, a0+i2)); kinds.append("end")
    if mesh_volume(verts, tris) < 0:
        tris = [(a, c, b) for a, b, c in tris]
    kind = feat["type"]
    main = {"kind": kind, "tris": [k for k, s in enumerate(kinds) if s == "main"], "planar": False}
    if filler: main["concave"] = True
    if kind == "chamfer" and m == 2 and not closed:          # straight edge → planar face
        r0, r1 = rings[0], rings[1]
        u = _unit(r1[0] - r0[0]); n = _unit(np.cross(u, r0[1] - r0[0]))
        if n @ secs[0][4] > 0: n = -n                       # cutter face normal → into the body
        main.update(planar=True, frame=(np.asarray(r0[0]), u, np.cross(n, u), n),
                    boundary=[("line", r0[0], r0[1]), ("line", r0[1], r1[1]),
                              ("line", r1[1], r1[0]), ("line", r1[0], r0[0])])
    faces = [main,
             {"kind": kind + " end", "tris": [k for k, s in enumerate(kinds) if s == "end"],
              "planar": False},
             {"kind": kind + " tool", "tris": [k for k, s in enumerate(kinds) if s == "tool"],
              "planar": False}]
    return verts, tris, faces

def _fillet_corner_blends(mesh, r):
    """After fillet edges are cut, find vertices where fillet faces meet at a sharp angle
    and subtract a sphere of radius r to create a smooth ball corner.
    Returns new mesh or original mesh if no corners found."""
    verts, tris, faces = mesh
    if not tris: return mesh
    # collect fillet face indices
    fillet_fi = {fi for fi, f in enumerate(faces)
                 if f.get("kind", "").startswith("fillet") and not f.get("concave")}
    if not fillet_fi: return mesh
    V = np.asarray(verts, float); T = np.asarray(tris, int).reshape(-1, 3)
    # find vertices shared by 2+ distinct fillet faces
    vert_faces = {}
    for fi in fillet_fi:
        for k in faces[fi]["tris"]:
            for vi in T[k]:
                vert_faces.setdefault(vi, set()).add(fi)
    # corner vertices: on 2+ fillet faces AND those fillet faces have different normals
    # compute per-face normals
    face_normals = {}
    for fi in fillet_fi:
        ns = []
        for k in faces[fi]["tris"]:
            a, b, c = T[k]
            e1 = V[b] - V[a]; e2 = V[c] - V[a]
            n = np.cross(e1, e2); ln = np.linalg.norm(n)
            if ln > 1e-12: ns.append(n / ln)
        if ns: face_normals[fi] = _unit(sum(ns))
    cutters = []
    visited = set()
    for vi, fis in vert_faces.items():
        if len(fis) < 2: continue
        # check that the fillet faces meeting here have sufficiently different normals
        norms = [face_normals[fi] for fi in fis if fi in face_normals]
        if len(norms) < 2: continue
        max_dot = max(abs(float(norms[i] @ norms[j]))
                      for i in range(len(norms)) for j in range(i+1, len(norms)))
        if max_dot > 0.98: continue  # nearly parallel faces — not a real corner
        P = V[vi]
        key = tuple(np.round(P, 4))
        if key in visited: continue
        visited.add(key)
        # sphere center: offset inward along average of face normals (pointing into solid)
        avg_n = _unit(sum(-face_normals[fi] for fi in fis if fi in face_normals))
        C = P + avg_n * r
        cutters.append(_sphere_cutter(C, r))
    if not cutters: return mesh
    result = csg_subtract(mesh, cutters, label="")
    return result if result[1] else mesh

def _sphere_cutter(C, r, n_lat=8, n_lon=8):
    """Full sphere mesh centred at C with radius r for CSG subtraction."""
    C = np.asarray(C, float)
    verts, tris = [], []
    # top and bottom poles
    verts.append(tuple(float(x) for x in C + np.array([0., 0., r])))   # 0 = north pole
    verts.append(tuple(float(x) for x in C + np.array([0., 0., -r])))  # 1 = south pole
    # latitude rings
    for i in range(1, n_lat):
        phi = math.pi * i / n_lat  # 0=north, pi=south
        for j in range(n_lon):
            theta = 2 * math.pi * j / n_lon
            x = r * math.sin(phi) * math.cos(theta)
            y = r * math.sin(phi) * math.sin(theta)
            z = r * math.cos(phi)
            verts.append(tuple(float(v) for v in C + np.array([x, y, z])))
    def ring_idx(lat, lon):  # lat 0..n_lat-2, lon 0..n_lon-1
        return 2 + lat * n_lon + (lon % n_lon)
    # north cap
    for j in range(n_lon):
        tris.append((0, ring_idx(0, j), ring_idx(0, j+1)))
    # middle bands
    for i in range(n_lat - 2):
        for j in range(n_lon):
            a, b = ring_idx(i, j), ring_idx(i, j+1)
            c, d = ring_idx(i+1, j), ring_idx(i+1, j+1)
            tris.extend([(a, b, d), (a, d, c)])
    # south cap
    for j in range(n_lon):
        tris.append((1, ring_idx(n_lat-2, j+1), ring_idx(n_lat-2, j)))
    if mesh_volume(verts, tris) < 0:
        tris = [(a, c, b) for a, b, c in tris]
    faces = [{"kind": "fillet corner", "tris": list(range(len(tris))), "planar": False}]
    return verts, tris, faces

def _rev_chain(c):
    """The same chain traversed the other way."""
    return dict(c, P=c["P"][::-1],
                frames=[(-t, n1, n2, u1, u2) for t, n1, n2, u1, u2 in c["frames"][::-1]])

def _avg_frame(f, g):
    return tuple(_unit(np.asarray(a, float) + np.asarray(b, float)) for a, b in zip(f, g))

def _chain_geom(c):
    L = np.linalg.norm(c["P"][1:] - c["P"][:-1], axis=1); tot = float(L.sum())
    mid = ((c["P"][1:] + c["P"][:-1])/2*L[:, None]).sum(0)/tot if tot > 0 else c["P"].mean(0)
    return dict(c, mid=mid, length=tot)

def merge_tangent_chains(chains, can_join=None, cos_min=math.cos(math.radians(25)), tol=1e-4):
    """Chains that touch end to end and continue smoothly (e.g. a straight edge and the arc
    next to it) are joined into one chain, so a chamfer / fillet runs through the junction as
    a single piece. A loop of such chains becomes a closed chain."""
    chains = list(chains)
    # Only chains whose end points coincide can be joined: keep every chain's two end points
    # in an array so the candidates are found with one vectorised distance test instead of
    # trying (and building reversed copies of) every pair of chains.
    E = np.array([(c["P"][0], c["P"][-1]) for c in chains], float).reshape(-1, 2, 3)
    i = 0
    while i < len(chains):
        a = chains[i]
        if a["closed"]:
            i += 1; continue
        if len(a["P"]) > 3 and np.linalg.norm(a["P"][0] - a["P"][-1]) < tol:
            ok = _tangent_joint(a, False, a, False, can_join, cos_min)   # a loop closing on itself
            if ok is not None and not ok:
                fr = list(a["frames"]); fr[0] = _avg_frame(fr[0], fr[-1])
                P = a["P"].copy(); P[-1] = P[0]
                chains[i] = _chain_geom(dict(a, P=P, frames=fr[:-1], closed=True))
                i += 1; continue
        m, j = _join_first(a, i, chains, E, can_join, cos_min, tol)
        if m is None:
            i += 1; continue
        chains[i] = m; E[i] = (m["P"][0], m["P"][-1])     # keep extending the joined chain
        del chains[j]; E = np.delete(E, j, axis=0)
        if j < i: i -= 1
    return chains

def _chain_end(c, tail):
    """(end point, neighbouring point, frame) at the tail (last point) or head of a chain."""
    P = c["P"]
    return (P[-1], P[-2], c["frames"][-1]) if tail else (P[0], P[1], c["frames"][0])

def _tangent_joint(a, ra, b, rb, can_join, cos_min):
    """Can chain a (reversed if ra) be continued by chain b (reversed if rb) — a's end on b's
    start? None if not; otherwise whether b's face order has to be swapped. Works on the end
    data only, so no reversed chain copies are built for the test."""
    if a["convex"] != b["convex"]: return None
    if can_join is not None and not can_join(a, b): return None
    common = [f for f in a["faces"] if f in b["faces"]]
    if not common: return None
    pa_, qa, fa = _chain_end(a, not ra)        # end of a after the optional reversal
    pb_, qb, fb = _chain_end(b, rb)            # start of b after the optional reversal
    if _unit(pa_ - qa) @ _unit(qb - pb_) < cos_min: return None
    s = common[0]; pa = list(a["faces"]).index(s); pb = list(b["faces"]).index(s)
    if pa != pb: fb = (fb[0], fb[2], fb[1], fb[4], fb[3])
    if fa[1] @ fb[1] < cos_min or fa[2] @ fb[2] < cos_min: return None
    return pa != pb

def _join_chains(a, ra, b, rb, swap):
    aa = _rev_chain(a) if ra else a; bb = _rev_chain(b) if rb else b
    fb = list(bb["frames"])
    if swap: fb = [(f[0], f[2], f[1], f[4], f[3]) for f in fb]
    joint = _avg_frame(aa["frames"][-1], fb[0])
    return _chain_geom(dict(aa, P=np.vstack([aa["P"], bb["P"][1:]]),
                            frames=list(aa["frames"][:-1]) + [joint] + fb[1:]))

# (end of a, start of b) indices into the (head, tail) end array for (ra, rb), in test order
_JOIN_ORDER = (((False, False), 1, 0), ((False, True), 1, 1), ((True, False), 0, 0), ((True, True), 0, 1))

def _join_first(a, i, chains, E, can_join, cos_min, tol):
    """Join a (= chains[i]) with the first open chain that continues it tangentially.
    Returns (joined chain, index of the absorbed chain) or (None, None)."""
    if not len(E): return None, None
    ea = np.asarray((a["P"][0], a["P"][-1]), float)
    D = np.linalg.norm(E[:, None, :, :] - ea[None, :, None, :], axis=-1)   # [j, end of a, end of b]
    for j in np.nonzero(D.min(axis=(1, 2)) <= tol)[0].tolist():
        b = chains[j]
        if j == i or b["closed"]: continue
        for (ra, rb), ka, kb in _JOIN_ORDER:
            if D[j, ka, kb] > tol: continue
            swap = _tangent_joint(a, ra, b, rb, can_join, cos_min)
            if swap is not None:
                return _join_chains(a, ra, b, rb, swap), j
    return None, None

def expand_tangent_chains(selected, candidates):
    """Expand selected edge segments to their full tangent-connected components."""
    expanded, claimed = [], set()
    cos_min = math.cos(math.radians(25))
    cand_E = np.array([(c["P"][0], c["P"][-1]) for c in candidates], float).reshape(-1, 2, 3)
    for chain in selected:
        if id(chain) in claimed:
            continue
        merged = chain
        members = {id(chain)}
        keep = [k for k, c in enumerate(candidates) if c is not chain]
        remaining = [candidates[k] for k in keep]
        E = cand_E[keep] if keep else cand_E[:0]
        while not merged["closed"]:
            if len(merged["P"]) > 3 and np.linalg.norm(merged["P"][0] - merged["P"][-1]) < 1e-4 \
                    and _tangent_joint(merged, False, merged, False, None, cos_min) is False:
                break                                  # the loop is complete
            m, j = _join_first(merged, -1, remaining, E, None, cos_min, 1e-4)
            if m is None: break
            merged = m
            members.add(id(remaining[j]))
            del remaining[j]; E = np.delete(E, j, axis=0)
        expanded.append(merged)
        claimed.update(members)
    return expanded

def _outer_mode(c, ref, feat, V, T, faces, others, cache=None):
    """Which face of a convex chain is continued as a plane when the corner is filled on the
    outside: "outer1" or "outer2". The wedge must not lie inside another body (the body the
    part sits on); otherwise the larger face is the one that is continued. Remembered in ref."""
    if ref.get("ext") in (1, 2): return f"outer{ref['ext']}"
    mi = len(c["frames"])//2
    t, n1, n2, u1, u2 = c["frames"][mi]
    d = float(feat.get("radius") if feat["type"] == "fillet" else feat.get("length", 2.0))
    mode = None
    if others:
        blocked = []
        for w in (_unit(u2 - u1), _unit(u1 - u2)):          # wedge direction of outer1 / outer2
            p = c["P"][mi] + w*0.3*d
            blocked.append(any(_point_in_mesh(p, om, cache) for om in others))
        if blocked[0] != blocked[1]: mode = "outer2" if blocked[0] else "outer1"
    if mode is None:
        def area(fi):
            ts = faces[fi]["tris"] if 0 <= fi < len(faces) else []
            if not ts: return 0.0
            a = V[T[ts, 0]]
            return float(np.linalg.norm(np.cross(V[T[ts, 1]] - a, V[T[ts, 2]] - a), axis=1).sum())
        mode = "outer1" if area(c["faces"][0]) >= area(c["faces"][1]) else "outer2"
    ref["ext"] = int(mode[-1])
    return mode

def _ray_arrays(mesh, cache=None):
    """(bbox lo, bbox hi, v0, e1, e2) of a mesh for point-in-mesh ray tests, or None if empty.
    cache: optional dict (keyed by id(mesh)) — reuse it while the meshes stay alive, so a body
    is converted to arrays once instead of on every probe."""
    key = id(mesh)
    if cache is not None and key in cache: return cache[key]
    V = np.asarray(mesh[0], float); T = np.asarray(mesh[1], int).reshape(-1, 3)
    arrays = None
    if len(T):
        v0 = V[T[:, 0]]
        arrays = (V.min(0), V.max(0), v0, V[T[:, 1]] - v0, V[T[:, 2]] - v0)
    if cache is not None: cache[key] = arrays
    return arrays

def _point_in_mesh(p, mesh, cache=None):
    arrays = _ray_arrays(mesh, cache)
    if arrays is None: return False
    lo, hi, v0, e1, e2 = arrays
    p = np.asarray(p, float)
    if np.any(p < lo - 1e-9) or np.any(p > hi + 1e-9): return False   # outside the bounding box
    return ray_hit_count(p, _PROBE_DIR, v0, e1, e2) % 2 == 1

def _fillet_contact_bodies(chain, radius, others, cache=None):
    if not others:
        return []
    index = len(chain["frames"]) // 2
    point = chain["P"][index]
    step = max(1e-5, min(1e-3, float(radius) * 1e-3))
    normals = chain["frames"][index][1:3]
    contacts = []
    for mesh in others:
        blocked = [_point_in_mesh(point + step * normal, mesh, cache) for normal in normals]
        if blocked[0] != blocked[1]:
            contacts.append(mesh)
    return contacts

def _fillet_contacts_body(chain, radius, others, cache=None):
    return bool(_fillet_contact_bodies(chain, radius, others, cache))

def _feature_envelope(mesh, others=()):
    """Closed convex envelope for the host body and any bodies touching its feature edge."""
    if _m3 is None:
        return None
    verts = np.vstack([np.asarray(mesh[0], float),
                       *(np.asarray(other[0], float) for other in others)])
    try:
        hull = _m3.Manifold.hull_points(np.ascontiguousarray(verts, dtype=np.float64))
        if hull.status() == _m3.Error.NoError and not hull.is_empty():
            result = hull.to_mesh64()
            hull_verts = np.asarray(result.vert_properties, float)[:, :3]
            hull_tris = np.asarray(result.tri_verts, np.int64).reshape(-1, 3)
            return (hull_verts.tolist(), hull_tris.tolist(),
                    [{"kind": "envelope", "tris": list(range(len(hull_tris))),
                      "planar": False}])
    except Exception as ex:
        _dbg(f"feature envelope hull failed: {ex}")
    return None

def _bound_inner_feature(chain, feat, V, T, faces):
    """Conservative size limit when the exact convex-envelope backend is unavailable."""
    sections = [_section(frame, point, feat)
                for frame, point in zip(chain["frames"], chain["P"])]
    limits = []
    for side, face_index in enumerate(chain["faces"]):
        face_tris = faces[face_index]["tris"] if 0 <= face_index < len(faces) else []
        if not face_tris:
            continue
        face_vertices = np.unique(T[np.asarray(face_tris, int)].ravel())
        available = [max(0.0, float(np.max((V[face_vertices] - point) @ frame[3 + side])))
                     for frame, point in zip(chain["frames"], chain["P"])]
        requested = max(section[1 + side] for section in sections)
        if requested > 1e-9:
            limits.append(min(available) / requested)
    if not limits:
        return feat
    scale = min(1.0, *limits)
    if scale >= 1.0:
        return feat
    bounded = dict(feat)
    if feat["type"] == "fillet":
        bounded["radius"] = float(feat.get("radius", 2.0)) * scale
    else:
        bounded["length"] = float(feat.get("length", 2.0)) * scale
        if feat.get("mode") == "dist":
            bounded["length2"] = float(feat.get("length2", feat["length"])) * scale
    return bounded

def _bound_outer_feature(chain, feat, mode, verts, others):
    frames = [(t, -n1, n2, -u1, u2) if mode == "outer1" else
              (t, n1, -n2, u1, -u2) for t, n1, n2, u1, u2 in chain["frames"]]
    points = np.vstack([np.asarray(verts, float),
                        *(np.asarray(other[0], float) for other in others)])
    sections = [_section(frame, point, feat)
                for frame, point in zip(frames, chain["P"])]
    limits = []
    for side in range(2):
        available = [max(0.0, float(np.max((points - point) @ frame[3 + side])))
                     for frame, point in zip(frames, chain["P"])]
        requested = max(section[1 + side] for section in sections)
        if requested > 1e-9:
            limits.append(min(available) / requested)
    if not limits:
        return feat
    scale = min(1.0, *limits)
    if scale >= 1.0:
        return feat
    scale *= 0.95
    if scale <= 1e-8:
        return None
    bounded = dict(feat)
    if feat["type"] == "fillet":
        bounded["radius"] = float(feat.get("radius", 2.0)) * scale
    else:
        bounded["length"] = float(feat.get("length", 2.0)) * scale
        if feat.get("mode") == "dist":
            bounded["length2"] = float(feat.get("length2", feat["length"])) * scale
    return bounded

def _clip_to_feature_envelope(mesh, envelope):
    """Limit an additive feature tool to the convex envelope of its host body."""
    feature_kind = next((face["kind"] for face in mesh[2]
                         if face.get("kind") in ("chamfer", "fillet")), "feature")
    outside = csg_subtract(mesh, [envelope], label="")
    if outside is mesh:
        return ([], [], [])
    if not outside[1]:
        return mesh
    volume = mesh_volume(*mesh[:2])
    outside_volume = mesh_volume(*outside[:2])
    if outside_volume <= volume * 1e-8:
        return mesh
    if outside_volume >= volume * (1.0 - 1e-6):
        return ([], [], [])
    clipped = csg_subtract(mesh, [outside], label="")
    if not clipped[1] or not _mesh_is_closed(clipped[1]):
        raise ValueError("could not contain the inner-corner feature within the body")
    if mesh_volume(*clipped[:2]) <= volume * 1e-8:
        return ([], [], [])
    for face in clipped[2]:
        if face.get("kind") == "envelope":
            face["kind"] = feature_kind
    return clipped

def apply_edge_feature(mesh, feat, chains=None, others=None, clip_outer=False):
    """Apply a chamfer / fillet entry to a body mesh. Returns (new mesh, matched chains).
    chains: the (cached) mesh_edge_chains of mesh, if known. others: meshes (verts, tris) of
    the other bodies — used by feat["outside"] to find the body the part sits on.
    Raises ValueError with a readable message if it cannot be applied."""
    if feat["type"] == "thread": return apply_thread_feature(mesh, feat), []
    verts, tris, faces = mesh
    if chains is None: chains = mesh_edge_chains(verts, tris, faces)
    matched, refs = [], []
    for ref in feat.get("edges", []):
        c = match_edge_ref(ref, chains)
        if c is None:
            raise ValueError(f"edge between faces {ref['faces'][0]} / {ref['faces'][1]} no longer exists")
        matched.append(c); refs.append(ref)
    if not matched or not feat.get("visible", True): return mesh, matched
    outside = bool(feat.get("outside"))
    automatic = feat["type"] == "fillet" and feat.get("auto_material", False)
    ray_cache = {}       # ray-test arrays of the other bodies, built once for this feature
    concave = [c for c in matched if not c["convex"]]      # inner corners: material is added
    outer, matched_cut = [], []
    for chain, ref in zip(matched, refs):
        if not chain["convex"]:
            continue
        supports = _fillet_contact_bodies(chain, feat.get("radius", 2.0), others, ray_cache) \
            if automatic else []
        add_material = bool(supports) if automatic else outside
        if add_material:
            outer.append((chain, ref))
        else:
            matched_cut.append(chain)
    V = np.asarray(verts, float); T = np.asarray(tris, int).reshape(-1, 3)
    # touching edges that continue smoothly become one chain
    matched_cut = merge_tangent_chains(expand_tangent_chains(matched_cut, chains))
    concave = merge_tangent_chains(expand_tangent_chains(concave, chains))
    if outer:
        outer = [(dict(c), r) for c, r in outer]
        for c, r in outer:
            c["_mode"] = _outer_mode(c, r, feat, V, T, faces, others, ray_cache)
            c["_vf"] = c["faces"][int(c["_mode"][-1]) - 1]
        outer = [(c, None) for c in merge_tangent_chains(
            [c for c, _ in outer], can_join=lambda a, b: a.get("_vf") == b.get("_vf"))]
    v0 = V[T[:, 0]]; e1 = V[T[:, 1]] - v0; e2 = V[T[:, 2]] - v0
    surface = _surface_arrays(V, T)
    probe = lambda p: ray_hit_count(np.asarray(p, float), _PROBE_DIR, v0, e1, e2) % 2 == 1
    # At a feature corner, extend cutters past the shared endpoint instead of capping inside it.
    corner_pts = set()
    r_corner = 0.0
    if matched_cut:
        r_corner = (float(feat.get("radius", 2.0)) if feat["type"] == "fillet" else
                    max(float(feat.get("length", 2.0)), float(feat.get("length2", 0.0))))
        ends = {}
        for c in matched_cut:
            if not c["closed"]:
                for P in (c["P"][0], c["P"][-1]):
                    k = tuple(np.round(P, 4))
                    ends[k] = ends.get(k, 0) + 1
        # shared corners within this operation
        corner_pts = {k for k, n in ends.items() if n >= 2}
        # Also extend past endpoints that meet an existing chamfer or fillet face.
        fillet_verts = set()
        for f in faces:
            if f.get("kind", "").startswith(("chamfer", "fillet")):
                for k in f.get("tris", []):
                    for vi in tris[k]: fillet_verts.add(vi)
        if fillet_verts:
            fv_pts = V[sorted(fillet_verts)]
            for c in matched_cut:
                if c["closed"]: continue
                for P in (c["P"][0], c["P"][-1]):
                    dists = np.linalg.norm(fv_pts - P, axis=1)
                    if dists.min() < r_corner * 0.5:
                        corner_pts.add(tuple(np.round(P, 4)))
    def probe_corner(p, orig_probe=probe, _r=r_corner, _cp=corner_pts):
        # at shared corners report "outside" so the cutter extends past the vertex
        if _cp:
            pa = np.asarray(p, float)
            for k in _cp:
                if np.linalg.norm(pa - np.array(k)) < _r * 0.5:
                    return False
        return orig_probe(p)
    use_probe = probe_corner if corner_pts else probe
    res = mesh
    if matched_cut:
        res = csg_subtract(res, [edge_cutter(c, feat, use_probe, surface=surface) for c in matched_cut], label="")
    envelope = _feature_envelope(mesh) if concave else None
    fillers = []
    fallback_cuts = []
    for c in concave:
        tool_feat = feat if envelope is not None else _bound_inner_feature(c, feat, V, T, faces)
        filler = edge_cutter(c, tool_feat, probe, filler=True, surface=surface)
        if envelope is not None:
            filler = _clip_to_feature_envelope(filler, envelope)
        if filler[1]:
            fillers.append(filler)
    if outer:
        ends = {}
        for ci, (c, _) in enumerate(outer):
            if not c["closed"]:
                for j in (0, len(c["P"]) - 1):
                    ends.setdefault(tuple(np.round(c["P"][j], 4)), []).append((ci, j))
        for lst in ends.values():      # two edges meet in a corner: both end on the mitre plane
            if len(lst) != 2 or lst[0][0] == lst[1][0]: continue
            walls = []
            for ci, j in lst:
                c = outer[ci][0]; fr = c["frames"][j]
                walls.append(np.asarray(fr[2] if c["_mode"] == "outer1" else fr[1], float))
            nm = walls[0] - walls[1]
            if np.linalg.norm(nm) < 1e-6: continue
            nm = _unit(nm)
            for (ci, j), s in zip(lst, (1.0, -1.0)):
                c = outer[ci][0]
                c.setdefault("_miter", {})[j] = (np.asarray(c["P"][j], float), s*nm)
        for c, _ in outer:
            supports = _fillet_contact_bodies(c, feat.get("radius", 2.0), others, ray_cache) \
                if clip_outer and automatic else []
            tool_feat = _bound_outer_feature(c, feat, c["_mode"], V, supports) \
                if clip_outer else feat
            filler = edge_cutter(c, tool_feat, probe, filler=c["_mode"], surface=surface) \
                if tool_feat is not None else ([], [], [])
            if clip_outer:
                fill_envelope = _feature_envelope(mesh, supports)
                if fill_envelope is not None:
                    filler = _clip_to_feature_envelope(filler, fill_envelope)
            if clip_outer and filler[1]:
                added = csg_subtract(filler, [res], label="")
                added_volume = mesh_volume(*added[:2]) if added[1] else 0.0
                if added_volume <= mesh_volume(*filler[:2]) * 1e-8:
                    filler = ([], [], [])
            if filler[1]:
                fillers.append(filler)
            elif clip_outer:
                fallback_cuts.append(edge_cutter(c, feat, probe, surface=surface))
    if fallback_cuts:
        res = csg_subtract(res, fallback_cuts, label="")
    if fillers:
        res = csg_subtract(res, fillers, label="", union=True)
    if not res[1]: raise ValueError("the result would be empty")
    return res, matched

def _feat_chains_cached(entry):
    """mesh_edge_chains for an entry, cached by mesh identity.
    Uses the final solid (post-CSG, post-features) so shared edges between
    connected extrusions are visible on the body the user actually sees."""
    mesh = (entry["solid"][0], entry["solid"][1], entry.get("faces", []))
    key = (id(mesh[0]), id(mesh[1]))
    cache = entry.get("_ec")
    if cache and cache[0] == key: return cache[1]
    chains = mesh_edge_chains(*mesh)
    entry["_ec"] = (key, chains)
    return chains

def bridge_stack_levels(objects):
    """{id(entry): level} for bodies that lie underneath a visible Bridge result. The Bridge
    fuses its source bodies, so their surfaces coincide with the Bridge surface; the deeper a
    body sits in such a stack the further it is pushed back in the depth buffer (and the
    higher its level), so coincident surfaces never fight each other."""
    level, claimed = {}, {}
    for bridge in reversed(objects):
        if bridge.get("source_format") != "bridge" or not entry_visible(bridge):
            continue
        sources = [s["entry"] for s in bridge.get("bridge_sources", []) if s.get("entry") is not None]
        lvl = level.get(id(bridge), 0)
        for source in sources:
            if id(source) in claimed: lvl = max(lvl, claimed[id(source)] + 1)
        if lvl: level[id(bridge)] = lvl
        for source in sources:
            claimed[id(source)] = lvl
            level[id(source)] = max(level.get(id(source), 0), lvl + 1)
    return level

def _is_feature_body(entry):
    return (entry.get("type") == "extrusion" and not entry.get("cut")) or \
           (entry.get("type") == "imported" and entry.get("source_format") == "bridge")

def tri_normal(v0,v1,v2):
    ax,ay,az=v1[0]-v0[0],v1[1]-v0[1],v1[2]-v0[2]
    bx,by,bz=v2[0]-v0[0],v2[1]-v0[1],v2[2]-v0[2]
    nx=ay*bz-az*by; ny=az*bx-ax*bz; nz=ax*by-ay*bx
    l=math.sqrt(nx*nx+ny*ny+nz*nz) or 1.
    return nx/l,ny/l,nz/l

def seg_dist_px(px,py,ax,ay,bx,by):
    dx,dy=bx-ax,by-ay; l2=dx*dx+dy*dy
    if l2==0: return math.hypot(px-ax,py-ay)
    t=max(0,min(1,((px-ax)*dx+(py-ay)*dy)/l2))
    return math.hypot(px-(ax+t*dx),py-(ay+t*dy))


def _projected_segment_hit(point, start, end):
    distances, nearest, _index = _projected_segments_hit(
        point, np.asarray(((start, end),), dtype=float))
    return distances, nearest


def _projected_segments_hit(point, segments):
    segments = np.asarray(segments, dtype=float).reshape(-1, 2, 2)
    if not len(segments):
        return float("inf"), None, None
    point = np.asarray(point, dtype=float)
    starts = segments[:, 0]
    directions = segments[:, 1] - starts
    lengths = np.einsum("ij,ij->i", directions, directions)
    fractions = np.clip(np.einsum("ij,ij->i", point - starts, directions) /
                        np.maximum(lengths, 1e-20), 0.0, 1.0)
    nearest = starts + directions * fractions[:, None]
    distances = np.linalg.norm(nearest - point, axis=1)
    index = int(distances.argmin())
    return float(distances[index]), nearest[index], index


def _projected_points_hit(point, points):
    points = np.asarray(points, dtype=float).reshape(-1, 2)
    if not len(points):
        return float("inf"), None
    distances = np.linalg.norm(points - np.asarray(point, dtype=float), axis=1)
    index = int(distances.argmin())
    return float(distances[index]), index


def _projected_polyline_hit(point, points):
    points = np.asarray(points, dtype=float).reshape(-1, 2)
    if len(points) < 2:
        return float("inf"), None, None
    segments = np.stack((points[:-1], points[1:]), axis=1)
    return _projected_segments_hit(point, segments)


def _projected_circle_hit(point, center, radius):
    point, center = np.asarray(point, dtype=float), np.asarray(center, dtype=float)
    direction = point - center
    distance = float(np.linalg.norm(direction))
    if distance <= 1e-12:
        direction = np.array((1.0, 0.0))
    else:
        direction /= distance
    nearest = center + direction * float(radius)
    return abs(distance - float(radius)), nearest


def _dimension_measurement(kind, target=None, points=None, axis_tolerance=0.0):
    """Shared measured values and default orientation for sketch and drawing dimensions."""
    if kind in ("radius", "diameter"):
        if isinstance(target, Circle):
            radius = float(target.radius)
        elif isinstance(target, Arc):
            radius = float(target.radius())
        elif isinstance(target, dict) and "radius" in target:
            radius = float(target["radius"])
        else:
            raise ValueError("A radius or diameter requires a circle or arc")
        return {"value": radius if kind == "radius" else 2.0 * radius}
    if kind == "length":
        if isinstance(target, Segment):
            value = float(target.length())
            first, second = target.v0.xy(), target.v1.xy()
        elif isinstance(target, dict):
            if "segment" in target:
                first, second = target["segment"]
            elif "curve" in target and target.get("linear"):
                first, second = target["curve"][0], target["curve"][-1]
            else:
                raise ValueError("A length requires a straight segment")
            value = float(np.linalg.norm(np.asarray(second) - np.asarray(first)))
        elif points is not None and len(points) == 2:
            first, second = points
            first = first.xy() if isinstance(first, Vertex) else first
            second = second.xy() if isinstance(second, Vertex) else second
            delta = np.asarray(second, dtype=float) - np.asarray(first, dtype=float)
            dx, dy = abs(float(delta[0])), abs(float(delta[1]))
            orientation = "H" if dy < axis_tolerance else \
                "V" if dx < axis_tolerance else "D"
            value = dx if orientation == "H" else dy if orientation == "V" else \
                float(np.linalg.norm(delta))
            return {"value": value, "orientation": orientation}
        else:
            raise ValueError("A length requires a segment or two points")
        return {"value": value}
    if kind == "angle" and points is not None and len(points) == 3:
        converted = [point.xy() if isinstance(point, Vertex) else point for point in points]
        vertex, ray_a, ray_b = (np.asarray(point, dtype=float) for point in converted)
        a, b = ray_a - vertex, ray_b - vertex
        denominator = float(np.linalg.norm(a) * np.linalg.norm(b))
        if denominator <= 1e-12:
            raise ValueError("An angle requires three distinct points")
        value = math.degrees(math.acos(float(np.clip((a @ b) / denominator, -1.0, 1.0))))
        return {"value": value}
    raise ValueError(f"Unsupported dimension kind: {kind}")

def min_seg_dist(p, A, B):
    """Smallest distance from point p (2,) to the segments A[i]→B[i] (N,2)."""
    if len(A) == 0: return float("inf")
    d = B - A; l2 = (d*d).sum(1); l2 = np.where(l2 == 0, 1e-12, l2)
    t = np.clip(((p - A)*d).sum(1)/l2, 0.0, 1.0)
    c = A + d*t[:, None]
    return float(np.hypot(c[:, 0]-p[0], c[:, 1]-p[1]).min())

def seg_intersection(s1, s2):
    """Crossing point of two segments (within both), or None."""
    (ax, ay), (bx, by) = s1.v0.xy(), s1.v1.xy()
    (cx, cy), (dx, dy) = s2.v0.xy(), s2.v1.xy()
    rx, ry, sx, sy = bx-ax, by-ay, dx-cx, dy-cy
    den = rx*sy - ry*sx
    if abs(den) < 1e-12: return None
    t = ((cx-ax)*sy - (cy-ay)*sx)/den
    u = ((cx-ax)*ry - (cy-ay)*rx)/den
    if -1e-9 <= t <= 1+1e-9 and -1e-9 <= u <= 1+1e-9:
        return (ax + t*rx, ay + t*ry)
    return None

# ── curves / intersections (scissor tool) ─────────────────────────────────────
TRIM_TOL = 1e-5   # mm — points closer than this to a curve lie on it

def curve_of(e):
    """("line", A, B) for segments, ("circle", C, r, span) for circles (span None) and arcs
    (span = (start angle, CCW sweep))."""
    if isinstance(e, Segment): return ("line", e.v0.xy(), e.v1.xy())
    if isinstance(e, Circle):  return ("circle", e.center.xy(), e.radius, None)
    return ("circle", e.center.xy(), e.radius(), e.angles())

def curve_end(cv):
    """Parameter at the end of a curve (length for lines, sweep for arcs, 2π for circles)."""
    if cv[0] == "line": return math.hypot(cv[2][0]-cv[1][0], cv[2][1]-cv[1][1])
    return cv[3][1] if cv[3] else 2*math.pi

def curve_param(cv, P):
    """Position of P along cv: mm from the start for lines, CCW angle from the start for
    arcs, angle in [0, 2π) for full circles."""
    if cv[0] == "line":
        (ax, ay), (bx, by) = cv[1], cv[2]; L = math.hypot(bx-ax, by-ay) or 1e-12
        return ((P[0]-ax)*(bx-ax) + (P[1]-ay)*(by-ay))/L
    a0 = cv[3][0] if cv[3] else 0.0
    return (math.atan2(P[1]-cv[1][1], P[0]-cv[1][0]) - a0) % (2*math.pi)

def curve_point(cv, s):
    """Point at parameter s (inverse of curve_param)."""
    if cv[0] == "line":
        (ax, ay), (bx, by) = cv[1], cv[2]; L = math.hypot(bx-ax, by-ay) or 1e-12
        return (ax + (bx-ax)*s/L, ay + (by-ay)*s/L)
    a = s + (cv[3][0] if cv[3] else 0.0)
    return (cv[1][0] + cv[2]*math.cos(a), cv[1][1] + cv[2]*math.sin(a))

def _within_curve(cv, P, tol=TRIM_TOL):
    """Is P (lying on the underlying line / circle) inside the bounded curve?"""
    if cv[0] == "circle" and cv[3] is None: return True
    s, end = curve_param(cv, P), curve_end(cv)
    if cv[0] == "line": return -tol <= s <= end + tol
    t = tol/max(cv[2], 1e-9)
    return s <= end + t or s >= 2*math.pi - t

def dist_to_curve(cv, P):
    if cv[0] == "line":
        return seg_dist_px(P[0], P[1], cv[1][0], cv[1][1], cv[2][0], cv[2][1])
    C, r = cv[1], cv[2]
    if _within_curve(cv, P, 0.0):
        return abs(math.hypot(P[0]-C[0], P[1]-C[1]) - r)
    ends = (curve_point(cv, 0.0), curve_point(cv, curve_end(cv)))
    return min(math.hypot(P[0]-x, P[1]-y) for x, y in ends)

def _raw_intersections(c1, c2):
    """Intersections of the underlying infinite lines / full circles (tangency counts)."""
    if c1[0] == "line" and c2[0] == "line":
        (ax, ay), (bx, by) = c1[1], c1[2]; (cx, cy), (dx, dy) = c2[1], c2[2]
        rx, ry, sx, sy = bx-ax, by-ay, dx-cx, dy-cy
        den = rx*sy - ry*sx
        if abs(den) < 1e-12: return []
        t = ((cx-ax)*sy - (cy-ay)*sx)/den
        return [(ax+t*rx, ay+t*ry)]
    if c1[0] == "circle" and c2[0] == "line": c1, c2 = c2, c1
    if c1[0] == "line":
        (ax, ay), (bx, by) = c1[1], c1[2]; (cx, cy), r = c2[1], c2[2]
        L = math.hypot(bx-ax, by-ay)
        if L < 1e-12: return []
        ux, uy = (bx-ax)/L, (by-ay)/L
        t0 = (cx-ax)*ux + (cy-ay)*uy
        fx, fy = ax+t0*ux, ay+t0*uy                     # foot of the centre on the line
        d = math.hypot(cx-fx, cy-fy)
        if abs(d - r) < TRIM_TOL: return [(fx, fy)]     # tangent
        if d > r: return []
        h = math.sqrt(r*r - d*d)
        return [(fx-h*ux, fy-h*uy), (fx+h*ux, fy+h*uy)]
    (x0, y0), r0 = c1[1], c1[2]; (x1, y1), r1 = c2[1], c2[2]
    d = math.hypot(x1-x0, y1-y0)
    if d < 1e-12 or d > r0+r1+TRIM_TOL or d < abs(r0-r1)-TRIM_TOL: return []
    a = (r0*r0 - r1*r1 + d*d)/(2*d)
    h = math.sqrt(max(0.0, r0*r0 - a*a))
    mx, my = x0 + a*(x1-x0)/d, y0 + a*(y1-y0)/d
    if h < TRIM_TOL: return [(mx, my)]
    ux, uy = -(y1-y0)/d, (x1-x0)/d
    return [(mx+h*ux, my+h*uy), (mx-h*ux, my-h*uy)]

def curve_intersections(c1, c2):
    """Intersection points of two bounded curves."""
    return [P for P in _raw_intersections(c1, c2) if _within_curve(c1, P) and _within_curve(c2, P)]

def ray_tris(o, d, v0, e1, e2):
    """Möller–Trumbore against many triangles; returns (nearest t, triangle index) or None."""
    if len(v0) == 0: return None
    h = np.cross(d, e2)
    a = np.einsum('ij,ij->i', e1, h)
    ok = np.abs(a) > 1e-12
    f = np.where(ok, 1.0/np.where(ok, a, 1.0), 0.0)
    s = o - v0
    u = f*np.einsum('ij,ij->i', s, h)
    q = np.cross(s, e1)
    v = f*(q @ d)
    t = f*np.einsum('ij,ij->i', e2, q)
    hit = ok & (u >= 0) & (u <= 1) & (v >= 0) & (u+v <= 1) & (t > 1e-9)
    if not hit.any(): return None
    k = int(np.argmin(np.where(hit, t, np.inf)))
    return float(t[k]), k

def sketch_polylines(sk, include_reference=False):
    """[(pts2d, construction)] for every drawable curve of a sketch."""
    out = [([s.v0.xy(), s.v1.xy()], s.construction) for s in sk.segments
           if include_reference or not s.reference]
    for c in sk.circles:
        if include_reference or not c.reference:
            pts = circle_pts(c.center.x, c.center.y, c.radius)
            out.append((pts + [pts[0]], c.construction))
    out += [(a.tess(), a.construction) for a in sk.arcs if include_reference or not a.reference]
    for ellipse in sk.ellipses:
        if include_reference or not ellipse.reference:
            pts = ellipse.tess()
            out.append((pts + [pts[0]], ellipse.construction))
    return out

# ── scene tree helpers ────────────────────────────────────────────────────────
def entry_visible(entry):
    """Display visibility belongs to the object, not its support/dependency chain."""
    return entry is None or entry.get("visible", True)

def entry_children(entry, objects):
    if entry["type"] == "sketch":
        return [o for o in objects if o["type"] == "extrusion" and o.get("parent") is entry]
    if entry["type"] == "surface":
        return [o for o in objects if o["type"] in ("sketch", "surface") and o.get("parent") is entry]
    if entry["type"] in ("extrusion", "imported"):
        children = [o for o in objects if o["type"] == "sketch" and o.get("parent") is entry]
        children += [o for o in objects if o["type"] == "extrusion" and o.get("parent") is entry]
        children += [o for o in objects if o["type"] == "feature" and o.get("parent") is entry]
        children += [o for o in objects if o["type"] == "technical_drawing" and o.get("parent") is entry]
        children += [o for o in objects if o["type"] == "surface" and o.get("parent") is entry]
        children += [o for o in objects if o.get("source_format") == "bridge" and
                     o.get("parent") is entry]
        return children
    return []


def sketch_selected_in_3d(sketch, selected):
    """A sketch is highlighted only when the sketch itself is selected."""
    return sketch.get("type") == "sketch" and sketch is selected


def sketch_preview_visible(sketch, selected):
    """Keep hidden profile sketches hidden unless the sketch itself is selected."""
    if entry_visible(sketch):
        return True
    return sketch_selected_in_3d(sketch, selected)


def related_extrusion_ids(selected, objects):
    """Select one extrusion, or all bodies of an explicitly grouped assembly component."""
    if selected is None or selected.get("type") != "extrusion" or selected.get("cut"):
        return set()
    component = selected.get("_component")
    if component is None:
        return {id(selected)}
    return {id(entry) for entry in objects
            if entry.get("type") == "extrusion" and not entry.get("cut")
            and entry.get("_component") is component}


def entry_descendants(entry, objects):
    out = []
    for ch in entry_children(entry, objects):
        out.append(ch); out += entry_descendants(ch, objects)
    return out

# ── measurement tool ──────────────────────────────────────────────────────────
MEASURE_TOL = 1e-3          # mm — two corners closer than this are the same point
MEASURE_ANGLE_TOL = 0.5     # degrees — "parallel" / "perpendicular" tolerance

def measure_highlight_color(entry):
    """Inverted body colour; mid-grey bodies (where inversion barely differs) get black / white."""
    col = np.asarray(entry.get("color", (0.5, 0.8, 1.0))[:3], float)
    inv = 1.0 - col
    if float(np.linalg.norm(inv - col)) < 0.3:
        return (0.0, 0.0, 0.0) if float(col @ (0.299, 0.587, 0.114)) > 0.5 else (1.0, 1.0, 1.0)
    return tuple(round(float(c), 4) for c in inv)

def measure_entries(objects):
    """Visible solid bodies whose edges and corners can be measured."""
    return [o for o in objects
            if o["type"] in ("extrusion", "imported") and not o.get("cut") and not o.get("preview")
            and entry_visible(o) and o.get("solid", (None, []))[1]]

def gear_centerline_points(entry):
    """World-space Z-axis centerline extending 3 mm beyond each end of a gear or rack."""
    parameters = entry.get("gear_parameters")
    if not parameters:
        return None
    rotation = _import_rotation_matrix(entry.get("gear_rotation", (0.0, 0.0, 0.0)))
    position = np.asarray(entry.get("gear_position", (0.0, 0.0, 0.0)), dtype=float)
    height = float(entry.get("height", parameters.get("thickness", 10.0)))
    axis = rotation[:, 2]
    extension = 3.0
    return np.asarray((position - extension * axis,
                       position + (height + extension) * axis))

def gear_centerline_measure_chain(entry):
    """Measurement-compatible straight edge for a generated gear's centerline datum."""
    points = gear_centerline_points(entry)
    if points is None:
        return None
    delta = points[1] - points[0]
    return {"P": points, "closed": False, "length": float(np.linalg.norm(delta)),
            "faces": (), "mid": points.mean(axis=0)}

def entry_corners(entry):
    """Corner points (open edge chain ends) of a body; cached per solid."""
    cache = entry.get("_mc")
    if cache and cache[0] is entry["solid"]: return cache[1]
    corners = [P for P, _ in chain_corners(_feat_chains_cached(entry))]
    entry["_mc"] = (entry["solid"], corners)
    return corners

def _edge_axis(P, closed):
    """(start, end, unit direction) when the edge is a straight line, else None."""
    if closed or len(P) < 2: return None
    A, B = P[0], P[-1]; L = float(np.linalg.norm(B - A))
    if L < 1e-9: return None
    d = (B - A)/L
    off = P - A; perp = off - np.outer(off @ d, d)
    if float(np.linalg.norm(perp, axis=1).max()) > 1e-4*L + 1e-6: return None
    return A, B, d

def measure_edge_item(entry, chain):
    P = np.asarray(chain["P"], float); closed = bool(chain["closed"])
    return {"kind": "edge", "entry": entry, "solid": entry["solid"], "P": P, "closed": closed,
            "length": float(chain["length"]), "faces": tuple(chain["faces"]),
            "axis": _edge_axis(P, closed), "label": P[len(P)//2],
            "key": ("e", id(entry), tuple(chain["faces"]),
                    tuple(np.round(chain["mid"], 3).tolist()))}

def measure_point_item(entry, P):
    P = np.asarray(P, float)
    return {"kind": "point", "entry": entry, "solid": entry["solid"], "P": P, "label": P,
            "key": ("p", tuple(np.round(P, 3).tolist()))}

def _angle_deg(u, v):
    return math.degrees(math.acos(max(-1.0, min(1.0, float(u @ v)))))

def _xy_unit(v):
    n = math.hypot(float(v[0]), float(v[1]))
    return None if n < 1e-9 else np.array([v[0]/n, v[1]/n, 0.0])

def _closest_seg_seg(p1, q1, p2, q2):
    """Closest points of the segments p1→q1 and p2→q2."""
    d1, d2, r = q1 - p1, q2 - p2, p1 - p2
    a, e, f = float(d1 @ d1), float(d2 @ d2), float(d2 @ r)
    eps = 1e-12
    if a <= eps and e <= eps: s = t = 0.0
    elif a <= eps: s = 0.0; t = min(1.0, max(0.0, f/e))
    else:
        c = float(d1 @ r)
        if e <= eps: t = 0.0; s = min(1.0, max(0.0, -c/a))
        else:
            b = float(d1 @ d2); den = a*e - b*b
            s = min(1.0, max(0.0, (b*f - c*e)/den)) if den > eps else 0.0
            t = (b*s + f)/e
            if t < 0.0:   t = 0.0; s = min(1.0, max(0.0, -c/a))
            elif t > 1.0: t = 1.0; s = min(1.0, max(0.0, (b - c)/a))
    return p1 + d1*s, p2 + d2*t

def _closest_polylines(PA, PB):
    """Closest points of two polylines (every vertex against every segment of the other)."""
    best = None
    for X, Y, flip in ((PA, PB, False), (PB, PA, True)):
        A = Y[:-1]; D = Y[1:] - A; L2 = np.maximum((D*D).sum(1), 1e-30)
        for x in X:
            t = np.clip(((x - A)*D).sum(1)/L2, 0.0, 1.0)
            C = A + D*t[:, None]; dist = np.linalg.norm(C - x, axis=1); k = int(dist.argmin())
            if best is None or dist[k] < best[0]:
                best = (float(dist[k]), (C[k], x) if flip else (x, C[k]))
    return best[1]

def _leaving_dir(P, S):
    """Unit direction in which an edge leaves its end point S."""
    seq = P if np.linalg.norm(P[0] - S) <= np.linalg.norm(P[-1] - S) else P[::-1]
    for q in seq[1:]:
        v = q - S; n = float(np.linalg.norm(v))
        if n > 1e-9: return v/n
    return None

def analyse_edge_pair(a, b):
    """Relationship of two measured edges (connected / same face / parallel / perpendicular)
    with 3-D and 2-D (projection onto the XY plane) values. None when they are unrelated."""
    ends_a = [] if a["closed"] else [a["P"][0], a["P"][-1]]
    ends_b = [] if b["closed"] else [b["P"][0], b["P"][-1]]
    shared = next((p for p in ends_a for q in ends_b
                   if float(np.linalg.norm(p - q)) < MEASURE_TOL), None)
    rel = []
    if shared is not None: rel.append("connected")
    if a["entry"] is b["entry"] and set(a["faces"]) & set(b["faces"]): rel.append("same face")
    ax_a, ax_b = a["axis"], b["axis"]
    parallel = perpendicular = False
    if ax_a and ax_b:
        c = abs(float(ax_a[2] @ ax_b[2]))
        parallel = c > math.cos(math.radians(MEASURE_ANGLE_TOL))
        perpendicular = c < math.sin(math.radians(MEASURE_ANGLE_TOL))
        if parallel: rel.append("parallel")
        if perpendicular: rel.append("perpendicular")
    if not rel: return None
    ang3 = ang2 = None
    if shared is not None:
        u, v = _leaving_dir(a["P"], shared), _leaving_dir(b["P"], shared)
        if u is not None and v is not None:
            ang3 = _angle_deg(u, v)
            u2, v2 = _xy_unit(u), _xy_unit(v)
            if u2 is not None and v2 is not None: ang2 = _angle_deg(u2, v2)
    elif ax_a and ax_b:
        ang3 = math.degrees(math.acos(min(1.0, abs(float(ax_a[2] @ ax_b[2])))))
        u2, v2 = _xy_unit(ax_a[2]), _xy_unit(ax_b[2])
        if u2 is not None and v2 is not None:
            ang2 = math.degrees(math.acos(min(1.0, abs(float(u2 @ v2)))))
    if parallel:
        m = ax_b[0] - ax_a[0]; off = m - (m @ ax_a[2])*ax_a[2]       # offset between the two lines
    else:
        p, q = _closest_seg_seg(ax_a[0], ax_a[1], ax_b[0], ax_b[1]) if ax_a and ax_b \
               else _closest_polylines(a["P"], b["P"])
        off = q - p
    return {"relations": rel, "angle3d": ang3, "angle2d": ang2, "offset": off,
            "dist3d": float(np.linalg.norm(off)), "dist2d": math.hypot(float(off[0]), float(off[1]))}

def analyse_point_pair(p, q):
    d = q - p; dxy = math.hypot(float(d[0]), float(d[1]))
    return {"delta": d, "dist3d": float(np.linalg.norm(d)), "dist2d": dxy,
            "angle_xy": math.degrees(math.atan2(float(d[1]), float(d[0]))) if dxy > 1e-9 else None,
            "elevation": math.degrees(math.atan2(float(d[2]), dxy)) if float(np.linalg.norm(d)) > 1e-9 else None}

def _fit_circle(P, closed):
    """(centre, radius) when an edge chain is a circle / arc, else None."""
    Q = np.asarray(P, float)
    if closed and len(Q) > 1 and float(np.linalg.norm(Q[0] - Q[-1])) < 1e-9: Q = Q[:-1]
    if len(Q) < 4: return None
    # Only polygon corners lie on the true circle; CSG splits insert collinear points on chords.
    a = Q - np.roll(Q, 1, 0); b = np.roll(Q, -1, 0) - Q
    turn = np.linalg.norm(np.cross(a, b), axis=1)
    keep = turn > 1e-7*np.linalg.norm(a, axis=1)*np.linalg.norm(b, axis=1)
    if not closed: keep[0] = keep[-1] = True
    K = Q[keep]
    if len(K) < (12 if closed else 4): return None
    c0 = K.mean(0); _, s, vt = np.linalg.svd(K - c0)
    if s[0] < 1e-12 or s[-1] > 1e-6*s[0]: return None
    x = (K - c0) @ vt[0]; y = (K - c0) @ vt[1]
    (cx, cy, c), *_ = np.linalg.lstsq(np.column_stack([x, y, np.ones_like(x)]), x*x + y*y, rcond=None)
    cx, cy = cx/2, cy/2
    d = np.hypot(x - cx, y - cy); r = float(d.mean())
    if r < 1e-9 or float(np.abs(d - r).max()) > 1e-4*r + 1e-6: return None
    return c0 + cx*vt[0] + cy*vt[1], r

def measurement_report(items):
    """(detail lines for the measurement panel, one-line summary for the status bar)."""
    edges = [i for i in items if i["kind"] == "edge"]
    points = [i for i in items if i["kind"] == "point"]
    if not items:
        return [], "Measure: click edges or corners (several possible) | RMB: deselect"
    L, S = [], []
    ang = lambda v: "n/a" if v is None else f"{v:.2f}°"
    for n, e in enumerate(edges, 1):
        _fmt = lambda v: f"{v:.3f}".rstrip('0').rstrip('.')
        L.append(f"E{n}  length {_fmt(e['length'])} mm")
        S.append(f"E{n} {_fmt(e['length'])} mm")
        if e["axis"]:
            A, B, _ = e["axis"]; d = B - A
            dxy = math.hypot(float(d[0]), float(d[1]))
            L.append(f"    straight  ΔX {d[0]:.3f}  ΔY {d[1]:.3f}  ΔZ {d[2]:.3f}")
            L.append(f"    2D (XY): length {dxy:.3f} mm" +
                     (f", angle {ang(math.degrees(math.atan2(float(d[1]), float(d[0]))))}" if dxy > 1e-9
                      else ", vertical"))
        else:
            fit = _fit_circle(e["P"], e["closed"])
            dia = 2.0*fit[1] if fit else None
            curve_label = "closed curve" if e["closed"] else "arc"
            if dia:
                r_val = dia / 2
                L.append(f"    {curve_label}  R {_fmt(r_val)} mm  Ø {_fmt(dia)} mm")
                S[-1] += f"  R {_fmt(r_val)} mm"
            else:
                L.append(f"    {curve_label}")
    for i in range(len(edges)):
        for j in range(i + 1, len(edges)):
            r = analyse_edge_pair(edges[i], edges[j])
            if r is None: continue
            o = r["offset"]
            L.append(f"E{i+1} – E{j+1}  ({', '.join(r['relations'])})")
            L.append(f"    3D: angle {ang(r['angle3d'])}, distance {r['dist3d']:.3f} mm")
            L.append(f"    2D (XY): angle {ang(r['angle2d'])}, ΔX {o[0]:.3f}, ΔY {o[1]:.3f}, "
                     f"distance {r['dist2d']:.3f} mm")
            S.append(f"E{i+1}–E{j+1} 3D ∠{ang(r['angle3d'])} d {r['dist3d']:.3f} mm · "
                     f"2D ∠{ang(r['angle2d'])} ΔX {o[0]:.3f} ΔY {o[1]:.3f}")
    for n, p in enumerate(points, 1):
        x, y, z = p["P"]
        L.append(f"P{n}  X {x:.3f}  Y {y:.3f}  Z {z:.3f}")
    pairs = [(i, j) for i in range(len(points)) for j in range(i + 1, len(points))
             if len(points) <= 4 or j == i + 1]
    for i, j in pairs:
        r = analyse_point_pair(points[i]["P"], points[j]["P"]); d = r["delta"]
        L.append(f"P{i+1} – P{j+1}  distance {r['dist3d']:.3f} mm")
        L.append(f"    ΔX {d[0]:.3f}  ΔY {d[1]:.3f}  ΔZ {d[2]:.3f}")
        L.append(f"    2D (XY): distance {r['dist2d']:.3f} mm, angle {ang(r['angle_xy'])} to +X")
        L.append(f"    3D: elevation {ang(r['elevation'])} to the XY plane")
        S.append(f"P{i+1}–P{j+1} {r['dist3d']:.3f} mm (ΔX {d[0]:.3f} ΔY {d[1]:.3f} ΔZ {d[2]:.3f}) "
                 f"∠{ang(r['angle_xy'])}")
    for i in range(1, len(points) - 1):
        u = points[i-1]["P"] - points[i]["P"]; v = points[i+1]["P"] - points[i]["P"]
        nu, nv = float(np.linalg.norm(u)), float(np.linalg.norm(v))
        if nu > 1e-9 and nv > 1e-9:
            a3 = _angle_deg(u/nu, v/nv)
            L.append(f"∠ P{i} – P{i+1} – P{i+2}  {a3:.2f}°")
            S.append(f"∠P{i}P{i+1}P{i+2} {a3:.2f}°")
    return L, "Measure | " + " | ".join(S)

# ── View3D ────────────────────────────────────────────────────────────────────
def dimension_drag_step(pixels_per_mm, fine=False):
    target = min(1.0, 16.0 / max(float(pixels_per_mm), 1e-9))
    decade = 10.0 ** math.floor(math.log10(target))
    step = max(value * decade for value in (1.0, 2.0, 5.0)
               if value * decade <= target * (1.0 + 1e-9))
    return max(0.01, step / 10.0 if fine else step)


class View3D(QGLWidget):
    planeSelected = pyqtSignal(str)
    faceSelected  = pyqtSignal(object, int)   # extrusion entry, face index
    bridgeFaceSelected = pyqtSignal(object, int)
    surfaceSelected = pyqtSignal(object)
    surfaceReferenceSelected = pyqtSignal(object, object)
    sigSelInfo    = pyqtSignal(str)
    sigCancelSketch = pyqtSignal()
    sigMeasureChanged = pyqtSignal()          # measurement selection changed

    def __init__(self, app_state, parent=None):
        gl_format = QGLFormat.defaultFormat()
        gl_format.setSampleBuffers(True)
        gl_format.setSamples(4)
        super().__init__(gl_format, parent)
        self.state     = app_state
        self.rot_x     = -54.735610317245346
        self.rot_z     = -135.0
        self.zoom      = 300.0
        self.pan       = [0.0, 0.0]
        self._last_pos = None
        self._mode     = MODE_NORMAL
        self._ortho_plane = None   # "XY"/"XZ"/"YZ" when in sketch ortho view
        self.grid_mm   = DEFAULT_GRID
        self.snap_mm   = DEFAULT_SNAP
        self.sel_snap  = True   # snap the grabbed point to the grid while dragging
        self.scale     = PX_PER_MM  # px/mm for 2-D overlay
        self.offset    = QPointF(0, 0)
        self._cursor_mm = (0.0, 0.0)
        self._snap_vtx  = None    # existing vertex the cursor is snapped to (sketch mode)
        self._pt_snap_segs = []   # lines the Point-tool cursor is snapped onto
        self._trim_hover = None   # scissor preview polyline (mm)
        self._pan_start = None
        self._pan_off0  = None
        # select-mode drag state
        self._drag_seg  = None
        self._drag_vtx  = None
        self._drag_curve = None   # ("circle"|"arc", index) being dragged in select mode
        self._drag_text = None
        self._text_resize = None
        self._drag_last = None
        self._rband_start = None
        self._rband_active = False
        self._rband_cur   = None   # raw pixel pos during rubber-band
        self._sel_info    = ""
        self._main_window = None  # set by MainWindow after construction
        self.show_fps = False
        self._fps_clock = QElapsedTimer()
        self._fps_frames = collections.deque()
        self._fps_font = QFont("Consolas", 10)
        self._fps_timer = QTimer(self)
        self._fps_timer.setTimerType(Qt.PreciseTimer)
        self._fps_timer.setInterval(16)
        self._fps_timer.timeout.connect(self.update)
        self._pending_buffer_deletes = []
        # hover / picking state
        self._hover3d   = None    # ("axis",i)|("origin",None)|("plane",name)|("face",(e,fi))|("sketch",e)
        self._hover_pick_pos = None
        self._hover_pick_timer = QTimer(self)
        self._hover_pick_timer.setSingleShot(True)
        self._hover_pick_timer.setInterval(16)
        self._hover_pick_timer.timeout.connect(self._process_hover_pick)
        self._hover2d   = None    # ("vtx",i)|("seg",i)|("circle",i)|("arc",i)|("axis","x"/"y")|("origin",None)|("dim",c)
        self._mvp       = None    # projection·modelview captured in paintGL
        self._press_pos = None
        self._arc_last_ang = None
        self._dim_hits  = []      # [(constraint, kind, data, text polygon, dim-line pts)] from last paint
        self._drag_dim  = None    # dimension being repositioned
        self._drag_origin = None  # {vertex: (x,y)} at drag start
        self._drag_start_mm = None
        self._drag_anchor = None
        self._feat_entry = None   # extrusion whose edges can be picked (feature mode)
        self._feat_mode  = False  # True while chamfer/fillet panel is open
        self._angle_mode = False
        self._angle_entry = None
        self._angle_faces = set()
        self._angle_pivot = None
        self._bridge_mode = False
        self._bridge_faces = []
        self._hover_chain = None  # index into mesh_edge_chains of the hovered chain
        self._hover_chain_entry = None  # entry the hovered chain belongs to
        self._measure_mode = False  # True while the Measure tool is active
        self._meas_sel = []         # measured edges / corners in selection order
        self._meas_hover = None     # edge / corner under the cursor (Measure tool)
        self._dimension_drag = None
        self._dimension_hovered = False
        self._grid_cache = None     # (key, pixmap) of the rendered sketch grid
        self.setMouseTracking(True)
        self.setFocusPolicy(Qt.StrongFocus)
        self.setMinimumSize(600, 500)

    def _default_cursor(self):
        return QCursor(Qt.CrossCursor if self._mode in (MODE_SELPLANE, MODE_THREADPICK)
                       else Qt.ArrowCursor)

    def set_mode(self, mode, plane=None):
        self._cancel_hover_pick()
        self._mode = mode
        self._ortho_plane = plane if plane in PLANE_VIEW else None
        self._hover3d = None; self._hover2d = None
        self._meas_hover = None
        self._grid_cache = None
        self.setCursor(self._default_cursor())
        self.update()

    def _queue_hover_pick(self, pos):
        self._hover_pick_pos = QPointF(pos)
        if not self._hover_pick_timer.isActive():
            self._hover_pick_timer.start()

    def _process_hover_pick(self):
        pos = self._hover_pick_pos
        self._hover_pick_pos = None
        if pos is not None and self._last_pos is None:
            self._set_hover3d(self._pick3d(pos))

    def _cancel_hover_pick(self):
        self._hover_pick_timer.stop()
        self._hover_pick_pos = None

    def _thread_faces(self):
        """(entry, face index) of the cylinders the thread tool has chosen so far."""
        mw = self._main_window
        if mw is None: return []
        targets = [*getattr(mw, "_thread_targets", ()), getattr(mw, "_thread_target_current", None)]
        return [(t["entry"], t["face"]) for t in targets if t is not None and t.get("face") is not None]

    def _thread_start_point(self, pos):
        """World point under the cursor for a thread start: corner, edge or a point on the chosen cylinder face."""
        item = self._measure_pick(pos)
        if item is not None:
            if item["kind"] == "point": return item["P"]
            S, valid = self._project(item["P"])
            dist = np.where(valid, np.hypot(S[:, 0] - pos.x(), S[:, 1] - pos.y()), np.inf)
            return item["P"][int(dist.argmin())]
        target = self._main_window._thread_active_target()
        origin, direction = self._ray(pos)
        hit = self._pick_face(origin, direction)
        if hit is not None and target is not None and hit[1] is target["entry"] and hit[2] == target["face"]:
            return origin + hit[0] * direction
        return None

    def _thread_click(self, pos):
        """A click picks the start on the chosen cylinder, else chooses the clicked cylinder."""
        mw = self._main_window
        point = self._thread_start_point(pos)
        if point is not None and mw._on_thread_start_picked(point): return
        origin, direction = self._ray(pos)
        hit = self._pick_face(origin, direction)
        if hit is not None and hit[2] is not None and hit[2] >= 0:
            mw._on_thread_surface_selected(hit[1], hit[2])
        else:
            mw._st("Click a cylindrical face, then a corner, an edge or a point on it")

    # ── measure tool ──────────────────────────────────────────────────────────
    def set_measure_mode(self, on):
        self._measure_mode = bool(on)
        self._meas_hover = None
        if self._meas_sel:
            self._meas_sel = []; self.sigMeasureChanged.emit()
        self._hover3d = None
        self.setCursor(self._default_cursor())
        self.update()

    def measure_clear(self):
        if self._meas_sel:
            self._meas_sel = []; self.sigMeasureChanged.emit()
        self.update()

    def _meas_valid(self, it):
        entry = it["entry"]
        return entry.get("solid") is it["solid"] and entry_visible(entry) and \
            any(o is entry for o in self.state.get("objects", []))

    def measure_validate(self):
        """Drop measured items whose body changed, was hidden or deleted."""
        keep = [s for s in self._meas_sel if self._meas_valid(s)]
        if len(keep) != len(self._meas_sel):
            self._meas_sel = keep; self.sigMeasureChanged.emit(); self.update()

    def _measure_pick(self, pos, thr_edge=8.0, thr_point=10.0):
        """Corner (wins) or edge under the cursor as a measurement item, else None."""
        if self._mvp is None: return None
        p = np.array([pos.x(), pos.y()], dtype=float)
        entries = measure_entries(self.state.get("objects", []))
        if self._angle_mode and self._angle_entry is not None and self._angle_entry.get("cut"):
            entries = [self._angle_entry] if entry_visible(self._angle_entry) else []
        target = self._main_window._thread_active_target() if self._mode == MODE_THREADPICK else None
        if target is not None: entries = [o for o in entries if o is target["entry"]]
        corners = [(entry, P) for entry in entries for P in entry_corners(entry)]
        if corners:
            S, valid = self._project(np.array([P for _, P in corners]))
            dist = np.where(valid, np.hypot(S[:, 0] - p[0], S[:, 1] - p[1]), np.inf)
            for k in np.argsort(dist):
                if dist[k] >= thr_point: break
                if not self._occluded(corners[k][1]): return measure_point_item(*corners[k])
        cands = []
        centerline_cands = []
        for entry in entries:
            chains = _feat_chains_cached(entry)
            if chains:
                S, valid = self._project(np.concatenate([c["P"] for c in chains], axis=0))
                off = 0
                for c in chains:
                    n = len(c["P"]); sl = slice(off, off + n); off += n
                    hit = self._chain_screen_hit(p, c["P"], S[sl], valid[sl])
                    if hit and hit[0] < thr_edge: cands.append((hit[0], hit[1], entry, c))
            centerline = gear_centerline_measure_chain(entry)
            if centerline is not None:
                S, valid = self._project(centerline["P"])
                hit = self._chain_screen_hit(p, centerline["P"], S, valid)
                if hit and hit[0] < thr_edge:
                    centerline_cands.append((hit[0], hit[1], entry, centerline))
        best = self._first_visible(cands)
        if centerline_cands:
            centerline_best = min(centerline_cands, key=lambda candidate: candidate[0])
            if best is None or centerline_best[0] <= best[0]:
                best = centerline_best
        return measure_edge_item(best[2], best[3]) if best else None

    def _measure_hover_update(self, pos):
        it = self._measure_pick(pos)
        if (it["key"] if it else None) == (self._meas_hover["key"] if self._meas_hover else None):
            return
        self._meas_hover = it
        self.setCursor(QCursor(Qt.PointingHandCursor if it else Qt.ArrowCursor))
        self.update()

    def _measure_click(self, pos):
        it = self._measure_pick(pos)
        if it is None or any(s["key"] == it["key"] for s in self._meas_sel): return
        self._meas_sel.append(it)
        self.sigMeasureChanged.emit(); self.update()

    def _measure_rclick(self, pos):
        """RMB on a measured item removes it; RMB anywhere else clears the whole measurement."""
        it = self._measure_pick(pos)
        if it is not None and any(s["key"] == it["key"] for s in self._meas_sel):
            self._meas_sel = [s for s in self._meas_sel if s["key"] != it["key"]]
            self.sigMeasureChanged.emit(); self.update()
        else:
            self.measure_clear()

    def _draw_measure(self):
        glPushAttrib(GL_ENABLE_BIT | GL_COLOR_BUFFER_BIT | GL_LINE_BIT | GL_POINT_BIT)
        glEnable(GL_BLEND); glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        glDisable(GL_LIGHTING); glDisable(GL_DEPTH_TEST)
        ne = npt = 0
        font = QFont("Arial", 10, QFont.Bold)
        for it in [s for s in self._meas_sel if self._meas_valid(s)]:
            if it["kind"] == "edge": ne += 1; label = f"E{ne}"
            else:                    npt += 1; label = f"P{npt}"
            self._draw_measure_item(it, label, font)
        hov = self._meas_hover       # hovered item is emphasised, also when it is already selected
        if hov is not None and self._meas_valid(hov):
            self._draw_measure_item(hov, None, hot=True)
        glLineWidth(1); glPointSize(1); glEnable(GL_DEPTH_TEST); glEnable(GL_LIGHTING)
        glPopAttrib()

    def _draw_measure_item(self, it, label, font=None, hot=False):
        glColor3f(*measure_highlight_color(it["entry"]))
        if it["kind"] == "edge":
            glLineWidth(7 if hot else 4)
            glBegin(GL_LINE_STRIP)
            for pt in it["P"]: glVertex3f(*pt)
            glEnd()
        else:
            glPushAttrib(GL_ENABLE_BIT)
            glDisable(GL_MULTISAMPLE)
            glPointSize(15 if hot else 11)
            glBegin(GL_POINTS); glVertex3f(*it["P"]); glEnd()
            glPopAttrib()
        if label:
            glColor3f(1.0, 1.0, 1.0)
            self.renderText(float(it["label"][0]), float(it["label"][1]), float(it["label"][2]),
                            label, font)

    # ── coordinate helpers (2-D overlay) ─────────────────────────────────────
    def to_px(self, mm):
        cx = self.width()/2  + self.offset.x()
        cy = self.height()/2 + self.offset.y()
        return QPointF(cx + mm[0]*self.scale, cy - mm[1]*self.scale)

    def to_mm(self, px):
        cx = self.width()/2  + self.offset.x()
        cy = self.height()/2 + self.offset.y()
        return ((px.x()-cx)/self.scale, (cy-px.y())/self.scale)

    def snap(self, mm):
        if not self.sel_snap: return (mm[0], mm[1])
        s = self.snap_mm
        return (round(mm[0]/s)*s, round(mm[1]/s)*s)

    def snap_point(self, px, exclude=()):
        """Snap target for a cursor position: an existing sketch point within VERTEX_SNAP_PX
        screen pixels wins, then enabled reference curves while drawing, then the grid.
        Returns (mm, vertex or None)."""
        sk = self.state.get("active_sketch")
        if sk is not None:
            best, best_d = None, VERTEX_SNAP_PX
            box_vertices = {v for group in sk.text_groups for v in group.box_vertices}
            for v in box_vertices:
                if v in exclude: continue
                pp = self.to_px(v.xy())
                d = math.hypot(px.x()-pp.x(), px.y()-pp.y())
                if d < best_d: best, best_d = v, d
            if best is not None: return best.xy(), best
            best_d = VERTEX_SNAP_PX
            for v in sk.vertices:
                if v in box_vertices: continue
                if v in exclude: continue
                if hasattr(v, "reference_level") and not self._level_reference_available(v):
                    continue
                pp = self.to_px(v.xy())
                d = math.hypot(px.x()-pp.x(), px.y()-pp.y())
                if d < best_d: best, best_d = v, d
            if best is not None: return best.xy(), best
            if self.state.get("sketch_view_state", {}).get("mode") == "draw" and not exclude:
                raw = self.to_mm(px)
                nearest, distance = None, 8.0
                for element in sk.segments + sk.circles + sk.arcs:
                    if not element.reference or not self._level_reference_available(element):
                        continue
                    curve = curve_of(element)
                    candidate = curve_point(curve, curve_param(curve, raw))
                    if not _within_curve(curve, candidate):
                        candidate = min((curve_point(curve, 0), curve_point(curve, curve_end(curve))),
                                        key=lambda point: math.dist(raw, point))
                    d = math.dist(raw, candidate) * self.scale
                    if d < distance:
                        nearest, distance = candidate, d
                if nearest is not None:
                    return nearest, None
        return self.snap(self.to_mm(px)), None

    def point_snap(self, px, thr=8.0):
        """Snap for the Point tool (existing points are deliberately NOT targets):
        crossing of two editable lines (incl. support lines) within thr px → that crossing;
        else the nearest line within thr px → a spot on it (grid-aligned along H/V lines);
        else the grid. Returns (mm, [segments the point lies on])."""
        sk = self.state.get("active_sketch")
        raw = self.to_mm(px)
        if sk is None: return self.snap(raw), []
        segs = sk.segments
        best = None
        for i in range(len(segs)):
            if segs[i].reference: continue
            for j in range(i+1, len(segs)):
                if segs[j].reference: continue
                X = seg_intersection(segs[i], segs[j])
                if X is None: continue
                ends = (segs[i].v0, segs[i].v1, segs[j].v0, segs[j].v1)
                if any(math.hypot(X[0]-v.x, X[1]-v.y) < 1e-6 for v in ends):
                    continue                       # crossing at an endpoint = an existing point
                pp = self.to_px(X); d = math.hypot(pp.x()-px.x(), pp.y()-px.y())
                if d < thr*1.5 and (best is None or d < best[0]): best = (d, X, [segs[i], segs[j]])
        if best: return best[1], best[2]
        si = self._near_seg(sk, px, thr)
        if si is not None and not segs[si].reference:
            s = segs[si]; (ax, ay), (bx, by) = s.v0.xy(), s.v1.xy()
            g = self.snap(raw)
            if s.axis() == 'H':   P = (min(max(g[0], min(ax, bx)), max(ax, bx)), ay)
            elif s.axis() == 'V': P = (ax, min(max(g[1], min(ay, by)), max(ay, by)))
            else:
                dx, dy = bx-ax, by-ay; l2 = dx*dx+dy*dy or 1e-12
                t = min(1.0, max(0.0, ((raw[0]-ax)*dx + (raw[1]-ay)*dy)/l2))
                P = (ax+t*dx, ay+t*dy)
            return P, [s]
        return self.snap(raw), []

    # ── GL ────────────────────────────────────────────────────────────────────
    def initializeGL(self):
        _GL_INFO[:] = [
            f"{name:<12}: {s.decode(errors='replace') if s else '?'}"
            for name, key in (("GL vendor", GL_VENDOR), ("GL renderer", GL_RENDERER),
                              ("GL version", GL_VERSION))
            for s in [glGetString(key)]]
        glEnable(GL_DEPTH_TEST)
        glEnable(GL_MULTISAMPLE)
        glEnable(GL_LINE_SMOOTH); glHint(GL_LINE_SMOOTH_HINT, GL_NICEST)
        glEnable(GL_POINT_SMOOTH); glHint(GL_POINT_SMOOTH_HINT, GL_NICEST)
        glEnable(GL_LIGHTING); glEnable(GL_LIGHT0)
        glEnable(GL_COLOR_MATERIAL)
        glColorMaterial(GL_FRONT_AND_BACK, GL_AMBIENT_AND_DIFFUSE)
        glLightfv(GL_LIGHT0, GL_POSITION, [1,2,3,0])
        glLightfv(GL_LIGHT0, GL_DIFFUSE,  [1,1,1,1])
        glLightfv(GL_LIGHT0, GL_AMBIENT,  [0.3,0.3,0.3,1])
        glClearColor(0.11, 0.11, 0.13, 1)

    def resizeGL(self, w, h):
        glViewport(0, 0, w, h or 1)
        glMatrixMode(GL_PROJECTION); glLoadIdentity()
        gluPerspective(45, w/(h or 1), 0.1, 10000)
        glMatrixMode(GL_MODELVIEW)

    def paintGL(self):
        self._flush_buffer_deletes()
        glClearColor(0.11, 0.11, 0.13, 1)   # re-assert after QPainter may dirty it
        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT)
        glLoadIdentity()
        if self._ortho_plane:
            self._setup_ortho_camera()
        else:
            gluLookAt(0,0,self.zoom, 0,0,0, 0,1,0)
            glTranslatef(self.pan[0], self.pan[1], 0)
            glRotatef(self.rot_x, 1,0,0)
            glRotatef(self.rot_z, 0,0,1)
        mv = np.array(glGetDoublev(GL_MODELVIEW_MATRIX), dtype=float).reshape(4, 4).T
        pj = np.array(glGetDoublev(GL_PROJECTION_MATRIX), dtype=float).reshape(4, 4).T
        self._mvp = pj @ mv
        self._draw_axes()
        self._draw_solids()
        self._draw_surfaces()
        if self._mode == MODE_SELPLANE:
            self._draw_plane_selectors()
        self._draw_gear_centerlines()
        if self._measure_mode or self._mode == MODE_THREADPICK: self._draw_measure()
        self._draw_sketch_previews()
        self._draw_dimension_handle()
        if self.show_fps:
            self._draw_fps()

    def release_buffers(self, entry):
        for key in ("_vbo_id", "_edge_vbo_id"):
            buffer = entry.pop(key, None)
            if buffer is not None:
                self._pending_buffer_deletes.append(buffer)

    def _flush_buffer_deletes(self):
        if self._pending_buffer_deletes:
            glDeleteBuffers(len(self._pending_buffer_deletes), self._pending_buffer_deletes)
            self._pending_buffer_deletes.clear()

    def set_show_fps(self, enabled):
        self.show_fps = bool(enabled)
        self._fps_frames.clear()
        self._fps_clock.start()
        if self.show_fps:
            self._fps_timer.start()
        else:
            self._fps_timer.stop()
        self.update()

    def _frame_rate_text(self):
        now = self._fps_clock.nsecsElapsed() / 1e9
        frames = self._fps_frames
        while frames and now - frames[0] > 1.0:
            frames.popleft()
        frames.append(now)
        elapsed = now - frames[0]
        if len(frames) < 2 or elapsed <= 0.0:
            return "FPS: --"
        return f"FPS: {(len(frames) - 1) / elapsed:.1f}"

    def _draw_fps(self, painter=None):
        text = self._frame_rate_text()
        if painter is not None:
            painter.save()
            painter.setFont(self._fps_font)
            painter.setPen(QColor(235, 235, 240))
            painter.drawText(QRectF(12, 10, max(0, self.width() - 24), 24),
                             Qt.AlignRight | Qt.AlignVCenter, text)
            painter.restore()
        else:
            width = QFontMetricsF(self._fps_font).horizontalAdvance(text)
            glPushAttrib(GL_ALL_ATTRIB_BITS)
            try:
                glDisable(GL_LIGHTING)
                glColor3f(235 / 255, 235 / 255, 240 / 255)
                self.renderText(max(12, int(self.width() - width - 12)), 26, text, self._fps_font)
            finally:
                glPopAttrib()

    def _dimension_handle_data(self, all_handles=False):
        mw = self._main_window
        if mw is None or self._mvp is None or self._mode not in (MODE_NORMAL, MODE_THREADPICK):
            return [] if all_handles else None
        surface_preview = getattr(self, "_surface_preview", None)
        if self._angle_mode and mw._angle_draft_ready():
            entry = mw._angle_draft_entry
            vertices = np.asarray(mw._angle_draft_base[0], dtype=float)
            axis = _unit(np.asarray(entry["parent"]["sketch"].frame[3], dtype=float))
            pivot = np.asarray(mw._angle_draft_pivot, dtype=float)
            axial = np.abs((vertices - pivot) @ axis)
            end = vertices[int(np.argmax(axial))]
            radial = end - pivot - axis * float((end - pivot) @ axis)
            if float(np.linalg.norm(radial)) < 1e-10:
                helper = np.eye(3)[int(np.argmin(np.abs(axis)))]
                radial = np.cross(axis, helper)
            tangent = _unit(np.cross(axis, radial))
            handle_specs = [(end, tangent, mw.sp_angle_draft,
                             "Draft angle", "°", 1.0)]
        elif getattr(mw, "_surface_panel_active", False) and surface_preview is not None:
            parent = mw._surface_reference_parent
            face = mw._surface_reference_face
            if mw.cb_surface_reference.currentData() == "origin":
                parent, face = None, None
            tangent_position = [spin.value() for spin in mw.sp_surface_position]
            try:
                base_frame = mw._surface_frame(parent, face, (0, 0, 0), (0, 0, 0),
                                               tangent_position)
            except ValueError:
                return [] if all_handles else None
            anchor = np.asarray(surface_preview["frame"][0], float)
            handle_specs = [
                (anchor, np.asarray(base_frame[1], float), mw.sp_surface_offset[0],
                 "Surface X offset", " mm", 1.0),
                (anchor, np.asarray(base_frame[2], float), mw.sp_surface_offset[1],
                 "Surface Y offset", " mm", 1.0),
            ]
        elif self._mode == MODE_THREADPICK and mw._thread_targets and \
                mw.cb_thread_extent.currentData() != "whole" and mw.sp_thread_length.isEnabled():
            target = mw._thread_targets[-1]
            start = float(target["start"])
            low, high = target["limits"]
            sign = 1.0 if high - start >= start - low else -1.0
            anchor = target["center"] + (start + sign * mw.sp_thread_length.value()) * target["axis"]
            handle_specs = [(anchor, sign * target["axis"], mw.sp_thread_length,
                             "Thread length", " mm", 1.0)]
        elif self._feat_mode and mw._feat_chains:
            chain = mw._feat_chains[0]
            index = len(chain["frames"]) // 2
            point = chain["mid"] if not chain["closed"] and len(chain["frames"]) == 2 else chain["P"][index]
            frame = chain["frames"][index]
            feature = dict(mw._feat_params(), type=mw._feat_type)
            try:
                profile = _section(frame, point, feature)[0]
            except ValueError:
                return [] if all_handles else None
            if mw._feat_type == "fillet":
                anchor = np.asarray(profile[len(profile) // 2])
                axis = _unit(frame[3] + frame[4])
                name = "Fillet radius"
            else:
                flipped = feature.get("flip", False)
                anchor = np.asarray(profile[-1 if flipped else 0])
                axis = frame[4 if flipped else 3]
                name = "Chamfer length"
            control = mw.sp_feat_size
            factor = 1.0
            handle_specs = [(anchor, axis, control, name, " mm", factor)]
            if mw._feat_type == "chamfer" and feature.get("mode") == "dist":
                anchor = np.asarray(profile[0 if flipped else -1])
                axis = frame[3 if flipped else 4]
                handle_specs.append((anchor, axis, mw.sp_feat_len2,
                                     "Chamfer length 2", " mm", factor))
            elif mw._feat_type == "chamfer" and feature.get("mode") == "angle":
                anchor = np.asarray(profile[0 if flipped else -1])
                axis = frame[3 if flipped else 4]
                handle_specs.append((anchor, axis, mw.sp_feat_angle,
                                     "Chamfer angle", "°", factor))
        elif mw._ext_pending is not None and not mw._dock_ext.isHidden():
            sketch = mw._ext_pending["sketch"]
            loops = sketch.profile_loop_edges()
            points = np.asarray([point for loop in loops for point in _flatten_loop(loop)[0]])
            if not len(points):
                return [] if all_handles else None
            center = (points.min(axis=0) + points.max(axis=0)) / 2.0
            frame = tuple(np.asarray(vector, float) for vector in sketch.frame)
            if mw._ext_ring_mode:
                if not loops:
                    return [] if all_handles else None
                rotation = math.radians(mw.sp_ring_rotation.value())
                if rotation:
                    origin, horizontal, vertical, normal = frame
                    pivot = origin + center[0]*horizontal + center[1]*vertical
                    frame = tuple(_rotate_about([vector], pivot if index == 0 else 0.0,
                                                 normal, rotation)[0]
                                  for index, vector in enumerate(frame))
                key_setting = mw.cb_ring_axis.currentData() or "u"
                try:
                    axis_origin, axis, _, key = ring_axis(
                        loops, frame, key_setting, mw.sp_ring_r.value(),
                        mw.cb_ring_ref.currentData() or "center")
                except ValueError:
                    return [] if all_handles else None
                origin, horizontal, vertical, normal = frame
                profile_center = origin + center[0]*horizontal + center[1]*vertical
                helical = mw.chk_ring_helical.isChecked()
                angle_value = mw.sp_ring_angle.value()
                angle = math.radians(360.0 * mw.sp_ring_turns.value() if helical else
                                     min(abs(angle_value), 360.0))
                sweep_direction = mw.cb_ext_dir.currentData() or "one"
                if sweep_direction == "sym":
                    start_angle, end_angle = -angle/2.0, angle/2.0
                else:
                    sweep_forward = angle_value >= 0.0 or helical
                    forward = sweep_forward != (sweep_direction == "rev")
                    start_angle, end_angle = (0.0, angle) if forward else (-angle, 0.0)
                if mw.cb_ext_extent.currentData() != "dist":
                    last_extent = getattr(mw, "_last_ext", None)
                    if last_extent is not None:
                        start_angle = last_extent[0]
                        end_angle = start_angle + math.radians(last_extent[1])
                middle_angle = (start_angle + end_angle) / 2.0
                radius_anchor = _rotate_about([profile_center], axis_origin, axis,
                                              middle_angle)[0]
                side = vertical if key in ("u", "-u") else horizontal
                radius_vector = side - _rotate_about([side], np.zeros(3), axis,
                                                      middle_angle)[0]
                handle_specs = [(radius_anchor, radius_vector, mw.sp_ring_r,
                                 "Ring radius", " mm", 1.0)]
                if helical:
                    height_anchor = _rotate_about([profile_center], axis_origin, axis,
                                                  middle_angle)[0]
                    handle_specs.append((height_anchor, axis, mw.sp_ring_height,
                                         "Helix height", " mm", 1.0, None, "red"))
                if mw.sp_ring_angle.isEnabled():
                    if sweep_direction == "sym":
                        angle_anchor_value, angle_factor = end_angle, 0.5
                    else:
                        reverse_sweep = sweep_direction == "rev"
                        negative_angle = angle_value < 0.0 and not helical
                        use_start = reverse_sweep != negative_angle
                        angle_anchor_value = start_angle if use_start else end_angle
                        angle_factor = -1.0 if reverse_sweep else 1.0
                    angle_anchor = _rotate_about([profile_center], axis_origin, axis,
                                                 angle_anchor_value)[0]
                    angle_vector = np.cross(axis, angle_anchor - axis_origin) * \
                                   (math.pi / 180.0 * angle_factor)
                    handle_specs.append((angle_anchor, angle_vector, mw.sp_ring_angle,
                                         "Ring sweep angle", "°", 1.0))
                if mw.sp_ring_rotation.isEnabled():
                    profile_point = max(points, key=lambda p: float(np.linalg.norm(p[:2] - center[:2])))
                    rotation_anchor = (profile_center + (profile_point[0] - center[0]) * horizontal +
                                       (profile_point[1] - center[1]) * vertical)
                    rotation_vector = np.cross(normal, rotation_anchor - profile_center) * (math.pi / 180.0)
                    handle_specs.append((rotation_anchor, rotation_vector, mw.sp_ring_rotation,
                                         "Ring surface rotation", "°", 1.0, profile_center))
            else:
                if not mw.sp_h.isEnabled():
                    return [] if all_handles else None
                origin, horizontal, vertical, normal = frame
                height = mw.sp_h.value()
                direction = mw.cb_ext_dir.currentData()
                sign = -1.0 if height < 0 else 1.0
                distance = height
                factor = sign
                if direction == "rev":
                    distance = -abs(height)
                elif direction == "sym":
                    distance = abs(height) / 2.0
                    factor *= 2.0
                axis = _unit(normal) * (-1.0 if distance < 0 else 1.0)
                anchor = origin + center[0]*horizontal + center[1]*vertical + distance*normal
                control = mw.sp_h
                name = "Extrusion height"
                handle_specs = [(anchor, axis, control, name, " mm", factor)]
        else:
            return [] if all_handles else None
        handles = []
        for spec in handle_specs:
            anchor, axis, control, name, unit, factor = spec[:6]
            screen, valid = self._project([anchor, anchor + axis])
            if not valid.all():
                continue
            projected = screen[1] - screen[0]
            pixels_per_mm = float(np.linalg.norm(projected))
            if pixels_per_mm < 0.25:
                depth = float((self._mvp @ np.r_[anchor, 1.0])[3])
                pixels_per_mm = (self.height() / (2.0 * max(depth, 0.1) *
                                                  math.tan(math.radians(22.5))) *
                                 float(np.linalg.norm(axis)))
                screen_direction = np.array([0.0, -1.0])
            else:
                screen_direction = projected / pixels_per_mm
            start = screen[0] + 10.0*screen_direction
            tip = screen[0] + 68.0*screen_direction
            lower = np.minimum(start, tip) - 12.0
            upper = np.maximum(start, tip) + 12.0
            shift = np.maximum(8.0 - lower, 0.0) + np.minimum(
                np.array([self.width() - 8.0, self.height() - 8.0]) - upper, 0.0)
            handle = {"control": control, "factor": factor, "name": name, "unit": unit,
                                "step": 0.1 if control is mw.sp_thread_length else
                                    1.0 if control in (mw.sp_feat_angle, mw.sp_ring_rotation,
                                                       mw.sp_angle_draft) else None,
                            "fine_modifier": Qt.ControlModifier if control in
                                (mw.sp_thread_length, mw.sp_angle_draft) else
                                            Qt.ControlModifier | Qt.ShiftModifier,
                            "start": start + shift, "tip": tip + shift,
                            "color": spec[7] if len(spec) > 7 else None,
                            "direction": screen_direction, "pixels_per_mm": pixels_per_mm}
            if control is mw.sp_angle_draft:
                handle["pixels_per_mm"] = 4.0
            if len(spec) > 6 and spec[6] is not None:
                center_screen, center_valid = self._project([spec[6]])
                if center_valid[0]:
                    arc_center = center_screen[0]
                    radius = max(6.0, min(42.0, arc_center[0] - 8.0,
                                          self.width() - 8.0 - arc_center[0],
                                          arc_center[1] - 8.0,
                                          self.height() - 8.0 - arc_center[1]))
                    theta_start = math.atan2(-screen_direction[0], screen_direction[1])
                    arc_angles = np.linspace(theta_start, theta_start + 1.5 * math.pi, 61)
                    arc_points = arc_center + radius * np.column_stack((np.cos(arc_angles),
                                                                          np.sin(arc_angles)))
                    tangent = arc_points[1] - arc_points[0]
                    tangent /= max(float(np.linalg.norm(tangent)), 1e-12)
                    handle.update(rotation_arc=arc_points, rotation_center=arc_center,
                                  start=arc_points[0], tip=arc_points[-1], direction=tangent,
                                  pixels_per_mm=radius * math.pi / 180.0)
            handles.append(handle)
        return handles if all_handles else (handles[0] if handles else None)

    def _dimension_handle_at(self, position):
        point = np.array([position.x(), position.y()], dtype=float)
        hits = []
        for handle in self._dimension_handle_data(all_handles=True):
            arc = handle.get("rotation_arc")
            if arc is not None:
                distance = min_seg_dist(point, arc[:-1], arc[1:])
            else:
                distance = min_seg_dist(point, np.asarray([handle["start"]]),
                                        np.asarray([handle["tip"]]))
            if distance <= 12.0:
                hits.append((distance, handle))
        return min(hits, key=lambda hit: hit[0])[1] if hits else None

    def _draw_dimension_handle(self):
        for handle in self._dimension_handle_data(all_handles=True):
            start, tip, direction = handle["start"], handle["tip"], handle["direction"]
            sideways = np.array([-direction[1], direction[0]])
            accent = ((1.0, 0.2, 0.2, 1.0) if handle.get("color") == "red" else
                      (0.25, 1.0, 0.35, 1.0) if handle.get("unit") == "°" else
                      (1.0, 0.88 if self._dimension_hovered or self._dimension_drag else 0.65,
                       0.15, 1.0))
            glPushAttrib(GL_ENABLE_BIT | GL_COLOR_BUFFER_BIT | GL_LINE_BIT | GL_CURRENT_BIT)
            glDisable(GL_LIGHTING); glDisable(GL_DEPTH_TEST)
            glEnable(GL_BLEND); glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            glMatrixMode(GL_PROJECTION); glPushMatrix(); glLoadIdentity()
            glOrtho(0, self.width(), self.height(), 0, -1, 1)
            glMatrixMode(GL_MODELVIEW); glPushMatrix(); glLoadIdentity()
            for width, color in ((8.0, (0.08, 0.09, 0.10, 0.9)),
                                 (4.0, accent)):
                glColor4f(*color); glLineWidth(width)
                arc = handle.get("rotation_arc")
                if arc is None:
                    glBegin(GL_LINES)
                    glVertex2f(*start); glVertex2f(*(tip - 10.0*direction))
                    glEnd()
                    head_width = 9.0 if width == 8.0 else 6.0
                    glBegin(GL_TRIANGLES)
                    glVertex2f(*tip)
                    glVertex2f(*(tip - 16.0*direction + head_width*sideways))
                    glVertex2f(*(tip - 16.0*direction - head_width*sideways))
                    glEnd()
                else:
                    middle = arc[len(arc) // 2]
                    glBegin(GL_LINES)
                    glVertex2f(*handle["rotation_center"]); glVertex2f(*middle)
                    glEnd()
                    glBegin(GL_LINE_STRIP)
                    for point in arc:
                        glVertex2f(*point)
                    glEnd()
                    head_width = 9.0 if width == 8.0 else 6.0
                    head_length = 16.0 if width == 8.0 else 12.0
                    for endpoint, tangent in ((arc[0], arc[0] - arc[1]),
                                              (arc[-1], arc[-1] - arc[-2])):
                        tangent = tangent / max(float(np.linalg.norm(tangent)), 1e-12)
                        side = np.array([-tangent[1], tangent[0]])
                        glBegin(GL_TRIANGLES)
                        glVertex2f(*endpoint)
                        glVertex2f(*(endpoint - head_length*tangent + head_width*side))
                        glVertex2f(*(endpoint - head_length*tangent - head_width*side))
                        glEnd()
            glPopMatrix(); glMatrixMode(GL_PROJECTION); glPopMatrix(); glMatrixMode(GL_MODELVIEW)
            glPopAttrib()
            value = (f"{handle['control'].value():.2f}".rstrip("0").rstrip(".") +
                     handle.get("unit", " mm"))
            font = self.font(); font.setBold(True)
            label = tip + np.array([12.0, -8.0])
            label[0] = np.clip(label[0], 4.0, max(4.0, self.width() - QFontMetricsF(font).horizontalAdvance(value) - 4.0))
            label[1] = np.clip(label[1], QFontMetricsF(font).height(), self.height() - 4.0)
            glPushAttrib(GL_ENABLE_BIT | GL_CURRENT_BIT)
            glDisable(GL_LIGHTING); glDisable(GL_DEPTH_TEST)
            glColor3f(0.05, 0.05, 0.05)
            self.renderText(int(label[0] + 1), int(label[1] + 1), value, font)
            glColor3f(*( (1.0, 0.35, 0.35) if handle.get("color") == "red" else
                         (1.0, 0.92, 0.65) ))
            self.renderText(int(label[0]), int(label[1]), value, font)
            glPopAttrib()

    def _begin_dimension_drag(self, event):
        handle = self._dimension_handle_at(event.pos())
        if handle is None:
            return False
        arc = handle.get("rotation_arc")
        if arc is not None:
            point = np.array([event.x(), event.y()], dtype=float)
            segments = np.diff(arc, axis=0)
            segment_lengths = np.einsum("ij,ij->i", segments, segments)
            offsets = point - arc[:-1]
            fractions = np.clip(np.einsum("ij,ij->i", offsets, segments) /
                                np.maximum(segment_lengths, 1e-12), 0.0, 1.0)
            nearest = arc[:-1] + fractions[:, None] * segments
            index = int(np.argmin(np.einsum("ij,ij->i", point - nearest, point - nearest)))
            handle = dict(handle, direction=segments[index] /
                          max(float(np.linalg.norm(segments[index])), 1e-12))
        self._dimension_drag = dict(handle, position=QPointF(event.pos()),
                                    value=handle["control"].value(),
                                    last_position=QPointF(event.pos()),
                                    fine=bool(event.modifiers() & handle["fine_modifier"]))
        self._last_pos = self._press_pos = None
        self.setCursor(QCursor(Qt.SizeAllCursor))
        return True

    def _update_dimension_drag(self, event):
        drag = self._dimension_drag
        handles = self._dimension_handle_data(all_handles=True)
        if not any(handle["control"] is drag["control"] for handle in handles):
            self._dimension_drag = None
            return
        fine = bool(event.modifiers() & drag["fine_modifier"])
        if fine != drag["fine"]:
            drag["position"] = drag["last_position"]
            drag["value"] = drag["control"].value()
            drag["fine"] = fine
        displacement = np.array([event.x() - drag["position"].x(),
                                  event.y() - drag["position"].y()])
        step = (drag["step"] * (0.1 if fine else 1.0) if drag["step"] is not None
            else dimension_drag_step(drag["pixels_per_mm"], fine))
        amount = float(displacement @ drag["direction"]) / drag["pixels_per_mm"] * drag["factor"]
        if fine:
            amount *= 0.1
        value = drag["value"] + round(amount / step)*step
        control = drag["control"]
        control.setValue(max(control.minimum(), min(control.maximum(), value)))
        drag["last_position"] = QPointF(event.pos())
        self.update()

    def _setup_ortho_camera(self):
        eye, up = PLANE_VIEW[self._ortho_plane]
        d = self.zoom
        gluLookAt(eye[0]*d, eye[1]*d, eye[2]*d, 0,0,0, up[0],up[1],up[2])
        glTranslatef(self.pan[0]*0.3, self.pan[1]*0.3, 0)

    def _face_sketch_rotation(self, frame):
        """Use world Z as face-view up, or world Y on horizontal faces; never use the camera."""
        _, u, v, _ = (np.asarray(a, float) for a in frame)
        up = np.array([0.0, 0.0, 1.0])
        cosine, sine = float(up @ v), -float(up @ u)
        length = math.hypot(cosine, sine)
        if length < 1e-8:
            up = np.array([0.0, 1.0, 0.0])
            cosine, sine = float(up @ v), -float(up @ u)
            length = math.hypot(cosine, sine)
        return cosine/length, sine/length

    def _draw_axes(self):
        hv = self._hover3d
        all_hot = hv is not None and hv[0] == "origin"
        glDisable(GL_LIGHTING)
        axes = [((1,0,0),(1,.55,.55),(60,0,0),"x"),
                ((0,1,0),(.6,1,.6),(0,60,0),"y"),
                ((0,0,1),(.6,.7,1),(0,0,60),"z")]
        labels = []
        for i,(col,hot_col,end,lbl) in enumerate(axes):
            hot = all_hot or (hv is not None and hv[0] == "axis" and hv[1] == i)
            glLineWidth(5 if hot else 2)
            glColor3f(*(hot_col if hot else col))
            glBegin(GL_LINES); glVertex3f(0,0,0); glVertex3f(*end); glEnd()
            labels.append((end, lbl, hot_col, hot))
        if all_hot:
            glPointSize(10); glColor3f(1,1,0.6)
            glBegin(GL_POINTS); glVertex3f(0,0,0); glEnd(); glPointSize(1)
        # small axis letters at the tips (always visible, bigger while hovered)
        glDisable(GL_DEPTH_TEST)
        f_small = QFont("Arial", 9); f_hot = QFont("Arial", 11, QFont.Bold)
        for end,lbl,col,hot in labels:
            glColor3f(*col)
            self.renderText(end[0]*1.1, end[1]*1.1, end[2]*1.1, lbl, f_hot if hot else f_small)
        glEnable(GL_DEPTH_TEST)
        glLineWidth(1); glEnable(GL_LIGHTING)

    def _draw_surfaces(self):
        surfaces = [entry for entry in self.state.get("objects", [])
                    if entry["type"] == "surface" and entry_visible(entry)]
        preview = getattr(self, "_surface_preview", None)
        if not surfaces and preview is None:
            return
        glDisable(GL_LIGHTING)
        glEnable(GL_BLEND); glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        glDepthMask(GL_FALSE)
        glEnable(GL_POLYGON_OFFSET_FILL); glPolygonOffset(-1.0, -1.0)
        selected = self.state.get("selected")
        if preview is not None:
            surfaces.append(preview)
        for entry in surfaces:
            is_preview = entry.get("preview", False)
            if is_preview:
                glDisable(GL_DEPTH_TEST)
            origin, u, v, _ = entry["frame"]
            u = np.asarray(u, float); v = np.asarray(v, float)
            origin = np.asarray(origin, float)
            half_w, half_h = entry["width"] / 2.0, entry["height"] / 2.0
            points = [origin - half_w*u - half_h*v, origin + half_w*u - half_h*v,
                      origin + half_w*u + half_h*v, origin - half_w*u + half_h*v]
            hovered = not is_preview and self._hover3d is not None and self._hover3d[0] == "surface" \
                and self._hover3d[1] is entry
            glColor4f(*( (0.35, 1.0, 0.55, 0.38) if is_preview
                         else (1.0, 0.72, 0.12, 0.40) if entry is selected
                         else (0.9, 0.85, 0.35, 0.34) if hovered
                         else (0.12, 0.62, 0.82, 0.22) ))
            glBegin(GL_QUADS)
            for point in points: glVertex3f(*point)
            glEnd()
            glColor4f(*( (0.35, 1.0, 0.55, 0.95) if is_preview
                         else (1.0, 0.78, 0.2, 0.95) if entry is selected
                         else (1.0, 0.95, 0.45, 0.98) if hovered
                         else (0.18, 0.72, 0.92, 0.9) ))
            glLineWidth(2.0 if is_preview or entry is selected else 1.25)
            if is_preview:
                glEnable(GL_LINE_STIPPLE); glLineStipple(1, 0x0F0F)
            glBegin(GL_LINE_LOOP)
            for point in points: glVertex3f(*point)
            glEnd()
            if is_preview:
                glDisable(GL_LINE_STIPPLE)
                glEnable(GL_DEPTH_TEST)
        glLineWidth(1.0)
        glDisable(GL_POLYGON_OFFSET_FILL)
        glDepthMask(GL_TRUE)
        glEnable(GL_LIGHTING)

    PLANE_QUADS = {"XY":[(0,0,0),(80,0,0),(80,80,0),(0,80,0)],
                   "XZ":[(0,0,0),(80,0,0),(80,0,80),(0,0,80)],
                   "YZ":[(0,0,0),(0,80,0),(0,80,80),(0,0,80)]}

    def _draw_plane_selectors(self):
        glPushAttrib(GL_DEPTH_BUFFER_BIT)
        glDisable(GL_LIGHTING)
        glEnable(GL_BLEND); glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        glDepthMask(GL_FALSE)
        hv = self._hover3d
        for name, col in [("XY",(0.3,0.5,1.0)),("XZ",(0.3,1.0,0.5)),("YZ",(1.0,0.5,0.3))]:
            pts = self.PLANE_QUADS[name]
            hot = hv is not None and hv[0] == "plane" and hv[1] == name
            glColor4f(col[0],col[1],col[2],0.35 if hot else 0.25); glBegin(GL_QUADS)
            for pt in pts: glVertex3f(*pt)
            glEnd()
            glColor4f(min(1,col[0]+.3),min(1,col[1]+.3),min(1,col[2]+.3),1.0) if hot else \
                glColor4f(col[0],col[1],col[2],0.9)
            glLineWidth(4 if hot else 2)
            glBegin(GL_LINE_LOOP)
            for pt in pts: glVertex3f(*pt)
            glEnd()
        glLineWidth(1); glDisable(GL_BLEND); glEnable(GL_LIGHTING)
        glPopAttrib()

    @staticmethod
    def _feature_edges(entry):
        """Edges on the silhouette of the prism (sharp edges); cached per solid."""
        solid = entry["solid"]
        cache = entry.get("_fe")
        if cache and cache[0] is solid: return cache[1]
        verts, tris = solid
        normals = [tri_normal(verts[a],verts[b],verts[c]) for a,b,c in tris]
        emap = {}
        for k,tri in enumerate(tris):
            for a,b in ((tri[0],tri[1]),(tri[1],tri[2]),(tri[2],tri[0])):
                emap.setdefault((min(a,b),max(a,b)), []).append(k)
        edges = []
        for key, fs in emap.items():
            if len(fs) != 2:
                edges.append(key); continue
            n0, n1 = normals[fs[0]], normals[fs[1]]
            if n0[0]*n1[0]+n0[1]*n1[1]+n0[2]*n1[2] < 0.94:   # > ~20° crease
                edges.append(key)
        entry["_fe"] = (solid, edges)
        return edges

    @staticmethod
    def _face_outline(entry, fi):
        """Boundary edges (vertex index pairs) of one face; cached per solid."""
        solid = entry["solid"]
        cache = entry.get("_fo")
        if not cache or cache[0] is not solid:
            cache = (solid, {}); entry["_fo"] = cache
        if fi not in cache[1]:
            tris = solid[1]; cnt = {}
            for k in entry["faces"][fi]["tris"]:
                t = tris[k]
                for a, b in ((t[0],t[1]),(t[1],t[2]),(t[2],t[0])):
                    key = (min(a,b), max(a,b)); cnt[key] = cnt.get(key, 0) + 1
            cache[1][fi] = [e for e, n in cnt.items() if n == 1]
        return cache[1][fi]

    @staticmethod
    def _face_outline_array(entry, fi):
        """Expanded float32 outline vertices, cached until the solid changes."""
        solid = entry["solid"]
        cache = entry.get("_face_outline_cache")
        if cache is None or cache[0] is not solid:
            cache = (solid, {})
            entry["_face_outline_cache"] = cache
        if fi not in cache[1]:
            edges = np.asarray(View3D._face_outline(entry, fi), dtype=np.intp)
            vertices = np.asarray(solid[0], dtype=np.float32).reshape(-1, 3)
            cache[1][fi] = np.ascontiguousarray(vertices[edges.ravel()])
        return cache[1][fi]

    @staticmethod
    def _draw_face_outline(entry, fi):
        vertices = View3D._face_outline_array(entry, fi)
        if not len(vertices): return
        glBindBuffer(GL_ARRAY_BUFFER, 0)
        glEnableClientState(GL_VERTEX_ARRAY)
        glVertexPointer(3, GL_FLOAT, 0, vertices)
        glDrawArrays(GL_LINES, 0, len(vertices))
        glDisableClientState(GL_VERTEX_ARRAY)

    @staticmethod
    def _face_vertex_array(entry, fi):
        """Expanded float32 triangle vertices for one face; cached per solid."""
        verts, tris = entry["solid"]
        cache = entry.get("_face_vertex_cache")
        if cache is None or cache[0] is not verts:
            cache = (verts, {})
            entry["_face_vertex_cache"] = cache
        if fi not in cache[1]:
            face_tris = np.asarray(entry["faces"][fi]["tris"], dtype=np.intp)
            tri_indices = np.asarray(tris, dtype=np.intp).reshape(-1, 3)
            face_verts = np.asarray(verts, dtype=np.float32)[tri_indices[face_tris].ravel()]
            cache[1][fi] = np.ascontiguousarray(face_verts)
        return cache[1][fi]

    @staticmethod
    def _draw_face_triangles(entry, fi):
        vertices = View3D._face_vertex_array(entry, fi)
        if not len(vertices): return
        glBindBuffer(GL_ARRAY_BUFFER, 0)
        glEnableClientState(GL_VERTEX_ARRAY)
        glVertexPointer(3, GL_FLOAT, 0, vertices)
        glDrawArrays(GL_TRIANGLES, 0, len(vertices))
        glDisableClientState(GL_VERTEX_ARRAY)

    def _hover_face(self):
        hv = self._hover3d
        if hv is None or hv[0] != "face" or hv[1][1] < 0: return None, None
        return hv[1]

    def _draw_solids(self):
        try:
            self._draw_solids_inner()
        except Exception as ex:
            import traceback; traceback.print_exc()
            print(f"_draw_solids error: {ex}")

    def _draw_solids_inner(self):
        glEnable(GL_BLEND); glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        hot_entry, hot_fi = self._hover_face()
        objs = [o for o in self.state.get("objects", [])
                if o["type"] in ("extrusion", "imported") and entry_visible(o) and "solid" in o]
        def opacity(entry):
            return max(0.0, min(1.0, float(entry.get("opacity", 1.0))))

        def transparent_depth(entry):
            mesh = entry["solid"]
            cached = entry.get("_transparency_sort")
            if cached is None or cached[0] is not mesh:
                vertices = np.asarray(mesh[0], dtype=float).reshape(-1, 3)
                centre = (vertices.min(0) + vertices.max(0)) / 2.0 if len(vertices) else np.zeros(3)
                cached = (mesh, centre)
                entry["_transparency_sort"] = cached
            if self._mvp is None:
                return 0.0
            clip = self._mvp @ np.append(cached[1], 1.0)
            return float(clip[2] / clip[3]) if abs(float(clip[3])) > 1e-12 else 0.0

        opaque = [entry for entry in objs if not entry.get("cut") and opacity(entry) >= 1.0]
        translucent = [entry for entry in objs if not entry.get("cut") and
                       0.0 < opacity(entry) < 1.0]
        translucent.sort(key=transparent_depth, reverse=True)
        cut_entries = [entry for entry in objs if entry.get("cut") and opacity(entry) > 0.0]
        render_entries = opaque + translucent + cut_entries
        stack_levels = bridge_stack_levels(self.state.get("objects", []))
        selected_object = self.state.get("selected")
        selected_extrusions = related_extrusion_ids(selected_object, self.state.get("objects", []))
        selected_entry_ids = self.state.get("selected_entry_ids", set())

        def highlight_depth(level, on):
            # Highlights of a body underneath a Bridge are pulled in front of the coincident
            # Bridge surface; the depth test still hides everything that is really in front.
            if not level: return
            if on:
                glEnable(GL_POLYGON_OFFSET_FILL); glEnable(GL_POLYGON_OFFSET_LINE)
                glPolygonOffset(-1.0, -1.0)
            else:
                glDisable(GL_POLYGON_OFFSET_FILL); glDisable(GL_POLYGON_OFFSET_LINE)
                glPolygonOffset(0.0, 0.0)
        # Opaque solids establish depth before the sorted translucent surfaces are blended.
        glPushAttrib(GL_DEPTH_BUFFER_BIT | GL_ENABLE_BIT)
        for entry in render_entries:
            verts, tris = entry["solid"]
            _sel_obj = selected_object
            sel = entry is _sel_obj or id(entry) in selected_extrusions or id(entry) in selected_entry_ids
            # check if a feature child of this entry is selected
            _sel_feat = None
            if _sel_obj is not None and _sel_obj.get("type") == "feature" and _sel_obj.get("parent") is entry:
                _sel_feat = id(_sel_obj)
            cut  = bool(entry.get("cut"))
            stack_level = stack_levels.get(id(entry), 0)
            alpha = opacity(entry)
            body_color = tuple(entry.get("color", (0.5, 0.8, 1.0)))
            selected_color = getattr(self, "selection_color", (1.0, 0.8, 0.2))
            if cut:
                alpha = (0.45 if sel else 0.28)*entry.get("opacity", 1.0)
                glDepthMask(GL_FALSE)
                glDisable(GL_CULL_FACE)
                glEnable(GL_POLYGON_OFFSET_FILL)
                active_cut = entry.get("preview") or entry is \
                    getattr(self._main_window, "_ext_edit", None)
                offset = -1.0 if active_cut else 1.0
                glPolygonOffset(offset, offset)
                body_color = (1.0, 0.55, 0.2) if sel else (1.0, 0.2, 0.2)
                glColor4f(*body_color, alpha)
            elif alpha < 1.0:
                glDepthMask(GL_FALSE)
                glEnable(GL_CULL_FACE); glCullFace(GL_BACK)
                glColor4f(*(selected_color if sel else body_color), alpha)
            else:
                glDepthMask(GL_TRUE)
                glDisable(GL_CULL_FACE)
                glColor4f(*(selected_color if sel else body_color), alpha)
            # suppress the solid only for entries that have a live preview (avoids z-fighting)
            _mw = self._main_window
            _active_preview = getattr(_mw, '_preview_mesh', None)
            _other_previews = getattr(_mw, '_preview_meshes', {})
            _entry_preview = None
            if self._feat_mode:
                pm = _active_preview if (self._feat_entry is entry and _active_preview is not None) \
                     else _other_previews.get(id(entry))
                if isinstance(pm, dict): _entry_preview = pm
            elif _mw is not None and getattr(_mw, "_thread_preview_entry", None) is entry:
                _entry_preview = getattr(_mw, "_thread_preview_mesh", None)
            _has_preview = _entry_preview is not None
            if stack_level and not cut:
                glEnable(GL_POLYGON_OFFSET_FILL)
                glPolygonOffset(float(stack_level), float(stack_level))
            if not _has_preview:
                # draw triangles via VBO — one GPU call instead of per-triangle Python loop
                faces = entry.get("faces", [])
                tri_vbo, edge_vbo = MainWindow._upload_vbo(entry)
                stride = 6 * 4  # 6 floats * 4 bytes
                if tri_vbo and not (_sel_feat and not sel):
                    glBindBuffer(GL_ARRAY_BUFFER, tri_vbo)
                    glEnableClientState(GL_NORMAL_ARRAY)
                    glEnableClientState(GL_VERTEX_ARRAY)
                    glNormalPointer(GL_FLOAT, stride, ctypes.c_void_p(0))
                    glVertexPointer(3, GL_FLOAT, stride, ctypes.c_void_p(12))
                    glDrawArrays(GL_TRIANGLES, 0, len(entry["solid"][1]) * 3)
                    glDisableClientState(GL_NORMAL_ARRAY)
                    glDisableClientState(GL_VERTEX_ARRAY)
                    glBindBuffer(GL_ARRAY_BUFFER, 0)
                else:
                    # Feature ownership is grouped in the VBO so colors vary without
                    # rebuilding or walking the triangle list during painting.
                    base_col = (selected_color if sel and not cut else body_color) + (alpha,)
                    feat_col = (1.0, 0.6, 0.1, alpha)
                    vbo_data = entry.get("_vbo_data")
                    if vbo_data is not None:
                        glDisableClientState(GL_COLOR_ARRAY)
                        if tri_vbo:
                            glBindBuffer(GL_ARRAY_BUFFER, tri_vbo)
                            normal_ptr = ctypes.c_void_p(0)
                            vertex_ptr = ctypes.c_void_p(12)
                        else:
                            data_ptr = vbo_data.ctypes.data
                            normal_ptr = ctypes.c_void_p(data_ptr)
                            vertex_ptr = ctypes.c_void_p(data_ptr + 12)
                        glEnableClientState(GL_NORMAL_ARRAY)
                        glEnableClientState(GL_VERTEX_ARRAY)
                        glNormalPointer(GL_FLOAT, stride, normal_ptr)
                        glVertexPointer(3, GL_FLOAT, stride, vertex_ptr)
                        for owner, first, count in entry.get("_vbo_draw_ranges", []):
                            glColor4f(*(feat_col if owner == _sel_feat else base_col))
                            glDrawArrays(GL_TRIANGLES, first, count)
                        glDisableClientState(GL_VERTEX_ARRAY)
                        glDisableClientState(GL_NORMAL_ARRAY)
                        glBindBuffer(GL_ARRAY_BUFFER, 0)
            else:
                # draw preview via VBO — upload once per worker result
                _pd = _entry_preview
                stride = 6 * 4
                if _pd.get("_vbo_id") is None and _pd.get("vbo_data") is not None:
                    buf = glGenBuffers(1)
                    glBindBuffer(GL_ARRAY_BUFFER, buf)
                    glBufferData(GL_ARRAY_BUFFER, _pd["vbo_data"].nbytes, _pd["vbo_data"], GL_STATIC_DRAW)
                    glBindBuffer(GL_ARRAY_BUFFER, 0)
                    _pd["_vbo_id"] = buf
                if _pd.get("_edge_vbo_id") is None and _pd.get("edge_data") is not None:
                    buf = glGenBuffers(1)
                    glBindBuffer(GL_ARRAY_BUFFER, buf)
                    glBufferData(GL_ARRAY_BUFFER, _pd["edge_data"].nbytes, _pd["edge_data"], GL_STATIC_DRAW)
                    glBindBuffer(GL_ARRAY_BUFFER, 0)
                    _pd["_edge_vbo_id"] = buf
                glDisable(GL_BLEND)
                if _pd.get("_vbo_id"):
                    glBindBuffer(GL_ARRAY_BUFFER, _pd["_vbo_id"])
                    glEnableClientState(GL_NORMAL_ARRAY)
                    glEnableClientState(GL_VERTEX_ARRAY)
                    glNormalPointer(GL_FLOAT, stride, ctypes.c_void_p(0))
                    glVertexPointer(3, GL_FLOAT, stride, ctypes.c_void_p(12))
                    glDrawArrays(GL_TRIANGLES, 0, len(_pd["vbo_data"]) // 6)
                    glDisableClientState(GL_NORMAL_ARRAY)
                    glDisableClientState(GL_VERTEX_ARRAY)
                    glBindBuffer(GL_ARRAY_BUFFER, 0)
                glDisable(GL_LIGHTING)
                glColor4f(0.1, 0.3, 0.5, min(1.0, alpha + 0.2))
                glLineWidth(1.5)
                if _pd.get("_edge_vbo_id"):
                    glBindBuffer(GL_ARRAY_BUFFER, _pd["_edge_vbo_id"])
                    glEnableClientState(GL_VERTEX_ARRAY)
                    glVertexPointer(3, GL_FLOAT, 0, ctypes.c_void_p(0))
                    glDrawArrays(GL_LINES, 0, len(_pd["edge_data"]) // 3)
                    glDisableClientState(GL_VERTEX_ARRAY)
                    glBindBuffer(GL_ARRAY_BUFFER, 0)
                glEnable(GL_LIGHTING)
                glEnable(GL_BLEND)
            if stack_level and not cut:
                glDisable(GL_POLYGON_OFFSET_FILL)
                glPolygonOffset(0.0, 0.0)
            # sharp (feature) edges (skip when preview mesh is shown instead)
            if not _has_preview:
                glDisable(GL_LIGHTING)
                if cut: glColor4f(1.0, 0.25, 0.25, 0.9)
                else:   glColor4f(0.1,0.3,0.5,min(1.0,alpha+0.2))
                glLineWidth(1.5)
                _, edge_vbo = MainWindow._upload_vbo(entry)
                if edge_vbo:
                    glBindBuffer(GL_ARRAY_BUFFER, edge_vbo)
                    glEnableClientState(GL_VERTEX_ARRAY)
                    glVertexPointer(3, GL_FLOAT, 0, ctypes.c_void_p(0))
                    n_edge_verts = len(entry["_edge_data"]) // 3
                    glDrawArrays(GL_LINES, 0, n_edge_verts)
                    glDisableClientState(GL_VERTEX_ARRAY)
                    glBindBuffer(GL_ARRAY_BUFFER, 0)
                glEnable(GL_LIGHTING)
            # hovered surface only -- skip when preview mesh is active (face indices mismatch)
            if not _has_preview and entry is hot_entry and hot_fi is not None \
                    and hot_fi < len(entry.get("faces", [])):
                glEnable(GL_LIGHTING)
                face = entry["faces"][hot_fi]
                planar_pick = self._mode not in (MODE_SELPLANE, MODE_SELSURFACE) or \
                              face["planar"] or self._mode == MODE_SELSURFACE
                highlight_depth(stack_level, True)
                glDepthFunc(GL_LEQUAL)
                glColor4f(1.0, 0.95, 0.35, 0.20) if planar_pick else glColor4f(1.0, 0.4, 0.4, 0.9)
                self._draw_face_triangles(entry, hot_fi)
                glColor4f(1.0, 1.0, 1.0, 1.0); glLineWidth(2.5)
                self._draw_face_outline(entry, hot_fi)
                glDepthFunc(GL_LESS)
                highlight_depth(stack_level, False)
            # selected surface (clicked in the 3-D view) and the cylinders chosen for a thread
            selected_faces = self.state.get("sel_faces") or [self.state.get("sel_face")]
            for _sf in [*selected_faces, *self._thread_faces()]:
                if _has_preview or _sf is None or _sf[0] is not entry or \
                        not 0 <= _sf[1] < len(entry.get("faces", [])):
                    continue
                glEnable(GL_LIGHTING)
                highlight_depth(stack_level, True)
                glDepthFunc(GL_LEQUAL)
                glColor4f(0.6, 0.8, 1.0, 0.9)
                self._draw_face_triangles(entry, _sf[1])
                glColor4f(0.0, 0.5, 1.0, 1.0); glLineWidth(3.0)
                self._draw_face_outline(entry, _sf[1])
                glDepthFunc(GL_LESS)
                highlight_depth(stack_level, False)
            if self._bridge_mode:
                for selected_entry, selected_face in self._bridge_faces:
                    if selected_entry is not entry or not 0 <= selected_face < len(entry.get("faces", [])):
                        continue
                    highlight_depth(stack_level, True)
                    glDepthFunc(GL_LEQUAL)
                    glColor4f(0.25, 1.0, 0.45, 0.22)
                    self._draw_face_triangles(entry, selected_face)
                    glDepthFunc(GL_LESS)
                    highlight_depth(stack_level, False)
            if self._angle_mode and entry is self._angle_entry:
                reference = getattr(self._main_window, "_angle_draft_reference", None)
                if self._angle_pivot is not None and reference is not None and reference["kind"] == "face":
                    pivot_face = reference["face"]
                    if 0 <= pivot_face < len(entry.get("faces", [])):
                        glDepthFunc(GL_LEQUAL)
                        glColor4f(1.0, 0.75, 0.2, 0.3)
                        self._draw_face_triangles(entry, pivot_face)
                        glColor4f(1.0, 0.75, 0.2, 1.0); glLineWidth(3.0)
                        self._draw_face_outline(entry, pivot_face)
                        glDepthFunc(GL_LESS)
                for selected_face in self._angle_faces:
                    if not 0 <= selected_face < len(entry.get("faces", [])):
                        continue
                    glDepthFunc(GL_LEQUAL)
                    glColor4f(0.2, 1.0, 0.35, 0.30)
                    self._draw_face_triangles(entry, selected_face)
                    glColor4f(0.25, 1.0, 0.4, 1.0); glLineWidth(3.0)
                    self._draw_face_outline(entry, selected_face)
                    glDepthFunc(GL_LESS)
            glEnable(GL_LIGHTING)
            if cut: glDepthMask(GL_TRUE); glDisable(GL_POLYGON_OFFSET_FILL)
        glPopAttrib()
        if self._angle_mode and self._angle_pivot is not None:
            reference = getattr(self._main_window, "_angle_draft_reference", None)
            glPushAttrib(GL_ENABLE_BIT | GL_POINT_BIT | GL_LINE_BIT | GL_CURRENT_BIT)
            glDisable(GL_LIGHTING); glDisable(GL_DEPTH_TEST)
            if reference is not None and reference["kind"] == "edge":
                origin, u, v, w = (np.asarray(axis, dtype=float) for axis in
                                   self._angle_entry["parent"]["sketch"].frame)
                glLineWidth(4.0); glColor3f(1.0, 0.75, 0.2)
                glBegin(GL_LINES)
                for point in reference["points"]:
                    glVertex3f(*(origin + point[0]*u + point[1]*v + point[2]*w))
                glEnd()
            elif reference is None:
                glPointSize(13.0); glColor3f(0.2, 1.0, 0.35)
                glBegin(GL_POINTS); glVertex3f(*self._angle_pivot); glEnd()
            glPopAttrib()
        glLineWidth(1); glDisable(GL_BLEND)
        # feature edge picking: highlight hovered chain (yellow) and selected chains (cyan)
        if self._feat_mode:
            fe = self._feat_entry
            mw = self._main_window
            sel_chains = mw._feat_chains if mw is not None else []
            entries_to_draw = [
                o for o in self.state.get("objects", [])
                if _is_feature_body(o) and entry_visible(o)
                and o.get("solid", (None, []))[1]]
            glDisable(GL_LIGHTING); glDisable(GL_DEPTH_TEST)
            glEnable(GL_BLEND); glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            for entry in entries_to_draw:
                chains = _feat_chains_cached(entry)
                for ci, c in enumerate(chains):
                    is_sel = any(
                        c["faces"] == s["faces"] and
                        s.get("_entry", fe) is entry and
                        float(np.linalg.norm(c["mid"]-s["mid"])) < 1.0
                        for s in sel_chains)
                    is_hov = (ci == self._hover_chain and entry is self._hover_chain_entry)
                    if not is_sel and not is_hov: continue
                    if is_sel:   glColor4f(0.2, 1.0, 1.0, 1.0); glLineWidth(4)
                    elif is_hov: glColor4f(1.0, 1.0, 0.2, 1.0); glLineWidth(3)
                    P = c["P"]
                    glBegin(GL_LINE_STRIP)
                    for pt in P: glVertex3f(*pt)
                    glEnd()
            glLineWidth(1); glDisable(GL_BLEND); glEnable(GL_DEPTH_TEST); glEnable(GL_LIGHTING)

    def _draw_sketch_previews(self):
        glDisable(GL_LIGHTING)
        glDisable(GL_DEPTH_TEST)   # always draw on top, never clipped by solids
        glEnable(GL_BLEND); glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        sel = self.state.get("selected")
        hv  = self._hover3d
        for entry in self.state.get("objects", []):
            if entry["type"] != "sketch": continue
            is_sel = sketch_selected_in_3d(entry, sel)
            if not entry_visible(entry) and not sketch_preview_visible(entry, sel): continue
            sk = entry["sketch"]
            op = float(entry.get("opacity", 1.0))
            hot = hv is not None and hv[0] == "sketch" and hv[1] is entry
            for pts, constr in sketch_polylines(sk):
                if constr:
                    glEnable(GL_LINE_STIPPLE); glLineStipple(2, 0x0F0F)
                    glColor4f(0.55,0.75,1.0,op) if hot else glColor4f(0.3,0.5,1.0,op)
                    glLineWidth(2 if hot else 1)
                else:
                    glDisable(GL_LINE_STIPPLE)
                    if is_sel and hot: glColor4f(1.0,0.7,0.3,op); glLineWidth(4)
                    elif is_sel:       glColor4f(1.0,0.4,0.0,op); glLineWidth(3)  # orange
                    elif hot:          glColor4f(1.0,1.0,0.5,op); glLineWidth(3)  # hover
                    else:              glColor4f(0.3,0.9,0.3,op); glLineWidth(1)  # thin green
                glBegin(GL_LINE_STRIP)
                for p3 in sk.to3d_many(pts): glVertex3f(*p3)
                glEnd()
            glDisable(GL_LINE_STIPPLE)
        glLineWidth(1); glEnable(GL_DEPTH_TEST); glEnable(GL_LIGHTING)

    def _draw_gear_centerlines(self):
        entries = [entry for entry in self.state.get("objects", [])
                   if entry.get("gear_parameters") and not entry.get("preview")
                   and entry_visible(entry) and entry.get("solid", (None, []))[1]]
        if not entries:
            return
        glPushAttrib(GL_ENABLE_BIT | GL_LINE_BIT | GL_COLOR_BUFFER_BIT)
        glDisable(GL_LIGHTING); glDisable(GL_DEPTH_TEST)
        glEnable(GL_BLEND); glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        glEnable(GL_LINE_STIPPLE); glLineStipple(2, 0xF0F0)
        glColor4f(0.65, 0.9, 1.0, 0.95); glLineWidth(1.5)
        glBegin(GL_LINES)
        for entry in entries:
            points = gear_centerline_points(entry)
            if points is not None:
                glVertex3f(*points[0]); glVertex3f(*points[1])
        glEnd()
        glPopAttrib()

    # ── 3-D picking (hover / click) ───────────────────────────────────────────
    def _project(self, pts):
        """World points → (screen px (N,2), valid mask) using the last paintGL matrices."""
        P = np.asarray(pts, dtype=float).reshape(-1, 3)
        H = np.c_[P, np.ones(len(P))] @ self._mvp.T
        w = H[:, 3]; valid = w > 1e-9
        w = np.where(valid, w, 1.0)
        sx = (H[:, 0]/w + 1.0)*0.5*self.width()
        sy = (1.0 - H[:, 1]/w)*0.5*self.height()
        return np.c_[sx, sy], valid

    def _ray(self, pos):
        inv = np.linalg.inv(self._mvp)
        nx = 2.0*pos.x()/max(1, self.width()) - 1.0
        ny = 1.0 - 2.0*pos.y()/max(1, self.height())
        p0 = inv @ np.array([nx, ny, -1.0, 1.0]); p1 = inv @ np.array([nx, ny, 1.0, 1.0])
        p0 = p0[:3]/p0[3]; p1 = p1[:3]/p1[3]
        return p0, p1 - p0

    @staticmethod
    def _solid_arrays(entry):
        """(v0, e1, e2, tri→face index) numpy arrays for ray casting; cached per solid."""
        solid = entry["solid"]
        cache = entry.get("_np")
        if cache and cache[0] is solid: return cache[1]
        V = np.asarray(solid[0], dtype=float); T = np.asarray(solid[1], dtype=int).reshape(-1, 3)
        tri_face = np.full(len(T), -1, dtype=int)
        for fi, face in enumerate(entry.get("faces", [])):
            tri_face[face["tris"]] = fi
        arr = (V[T[:,0]], V[T[:,1]]-V[T[:,0]], V[T[:,2]]-V[T[:,0]], tri_face)
        entry["_np"] = (solid, arr)
        return arr

    def _polyline_dist(self, p, pts3):
        S, valid = self._project(pts3)
        m = valid[:-1] & valid[1:]
        return min_seg_dist(p, S[:-1][m], S[1:][m])

    def _pick_face(self, o, d, planar_only=False):
        """Nearest visible solid face hit by the ray → (t, entry, face index) or None."""
        hits = []
        excluded=getattr(self, "_surface_pick_excluded", set()) \
            if self._mode == MODE_SELSURFACE else set()
        for entry in self.state.get("objects", []):
            solid = entry.get("solid")
            if self._angle_mode and self._angle_entry is not None and self._angle_entry.get("cut") \
                    and entry is not self._angle_entry:
                continue
            if entry["type"] not in ("extrusion", "imported") or \
                    id(entry) in excluded or not solid or not solid[1] or not entry_visible(entry):
                continue
            if entry.get("cut") and self._mode == MODE_SELPLANE:
                continue        # sketches go on the real (cut) surfaces, not on the red tool body
            v0, e1, e2, tri_face = self._solid_arrays(entry)
            hit = ray_tris(o, d, v0, e1, e2)
            if hit is None: continue
            t, k = hit
            hits.append((t, entry, int(tri_face[k])))
        best = min(hits, key=lambda hit: hit[0]) if hits else None
        if best is not None:
            # A Bridge fuses its source bodies, so its surface coincides with theirs. Among the
            # coincident hits the source body wins (its faces stay highlightable); the Bridge
            # tool itself picks on the topmost fused body so merges can be chained.
            levels = bridge_stack_levels(self.state.get("objects", []))
            reach = 1e-3 / max(float(np.linalg.norm(d)), 1e-12)
            stacked = [hit for hit in hits
                       if hit[0] <= best[0] + reach and
                       (id(hit[1]) in levels or hit[1].get("source_format") == "bridge")]
            if len(stacked) > 1:
                level_of = lambda hit: levels.get(id(hit[1]), 0)
                best = (min if self._bridge_mode else max)(
                    stacked, key=lambda hit: (level_of(hit), hit[0]))
        if best and planar_only:
            fi = best[2]
            faces = best[1].get("faces", [])
            if fi < 0 or fi >= len(faces) or not faces[fi]["planar"]: return best[:2] + (None,)
        return best

    def _pick_surface(self, o, d):
        """Nearest visible datum surface intersected inside its display rectangle."""
        best = None
        excluded=getattr(self, "_surface_pick_excluded", set()) \
            if self._mode == MODE_SELSURFACE else set()
        for entry in self.state.get("objects", []):
            if entry["type"] != "surface" or id(entry) in excluded or not entry_visible(entry):
                continue
            origin, u, v, normal = (np.asarray(axis, float) for axis in entry["frame"])
            denominator = float(np.dot(d, normal))
            if abs(denominator) < 1e-12:
                continue
            t = float(np.dot(origin - o, normal) / denominator)
            if t <= 1e-9 or (best is not None and t >= best[0]):
                continue
            point = o + t*d - origin
            if abs(float(np.dot(point, u))) <= entry["width"]/2 and \
                    abs(float(np.dot(point, v))) <= entry["height"]/2:
                best = (t, entry)
        return best

    def _pick3d(self, pos, thr=7.0):
        if self._mvp is None: return None
        p = np.array([pos.x(), pos.y()], dtype=float)
        objects = self.state.get("objects", [])
        o, d = self._ray(pos)
        # Plane selection accepts planar faces; Surface references also accept curved faces.
        if self._mode in (MODE_SELPLANE, MODE_SELSURFACE):
            fh = self._pick_face(o, d)
            sh = self._pick_surface(o, d)
            if sh is not None and (fh is None or sh[0] <= fh[0] + 1e-8):
                return ("surface", sh[1])
            if fh is not None and fh[2] is not None and fh[2] >= 0:
                return ("face", (fh[1], fh[2]))
            if self._mode == MODE_SELSURFACE:
                return None
            best_t, best = float("inf"), None
            for name, q in self.PLANE_QUADS.items():
                Q = np.asarray(q, dtype=float)
                v0 = np.array([Q[0], Q[0]]); e1 = np.array([Q[1]-Q[0], Q[2]-Q[0]])
                e2 = np.array([Q[2]-Q[0], Q[3]-Q[0]])
                hit = ray_tris(o, d, v0, e1, e2)
                if hit is not None and hit[0] < best_t: best_t, best = hit[0], ("plane", name)
            return best
        # sketch outlines (drawn on top of everything)
        best_d, best = thr, None
        for entry in objects:
            if entry["type"] != "sketch" or not entry_visible(entry): continue
            sk = entry["sketch"]
            for pts, _ in sketch_polylines(sk):
                dd = self._polyline_dist(p, sk.to3d_many(pts))
                if dd < best_d: best_d, best = dd, ("sketch", entry)
        if best: return best
        fh = self._pick_face(o, d)
        solid_t = fh[0] if fh else float("inf")
        # coordinate system (origin first, then axes) — unless hidden behind a solid
        def ray_t_at(A, B):
            """Ray parameter of the point closest to world segment A→B."""
            A = np.asarray(A, float); u = np.asarray(B, float) - A; w0 = o - A
            a, b, c = d @ d, d @ u, u @ u
            den = a*c - b*b
            s = 0.0 if abs(den) < 1e-12 else min(1.0, max(0.0, (a*(u @ w0) - b*(d @ w0))/den))
            return float(((A + s*u) - o) @ d / a)
        S, valid = self._project([(0,0,0),(60,0,0),(0,60,0),(0,0,60)])
        if valid[0] and math.hypot(S[0,0]-p[0], S[0,1]-p[1]) < 9 and \
                ray_t_at((0,0,0), (0,0,0)) <= solid_t:
            return ("origin", None)
        ends = [(60,0,0),(0,60,0),(0,0,60)]
        best_d, best = thr, None
        for i in range(3):
            if valid[0] and valid[i+1]:
                dd = min_seg_dist(p, S[0:1], S[i+1:i+2])
                if dd < best_d and ray_t_at((0,0,0), ends[i]) <= solid_t:
                    best_d, best = dd, ("axis", i)
        if best: return best
        if fh and fh[1]["type"] == "imported" and fh[1].get("source_format") != "bridge":
            return ("object", fh[1])
        return ("face", (fh[1], fh[2])) if fh else None

    @staticmethod
    def _hover_text(hv):
        if hv is None: return ""
        kind, obj = hv
        if kind == "axis":   return f"{'XYZ'[obj]} axis"
        if kind == "origin": return "Coordinate system origin"
        if kind == "plane":  return f"{obj} plane — click to start sketch"
        if kind == "surface": return f"{obj['name']} — click to start sketch"
        if kind == "face":
            entry, fi = obj
            faces = entry.get("faces", [])
            face = faces[fi] if 0 <= fi < len(faces) else None
            what = f"{face['kind']} face {fi}" if face else "face"
            if face is not None and not face["planar"]: what += " (curved)"
            return f"{entry['name']} — {what}"
        if kind == "object": return f"{obj['name']} — click to select"
        return f"{obj['name']} — click to select"

    @staticmethod
    def _hover_key(hv):
        if hv is None: return None
        kind, obj = hv
        if kind == "face":            return (kind, id(obj[0]), obj[1])
        if isinstance(obj, dict):     return (kind, id(obj))
        return (kind, obj)

    def _set_hover3d(self, hv):
        if self._hover_key(hv) == self._hover_key(self._hover3d): return
        self._hover3d = hv
        if hv is None:
            clickable = False
        elif hv[0] == "face":
            faces = hv[1][0].get("faces", [])
            planar = 0 <= hv[1][1] < len(faces) and faces[hv[1][1]]["planar"]
            clickable = planar or self._mode != MODE_SELPLANE
        else:
            clickable = hv[0] in ("plane", "sketch", "surface")
        self.setCursor(QCursor(Qt.PointingHandCursor) if clickable else self._default_cursor())
        mw = self._main_window
        if mw is not None and hv is not None:
            txt = self._hover_text(hv)
            if self._mode == MODE_SELSURFACE:
                txt += " — click to use as Surface reference" if hv[0] in ("face", "surface") and clickable \
                    else " — select a Surface or solid face"
            elif self._mode == MODE_THREADPICK and hv[0] == "face":
                txt += " — click to choose this cylinder / set the thread start"
            elif self._mode == MODE_SELPLANE and hv[0] == "face":
                txt += " — click to sketch on this face" if clickable else " — not planar"
            elif hv[0] == "face":
                txt += " — click to select this surface"
            mw._st(txt)
        self.update()

    # ── 2-D sketch overlay (painted via QPainter on top of GL) ────────────────
    def paintEvent(self, ev):
        if self._mode == MODE_SKETCH:
            p = QPainter(self)
            p.setRenderHint(QPainter.Antialiasing)
            p.fillRect(self.rect(), QColor(28, 28, 32))
            self._paint_grid(p)
            self._paint_axes(p)
            sk = self.state.get("active_sketch")
            if sk:
                self._paint_solid_underlay(p)
                self._paint_sketch_underlays(p)
                self._paint_sketch(p, sk)
                self._paint_paste_preview(p, sk, self.state.get("sketch_view_state", {}))
            self._paint_hud(p)
            if self.show_fps:
                self._draw_fps(p)
            p.end()
            # refresh sidebar while in sketch mode
            mw = self._main_window
            if mw is not None:
                sk2 = self.state.get("active_sketch")
                if sk2:
                    mw.sketch_panel.refresh(sk2)
                    sv2 = self.state.get("sketch_view_state", {})
                    mw.sketch_panel.mark_constraints(self._selection_constraints(sv2, sk2))
                    has_sel = (sv2.get("sel_seg") is not None or sv2.get("sel_vtx1") is not None
                               or sv2.get("sel_curve") is not None or bool(sv2.get("_sel_extra")))
                    mw.sketch_panel.set_has_selection(has_sel and sv2.get("mode") == DTOOL_SELECT)
        else:
            self.updateGL()

    def _paint_solid_underlay(self, painter):
        underlay = self.state.get("sketch_view_state", {}).get("solid_underlay")
        if underlay is None:
            return
        transform = QTransform(self.scale, 0.0, 0.0, -self.scale,
                               self.width()/2 + self.offset.x(),
                               self.height()/2 + self.offset.y())
        painter.save()
        painter.setBrush(QColor(120, 155, 185, 45))
        painter.setPen(QPen(QColor(150, 185, 215, 190), 1.5))
        painter.drawPath(transform.map(underlay["outline"]))
        painter.setBrush(Qt.NoBrush)
        painter.setPen(QPen(QColor(150, 185, 215, 190), 1.0))
        painter.drawPath(transform.map(underlay["edges"]))
        painter.restore()

    def _paint_sketch_underlays(self, painter):
        underlays = self.state.get("sketch_view_state", {}).get("underlays", [])
        if not underlays:
            return
        painter.setBrush(Qt.NoBrush)
        for underlay in underlays:
            if not underlay["visible"]:
                continue
            if underlay["reference"]:
                continue
            painter.setPen(QPen(QColor(*underlay["color"]), 1.5, Qt.DashLine))
            for points in underlay["paths"]:
                if len(points) < 2:
                    continue
                painter.drawPolyline(QPolygonF([self.to_px(point) for point in points]))
            for point in underlay["points"]:
                painter.drawEllipse(self.to_px(point), 3.0, 3.0)

    def _paint_grid(self, p):
        """Grid, grid lines and snap dots. They only change with zoom / pan / size / grid / snap,
        so they are rendered into a cached pixmap instead of being redrawn on every mouse move."""
        w, h = self.width(), self.height()
        dpr = self.devicePixelRatioF()
        key = (w, h, dpr, self.scale, self.offset.x(), self.offset.y(), self.grid_mm, self.snap_mm)
        cache = self._grid_cache
        if cache is None or cache[0] != key:
            pix = QPixmap(max(1, int(w*dpr)), max(1, int(h*dpr)))
            pix.setDevicePixelRatio(dpr)
            pix.fill(QColor(28, 28, 32))
            q = QPainter(pix); q.setRenderHint(QPainter.Antialiasing)
            self._draw_grid(q)
            q.end()
            self._grid_cache = cache = (key, pix)
        p.drawPixmap(0, 0, cache[1])

    def _draw_grid(self, p):
        w,h = self.width(), self.height()
        x0,y0 = self.to_mm(QPointF(0,h)); x1,y1 = self.to_mm(QPointF(w,0))
        MIN_PX = 8.0   # never draw grid lines / dots closer together than this on screen
        grid = self.grid_mm
        # when zoomed out, only draw every k-th grid line (k from a 1-2-5 series)
        k = 1
        for m in (2, 5, 2, 5):
            if grid*k*self.scale >= MIN_PX: break
            k *= m
        while grid*k*self.scale < MIN_PX:
            k *= 10
        step = grid*k
        minor_v, major_v, minor_h, major_h = [], [], [], []
        axis_v = axis_h = None
        i0 = math.floor(x0/step); i1 = math.ceil(x1/step)
        for i in range(i0, i1+1):
            px = int(self.to_px((i*step,0)).x())
            if i == 0:         axis_v = px
            elif i % 5 == 0:   major_v.append(QLine(px,0,px,h))
            else:              minor_v.append(QLine(px,0,px,h))
        j0 = math.floor(y0/step); j1 = math.ceil(y1/step)
        for j in range(j0, j1+1):
            py = int(self.to_px((0,j*step)).y())
            if j == 0:         axis_h = py
            elif j % 5 == 0:   major_h.append(QLine(0,py,w,py))
            else:              minor_h.append(QLine(0,py,w,py))
        for col, lines in ((QColor(38,38,38), minor_v+minor_h), (QColor(60,60,60), major_v+major_h)):
            if lines:
                p.setPen(QPen(col,1)); p.drawLines(lines)
        if axis_v is not None:
            p.setPen(QPen(QColor(80,80,180),1)); p.drawLine(axis_v,0,axis_v,h)
        if axis_h is not None:
            p.setPen(QPen(QColor(80,180,80),1)); p.drawLine(0,axis_h,w,axis_h)
        # snap dots: skipped when they would be too dense to be useful
        sn = self.snap_mm
        if sn*self.scale >= MIN_PX:
            ia, ib = math.floor(x0/sn), math.ceil(x1/sn)
            ja, jb = math.floor(y0/sn), math.ceil(y1/sn)
            if (ib-ia+1)*(jb-ja+1) <= 40000:
                cx = w/2 + self.offset.x(); cy = h/2 + self.offset.y(); s = self.scale
                pts = QPolygonF([QPointF(cx + i*sn*s, cy - j*sn*s)
                                 for i in range(ia, ib+1) for j in range(ja, jb+1)])
                dot_pen = QPen(QColor(55,55,55), 2); dot_pen.setCapStyle(Qt.RoundCap)
                p.setPen(dot_pen); p.drawPoints(pts)

    def _paint_axes(self, p):
        """Draw X/Y axis lines and origin marker over the sketch grid (hover-highlighted)."""
        ox = self.to_px((0, 0))
        w, h = self.width(), self.height()
        hv = self._hover2d
        o_hot = hv is not None and hv[0] == "origin"
        x_hot = o_hot or (hv is not None and hv[0] == "axis" and hv[1] == "x")
        y_hot = o_hot or (hv is not None and hv[0] == "axis" and hv[1] == "y")
        # X axis
        p.setPen(QPen(QColor(130, 130, 255, 255) if x_hot else QColor(80, 80, 200, 120),
                      3 if x_hot else 1))
        p.drawLine(0, int(ox.y()), w, int(ox.y()))
        # Y axis
        p.setPen(QPen(QColor(120, 230, 120, 255) if y_hot else QColor(80, 180, 80, 120),
                      3 if y_hot else 1))
        p.drawLine(int(ox.x()), 0, int(ox.x()), h)
        # origin dot
        p.setPen(Qt.NoPen)
        p.setBrush(QColor(255, 255, 140, 255) if o_hot else QColor(200, 200, 80, 180))
        p.drawEllipse(ox, 6 if o_hot else 4, 6 if o_hot else 4)
        if o_hot:
            p.setPen(QPen(QColor(255, 255, 160), 1.5)); p.setBrush(Qt.NoBrush)
            p.drawEllipse(ox, 10, 10)
        p.setFont(QFont("Arial", 9, QFont.Bold))
        def arrow(start, end, label, color):
            p.setPen(QPen(color, 2)); p.setBrush(color)
            p.drawLine(start, end)
            direction = end-start
            length = math.hypot(direction.x(), direction.y())
            dx, dy = direction.x()/length, direction.y()/length
            p.drawPolygon(QPolygonF([end, end-QPointF(dx*8-dy*4, dy*8+dx*4),
                                    end-QPointF(dx*8+dy*4, dy*8-dx*4)]))
            p.drawText(QPointF(max(6, min(w-80, end.x()+6)),
                              max(16, min(h-6, end.y()-6))), label)
        # A fixed indicator remains visible when the sketch origin has been panned off-screen.
        anchor = QPointF(72, h-72)
        sk = self.state.get("active_sketch")
        if sk is not None:
            colors = (QColor(255, 110, 100), QColor(110, 230, 130), QColor(110, 150, 255))
            for i, (axis, color) in enumerate(zip("XYZ", colors)):
                direction = QPointF(float(sk.frame[1][i]), -float(sk.frame[2][i]))
                if math.hypot(direction.x(), direction.y()) > 1e-8:
                    arrow(anchor, anchor+direction*48, "+"+axis, color)

    def _arc_px(self, center_mm, r_mm, a0, sweep):
        """QRectF + Qt 1/16-degree start/span for an arc given in mm/radians."""
        cp = self.to_px(center_mm); rpx = r_mm*self.scale
        return (QRectF(cp.x()-rpx, cp.y()-rpx, 2*rpx, 2*rpx),
                int(round(math.degrees(a0)*16)), int(round(math.degrees(sweep)*16)))

    def _paint_hover(self, p, sk, hv):
        """Soft glow under the hovered sketch entity."""
        if hv is None: return
        kind, i = hv
        element = (sk.segments[i] if kind == "seg" and i < len(sk.segments) else
                   sk.vertices[i] if kind == "vtx" and i < len(sk.vertices) else None)
        group = sk.text_group_for(element) if element is not None else None
        glow = QPen(QColor(255, 255, 255, 70), 10, Qt.SolidLine, Qt.RoundCap)
        p.setBrush(Qt.NoBrush)
        if group is not None:
            p.setPen(glow)
            for s in group.segments: p.drawLine(self.to_px(s.v0.xy()), self.to_px(s.v1.xy()))
        elif kind == "seg" and i < len(sk.segments):
            s = sk.segments[i]; p.setPen(glow)
            p.drawLine(self.to_px(s.v0.xy()), self.to_px(s.v1.xy()))
        elif kind == "circle" and i < len(sk.circles):
            c = sk.circles[i]; p.setPen(glow)
            p.drawEllipse(self.to_px(c.center.xy()), c.radius*self.scale, c.radius*self.scale)
        elif kind == "arc" and i < len(sk.arcs):
            a = sk.arcs[i]; a0, sw = a.angles(); p.setPen(glow)
            p.drawArc(*self._arc_px(a.center.xy(), a.radius(), a0, sw))
        elif kind == "vtx" and i < len(sk.vertices):
            pp = self.to_px(sk.vertices[i].xy())
            p.setPen(Qt.NoPen); p.setBrush(QColor(255, 255, 255, 70)); p.drawEllipse(pp, 10, 10)
            p.setPen(QPen(QColor(255, 255, 255, 220), 1.5)); p.setBrush(Qt.NoBrush)
            p.drawEllipse(pp, 7, 7)

    def _paint_paste_preview(self, p, sk, sv):
        data = sv.get("paste_preview")
        if data is None:
            return
        vertices = Sketch.clip_vertices(data)
        if not vertices:
            return
        x0 = min(vertex.x for vertex in vertices)
        y0 = min(vertex.y for vertex in vertices)
        dx, dy = self._cursor_mm[0] - x0, self._cursor_mm[1] - y0
        move = lambda point: (point[0] + dx, point[1] + dy)
        color = QColor(80, 225, 240, 210)
        p.save()
        p.setBrush(Qt.NoBrush)
        p.setPen(QPen(color, 1.5, Qt.DashLine, Qt.RoundCap, Qt.RoundJoin))
        for segment in data["segments"]:
            p.drawLine(self.to_px(move(segment.v0.xy())), self.to_px(move(segment.v1.xy())))
        for circle in data["circles"]:
            center = self.to_px(move(circle.center.xy()))
            radius = circle.radius * self.scale
            p.drawEllipse(center, radius, radius)
            p.drawLine(QPointF(center.x()-4, center.y()), QPointF(center.x()+4, center.y()))
            p.drawLine(QPointF(center.x(), center.y()-4), QPointF(center.x(), center.y()+4))
        for arc in data["arcs"]:
            start_angle, sweep = arc.angles()
            p.drawArc(*self._arc_px(move(arc.center.xy()), arc.radius(), start_angle, sweep))
        p.setPen(QPen(color, 1.5))
        for point in data["points"]:
            center = self.to_px(move(point.xy()))
            p.drawEllipse(center, 4, 4)
            p.drawLine(QPointF(center.x()-5, center.y()), QPointF(center.x()+5, center.y()))
            p.drawLine(QPointF(center.x(), center.y()-5), QPointF(center.x(), center.y()+5))
        p.restore()

    def _paint_sketch(self, p, sk):
        sv = self.state.get("sketch_view_state", {})
        levels = {item["level"]: item for item in sv.get("underlays", [])}

        def visible(geometry):
            level = getattr(geometry, "reference_level", None)
            if level is None:
                return True
            item = levels.get(level)
            return item is not None and item["visible"] and item["reference"]

        def reference_color(geometry):
            item = levels.get(getattr(geometry, "reference_level", None))
            return QColor(*item["color"]) if item is not None else REF

        sel_seg  = sv.get("sel_seg")
        sel_vtx1 = sv.get("sel_vtx1")
        sel_vtx2 = sv.get("sel_vtx2")
        sel_curve= sv.get("sel_curve")
        sel_extra= set(sv.get("_sel_extra") or []) if sv.get("mode") == DTOOL_SELECT else set()
        sel_vs   = {sel_vtx1, sel_vtx2} | {i for kind, i in sel_extra if kind == "vtx"}
        mode     = sv.get("mode", "draw")
        constr_mode = bool(sv.get("construction"))
        CONSTR   = QColor(80, 140, 255)
        REF      = QColor(190, 150, 255)
        DEFINED  = QColor(0, 220, 100)     # fully constrained (no DOF left)
        FREE     = QColor(0, 180, 255)     # still movable
        wip_col  = QColor(80, 140, 255, 170) if constr_mode else QColor(0, 180, 255, 140)
        an       = sk.analysis()
        det_v, det_c = an["det_v"], an["det_c"]

        self._paint_hover(p, sk, self._hover2d)
        self._paint_constraint_highlight(p, sk, sv.get("hl_constraint"))

        def style(geom, defined, selected=False, first_pick=False):
            if selected and mode == DTOOL_SELECT: col = QColor(255, 80, 0)
            elif first_pick:                      col = QColor(255, 200, 0)
            elif selected:                        col = QColor(255, 220, 0)
            elif geom.reference:                  col = reference_color(geom)
            elif geom.construction:               col = CONSTR
            else:                                 col = DEFINED if defined else FREE
            lw = 3 if (selected or first_pick) else (1.5 if geom.construction else 2)
            pen = QPen(col, lw)
            if geom.reference:      pen.setStyle(Qt.DashDotLine)
            elif geom.construction: pen.setStyle(Qt.DashLine)
            return pen, col

        hv_marks = {c.seg: ("H" if isinstance(c, CHorizontal) else "V")
                    for c in sk.constraints if isinstance(c, (CHorizontal, CVertical))}

        # segments
        ctool        = sv.get("ctool", CTOOL_NONE)
        sel_segs_multi = sv.get("_sel_segs", [])
        selected_segs = self._selection_geometry(sv, sk)[0]
        for i, seg in enumerate(sk.segments):
            if not visible(seg):
                continue
            defined = seg.v0 in det_v and seg.v1 in det_v
            is_sel = (i == sel_seg) or (i in sel_segs_multi) or seg in selected_segs
            # first-pick highlight in constrain tools that use segments
            is_first_pick = (is_sel and mode == "constrain" and
                             ctool in (CTOOL_PERP, CTOOL_DIM, CTOOL_PTPT, CTOOL_COLLINEAR,
                                       CTOOL_PARA)) or \
                            (mode == "constrain" and ctool == CTOOL_SYM and
                             sv.get("_sym_center") == ("seg", i)) or \
                            (mode == "constrain" and ctool == CTOOL_EQUAL and
                             sv.get("equal_first") is seg)
            pen, col = style(seg, defined, is_sel, is_first_pick)
            p.setPen(pen)
            pp0=self.to_px(seg.v0.xy()); pp1=self.to_px(seg.v1.xy())
            p.drawLine(pp0, pp1)
            # horizontal / vertical constraint marker
            if seg in hv_marks:
                p.setPen(QPen(QColor(130,130,255),1))
                mid=self.to_px(seg.midpoint())
                p.setFont(QFont("Arial",7))
                p.drawText(mid.toPoint(), f" {hv_marks[seg]}")
            elif not defined and not seg.construction:
                mid=self.to_px(seg.midpoint())
                p.setPen(QColor(255,80,80)); p.setFont(QFont("Arial",8))
                p.drawText(mid.toPoint(), " ?")
            # perp markers
            for c in sk.constraints:
                if isinstance(c,CPerpendicular):
                    for sa,sb in [(c.seg_a,c.seg_b),(c.seg_b,c.seg_a)]:
                        if sa is seg:
                            self._draw_perp_mark(p, sa, sb)

        # circles
        for ci, circ in enumerate(sk.circles):
            if not visible(circ):
                continue
            equal_first = mode == "constrain" and ctool == CTOOL_EQUAL and \
                          sv.get("equal_first") is circ
            pen, col = style(circ, circ in det_c,
                             sel_curve == ("circle", ci) or ("circle", ci) in sel_extra or equal_first,
                             equal_first)
            p.setPen(pen); p.setBrush(Qt.NoBrush)
            cp=self.to_px(circ.center.xy()); rpx=circ.radius*self.scale
            p.drawEllipse(cp, rpx, rpx)
            p.setPen(QPen(col,1))
            p.drawLine(QPointF(cp.x()-5,cp.y()), QPointF(cp.x()+5,cp.y()))
            p.drawLine(QPointF(cp.x(),cp.y()-5), QPointF(cp.x(),cp.y()+5))

        # arcs
        for ai, arc in enumerate(sk.arcs):
            if not visible(arc):
                continue
            defined = {arc.center, arc.v_start, arc.v_end} <= det_v
            pen, col = style(arc, defined, sel_curve == ("arc", ai) or ("arc", ai) in sel_extra)
            p.setPen(pen); p.setBrush(Qt.NoBrush)
            a0, sw = arc.angles()
            p.drawArc(*self._arc_px(arc.center.xy(), arc.radius(), a0, sw))
            cp = self.to_px(arc.center.xy())
            p.setPen(QPen(col,1))
            p.drawLine(QPointF(cp.x()-5,cp.y()), QPointF(cp.x()+5,cp.y()))
            p.drawLine(QPointF(cp.x(),cp.y()-5), QPointF(cp.x(),cp.y()+5))

        for ellipse in sk.ellipses:
            if not visible(ellipse):
                continue
            defined = set(ellipse.vertices()) <= det_v
            selected = any(i in sel_vs and sk.vertices[i] in ellipse.vertices()
                           for i in sel_vs if i is not None and i < len(sk.vertices))
            pen, _col = style(ellipse, defined, selected)
            p.setPen(pen); p.setBrush(Qt.NoBrush)
            points = [self.to_px(point) for point in ellipse.tess()]
            if points: p.drawPolyline(QPolygonF(points + [points[0]]))

        # vertices: blue = only support geometry, green = fully defined, violet = reference
        profile_vs = set(sk.points_free)
        for s in sk.segments:
            if not s.construction: profile_vs |= {s.v0, s.v1}
        for a in sk.arcs:
            if not a.construction: profile_vs |= {a.center, a.v_start, a.v_end}
        for c in sk.circles:
            if not c.construction: profile_vs.add(c.center)
        for ellipse in sk.ellipses:
            if not ellipse.construction: profile_vs.update(ellipse.vertices())
        text_vertices = sk.text_vertices()
        for i,v in enumerate(sk.vertices):
            if v in text_vertices: continue
            if not visible(v): continue
            pp=self.to_px(v.xy()); p.setPen(Qt.NoPen)
            is_fixed = any(isinstance(c,CFixed) and c.vertex is v
                           for c in sk.constraints)
            if v.locked and i not in sel_vs:
                p.setBrush(reference_color(v)); p.drawRect(QRectF(pp.x()-3, pp.y()-3, 6, 6)); continue
            if i in sel_vs:
                p.setBrush(QColor(255,120,0))
            elif is_fixed:
                p.setBrush(QColor(255,60,60))
            elif v not in profile_vs:
                p.setBrush(QColor(110,160,255))
            elif v in det_v:
                p.setBrush(QColor(60,230,120))
            else:
                p.setBrush(QColor(255,200,0))
            p.drawEllipse(pp, 4, 4)
            if is_fixed:
                p.setPen(QPen(QColor(255,60,60),1)); p.setBrush(Qt.NoBrush)
                p.drawRect(QRectF(pp.x()-6,pp.y()-6,12,12))
            if v in sk.points_free:
                p.setPen(QPen(QColor(255,200,0),1.5))
                p.drawLine(QPointF(pp.x()-6,pp.y()-6), QPointF(pp.x()+6,pp.y()+6))
                p.drawLine(QPointF(pp.x()-6,pp.y()+6), QPointF(pp.x()+6,pp.y()-6))

        selected_text = set(self._selected_text_groups(sv, sk)) if mode == DTOOL_SELECT else set()
        first_vtx = sk.vertices[sel_vtx1] if sel_vtx1 is not None and sel_vtx1 < len(sk.vertices) else None
        ptpt_active = mode == "constrain" and ctool == CTOOL_PTPT
        for group in sk.text_groups:
            selected = group in selected_text
            color = QColor(255, 120, 0) if selected else \
                    QColor(80, 220, 245) if ptpt_active else QColor(95, 155, 190, 190)
            corners = [self.to_px(corner) for corner in group.corners()]
            p.setPen(QPen(color, 1, Qt.DashLine)); p.setBrush(Qt.NoBrush)
            p.drawPolygon(QPolygonF(corners))
            p.setPen(QPen(color, 1))
            for i, (vertex, point) in enumerate(zip(group.box_vertices,
                                                     group.constraint_points())):
                pt = self.to_px(point)
                is_first = vertex is first_vtx
                p.setBrush(QColor(255, 145, 35) if is_first else
                           QColor(255, 255, 255) if selected else QColor(32, 35, 41))
                if i == 8:
                    p.drawEllipse(pt, 5 if is_first else 4, 5 if is_first else 4)
                else:
                    radius = 5 if is_first else 4
                    p.drawRect(QRectF(pt.x()-radius, pt.y()-radius, radius*2, radius*2))

        # point-on-line markers: ring + tick along the target line
        for c in sk.constraints:
            if not isinstance(c, CPointOnLine): continue
            pp = self.to_px(c.vertex.xy())
            a = self.to_px(c.seg.v0.xy()); b = self.to_px(c.seg.v1.xy())
            L = math.hypot(b.x()-a.x(), b.y()-a.y()) or 1.0
            ux, uy = (b.x()-a.x())/L, (b.y()-a.y())/L
            p.setPen(QPen(QColor(255,110,255),1.5)); p.setBrush(Qt.NoBrush)
            p.drawEllipse(pp, 7, 7)
            p.drawLine(QPointF(pp.x()-ux*12, pp.y()-uy*12), QPointF(pp.x()+ux*12, pp.y()+uy*12))
        for c in sk.constraints:
            if not isinstance(c, CPointOnCurve): continue
            pp = self.to_px(c.vertex.xy()); cp = self.to_px(c.curve.center.xy())
            L = math.hypot(pp.x()-cp.x(), pp.y()-cp.y()) or 1.0
            ux, uy = -(pp.y()-cp.y())/L, (pp.x()-cp.x())/L        # tangent direction
            p.setPen(QPen(QColor(255,110,255),1.5)); p.setBrush(Qt.NoBrush)
            p.drawEllipse(pp, 7, 7)
            p.drawLine(QPointF(pp.x()-ux*12, pp.y()-uy*12), QPointF(pp.x()+ux*12, pp.y()+uy*12))

        # dimensions (technical drawing style, user-movable)
        self._paint_dimensions(p, sk)
        self._paint_support_info(p, sk)

        # scissor preview: the part that a click would remove
        if mode == "draw" and sv.get("draw_tool") == "trim" and self._trim_hover is not None:
            pts = [self.to_px(q) for q in self._trim_hover]
            p.setPen(QPen(QColor(255, 70, 70, 220), 4, Qt.SolidLine, Qt.RoundCap))
            p.setBrush(Qt.NoBrush)
            p.drawPolyline(QPolygonF(pts))

        # WIP polygon
        wip = sv.get("wip_pts",[])
        if wip:
            for pt in wip:
                pp=self.to_px(pt.xy()); p.setPen(Qt.NoPen)
                p.setBrush(QColor(255,200,0)); p.drawEllipse(pp,4,4)
            last=self.to_px(wip[-1].xy()); cur=self.to_px(self._cursor_mm)
            p.setPen(QPen(wip_col,1,Qt.DashLine))
            p.drawLine(last, cur)

        # WIP rect
        rp0 = sv.get("rect_p0")
        if rp0:
            x0,y0=rp0.x,rp0.y; x1,y1=self._cursor_mm
            corners=[(x0,y0),(x1,y0),(x1,y1),(x0,y1)]
            pxc=[self.to_px(c) for c in corners]
            p.setPen(QPen(wip_col,1,Qt.DashLine)); p.setBrush(Qt.NoBrush)
            for k in range(4):
                p.drawLine(pxc[k], pxc[(k+1)%4])

        # WIP circle (centre stored as mm tuple until committed)
        cc = sv.get("circle_ctr")
        if cc:
            cp=self.to_px(cc); cur=self.to_px(self._cursor_mm)
            rpx=math.hypot(cur.x()-cp.x(),cur.y()-cp.y())
            p.setPen(QPen(wip_col,1,Qt.DashLine)); p.setBrush(Qt.NoBrush)
            p.drawEllipse(cp,rpx,rpx)
            p.drawLine(cp, cur)
            p.setPen(Qt.NoPen); p.setBrush(QColor(255,200,0))
            p.drawEllipse(cp,4,4)

        # WIP ellipse: centre, major-axis endpoint, then minor-axis endpoint.
        ellipse_center = sv.get("ellipse_ctr")
        if ellipse_center is not None:
            ellipse_axis = sv.get("ellipse_axis")
            axis_endpoint = ellipse_axis or self._cursor_mm
            points = self._ellipse_points(ellipse_center, axis_endpoint, self._cursor_mm)
            cp = self.to_px(ellipse_center)
            p.setPen(QPen(wip_col,1,Qt.DashLine)); p.setBrush(Qt.NoBrush)
            if points is None:
                radius = math.dist(ellipse_center, self._cursor_mm)*self.scale
                p.drawEllipse(cp, radius, radius)
            else:
                p.drawPolygon(QPolygonF([self.to_px(point) for point in points]))
            p.drawLine(cp, self.to_px(axis_endpoint))
            p.setPen(Qt.NoPen); p.setBrush(QColor(255,200,0)); p.drawEllipse(cp,4,4)

        # WIP regular polygon (centre + circumradius)
        pc = sv.get("polygon_ctr")
        if pc:
            radius = math.hypot(self._cursor_mm[0]-pc[0], self._cursor_mm[1]-pc[1])
            sides = max(5, min(64, int(sv.get("polygon_sides", 6))))
            pts = [self.to_px((pc[0] + radius*math.cos(2*math.pi*i/sides),
                               pc[1] + radius*math.sin(2*math.pi*i/sides)))
                   for i in range(sides)]
            p.setPen(QPen(wip_col,1,Qt.DashLine)); p.setBrush(Qt.NoBrush)
            p.drawPolygon(QPolygonF(pts))
            cp = self.to_px(pc)
            p.drawLine(cp, self.to_px(self._cursor_mm))
            p.setPen(Qt.NoPen); p.setBrush(QColor(255,200,0)); p.drawEllipse(cp,4,4)

        # WIP freehand stroke
        fp = sv.get("free_pts")
        if fp and len(fp) > 1:
            p.setPen(QPen(wip_col, 2, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)); p.setBrush(Qt.NoBrush)
            p.drawPolyline(QPolygonF([self.to_px(q) for q in fp]))

        # WIP arc: centre → start (radius) → end (direction follows the mouse sweep)
        ac = sv.get("arc_ctr")
        if ac:
            cp = self.to_px(ac); cur = self.to_px(self._cursor_mm)
            ast = sv.get("arc_start")
            p.setBrush(Qt.NoBrush)
            if ast is None:
                rpx = math.hypot(cur.x()-cp.x(), cur.y()-cp.y())
                p.setPen(QPen(QColor(wip_col.red(),wip_col.green(),wip_col.blue(),60),1,Qt.DotLine))
                p.drawEllipse(cp, rpx, rpx)
                p.setPen(QPen(wip_col,1,Qt.DashLine)); p.drawLine(cp, cur)
            else:
                r = math.hypot(ast[0]-ac[0], ast[1]-ac[1])
                a0 = math.atan2(ast[1]-ac[1], ast[0]-ac[0])
                sweep = sv.get("arc_sweep", 0.0)
                p.setPen(QPen(QColor(wip_col.red(),wip_col.green(),wip_col.blue(),60),1,Qt.DotLine))
                p.drawEllipse(cp, r*self.scale, r*self.scale)
                p.setPen(QPen(wip_col,2,Qt.DashLine))
                if abs(sweep) > 1e-6:
                    p.drawArc(*self._arc_px(ac, r, a0, sweep))
                p.setPen(QPen(wip_col,1,Qt.DotLine))
                sp = self.to_px(ast)
                ep = self.to_px((ac[0]+r*math.cos(a0+sweep), ac[1]+r*math.sin(a0+sweep)))
                p.drawLine(cp, sp); p.drawLine(cp, ep)
                p.setPen(Qt.NoPen); p.setBrush(QColor(255,200,0))
                p.drawEllipse(sp,4,4); p.drawEllipse(ep,3,3)
            p.setPen(Qt.NoPen); p.setBrush(QColor(255,200,0))
            p.drawEllipse(cp,4,4)

        # snap marker: square = existing point, ✕ = line crossing, ring = on a line, + = grid
        if mode == "draw" and self.underMouse() and sv.get("draw_tool") != "trim":
            cp = self.to_px(self._cursor_mm)
            p.setBrush(Qt.NoBrush)
            on_lines = self._pt_snap_segs if sv.get("draw_tool") == "point" else []
            if self._snap_vtx is not None:
                p.setPen(QPen(QColor(255, 230, 0), 1.5))
                p.drawRect(QRectF(cp.x()-6, cp.y()-6, 12, 12))
            elif len(on_lines) >= 2:
                p.setPen(QPen(QColor(255, 90, 255), 2))
                p.drawLine(QPointF(cp.x()-7, cp.y()-7), QPointF(cp.x()+7, cp.y()+7))
                p.drawLine(QPointF(cp.x()-7, cp.y()+7), QPointF(cp.x()+7, cp.y()-7))
            elif on_lines:
                p.setPen(QPen(QColor(255, 90, 255), 1.5)); p.drawEllipse(cp, 6, 6)
            else:
                p.setPen(QPen(QColor(220, 220, 220, 200), 1))
                p.drawLine(QPointF(cp.x()-5, cp.y()), QPointF(cp.x()+5, cp.y()))
                p.drawLine(QPointF(cp.x(), cp.y()-5), QPointF(cp.x(), cp.y()+5))

        # first pick of the Distance tool
        first = sv.get("dist_first")
        if first is not None:
            glow = QPen(QColor(255, 160, 0, 150), 9, Qt.SolidLine, Qt.RoundCap)
            if isinstance(first, Segment) and first in sk.segments:
                p.setPen(glow); p.drawLine(self.to_px(first.v0.xy()), self.to_px(first.v1.xy()))
            elif isinstance(first, Vertex) and first in sk.vertices:
                p.setPen(Qt.NoPen); p.setBrush(QColor(255, 160, 0, 170))
                p.drawEllipse(self.to_px(first.xy()), 9, 9); p.setBrush(Qt.NoBrush)

        # two-point guide
        if sel_vtx1 is not None and mode != DTOOL_SELECT and sel_vtx1 < len(sk.vertices):
            v1=sk.vertices[sel_vtx1]
            pp1=self.to_px(v1.xy()); cur=self.to_px(self._cursor_mm)
            p.setPen(QPen(QColor(255,120,0,160),1,Qt.DashLine))
            p.drawLine(pp1, cur)

        # rubber-band selection rectangle
        if mode == DTOOL_SELECT and self._rband_active and self._rband_start is not None:
            cur_px = QPointF(self._rband_cur) if self._rband_cur else self._rband_start
            rx0 = int(min(self._rband_start.x(), cur_px.x()))
            ry0 = int(min(self._rband_start.y(), cur_px.y()))
            rw  = int(abs(cur_px.x() - self._rband_start.x()))
            rh  = int(abs(cur_px.y() - self._rband_start.y()))
            p.setPen(QPen(QColor(200,200,200,180), 1, Qt.DashLine))
            p.setBrush(QColor(180,180,180,30))
            p.drawRect(rx0, ry0, rw, rh)

    def _paint_constraint_highlight(self, p, sk, c):
        """Magenta glow on the geometry referenced by the constraint selected in the list."""
        if c is None or c not in sk.constraints: return
        glow = QPen(QColor(255, 60, 255, 110), 10, Qt.SolidLine, Qt.RoundCap)
        p.setBrush(Qt.NoBrush)
        for g in constraint_refs(c):
            level = getattr(g, "reference_level", None)
            if level is not None and not any(
                    item["level"] == level and item["visible"]
                    for item in self.state.get("sketch_view_state", {}).get("underlays", [])):
                continue
            p.setPen(glow)
            if isinstance(g, Segment):
                p.drawLine(self.to_px(g.v0.xy()), self.to_px(g.v1.xy()))
            elif isinstance(g, Circle):
                p.drawEllipse(self.to_px(g.center.xy()), g.radius*self.scale, g.radius*self.scale)
            elif isinstance(g, Arc):
                a0, sw = g.angles(); p.drawArc(*self._arc_px(g.center.xy(), g.radius(), a0, sw))
            elif isinstance(g, Vertex):
                p.setPen(Qt.NoPen); p.setBrush(QColor(255, 60, 255, 140))
                p.drawEllipse(self.to_px(g.xy()), 10, 10); p.setBrush(Qt.NoBrush)

    # ── technical-drawing dimensions ──────────────────────────────────────────
    DIM_COL = QColor(170, 240, 170)
    INFO_COL = QColor(140, 175, 235)   # information-only (reference) distances

    @staticmethod
    def _arrow(p, tip, u, col, length=9.0, half_w=3.0):
        """Filled arrowhead whose tip is at `tip`, pointing along unit vector u."""
        bx, by = tip.x()-u[0]*length, tip.y()-u[1]*length
        p.setPen(Qt.NoPen); p.setBrush(col)
        p.drawPolygon(QPolygonF([QPointF(tip), QPointF(bx-u[1]*half_w, by+u[0]*half_w),
                                 QPointF(bx+u[1]*half_w, by-u[0]*half_w)]))
        p.setBrush(Qt.NoBrush)

    @staticmethod
    def _dim_text_box(p, rect, text, col):
        p.setPen(Qt.NoPen); p.setBrush(QColor(28, 28, 32, 220)); p.drawRect(rect)
        p.setPen(col); p.drawText(rect, Qt.AlignCenter, text)
        p.setBrush(Qt.NoBrush)

    def _dim_text(self, p, center, angle_deg, text, col):
        """Text centred above the dimension line, rotated to stay readable.
        Returns the text box as a screen polygon (for hit testing)."""
        a = angle_deg
        while a >= 90:  a -= 180
        while a < -90:  a += 180
        p.save(); p.translate(center); p.rotate(a)
        p.setFont(QFont("Arial", 8))
        fm = p.fontMetrics(); w = fm.horizontalAdvance(text) + 4; h = fm.height()
        rect = QRectF(-w/2, -h-1, w, h)
        self._dim_text_box(p, rect, text, col)
        poly = p.transform().map(QPolygonF(rect))
        p.restore()
        return poly

    def _paint_dim_linear(self, p, c, A, B, n0, text, col):
        """A,B: measured points (px). n0: unit base normal (px) of the measuring direction.
        The dimension line sits c.off_mm beyond the outermost point on side c.side of n0;
        the text sits at fraction c.t_frac along the dimension line."""
        side = c.side if c.side is not None else getattr(c, "_auto_side", 1)
        n = (n0[0]*side, n0[1]*side)
        off = c.off_mm*self.scale if c.off_mm is not None else 22.0
        sA = A.x()*n[0]+A.y()*n[1]; sB = B.x()*n[0]+B.y()*n[1]
        s  = max(sA, sB) + off
        A2 = QPointF(A.x()+n[0]*(s-sA), A.y()+n[1]*(s-sA))
        B2 = QPointF(B.x()+n[0]*(s-sB), B.y()+n[1]*(s-sB))
        L = math.hypot(B2.x()-A2.x(), B2.y()-A2.y())
        if L < 1e-6: return
        u = ((B2.x()-A2.x())/L, (B2.y()-A2.y())/L)
        pen = QPen(col, 1); p.setPen(pen)
        # extension lines: small gap at the geometry, small overshoot past the dimension line
        for P, P2, sP in ((A, A2, sA), (B, B2, sB)):
            if s - sP > 5:
                p.drawLine(QPointF(P.x()+n[0]*3, P.y()+n[1]*3),
                           QPointF(P2.x()+n[0]*4, P2.y()+n[1]*4))
        p.drawLine(A2, B2)
        if L > 26:
            self._arrow(p, A2, (-u[0], -u[1]), col); self._arrow(p, B2, u, col)
        else:   # too short — arrows outside, pointing inwards
            p.setPen(pen)
            p.drawLine(A2, QPointF(A2.x()-u[0]*16, A2.y()-u[1]*16))
            p.drawLine(B2, QPointF(B2.x()+u[0]*16, B2.y()+u[1]*16))
            self._arrow(p, A2, u, col); self._arrow(p, B2, (-u[0], -u[1]), col)
        t = c.t_frac
        T = QPointF(A2.x()+(B2.x()-A2.x())*t, A2.y()+(B2.y()-A2.y())*t)
        if t < 0 or t > 1:          # text moved outside: extend the dimension line to it
            p.setPen(pen); p.drawLine(A2 if t < 0 else B2, T)
        poly = self._dim_text(p, T, math.degrees(math.atan2(u[1], u[0])), text, col)
        self._dim_hits.append((c, "linear", (A, B, n0), poly, (A2, B2)))

    def _paint_dim_radial(self, p, c, cp, rpx, ang, text, diameter, col):
        """Diameter (through centre, two arrows) or radius (centre→edge) with leader + shoulder."""
        u = (math.cos(ang), -math.sin(ang))          # mm angle → screen direction
        P2 = QPointF(cp.x()+u[0]*rpx, cp.y()+u[1]*rpx)
        p.setPen(QPen(col, 1))
        if diameter:
            P1 = QPointF(cp.x()-u[0]*rpx, cp.y()-u[1]*rpx)
            p.drawLine(P1, P2); self._arrow(p, P1, (-u[0], -u[1]), col)
            line = (P1, P2)
        else:
            p.drawLine(cp, P2)
            p.setPen(Qt.NoPen); p.setBrush(col); p.drawEllipse(cp, 2, 2)
            line = (cp, P2)
        self._arrow(p, P2, u, col)
        p.setFont(QFont("Arial", 8))
        fm = p.fontMetrics(); w = fm.horizontalAdvance(text) + 6; h = fm.height()
        P3 = QPointF(P2.x()+u[0]*16, P2.y()+u[1]*16)
        sgn = 1 if u[0] >= 0 else -1
        P4 = QPointF(P3.x()+sgn*w, P3.y())
        p.setPen(QPen(col, 1)); p.drawLine(P2, P3); p.drawLine(P3, P4)
        rect = QRectF(min(P3.x(), P4.x()), P3.y()-h-1, w, h)
        self._dim_text_box(p, rect, text, col)
        self._dim_hits.append((c, "radial", cp, QPolygonF(rect), line))

    def _paint_dimensions(self, p, sk):
        self._dim_hits = []
        sv = self.state.get("sketch_view_state", {})
        hv = self._hover2d
        active = {hv[1]} if hv is not None and hv[0] == "dim" else set()
        if self._drag_dim is not None: active.add(self._drag_dim[0])
        hl = sv.get("hl_constraint")
        vs = list(sk.used_vertices()) or sk.vertices
        if vs:
            C = self.to_px((sum(v.x for v in vs)/len(vs), sum(v.y for v in vs)/len(vs)))
        else:
            C = QPointF(self.width()/2, self.height()/2)
        def auto_side(n, mid):
            d = n[0]*(mid.x()-C.x()) + n[1]*(mid.y()-C.y())
            if abs(d) < 1e-6: return 1 if n[1] <= 0 else -1
            return 1 if d > 0 else -1
        for c in sk.constraints:
            if isinstance(c, CDistance):
                col = QColor(255, 255, 255) if c in active else \
                      QColor(255, 120, 255) if c is hl else \
                      (self.DIM_COL if c.driving else self.INFO_COL)
                self._paint_distance(p, c, col, auto_side)
                continue
            if not isinstance(c, CDimension): continue
            col = QColor(255, 255, 255) if c in active else \
                  QColor(255, 120, 255) if c is hl else self.DIM_COL
            t = c.target
            if isinstance(t, Segment) or (isinstance(t, tuple) and t[0] is not t[1]):
                v0, v1 = (t.v0, t.v1) if isinstance(t, Segment) else t
                A = self.to_px(v0.xy()); B = self.to_px(v1.xy())
                mid = QPointF((A.x()+B.x())/2, (A.y()+B.y())/2)
                orient = c.orient if isinstance(t, tuple) else None
                if orient == "H":   n0 = (0.0, 1.0)
                elif orient == "V": n0 = (1.0, 0.0)
                else:
                    L = math.hypot(B.x()-A.x(), B.y()-A.y())
                    if L < 1e-6: continue
                    n0 = (-(B.y()-A.y())/L, (B.x()-A.x())/L)
                c._auto_side = auto_side(n0, mid)   # used until the user moves the dimension
                self._paint_dim_linear(p, c, A, B, n0, f"{c.value:.1f}", col)
            elif isinstance(t, Circle):
                dia = c.dim_mode == "diameter"
                lbl = f"⌀{c.value:.1f}" if dia else f"R{c.value:.1f}"
                ang = c.angle if c.angle is not None else math.pi/4
                self._paint_dim_radial(p, c, self.to_px(t.center.xy()), t.radius*self.scale,
                                       ang, lbl, dia, col)
            elif isinstance(t, Arc):
                ang = c.angle if c.angle is not None else t.mid_angle()
                self._paint_dim_radial(p, c, self.to_px(t.center.xy()), t.radius()*self.scale,
                                       ang, f"R{c.value:.1f}", False, col)

    def _paint_support_info(self, p, sk):
        """Support geometry always shows its size as information (blue, in brackets):
        line length, circle diameter, arc radius — unless a dimension already shows it."""
        dimmed = {c.target for c in sk.constraints if isinstance(c, CDimension)
                  and isinstance(c.target, (Segment, Circle, Arc))}
        col = self.INFO_COL
        for s in sk.segments:
            if not s.construction or s.reference or s in dimmed: continue
            A, B = self.to_px(s.v0.xy()), self.to_px(s.v1.xy())
            if math.hypot(B.x()-A.x(), B.y()-A.y()) < 24: continue
            mid = QPointF((A.x()+B.x())/2, (A.y()+B.y())/2)
            self._dim_text(p, mid, math.degrees(math.atan2(B.y()-A.y(), B.x()-A.x())),
                           f"({s.length():.1f})", col)
        for c in sk.circles:
            if not c.construction or c.reference or c in dimmed: continue
            cp, r = self.to_px(c.center.xy()), c.radius*self.scale
            if r < 6: continue
            self._dim_text(p, QPointF(cp.x(), cp.y()-r-2), 0.0, f"(⌀{2*c.radius:.1f})", col)
        for a in sk.arcs:
            if not a.construction or a.reference or a in dimmed: continue
            cp, r, m = self.to_px(a.center.xy()), a.radius()*self.scale, a.mid_angle()
            if r < 6: continue
            P = QPointF(cp.x()+(r+4)*math.cos(m), cp.y()-(r+4)*math.sin(m)+6)
            self._dim_text(p, P, 0.0, f"(R{a.radius():.1f})", col)

    def _paint_distance(self, p, c, col, auto_side):
        """Distance between points, lines or circles, or angle between two lines."""
        def foot(P, a, b):            # foot of P on the infinite line a→b (all px)
            dx, dy = b.x()-a.x(), b.y()-a.y(); l2 = dx*dx+dy*dy or 1e-12
            t = ((P.x()-a.x())*dx + (P.y()-a.y())*dy)/l2
            return QPointF(a.x()+t*dx, a.y()+t*dy), t
        def extend(a, b, F, t):      # thin dashed extension of a line out to F
            if t < 0 or t > 1:
                p.setPen(QPen(col, 1, Qt.DotLine)); p.drawLine(a if t < 0 else b, F)
        if c.pair == "ss" and c.mode == "angle":
            self._paint_angle(p, c, col); return
        if c.pair == "cc":
            center_a = np.asarray(c.a.center.xy(), dtype=float)
            center_b = np.asarray(c.b.center.xy(), dtype=float)
            delta = center_b - center_a
            center_distance = float(np.linalg.norm(delta))
            direction = delta / center_distance if center_distance > 1e-9 else np.array([1.0, 0.0])
            if c.circle_relation == "center":
                point_a, point_b = center_a, center_b
            elif c.circle_relation == "concentric":
                direction = np.array([math.cos(c.angle), math.sin(c.angle)]) \
                            if c.angle is not None else direction
                point_a = center_a + c.a.radius * direction
                point_b = center_a + c.b.radius * direction
            elif c.circle_relation == "nested":
                inner = c.b if c.circle_outer is c.a else c.a
                outer = c.circle_outer
                outer_center = np.asarray(outer.center.xy(), dtype=float)
                inner_center = np.asarray(inner.center.xy(), dtype=float)
                inner_direction = (inner_center - outer_center) / center_distance \
                                  if center_distance > 1e-9 else direction
                point_a = outer_center - outer.radius * inner_direction
                point_b = inner_center - inner.radius * inner_direction
            else:
                point_a = center_a + c.a.radius * direction
                point_b = center_b - c.b.radius * direction
            A, B = self.to_px(point_a), self.to_px(point_b)
            L = math.hypot(B.x()-A.x(), B.y()-A.y())
            if L < 1e-6:
                poly = self._dim_text(p, QPointF(A.x(), A.y()-6), 0.0, c.label(), col)
                self._dim_hits.append((c, "linear", (A, B, (0.0, -1.0)), poly, None))
                return
            n0 = (-(B.y()-A.y())/L, (B.x()-A.x())/L)
            c._auto_side = auto_side(n0, QPointF((A.x()+B.x())/2, (A.y()+B.y())/2))
            self._paint_dim_linear(p, c, A, B, n0, c.label(), col)
            return
        elif c.pair == "vv":
            A, B = self.to_px(c.a.xy()), self.to_px(c.b.xy())
        elif c.pair == "cs":
            line = c.b
            a, b = self.to_px(line.v0.xy()), self.to_px(line.v1.xy())
            center = self.to_px(c.a.center.xy())
            foot_point, t = foot(center, a, b)
            extend(a, b, foot_point, t)
            dx, dy = foot_point.x()-center.x(), foot_point.y()-center.y()
            length = math.hypot(dx, dy)
            if length < 1e-6:
                line_dx, line_dy = b.x()-a.x(), b.y()-a.y()
                line_length = math.hypot(line_dx, line_dy) or 1.0
                dx, dy = -line_dy/line_length*c.circle_side, line_dx/line_length*c.circle_side
            else:
                dx, dy = dx/length, dy/length
            A = QPointF(center.x()+dx*c.a.radius*self.scale,
                        center.y()+dy*c.a.radius*self.scale)
            B = foot_point
        else:
            line = c.b if c.pair == "vs" else c.a          # the line the distance is measured to
            a, b = self.to_px(line.v0.xy()), self.to_px(line.v1.xy())
            if c.pair == "vs":
                A = self.to_px(c.a.xy())
            else:                                           # from the midpoint of line b
                A = self.to_px(c.b.midpoint())
            B, t = foot(A, a, b)
            extend(a, b, B, t)
        L = math.hypot(B.x()-A.x(), B.y()-A.y())
        orient = getattr(c, "orient", "D") if c.pair == "vv" else "D"
        if orient in ("H", "V") and L >= 1e-6:
            n0 = (0.0, 1.0) if orient == "H" else (1.0, 0.0)
            along = abs(B.x()-A.x()) if orient == "H" else abs(B.y()-A.y())
            if along < 0.5:          # 0 distance = points aligned: dashed alignment line + value
                p.setPen(QPen(col, 1, Qt.DashLine)); p.drawLine(A, B)
                M = QPointF((A.x()+B.x())/2 + (8 if orient == "H" else 0),
                            (A.y()+B.y())/2 - (0 if orient == "H" else 4))
                poly = self._dim_text(p, M, 0.0 if orient == "V" else -90.0, c.label(), col)
                self._dim_hits.append((c, "linear", (A, B, n0), poly, (A, B))); return
            c._auto_side = auto_side(n0, QPointF((A.x()+B.x())/2, (A.y()+B.y())/2))
            self._paint_dim_linear(p, c, A, B, n0, c.label(), col); return
        if L < 1e-6:
            poly = self._dim_text(p, QPointF(A.x(), A.y()-6), 0.0, c.label(), col)
            self._dim_hits.append((c, "linear", (A, B, (0.0, -1.0)), poly, None)); return
        n0 = (-(B.y()-A.y())/L, (B.x()-A.x())/L)
        c._auto_side = auto_side(n0, QPointF((A.x()+B.x())/2, (A.y()+B.y())/2))
        self._paint_dim_linear(p, c, A, B, n0, c.label(), col)

    def _paint_angle(self, p, c, col):
        """Angle between two lines: arc around their intersection, arrows, text."""
        a0, a1 = self.to_px(c.a.v0.xy()), self.to_px(c.a.v1.xy())
        b0, b1 = self.to_px(c.b.v0.xy()), self.to_px(c.b.v1.xy())
        rx, ry, sx, sy = a1.x()-a0.x(), a1.y()-a0.y(), b1.x()-b0.x(), b1.y()-b0.y()
        den = rx*sy - ry*sx
        if abs(den) < 1e-9:            # parallel: just show the value between them
            M = QPointF((a0.x()+b0.x())/2, (a0.y()+b0.y())/2)
            poly = self._dim_text(p, M, 0.0, c.label(), col)
            self._dim_hits.append((c, "angle", M, poly, None)); return
        t = ((b0.x()-a0.x())*sy - (b0.y()-a0.y())*sx)/den
        I = QPointF(a0.x()+t*rx, a0.y()+t*ry)
        def unit(x, y):
            l = math.hypot(x, y) or 1.0; return (x/l, y/l)
        sides = getattr(c, "angle_sides", None)
        if sides is not None:
            dA = unit(rx*sides[0], ry*sides[0])
            dB = unit(sx*sides[1], sy*sides[1])
        else:
            ma = QPointF((a0.x()+a1.x())/2, (a0.y()+a1.y())/2)
            sgn = 1.0 if (ma.x()-I.x())*rx + (ma.y()-I.y())*ry >= 0 else -1.0
            dA = unit(rx*sgn, ry*sgn)
        R = c.off_mm*self.scale if c.off_mm is not None else 40.0
        angA = math.degrees(math.atan2(-dA[1], dA[0]))
        if sides is not None:
            angB = math.degrees(math.atan2(-dB[1], dB[0]))
            span = (angB-angA+180.0) % 360.0 - 180.0
        else:
            span = -float(c.value if c.driving else c.measure())
            angB = math.radians(angA+span)
            dB = (math.cos(angB), -math.sin(angB))
        pen = QPen(col, 1); p.setPen(pen); p.setBrush(Qt.NoBrush)
        # thin extensions from the intersection to each line when needed
        p.setPen(QPen(col, 1, Qt.DotLine))
        p.drawLine(I, QPointF(I.x()+dA[0]*(R+8), I.y()+dA[1]*(R+8)))
        p.drawLine(I, QPointF(I.x()+dB[0]*(R+8), I.y()+dB[1]*(R+8)))
        p.setPen(pen)
        p.drawArc(QRectF(I.x()-R, I.y()-R, 2*R, 2*R), int(angA*16), int(span*16))
        def at(deg): r = math.radians(deg); return QPointF(I.x()+R*math.cos(r), I.y()-R*math.sin(r))
        def tangent(deg, sense):        # screen direction of increasing visual angle * sense
            r = math.radians(deg); return (-math.sin(r)*sense, -math.cos(r)*sense)
        s = 1.0 if span >= 0 else -1.0
        self._arrow(p, at(angA), tangent(angA, -s), col)
        self._arrow(p, at(angA+span), tangent(angA+span, s), col)
        mid = math.radians(angA + span/2)
        T = QPointF(I.x()+(R+12)*math.cos(mid), I.y()-(R+12)*math.sin(mid))
        poly = self._dim_text(p, T, 0.0, c.label(), col)
        self._dim_hits.append((c, "angle", I, poly, None))

    def _draw_perp_mark(self, p, sa, sb):
        # small square at the shared vertex
        shared = None
        if sa.v1 is sb.v0: shared = sa.v1
        elif sa.v0 is sb.v1: shared = sa.v0
        if not shared: return
        pp=self.to_px(shared.xy())
        p.setPen(QPen(QColor(180,180,255),1)); p.setBrush(Qt.NoBrush)
        p.drawRect(int(pp.x()-4),int(pp.y()-4),8,8)

    def _paint_hud(self, p):
        sk = self.state.get("active_sketch")
        plane = sk.plane if sk else "—"
        sv = self.state.get("sketch_view_state",{})
        tool = sv.get("draw_tool","line")
        mode = sv.get("mode","draw")
        ctool= sv.get("ctool", CTOOL_NONE)
        p.setPen(QColor(200,200,200)); p.setFont(QFont("Arial",9))
        support = "  SUPPORT GEOMETRY" if sv.get("construction") else ""
        p.drawText(8,18,f"{plane}  [{mode}/{tool}]  "
                        f"snap:{self.snap_mm}mm  grid:{self.grid_mm}mm  "
                        f"cursor:{self._cursor_mm[0]:.1f},{self._cursor_mm[1]:.1f}")
        if support:
            p.setPen(QColor(110,160,255)); p.setFont(QFont("Arial",9,QFont.Bold))
            p.drawText(self.width()-160, 18, "┄ Support geometry")
            p.setPen(QColor(200,200,200)); p.setFont(QFont("Arial",9))
        if sk:
            dof = sk.total_dof(); blocking = sk.blocking_issues()
            if blocking:
                p.setPen(QColor(255,100,100))
                p.drawText(8,36,f"⚠ {blocking[0]}  DOF:{dof}")
            elif dof > 0:
                p.setPen(QColor(255,200,80))
                p.drawText(8,36,f"◐ Under-constrained — {dof} DOF left (Accept allowed)")
            else:
                p.setPen(QColor(100,255,100))
                p.drawText(8,36,"✔ Fully constrained — DOF:0")
            opt = sk.optional_dof()
            if opt and not blocking:
                p.setPen(QColor(120,160,230))
                p.drawText(8,72, f"Support geometry / points: {opt} optional DOF (not required)")
        if sv.get("paste_preview") is not None:
            p.setPen(QColor(80,225,240)); p.setFont(QFont("Arial",9))
            p.drawText(8,54,"Paste preview — X/Y mirror · click to place · Esc / right-click to cancel")
        elif mode == DTOOL_SELECT and ctool == CTOOL_NONE:
            p.setPen(QColor(170,170,170)); p.setFont(QFont("Arial",9))
            p.drawText(8,54,"Drag geometry (constraints are kept) · drag dimensions to move them · "
                            "double-click a dimension or text to edit")
        if ctool != CTOOL_NONE and sv.get("paste_preview") is None:
            p.setPen(QColor(255,80,80)); p.setFont(QFont("Arial",9))
            hints={CTOOL_LENGTH:"Choose two points, lines or circles for a distance or clearance",
            CTOOL_DIM:"Click a circle to set its diameter or radius",
            CTOOL_COLLINEAR:"Click two lines to make them collinear",
            CTOOL_ANGLE:"Click first line, then second line to set their angle",
            CTOOL_PERP:"Click first segment, then second", CTOOL_FIX:"Click vertex to fix/unfix",
            CTOOL_PTPT:"Click a point or line to move, then a point, line, circle/arc or origin",
            CTOOL_EQUAL:"Click two lines for equal length or two circles for equal diameter",
            CTOOL_PARA:"Click first line, then second line to make parallel",
            CTOOL_SYM:"Click center line or point, then two points, lines, or circles",
            CTOOL_TANGENT:"Click a line and circle/arc, or two circles/arcs, to make them tangent"}
            p.drawText(8,54, hints.get(ctool,""))
        elif mode == "draw" and sv.get("paste_preview") is None:
            step_hints = {
                "circle": "Click centre, then click to set radius",
                "ellipse": ("Click centre, major-axis endpoint, then minor-axis endpoint"),
                "polygon": "Click centre, then click to set circumradius",
                "arc": ("Click centre" if sv.get("arc_ctr") is None else
                        "Click start point (sets radius)" if sv.get("arc_start") is None else
                        "Move around the centre for direction, click end point"),
                "freehand": "Press and drag to draw a freehand line; release to convert it to line segments "
                            "(release on the start point to close the shape)",
                "point": "Click to place a point — snaps to line crossings (✕) and onto lines (○)",
                "text": "Click to open the text editor and place a label",
                "trim": "Scissor: click the part of a line / circle / arc to remove (red) — "
                        "it is cut at crossings and points",
            }
            if tool in step_hints:
                p.setPen(QColor(255,200,80)); p.setFont(QFont("Arial",9))
                p.drawText(8,54, step_hints[tool])

    # ── mouse ─────────────────────────────────────────────────────────────────
    def mousePressEvent(self, e):
        if e.button() == Qt.LeftButton and self._mode != MODE_SKETCH and self._begin_dimension_drag(e):
            return
        if self._angle_mode:
            if e.button() == Qt.LeftButton:
                self._last_pos = self._press_pos = e.pos()
                return
            if e.button() == Qt.RightButton:
                if self._main_window is not None:
                    self._main_window._angle_draft_backstep()
                return
        if self._mode == MODE_THREADPICK:
            if e.button() == Qt.LeftButton:
                self._last_pos = self._press_pos = e.pos()    # a click picks on release, a drag orbits
                return
            if e.button() == Qt.RightButton:
                if self._main_window is not None: self._main_window._cancel_thread_pick()
                return
        if self._mode in (MODE_SELPLANE, MODE_SELSURFACE) and e.button()==Qt.LeftButton:
            hv = self._pick3d(e.pos())
            if self._mode == MODE_SELSURFACE and hv is not None and hv[0] == "surface":
                self.surfaceReferenceSelected.emit(hv[1], None)
            elif self._mode == MODE_SELSURFACE and hv is not None and hv[0] == "face":
                self.surfaceReferenceSelected.emit(*hv[1])
            elif self._mode == MODE_SELPLANE and hv is not None and hv[0] == "plane":
                self.planeSelected.emit(hv[1])
            elif self._mode == MODE_SELPLANE and hv is not None and hv[0] == "surface":
                self.surfaceSelected.emit(hv[1])
            elif self._mode == MODE_SELPLANE and hv is not None and hv[0] == "face":
                entry, fi = hv[1]
                if 0 <= fi < len(entry.get("faces", [])) and entry["faces"][fi]["planar"]:
                    self.faceSelected.emit(entry, fi)
            return
        if self._mode in (MODE_SELPLANE, MODE_SELSURFACE) and e.button()==Qt.RightButton:
            self.sigCancelSketch.emit(); return
        if self._bridge_mode and e.button() == Qt.LeftButton:
            origin, direction = self._ray(e.pos())
            hit = self._pick_face(origin, direction)
            if hit is not None and hit[2] is not None and hit[2] >= 0:
                self.bridgeFaceSelected.emit(hit[1], hit[2])
            elif self._main_window is not None:
                self._main_window._st("Click a face on a solid")
            return
        if self._bridge_mode and e.button() == Qt.RightButton:
            if self._main_window is not None:
                self._main_window._cancel_bridge()
            return
        if self._measure_mode and e.button() == Qt.RightButton:
            self._measure_rclick(e.pos()); return
        if self._feat_mode and e.button() == Qt.LeftButton:
            mw = self._main_window
            # always search all extrusions so the user can click edges on any body
            entry, ci = self._pick_any_feat_edge(e.pos())
            _dbg(f"feat LMB click: picked entry={entry and entry.get('name')} ci={ci} mw_feat_entry={mw and mw._feat_entry and mw._feat_entry.get('name')} view_feat_entry={self._feat_entry and self._feat_entry.get('name')}")
            if ci is not None and mw is not None and entry is not None:
                # update active entry without clearing previously selected chains
                if entry is not mw._feat_entry:
                    pass   # let _update_feat_preview handle preview transitions smoothly
                self._feat_entry = entry
                mw._feat_entry = entry
                ft = mw._feat_type
                mw.lbl_feat_title.setText(
                    f"<b>{'Chamfer' if ft=='chamfer' else 'Fillet'}: {entry['name']}</b>")
                chains = _feat_chains_cached(entry)
                c = chains[ci]
                existing = next((i for i, s in enumerate(mw._feat_chains)
                                 if s["faces"] == c["faces"] and
                                 s.get("_entry") is entry and
                                 float(np.linalg.norm(c["mid"]-s["mid"])) < 1.0), None)
                if existing is not None:
                    mw._feat_chains.pop(existing)
                    mw.lst_feat_edges.takeItem(existing)
                    mw._st(f"Edge deselected ({len(mw._feat_chains)} selected)")
                else:
                    tagged = dict(c); tagged["_entry"] = entry
                    mw._feat_chains.append(tagged)
                    f1, f2 = c["faces"]
                    mw.lst_feat_edges.addItem(f"{entry['name']}  faces {f1}/{f2}  L={c['length']:.1f}mm")
                    mw._st(f"Edge added ({len(mw._feat_chains)} selected) — click OK to apply")
                mw._schedule_feat_preview()
                self.update()
        if self._feat_mode and e.button() == Qt.RightButton:
            # RMB deselects hovered edge, doesn't cancel the mode
            self._hover_chain = None
            self._hover_chain_entry = None
            self.update()
            return
        if self._feat_mode and e.button() == Qt.LeftButton:
            self._last_pos = e.pos()  # allow LMB drag to rotate camera
            return
        if self._mode == MODE_SKETCH:
            self._sketch_press(e); self._history_commit(); return
        if e.button() == Qt.RightButton:
            # RMB in 3D/normal mode always deselects
            self.state["selected"] = None
            mw = self._main_window
            if mw is not None:
                mw._deselect()
            self.update(); return
        if e.button()==Qt.MiddleButton:
            # MMB drag pans the 3-D view (moves the coordinate system on screen)
            self._last_pos = e.pos()
            self.setCursor(QCursor(Qt.ClosedHandCursor)); return
        self._last_pos = e.pos()
        if e.button() == Qt.LeftButton:
            self._press_pos = e.pos()

    def mouseMoveEvent(self, e):
        if self._dimension_drag is not None:
            if e.buttons() & Qt.LeftButton:
                self._update_dimension_drag(e)
                return
            self._dimension_drag = None
        if self._mode != MODE_SKETCH and not e.buttons():
            handle = self._dimension_handle_at(e.pos())
            hovered = handle is not None
            if hovered != self._dimension_hovered:
                self._dimension_hovered = hovered
                self.setToolTip(handle["name"] if hovered else "")
                self.setCursor(QCursor(Qt.SizeAllCursor) if hovered else self._default_cursor())
                self.update()
            if hovered:
                return
        if self._mode == MODE_SKETCH:
            sv = self.state.get("sketch_view_state", {})
            if sv.get("mode") == "draw" and sv.get("draw_tool") == "point":
                self._cursor_mm, self._pt_snap_segs = self.point_snap(QPointF(e.pos()))
                self._snap_vtx = None
            else:
                self._cursor_mm, self._snap_vtx = self.snap_point(QPointF(e.pos()))
                self._pt_snap_segs = []
            if self._pan_start and e.buttons()&Qt.MiddleButton:
                delta=e.pos()-self._pan_start
                self.offset=self._pan_off0+QPointF(delta)
            elif e.buttons()&Qt.LeftButton:
                self._sketch_drag(e)
            else:
                self._update_hover2d(QPointF(e.pos()))
            self._update_trim_hover(sv, QPointF(e.pos()))
            self._track_arc_sweep()
            self.update(); return
        if self._last_pos is None or not (e.buttons() & (Qt.LeftButton | Qt.MiddleButton)):
            if self._feat_mode and not e.buttons():
                entry, ci = self._pick_any_feat_edge(e.pos())
                if ci != self._hover_chain or entry is not self._hover_chain_entry:
                    self._hover_chain = ci; self._hover_chain_entry = entry
                    cur = Qt.PointingHandCursor if ci is not None else Qt.ArrowCursor
                    self.setCursor(QCursor(cur)); self.update()
                return
            if self._measure_mode and not e.buttons():
                self._measure_hover_update(e.pos()); return
            if self._mode == MODE_THREADPICK and not e.buttons():
                self._measure_hover_update(e.pos())
                self._set_hover3d(None if self._meas_hover else self._pick3d(e.pos()))
                return
            self._queue_hover_pick(e.pos())
            return
        self._hover3d = None
        dx=e.x()-self._last_pos.x(); dy=e.y()-self._last_pos.y()
        if e.buttons()&Qt.LeftButton:
            self.rot_z+=dx*0.5; self.rot_x+=dy*0.5
        elif e.buttons()&Qt.MiddleButton:
            # world units per pixel at the orbit centre → origin follows the cursor exactly
            k = 2.0*self.zoom*math.tan(math.radians(22.5))/max(1, self.height())
            self.pan[0]+=dx*k; self.pan[1]-=dy*k
        self._last_pos=e.pos(); self.update()

    def mouseReleaseEvent(self, e):
        self._cancel_hover_pick()
        if e.button() == Qt.LeftButton and self._dimension_drag is not None:
            self._update_dimension_drag(e)
            self._dimension_drag = None
            self._dimension_hovered = self._dimension_handle_at(e.pos()) is not None
            self.setCursor(QCursor(Qt.SizeAllCursor) if self._dimension_hovered else self._default_cursor())
            self.update()
            return
        if e.button() == Qt.LeftButton and self._angle_mode:
            clicked = self._press_pos is not None and \
                (e.pos() - self._press_pos).manhattanLength() < 4
            if clicked and self._main_window is not None:
                self._main_window._angle_draft_click(e.pos())
            self._press_pos = None
            self._last_pos = None
            self.update()
            return
        if e.button()==Qt.MiddleButton:
            self._pan_start=None; self.setCursor(self._default_cursor())
        if e.button()==Qt.LeftButton:
            clicked = self._press_pos is not None and (e.pos()-self._press_pos).manhattanLength() < 4
            if clicked and self._mode == MODE_NORMAL:
                if self._measure_mode: self._measure_click(e.pos())
                else: self._click_select3d(e.pos(), bool(e.modifiers() & Qt.ControlModifier))
            elif clicked and self._mode == MODE_THREADPICK:
                self._thread_click(e.pos())
            self._press_pos = None
            sv = self.state.get("sketch_view_state", {})
            if self._mode == MODE_SKETCH and sv.get("free_pts"):
                self._finish_freehand(sv, self.state.get("active_sketch"), QPointF(e.pos()))
            if sv.get("mode") == DTOOL_SELECT and self._rband_active:
                sk = self.state.get("active_sketch")
                if sk and self._rband_start is not None:
                    self._finish_rband(sv, sk, self._rband_start, QPointF(e.pos()))
            self._rband_start  = None
            self._rband_active = False
            self._rband_cur    = None
            self._drag_seg = None; self._drag_vtx = None; self._drag_last = None
            self._drag_curve = None; self._drag_origin = None; self._drag_dim = None
            self._drag_text = None; self._text_resize = None
        self._last_pos = None
        if self._mode != MODE_SKETCH:
            self._hover3d = None
            if self._measure_mode or self._mode == MODE_THREADPICK: self._measure_hover_update(e.pos())
            else: self._set_hover3d(self._pick3d(e.pos()))
        else:
            self._history_commit()      # end of a drag / dimension move = one undo step

    def leaveEvent(self, e):
        self._cancel_hover_pick()
        self._hover2d = None
        self._set_hover3d(None)
        if self._meas_hover is not None: self._meas_hover = None
        self.update()

    def mouseDoubleClickEvent(self, e):
        if self._mode != MODE_SKETCH or e.button() != Qt.LeftButton: return
        sv = self.state.get("sketch_view_state", {})
        if sv.get("mode") != DTOOL_SELECT: return
        sk = self.state.get("active_sketch")
        hit = self._dim_pick(sk, QPointF(e.pos())) if sk else None
        mw = self._main_window
        if hit is not None and mw is not None:
            self._drag_dim = None
            mw._edit_constraint(hit[0])
            return
        if sk is None:
            return
        group = self._text_group_at(sk, QPointF(e.pos()))
        if group is not None:
            if self._edit_text_group(sk, group):
                self._history_commit()
                self.update()

    # ── dimension annotations: hit test + repositioning ──────────────────────
    def _dim_at(self, px, text_only=False):
        for c, kind, data, poly, line in reversed(self._dim_hits):
            if poly is not None and poly.containsPoint(px, Qt.OddEvenFill):
                return (c, kind, data)
        if text_only: return None
        for c, kind, data, poly, line in reversed(self._dim_hits):
            if line is not None:
                a, b = line
                if seg_dist_px(px.x(), px.y(), a.x(), a.y(), b.x(), b.y()) < 4:
                    return (c, kind, data)
        return None

    def _dim_pick(self, sk, px):
        """Dimension under the cursor: its text always wins; its lines only when no sketch
        geometry is under the cursor (so geometry under a leader stays selectable)."""
        hit = self._dim_at(px, text_only=True)
        if hit is None and self._near_vtx(sk, px, thr=6.0) is None and \
           self._near_seg(sk, px, thr=8.0) is None and \
           self._near_circle(sk, px, thr=8.0) is None and self._near_arc(sk, px, thr=8.0) is None:
            hit = self._dim_at(px)
        return hit

    def _move_dimension(self, hit, px):
        c, kind, data = hit
        if kind == "linear":
            A, B, n = data
            sA, sB = A.x()*n[0]+A.y()*n[1], B.x()*n[0]+B.y()*n[1]
            s = px.x()*n[0]+px.y()*n[1]
            if s >= max(sA, sB):   c.side, off = 1, s - max(sA, sB)
            elif s <= min(sA, sB): c.side, off = -1, min(sA, sB) - s
            else:
                off = 4.0
                if c.side is None: c.side = getattr(c, "_auto_side", 1)
            c.off_mm = max(off, 4.0)/self.scale
            u = (-n[1], n[0])
            tA, tB = A.x()*u[0]+A.y()*u[1], B.x()*u[0]+B.y()*u[1]
            if abs(tB - tA) > 1e-6:
                t = (px.x()*u[0]+px.y()*u[1] - tA)/(tB - tA)
                c.t_frac = min(1.6, max(-0.6, t))
        elif kind == "radial":
            cp = data
            c.angle = math.atan2(-(px.y()-cp.y()), px.x()-cp.x())
        elif kind == "angle":
            I = data
            c.off_mm = max(10.0, math.hypot(px.x()-I.x(), px.y()-I.y()))/self.scale

    def _click_select3d(self, pos, ctrl=False):
        hv = self._pick3d(pos)
        if hv is None or hv[0] not in ("face", "sketch", "object"): return
        mw = self._main_window
        if mw is None: return
        if hv[0] in ("sketch", "object"):
            mw._select_entry(hv[1]); return
        entry, fi = hv[1]
        # Face clicks select only the surface; bodies and features are selected in the explorer.
        mw._select_face(entry, fi, ctrl=ctrl)

    def _pick_feat_edge(self, pos, thr=8.0):
        """Nearest edge chain (outer or inner) of _feat_entry under the cursor. Returns chain index or None."""
        if self._feat_entry is None or self._mvp is None: return None
        chains = _feat_chains_cached(self._feat_entry)
        conv = list(enumerate(chains))
        if not conv: return None
        p = np.array([pos.x(), pos.y()], dtype=float)
        all_pts = np.concatenate([c["P"] for _, c in conv], axis=0)
        S, valid = self._project(all_pts)
        cands = []
        off = 0
        for ci, c in conv:
            n = len(c["P"]); sl = slice(off, off + n); off += n
            hit = self._chain_screen_hit(p, c["P"], S[sl], valid[sl])
            if hit and hit[0] < thr: cands.append((hit[0], hit[1], ci))
        best = self._first_visible(cands)
        return best[2] if best else None

    def _pick_any_feat_edge(self, pos, thr=8.0):
        """Nearest edge chain across visible extrusions and merged Bridge bodies (fast batch).
        Returns (entry, chain_index) or (None, None)."""
        if self._mvp is None: return None, None
        p = np.array([pos.x(), pos.y()], dtype=float)
        cands = []
        for entry in self.state.get("objects", []):
            if not _is_feature_body(entry) or not entry_visible(entry): continue
            if not entry.get("solid", (None, []))[1]: continue
            chains = _feat_chains_cached(entry)
            if not chains: continue
            # batch-project all points of all chains in one MVP multiply
            all_pts = np.concatenate([c["P"] for c in chains], axis=0)
            S, valid = self._project(all_pts)
            off = 0
            for ci, c in enumerate(chains):
                n = len(c["P"]); sl = slice(off, off + n); off += n
                hit = self._chain_screen_hit(p, c["P"], S[sl], valid[sl])
                if hit and hit[0] < thr: cands.append((hit[0], hit[1], entry, ci))
        best = self._first_visible(cands)
        return (best[2], best[3]) if best else (None, None)

    @staticmethod
    def _chain_screen_hit(p, P, S, valid):
        """(screen distance, world point) of the chain point nearest to cursor p, or None."""
        idx = np.flatnonzero(valid[:-1] & valid[1:])
        if not len(idx): return None
        A = S[idx]; AB = S[idx + 1] - A
        L2 = np.einsum('ij,ij->i', AB, AB)
        t = np.clip(np.einsum('ij,ij->i', p - A, AB) / np.where(L2 < 1e-12, 1.0, L2), 0.0, 1.0)
        dist = np.hypot(*(A + t[:, None]*AB - p).T)
        k = int(dist.argmin()); i = int(idx[k])
        P = np.asarray(P, float)
        return float(dist[k]), P[i] + t[k]*(P[i + 1] - P[i])

    def _first_visible(self, cands):
        """Nearest candidate (screen distance, world point, ...) not hidden behind a solid."""
        for cand in sorted(cands, key=lambda c: c[0]):
            if not self._occluded(cand[1]): return cand
        return None

    def _occluded(self, P):
        """True when an opaque visible solid lies between the camera and world point P."""
        P = np.asarray(P, float)
        S, valid = self._project(P[None])
        if not valid[0]: return True
        o, d = self._ray(QPointF(float(S[0, 0]), float(S[0, 1])))
        dd = float(d @ d)
        if dd < 1e-24: return False
        t_point = float((P - o) @ d) / dd
        # Faces meeting at the edge are hit at t_point; allow a small depth tolerance.
        tol = (1e-3 + 1e-5*abs(t_point)*math.sqrt(dd)) / math.sqrt(dd)
        for entry in self.state.get("objects", []):
            if entry["type"] not in ("extrusion", "imported") or entry.get("cut") or \
                    entry.get("preview") or not entry.get("solid", (None, []))[1] or \
                    entry.get("opacity", 1.0) < 0.99 or not entry_visible(entry):
                continue
            v0, e1, e2, _ = self._solid_arrays(entry)
            hit = ray_tris(o, d, v0, e1, e2)
            if hit is not None and hit[0] < t_point - tol: return True
        return False

    def _update_hover2d(self, px):
        """Find the sketch entity (or sketch axis/origin) under the cursor."""
        sk = self.state.get("active_sketch"); hv = None
        sv = self.state.get("sketch_view_state", {})
        if sk and sv.get("mode") == DTOOL_SELECT:
            handle = self._text_handle_at(sv, sk, px)
            if handle is not None:
                idx = handle[1]
                if idx in (0, 2):
                    cur = Qt.SizeFDiagCursor
                elif idx in (1, 3):
                    cur = Qt.SizeBDiagCursor
                elif idx in (4, 6):
                    cur = Qt.SizeVerCursor
                elif idx in (5, 7):
                    cur = Qt.SizeHorCursor
                else:
                    cur = Qt.SizeAllCursor
                self.setCursor(QCursor(cur))
                self._hover2d = None
                return
            self.setCursor(self._default_cursor())
            hit = self._dim_pick(sk, px)
            if hit is not None:
                self._hover2d = ("dim", hit[0]); return
        if sk:
            vi = self._near_vtx(sk, px, thr=8.0)
            if vi is not None:
                hv = ("vtx", vi)
            else:
                si = self._near_seg(sk, px, thr=8.0)
                ci = self._near_circle(sk, px, thr=8.0)
                ai = self._near_arc(sk, px, thr=8.0)
                if si is not None:   hv = ("seg", si)
                elif ci is not None: hv = ("circle", ci)
                elif ai is not None: hv = ("arc", ai)
        if hv is None:
            ox = self.to_px((0, 0))
            if math.hypot(px.x()-ox.x(), px.y()-ox.y()) < 10: hv = ("origin", None)
            elif abs(px.y()-ox.y()) < 6: hv = ("axis", "x")
            elif abs(px.x()-ox.x()) < 6: hv = ("axis", "y")
        self._hover2d = hv

    def _track_arc_sweep(self):
        """Accumulate the signed angle the cursor travels around the arc centre so the
        arc direction (CW/CCW) follows the mouse movement."""
        sv = self.state.get("sketch_view_state", {})
        ac, ast = sv.get("arc_ctr"), sv.get("arc_start")
        if ac is None or ast is None:
            self._arc_last_ang = None; return
        cur = self._cursor_mm
        if math.hypot(cur[0]-ac[0], cur[1]-ac[1]) < 1e-9: return
        ang = math.atan2(cur[1]-ac[1], cur[0]-ac[0])
        if self._arc_last_ang is None:
            self._arc_last_ang = math.atan2(ast[1]-ac[1], ast[0]-ac[0])
        d = (ang - self._arc_last_ang + math.pi) % (2*math.pi) - math.pi
        sw = sv.get("arc_sweep", 0.0) + d
        sv["arc_sweep"] = max(-2*math.pi, min(2*math.pi, sw))
        self._arc_last_ang = ang

    def _finish_rband(self, sv, sk, p0, p1):
        """Select all segments that touch the rubber-band rect (partial overlap ok)."""
        rx0,rx1 = min(p0.x(),p1.x()), max(p0.x(),p1.x())
        ry0,ry1 = min(p0.y(),p1.y()), max(p0.y(),p1.y())
        def in_rect(v):
            pp = self.to_px(v.xy())
            return rx0<=pp.x()<=rx1 and ry0<=pp.y()<=ry1
        def seg_touches(seg):
            # either endpoint inside, or segment crosses rect
            if in_rect(seg.v0) or in_rect(seg.v1): return True
            pp0=self.to_px(seg.v0.xy()); pp1=self.to_px(seg.v1.xy())
            return seg_dist_px((rx0+rx1)/2,(ry0+ry1)/2,
                               pp0.x(),pp0.y(),pp1.x(),pp1.y()) < max(rx1-rx0,ry1-ry0)/2
        sel_segs = [i for i,seg in enumerate(sk.segments) if not seg.reference and seg_touches(seg)]
        expanded = sk.expand_text_selection(sk.segments[i] for i in sel_segs)
        sel_segs = [i for i, seg in enumerate(sk.segments) if seg in expanded]
        reference_vertices = sk.reference_vertices()
        sel_verts= [i for i,v  in enumerate(sk.vertices) if v not in reference_vertices and in_rect(v)]
        sv["sel_curve"] = None
        sv["_sel_extra"] = []
        if sel_segs:
            sv["sel_seg"]  = sel_segs[0]
            sv["_sel_segs"]= sel_segs
            sv["sel_vtx1"] = None
            self._sel_info = f"{len(sel_segs)} segment(s) selected"
        elif sel_verts:
            sv["sel_vtx1"] = sel_verts[0]
            sv["_sel_segs"]= []
            sv["sel_seg"]  = None
            v = sk.vertices[sel_verts[0]]
            self._sel_info = f"Vertex {sel_verts[0]}  ({v.x:.1f}, {v.y:.1f})"
        else:
            self._sel_info = ""
        self.sigSelInfo.emit(self._sel_info)
        self.update()

    def wheelEvent(self, e):
        if self._mode==MODE_SKETCH:
            f=1.15 if e.angleDelta().y()>0 else 1/1.15
            mp=QPointF(e.pos()); mb=self.to_mm(mp)
            self.scale=max(0.5,min(self.scale*f,50.0))
            ma=self.to_mm(mp)
            self.offset+=QPointF((ma[0]-mb[0])*self.scale,-(ma[1]-mb[1])*self.scale)
            self.update(); return
        self.zoom*=(0.9 if e.angleDelta().y()>0 else 1.1)
        self.zoom=max(10,min(self.zoom,5000)); self.update()

    def keyPressEvent(self, e):
        if self._main_window is not None and (
                self._main_window._matches_shortcut("undo", e)
                or self._main_window._matches_shortcut("redo", e)):
            # normally handled by the Edit menu shortcuts; fallback when they don't fire
            redo = self._main_window._matches_shortcut("redo", e)
            if redo: self._main_window._redo()
            else:    self._main_window._undo()
            return
        if self._mode == MODE_SKETCH:
            self._sketch_key(e); self._history_commit(); return
        if self._mode == MODE_THREADPICK and e.key() == Qt.Key_Escape:
            if self._main_window is not None: self._main_window._cancel_thread_pick()
            return
        if self._mode in (MODE_SELPLANE, MODE_SELSURFACE) and e.key() == Qt.Key_Escape:
            self.sigCancelSketch.emit(); return
        if self._bridge_mode and e.key() == Qt.Key_Escape:
            if self._main_window is not None:
                self._main_window._cancel_bridge()
            return
        if self._measure_mode and e.key() == Qt.Key_Escape:
            self.measure_clear(); return
        super().keyPressEvent(e)

    def _history_commit(self):
        """Record the sketch state for undo / redo (no-op when nothing changed)."""
        if self._mode == MODE_SKETCH and self._main_window is not None:
            self._main_window._sketch_commit()

    def _sketch_key(self, e):
        sv = self.state.get("sketch_view_state", {})
        main_window = self._main_window
        if sv.get("mirror_pending") is not None:
            if e.key() == Qt.Key_Escape:
                sv.pop("mirror_pending")
                self.sigSelInfo.emit("Mirror cancelled")
                self.update()
            return
        if main_window is not None and any(
                main_window._matches_shortcut(key, e)
                for key in ("sketch_cut", "sketch_copy", "sketch_paste")):
            sk = self.state.get("active_sketch")
            if sk is not None:
                if main_window._matches_shortcut("sketch_paste", e):
                    self._paste(sv, sk, self._cursor_mm)
                else:
                    self._copy_selection(sv, sk, cut=main_window._matches_shortcut("sketch_cut", e))
            self.update(); return
        if sv.get("paste_preview") is not None and e.key() in (Qt.Key_X, Qt.Key_Y) and not (
                e.modifiers() & (Qt.ControlModifier | Qt.AltModifier | Qt.MetaModifier)):
            axis = "x" if e.key() == Qt.Key_X else "y"
            Sketch.mirror_clipboard(sv["paste_preview"], axis)
            self.sigSelInfo.emit(f"Paste preview mirrored about the {axis.upper()} axis")
            self.update(); return
        if e.key() == Qt.Key_Backspace or (
                main_window is not None and main_window._matches_shortcut("delete_selected", e)):
            self._delete_selected(sv, self.state.get("active_sketch"))
            self.update(); return
        if e.key() == Qt.Key_Escape:
            if not self._has_pending(sv):
                # nothing in progress → Esc cancels the whole sketch
                self.sigCancelSketch.emit(); return
            sv["wip_pts"]=[]; sv["rect_p0"]=None; sv["circle_ctr"]=None
            sv["polygon_ctr"]=None; sv["free_pts"]=None
            sv["arc_ctr"]=None; sv["arc_start"]=None; sv["arc_sweep"]=0.0
            sv.pop("paste_preview", None)
            sv["sel_seg"]=None; sv["sel_vtx1"]=None; sv["sel_vtx2"]=None
            sv["ctool"]=CTOOL_NONE; sv["_sel_segs"]=[]; sv["sel_curve"]=None; sv["_sel_extra"]=[]
            sv["dist_first"]=None; sv["equal_first"]=None; sv.pop("_sym_center",None)
            self._drag_seg=None; self._drag_vtx=None; self._drag_last=None
            self._drag_curve=None; self._arc_last_ang=None; self._drag_dim=None
            self._drag_text=None; self._text_resize=None; self._drag_origin=None
            self._rband_start=None; self._rband_active=False
            mw = self._main_window
            if mw is not None: mw.sketch_panel.set_ctool(CTOOL_NONE)
            self.update()
        return

    # ── sketch mouse dispatch ─────────────────────────────────────────────────
    def _sketch_press(self, e):
        sv  = self.state.get("sketch_view_state", {})
        sk  = self.state.get("active_sketch")
        if not sk: return
        px  = QPointF(e.pos())
        mm, self._snap_vtx = self.snap_point(px)
        self._cursor_mm = mm
        btn = e.button()
        mode  = sv.get("mode", "draw")

        if btn==Qt.MiddleButton:
            self._pan_start=e.pos(); self._pan_off0=QPointF(self.offset)
            self.setCursor(QCursor(Qt.ClosedHandCursor)); return

        if sv.get("mirror_pending") is not None:
            if btn == Qt.LeftButton:
                self._mirror_axis_press(sv, sk, px)
            elif btn == Qt.RightButton:
                sv.pop("mirror_pending")
                self.sigSelInfo.emit("Mirror cancelled")
            self.update(); return

        if sv.get("paste_preview") is not None:
            if btn == Qt.LeftButton:
                self._place_paste_preview(sv, sk, mm)
            elif btn == Qt.RightButton:
                sv.pop("paste_preview", None)
                self.sigSelInfo.emit("Paste cancelled")
            self.update(); return

        if btn in (Qt.LeftButton, Qt.RightButton):
            self._clear_constraint_pick(sv)

        if btn==Qt.RightButton:
            # RMB never closes the sketch. Over geometry (no drawing step / constraint pick in
            # progress) it opens the context menu; otherwise it deselects or aborts the action.
            busy = self._drawing_step_pending(sv) or (mode == "constrain" and (
                       sv.get("sel_seg") is not None or sv.get("sel_vtx1") is not None
                       or sv.get("dist_first") is not None
                       or sv.get("equal_first") is not None))
            ent = None if busy else self._entity_at(sk, px)
            if ent is not None:
                self._sketch_context_menu(sv, sk, ent, px, e.globalPos())
                self.update(); return
            had_sel = (sv.get("sel_seg") is not None or
                       sv.get("sel_vtx1") is not None or
                       sv.get("sel_curve") is not None or
                       sv.get("dist_first") is not None or
                       sv.get("equal_first") is not None or
                       bool(sv.get("_sel_segs")) or bool(sv.get("_sel_extra")))
            sv["sel_seg"] = None; sv["sel_vtx1"] = None; sv["_sel_segs"] = []
            sv["_sel_extra"] = []
            sv["sel_curve"] = None; sv["dist_first"] = None
            sv["equal_first"] = None
            if had_sel:
                self.sigSelInfo.emit("Selection cleared")
            elif self._abort_drawing_step(sv, sk):
                self.sigSelInfo.emit("Drawing step aborted")
            elif sv.get("ctool", CTOOL_NONE) != CTOOL_NONE:
                sv["ctool"] = CTOOL_NONE
                mw = self._main_window
                if mw is not None: mw.sketch_panel.set_ctool(CTOOL_NONE)
                self.sigSelInfo.emit("Constraint tool ended")
            elif SKETCH_CLIPBOARD["data"] is not None:
                self._sketch_context_menu(sv, sk, None, px, e.globalPos())
            self.update(); return

        if mode == DTOOL_SELECT:
            self._select_press(sv, sk, px, mm, bool(e.modifiers() & Qt.ControlModifier)); return

        if mode=="draw":
            used_before = sk.used_vertices()
            tool=sv.get("draw_tool","line")
            constr=bool(sv.get("construction"))
            if tool=="line":   self._draw_line(sv,sk,mm,px,constr)
            elif tool=="rect": self._draw_rect(sv,sk,mm,constr)
            elif tool=="circle": self._draw_circle(sv,sk,mm,constr)
            elif tool=="ellipse": self._draw_ellipse(sv,sk,mm,constr)
            elif tool=="polygon": self._draw_polygon(sv,sk,mm,constr)
            elif tool=="arc":    self._draw_arc(sv,sk,mm,constr)
            elif tool=="freehand": sv["free_pts"]=[tuple(mm)]
            elif tool=="point":  self._draw_point(sk,px)
            elif tool=="text":   self._draw_text(sk,mm)
            elif tool=="trim":   self._trim_at(sk,px)
            if tool not in ("trim", "text"):
                self._attach_reference_constraints(sk, sk.used_vertices() - used_before)
        elif mode=="constrain":
            self._constrain_press(sv,sk,px,mm,e.modifiers()&Qt.ControlModifier)
        self.update()

    def _clear_constraint_pick(self, sv):
        """Drop the constraint highlighted from the list when the drawing is clicked."""
        if sv.get("hl_constraint") is None: return
        sv["hl_constraint"] = None
        mw = self._main_window
        if mw is not None:
            mw.sketch_panel.lst_con.clearSelection(); mw.sketch_panel.lst_con.setCurrentRow(-1)

    def _toggle_selection(self, sv, sk, px):
        """Ctrl+click: add the element under the cursor to the selection or remove it."""
        vi = self._near_vtx(sk, px, thr=6.0)
        si = self._near_seg(sk, px, thr=12.0)
        ci = self._near_circle(sk, px, thr=10.0)
        ai = self._near_arc(sk, px, thr=10.0)
        ei = self._near_ellipse(sk, px, thr=10.0)
        hit = ("vtx", vi) if vi is not None else ("seg", si) if si is not None else \
              ("circle", ci) if ci is not None else ("arc", ai) if ai is not None else \
              ("vtx", sk.vertices.index(sk.ellipses[ei].major_start)) if ei is not None else None
        if hit is None: return
        segs = list(sv.get("_sel_segs") or [])
        if sv.get("sel_seg") is not None and sv["sel_seg"] not in segs: segs.append(sv["sel_seg"])
        extra = list(sv.get("_sel_extra") or [])
        if sv.get("sel_vtx1") is not None: extra.append(("vtx", sv["sel_vtx1"]))
        if sv.get("sel_curve") is not None: extra.append(tuple(sv["sel_curve"]))
        group, key = (segs, hit[1]) if hit[0] == "seg" else (extra, hit)
        if key in group: group.remove(key)
        else: group.append(key)
        sv["_sel_segs"] = segs; sv["sel_seg"] = segs[0] if segs else None
        sv["_sel_extra"] = extra; sv["sel_vtx1"] = None; sv["sel_curve"] = None
        self._drag_origin = None
        n = len(segs) + len(extra)
        self._sel_info = f"{n} element(s) selected" if n else ""
        self.sigSelInfo.emit(self._sel_info)
        self.update()

    def _select_press(self, sv, sk, px, mm, ctrl=False):
        """Begin click or rubber-band. Actual selection on release."""
        self._rband_start  = px
        self._rband_active = False
        self._drag_last    = self.to_mm(px)  # always raw mm baseline
        self._drag_seg     = None
        self._drag_vtx     = None
        self._drag_curve   = None
        self._drag_origin  = None
        self._drag_dim     = None
        self._drag_text    = None
        self._text_resize  = None
        if ctrl:
            self._rband_start = None
            self._toggle_selection(sv, sk, px)
            return
        sv["sel_curve"]    = None; sv["_sel_extra"] = []
        handle = self._text_handle_at(sv, sk, px)
        if handle is not None:
            group, corner = handle
            self._begin_text_drag(sv, sk, group, px, corner)
            return
        # dimension annotations can be grabbed and moved
        hit = self._dim_pick(sk, px)
        if hit is not None:
            self._drag_dim = hit; self._rband_start = None
            sv["sel_seg"] = None; sv["sel_vtx1"] = None; sv["_sel_segs"] = []
            self._sel_info = f"{describe_constraint(sk, hit[0])}  — drag to move, double-click to edit"
            self.sigSelInfo.emit(self._sel_info); self.update(); return
        # single-item selection
        vi = self._near_vtx(sk, px, thr=6.0)
        si = self._near_seg(sk, px, thr=12.0)
        ci = self._near_circle(sk, px, thr=10.0)
        ai = self._near_arc(sk, px, thr=10.0)
        ei = self._near_ellipse(sk, px, thr=10.0)
        element = sk.vertices[vi] if vi is not None else sk.segments[si] if si is not None else None
        group = sk.text_group_for(element) if element is not None else None
        if group is not None:
            self._begin_text_drag(sv, sk, group, px)
            return
        if vi is not None:
            sv["sel_vtx1"] = vi; sv["sel_seg"] = None; sv["_sel_segs"] = []
            self._drag_vtx = vi
            v = sk.vertices[vi]
            self._sel_info = f"Vertex {vi}  ({v.x:.1f}, {v.y:.1f})"
        elif si is not None:
            sv["sel_seg"] = si; sv["sel_vtx1"] = None; sv["_sel_segs"] = [si]
            self._drag_seg = si
            seg = sk.segments[si]
            self._sel_info = (f"Seg {si}  "
                              f"({seg.v0.x:.1f},{seg.v0.y:.1f})"
                              f"→({seg.v1.x:.1f},{seg.v1.y:.1f})"
                              f"  L={seg.length():.1f}mm"
                              + ("  [support]" if seg.construction else ""))
        elif ci is not None or ai is not None:
            sv["sel_seg"] = None; sv["sel_vtx1"] = None; sv["_sel_segs"] = []
            sel = ("circle", ci) if ci is not None else ("arc", ai)
            sv["sel_curve"] = sel; self._drag_curve = sel
            if ci is not None:
                c = sk.circles[ci]
                self._sel_info = (f"Circle {ci}  centre ({c.center.x:.1f},{c.center.y:.1f})"
                                  f"  R={c.radius:.1f}mm")
            else:
                a = sk.arcs[ai]; _, sw = a.angles()
                self._sel_info = (f"Arc {ai}  centre ({a.center.x:.1f},{a.center.y:.1f})"
                                  f"  R={a.radius():.1f}mm  {math.degrees(sw):.1f}°")
        elif ei is not None:
            sv["sel_seg"] = None; sv["_sel_segs"] = []
            sv["sel_vtx1"] = sk.vertices.index(sk.ellipses[ei].major_start)
            self._sel_info = f"Ellipse {ei} selected"
        else:
            sv["sel_seg"] = None; sv["sel_vtx1"] = None; sv["_sel_segs"] = []
            self._sel_info = ""
        moving = self._drag_vertex_set(sk)
        self._drag_origin = {v: (v.x, v.y) for v in moving}
        self._drag_start_mm = self.to_mm(px)
        # the vertex closest to the grab position is the one that snaps while dragging
        self._drag_anchor = min(moving, key=lambda v: math.hypot(v.x-self._drag_start_mm[0],
                                                               v.y-self._drag_start_mm[1]),
                                default=None)
        self.sigSelInfo.emit(self._sel_info)
        self.update()

    def _selected_text_groups(self, sv, sk):
        segs = self._selection_geometry(sv, sk)[0]
        return [group for group in sk.text_groups if set(group.segments) <= segs]

    def _text_group_at(self, sk, px):
        vi = self._near_vtx(sk, px, thr=8.0)
        if vi is not None:
            group = sk.text_group_for(sk.vertices[vi])
            if group is not None:
                return group
        si = self._near_seg(sk, px, thr=10.0)
        if si is not None:
            return sk.text_group_for(sk.segments[si])
        return None

    def _edit_text_group(self, sk, group):
        style = self.text_style_dialog({
            "label": group.label,
            "font_family": group.font_family,
            "font_size": group.font_size,
            "bold": group.bold,
            "italic": group.italic,
            "underline": group.underline,
            "align": group.align,
        }, title="Edit text")
        if style is None:
            return False
        old_segments = list(group.segments)
        old_vertices = [v for s in old_segments for v in (s.v0, s.v1)]
        new_contours = text_contours(style["label"],
                                     font_family=style["font_family"],
                                     font_size=style["font_size"],
                                     bold=style["bold"],
                                     italic=style["italic"],
                                     underline=style["underline"],
                                     align=style["align"])
        if not new_contours:
            self.sigSelInfo.emit("Text edit cancelled: empty outline")
            return False
        x0, y0, x1, y1 = group.bounds()
        cx, cy = (x0+x1)/2.0, (y0+y1)/2.0
        new_segments = []
        for contour in new_contours:
            vertices = []
            for x, y in contour:
                px, py = cx+x, cy+y
                vertex = next((v for v in vertices
                               if math.hypot(v.x-px, v.y-py) <= MERGE_TOL), None)
                if vertex is None:
                    vertex = Vertex(px, py, locked=True)
                    sk.vertices.append(vertex)
                vertices.append(vertex)
            made = [Segment(a, b) for a, b in zip(vertices, vertices[1:]) if a is not b]
            sk.segments.extend(made)
            new_segments.extend(made)
        if not new_segments:
            self.sigSelInfo.emit("Text edit failed")
            return False
        keep_constraints = []
        for c in sk.constraints:
            refs = constraint_refs(c)
            if refs.intersection(old_segments) or refs.intersection(old_vertices):
                continue
            keep_constraints.append(c)
        sk.constraints = keep_constraints
        sk.segments = [s for s in sk.segments if s not in old_segments]
        sk.vertices = [v for v in sk.vertices if v not in old_vertices]
        group.segments = new_segments
        group.label = style["label"]
        group.font_family = style["font_family"]
        group.font_size = style["font_size"]
        group.bold = style["bold"]
        group.italic = style["italic"]
        group.underline = style["underline"]
        group.align = style["align"]
        if len(group.box_vertices) >= 9:
            glyph = {v for s in new_segments for v in (s.v0, s.v1)}
            nx0 = min(v.x for v in glyph); ny0 = min(v.y for v in glyph)
            nx1 = max(v.x for v in glyph); ny1 = max(v.y for v in glyph)
            nxm, nym = (nx0+nx1)/2.0, (ny0+ny1)/2.0
            new_box = [(nx0, ny0), (nx1, ny0), (nx1, ny1), (nx0, ny1),
                       (nxm, ny0), (nx1, nym), (nxm, ny1), (nx0, nym), (nxm, nym)]
            for v, (x, y) in zip(group.box_vertices[:9], new_box):
                v.x, v.y = x, y
        sv = self.state.get("sketch_view_state", {})
        indices = [i for i, seg in enumerate(sk.segments) if seg in group.segments]
        sv["_sel_segs"] = indices
        sv["sel_seg"] = indices[0] if indices else None
        sv["sel_vtx1"] = None
        sv["sel_curve"] = None
        sk._an_key = None
        ok = sk.solve()
        if not ok:
            self.sigSelInfo.emit("Text updated; some constraints became invalid and were removed")
        else:
            self.sigSelInfo.emit(f'Text "{group.label}" updated')
        return True

    def _text_handle_at(self, sv, sk, px):
        for group in self._selected_text_groups(sv, sk):
            for i, point in enumerate(group.constraint_points()):
                pos = self.to_px(point)
                if math.hypot(pos.x()-px.x(), pos.y()-px.y()) <= 8:
                    return group, i
        return None

    def _begin_text_drag(self, sv, sk, group, px, corner=None):
        indices = [i for i, seg in enumerate(sk.segments) if seg in group.segments]
        sv["sel_seg"] = indices[0]; sv["_sel_segs"] = indices
        sv["sel_vtx1"] = sv["sel_vtx2"] = sv["sel_curve"] = None
        self._rband_start = None
        self._drag_text = group
        self._drag_origin = {v: v.xy() for v in group.vertices()}
        self._drag_start_mm = self.to_mm(px)
        self._drag_anchor = min(group.vertices(),
                                key=lambda v: math.dist(v.xy(), self._drag_start_mm))
        if corner is not None and corner < 4:
            corners = group.corners()
            self._text_resize = (corners[(corner+2) % 4], corners[corner])
        self._sel_info = f'Text "{group.label}" — drag to move; drag a corner to resize proportionally; double-click to edit'
        self.sigSelInfo.emit(self._sel_info)
        self.update()

    def _drag_vertex_set(self, sk):
        if self._drag_vtx is not None and self._drag_vtx < len(sk.vertices):
            return {sk.vertices[self._drag_vtx]}
        if self._drag_seg is not None and self._drag_seg < len(sk.segments):
            s = sk.segments[self._drag_seg]; return {s.v0, s.v1}
        if self._drag_curve is not None:
            kind, i = self._drag_curve
            if kind == "circle" and i < len(sk.circles): return {sk.circles[i].center}
            if kind == "arc" and i < len(sk.arcs):
                a = sk.arcs[i]; return {a.center, a.v_start, a.v_end}
        return set()

    def _freehand_extend(self, sv, px):
        pts = sv["free_pts"]
        raw = self.to_mm(px)
        last = self.to_px(pts[-1])
        if math.hypot(px.x()-last.x(), px.y()-last.y()) >= 3.0:
            pts.append(tuple(raw))

    @staticmethod
    def _simplify_polyline(pts, tol):
        """Douglas-Peucker simplification (iterative); keeps the first and last point."""
        keep = {0, len(pts)-1}
        stack = [(0, len(pts)-1)]
        while stack:
            i0, i1 = stack.pop()
            ax, ay = pts[i0]; bx, by = pts[i1]
            far, far_d = None, tol
            for i in range(i0+1, i1):
                d = seg_dist_px(pts[i][0], pts[i][1], ax, ay, bx, by)
                if d > far_d: far, far_d = i, d
            if far is not None:
                keep.add(far); stack += [(i0, far), (far, i1)]
        return [pts[i] for i in sorted(keep)]

    def _finish_freehand(self, sv, sk, px):
        """Turn the dragged stroke into a chain of lines; ending on its own start closes it."""
        pts = sv.get("free_pts"); sv["free_pts"] = None
        if not pts or sk is None: return
        end_mm, _ = self.snap_point(px)
        pts = self._simplify_polyline(pts + [tuple(end_mm)], 1.5/max(self.scale, 1e-9))
        verts = []
        for x, y in pts:
            v = sk.get_or_merge(x, y, MERGE_TOL)
            if not verts or verts[-1] is not v: verts.append(v)
        constr = bool(sv.get("construction"))
        segs = [Segment(a, b, constr) for a, b in zip(verts, verts[1:])]
        if not segs:
            self._drop_if_orphan(sk, *verts); return
        sk.segments.extend(segs)
        self._auto_merge_endpoints(sk)
        self._attach_reference_constraints(sk, set(verts) & sk.used_vertices())
        self.sigSelInfo.emit(f"Freehand: {len(segs)} line segments")

    def _sketch_drag(self, e):
        sv = self.state.get("sketch_view_state", {})
        if sv.get("mode") == "draw" and sv.get("free_pts"):
            self._freehand_extend(sv, QPointF(e.pos())); return
        if sv.get("mode") != DTOOL_SELECT: return
        sk = self.state.get("active_sketch")
        if not sk: return
        px = QPointF(e.pos())
        if self._drag_dim is not None:
            self._move_dimension(self._drag_dim, px); self.update(); return
        dragging = bool(self._drag_origin)
        if self._rband_start is not None and not dragging:
            dist = (px.x()-self._rband_start.x())**2+(px.y()-self._rband_start.y())**2
            if dist > 25 and not self._rband_active:
                self._rband_active = True
        if self._rband_active:
            self._rband_cur = px
            self.update(); return
        if not dragging or self._drag_start_mm is None: return
        raw_mm = self.to_mm(px)
        dx = raw_mm[0] - self._drag_start_mm[0]
        dy = raw_mm[1] - self._drag_start_mm[1]
        if self._drag_text is not None and self._text_resize is not None:
            center, corner = self._text_resize
            ux, uy = corner[0]-center[0], corner[1]-center[1]
            factor = max(0.001, 1+(dx*ux+dy*uy)/max(ux*ux+uy*uy, 1e-18))
            if not sk.transform_text(self._drag_text, self._drag_origin, scale=factor, center=center):
                self.sigSelInfo.emit("Cannot resize text: blocked by constraints")
            self.update(); return
        anchor = self._drag_anchor
        if self.sel_snap and anchor in self._drag_origin:
            # the grabbed point lands on the nearest grid point (or a nearby existing point)
            ax0, ay0 = self._drag_origin[anchor]
            target, _ = self.snap_point(self.to_px((ax0+dx, ay0+dy)),
                                        exclude=set(self._drag_origin))
            dx, dy = target[0]-ax0, target[1]-ay0
        if self._drag_text is not None:
            if not sk.transform_text(self._drag_text, self._drag_origin, offset=(dx, dy)):
                self.sigSelInfo.emit("Cannot move text: blocked by constraints")
            self.update(); return
        # targets relative to the drag start; the solver keeps every constraint satisfied,
        # so constrained geometry only moves within its remaining degrees of freedom
        moves = {v: (x0+dx, y0+dy) for v, (x0, y0) in self._drag_origin.items() if not v.locked}
        if moves and not sk.drag(moves):
            self.sigSelInfo.emit("Cannot move: blocked by constraints")
        self.update()

    def _selection_geometry(self, sv, sk):
        """(segments, circles, arcs, points) of the current selection; a selected vertex
        stands for itself (free point) plus every element attached to it."""
        si   = sv.get("sel_seg")
        vi   = sv.get("sel_vtx1")
        sc   = sv.get("sel_curve")
        multi= sv.get("_sel_segs", [])
        segs = {sk.segments[i] for i in multi if i < len(sk.segments)}
        circles, arcs, points = set(), set(), set()
        if sv.get("mode") == DTOOL_SELECT:
            for kind, i in sv.get("_sel_extra") or []:
                if kind == "circle" and i < len(sk.circles): circles.add(sk.circles[i])
                elif kind == "arc" and i < len(sk.arcs): arcs.add(sk.arcs[i])
                elif kind == "vtx" and i < len(sk.vertices) and (
                        sk.vertices[i] in sk.points_free or any(
                            sk.vertices[i] in ellipse.vertices() for ellipse in sk.ellipses)):
                    points.add(sk.vertices[i])
        if si is not None and si < len(sk.segments):
            segs.add(sk.segments[si])
        elif sc is not None:
            kind, i = sc
            if kind == "circle" and i < len(sk.circles): circles.add(sk.circles[i])
            if kind == "arc" and i < len(sk.arcs):       arcs.add(sk.arcs[i])
        elif vi is not None and vi < len(sk.vertices) and not segs:
            v = sk.vertices[vi]
            segs    = {s for s in sk.segments if s.v0 is v or s.v1 is v}
            arcs    = {a for a in sk.arcs if v in (a.center, a.v_start, a.v_end)}
            circles = {c for c in sk.circles if c.center is v}
            points  = {v} if v in sk.points_free or any(
                v in ellipse.vertices() for ellipse in sk.ellipses) else set()
        return sk.expand_text_selection(segs), circles, arcs, points

    def _start_mirror(self, direction):
        sk = self.state.get("active_sketch")
        sv = self.state.get("sketch_view_state", {})
        if sk is None or sv.get("mode") != DTOOL_SELECT:
            self.sigSelInfo.emit("Select geometry before using Mirror")
            return
        segs, circles, arcs, points = self._selection_geometry(sv, sk)
        vertices = points | self._extra_vertices(sv, sk)
        ellipses = {ellipse for ellipse in sk.ellipses
                    if set(ellipse.vertices()) & vertices}
        points = {point for point in vertices if point in sk.points_free}
        if any(sk.text_group_for(element) is not None for element in segs | vertices):
            self.sigSelInfo.emit("Text cannot be mirrored")
            return
        if not (segs or circles or arcs or ellipses or points):
            self.sigSelInfo.emit("Select geometry to mirror")
            return
        sv["mirror_pending"] = (direction, segs, circles, arcs, ellipses, points)
        self.sigSelInfo.emit(f"Choose a {direction} sketch line or the {direction} sketch axis; "
                             "Esc / right-click cancels")
        self.update()

    def _mirror_axis_press(self, sv, sk, px):
        direction, segs, circles, arcs, ellipses, points = sv["mirror_pending"]
        index = self._near_seg(sk, px, thr=8.0)
        axis = sk.segments[index] if index is not None else None
        if axis is not None:
            expected = "H" if direction == "horizontal" else "V"
            if axis.axis() != expected:
                self.sigSelInfo.emit(f"Choose a {direction} line as the mirror axis")
                return
        else:
            origin = self.to_px((0, 0))
            distance = abs(px.y()-origin.y()) if direction == "horizontal" else \
                       abs(px.x()-origin.x())
            if distance > 8:
                self.sigSelInfo.emit(f"Choose a {direction} sketch line or sketch axis")
                return
            axis = direction
        try:
            count = sk.mirror_geometry(segs, circles, arcs, ellipses, points, axis)
        except ValueError as error:
            self.sigSelInfo.emit(str(error))
            return
        sv.pop("mirror_pending")
        self._clear_selection(sv)
        self.sigSelInfo.emit(f"Mirrored {count} element(s); copies follow the original geometry")

    def _extra_vertices(self, sv, sk):
        """Vertices added to the selection with Ctrl+click."""
        if sv.get("mode") != DTOOL_SELECT: return set()
        return {sk.vertices[i] for kind, i in sv.get("_sel_extra") or []
                if kind == "vtx" and i < len(sk.vertices)}

    def _clear_selection(self, sv):
        sv["sel_seg"] = None; sv["sel_vtx1"] = None; sv["_sel_segs"] = []
        sv["sel_curve"] = None; sv["_sel_extra"] = []
        self._drag_seg = None; self._drag_vtx = None; self._drag_curve = None
        self._drag_text = None; self._text_resize = None; self._drag_origin = None

    def _selection_constraints(self, sv, sk):
        """Constraints that act on the selected geometry (Fix also via the end points)."""
        segs, circles, arcs, points = self._selection_geometry(sv, sk)
        vi = sv.get("sel_vtx1")
        if vi is not None and vi < len(sk.vertices) and not (segs or circles or arcs):
            elements, ends = {sk.vertices[vi]}, set()
        else:
            elements = segs | circles | arcs | points | self._extra_vertices(sv, sk)
            ends = {v for s in segs for v in (s.v0, s.v1)}
            ends |= {v for a in arcs for v in (a.center, a.v_start, a.v_end)}
            ends |= {c.center for c in circles}
        if not (elements or ends): return []
        return [c for c in sk.constraints
                if constraint_refs(c) & elements or (isinstance(c, CFixed) and c.vertex in ends)]

    def _fix_selection(self, sv, sk):
        """Fix every vertex of the selection (unfix them all when already fixed).
        Returns False when nothing is selected."""
        if sk is None: return False
        segs, circles, arcs, points = self._selection_geometry(sv, sk)
        vi = sv.get("sel_vtx1")
        if vi is not None and vi < len(sk.vertices) and not (segs or circles or arcs):
            verts = {sk.vertices[vi]}      # a selected point fixes only itself
        else:
            verts = set(points) | self._extra_vertices(sv, sk)
            for s in segs: verts |= {s.v0, s.v1}
            for a in arcs: verts |= {a.center, a.v_start, a.v_end}
            for c in circles: verts.add(c.center)
        if not verts: return False
        reference = sk.reference_vertices()
        verts = [v for v in sk.vertices if v in verts and v not in reference and not v.locked]
        fixed = {c.vertex: c for c in sk.constraints if isinstance(c, CFixed)}
        if verts and all(v in fixed for v in verts):
            for v in verts: sk.constraints.remove(fixed[v])
            self.sigSelInfo.emit(f"Fix removed from {len(verts)} point(s)")
            return True
        n_ok = sum(1 for v in verts if v not in fixed
                   and self._add_constraint(sk, CFixed(v), "", silent=True))
        self.sigSelInfo.emit(f"{n_ok} point(s) fixed")
        return True

    def _delete_selected(self, sv, sk):
        """Delete selected segment(s)/circle/arc, or everything attached to a selected vertex."""
        if sk is None: return
        segs, circles, arcs, points = self._selection_geometry(sv, sk)
        vi = sv.get("sel_vtx1")
        if vi is not None and vi < len(sk.vertices) and not (segs or circles or arcs):
            points = {sk.vertices[vi]}
        if not (segs or circles or arcs or points): return
        if any(e.reference for e in segs | circles | arcs) or any(v.locked for v in points):
            self.sigSelInfo.emit("Reference geometry cannot be deleted; projected edges and vertices are preserved")
        sk.remove_geometry(segs, circles, arcs, points)
        self._clear_selection(sv)

    # ── context menu / clipboard / support switch ─────────────────────────────
    def _entity_at(self, sk, px):
        """Sketch element under the cursor for the context menu: free point, line, circle,
        arc, or (failing those) a vertex. → (kind, index) or None."""
        vi = self._near_vtx(sk, px, thr=6.0)
        if vi is not None and sk.vertices[vi] in sk.points_free: return ("vtx", vi)
        ent = self._curve_entity_at(sk, px, thr=8.0)
        if ent is not None: return ent
        return ("vtx", vi) if vi is not None else None

    def _curve_entity_at(self, sk, px, thr=10.0):
        si = self._near_seg(sk, px, thr=thr)
        if si is not None: return ("seg", si)
        ci = self._near_circle(sk, px, thr=thr)
        if ci is not None: return ("circle", ci)
        ai = self._near_arc(sk, px, thr=thr)
        return ("arc", ai) if ai is not None else None

    def _select_entity(self, sv, ent):
        """Select ent (an element already in a multi-selection keeps that selection)."""
        kind, i = ent
        if kind == "seg" and (i in (sv.get("_sel_segs") or []) or sv.get("sel_seg") == i):
            return
        if (kind, i) in (sv.get("_sel_extra") or []):
            return
        self._clear_selection(sv)
        if kind == "seg":   sv["sel_seg"] = i; sv["_sel_segs"] = [i]
        elif kind == "vtx": sv["sel_vtx1"] = i
        else:               sv["sel_curve"] = (kind, i)

    @staticmethod
    def _exec_menu(menu, global_pos):
        return menu.exec_(global_pos)

    def _sketch_context_menu(self, sv, sk, ent, px, global_pos):
        """RMB menu on sketch geometry: switch support/normal, Cut, Copy, Paste, Delete, Cancel.
        ent None = empty space (only Paste / Cancel)."""
        if ent is not None: self._select_entity(sv, ent)
        segs, circles, arcs, points = self._selection_geometry(sv, sk)
        elems = [e for e in list(segs) + list(circles) + list(arcs) if not e.reference]
        editable = bool(elems or any(not v.locked for v in points))
        to_support = any(not e.construction for e in elems)
        self.update()
        menu = QMenu(self); acts = {}
        if ent is not None:
            acts[menu.addAction("┄ Switch to support geometry" if to_support or not elems
                                else "━ Switch to normal geometry")] = "switch"
            list(acts)[-1].setEnabled(bool(elems))
            menu.addSeparator()
            acts[menu.addAction("✂ Cut\tCtrl+X")] = "cut"
            list(acts)[-1].setEnabled(editable)
            acts[menu.addAction("⧉ Copy\tCtrl+C")] = "copy"
            list(acts)[-1].setEnabled(editable)
        a_paste = menu.addAction("📋 Paste\tCtrl+V"); acts[a_paste] = "paste"
        a_paste.setEnabled(SKETCH_CLIPBOARD["data"] is not None)
        if ent is not None:
            acts[menu.addAction("🗑 Delete\tDel")] = "delete"
            list(acts)[-1].setEnabled(editable)
        menu.addSeparator()
        acts[menu.addAction("✖ Cancel")] = "cancel"
        what = acts.get(self._exec_menu(menu, global_pos), "cancel")
        if what == "switch":
            n = sk.set_construction(elems, to_support)
            self.sigSelInfo.emit(f"{n} element(s) switched to "
                                 + ("support geometry" if to_support else "normal geometry"))
        elif what in ("cut", "copy"):
            self._copy_selection(sv, sk, cut=what == "cut")
        elif what == "paste":
            self._paste(sv, sk, self.snap_point(px)[0])
        elif what == "delete":
            self._delete_selected(sv, sk)
        if sv.get("mode") != DTOOL_SELECT and what != "paste":
            self._clear_selection(sv)      # RMB selection outside Select mode is temporary
        self.update()

    def _copy_selection(self, sv, sk, cut=False):
        segs, circles, arcs, points = self._selection_geometry(sv, sk)
        data = sk.extract(segs, circles, arcs, points)
        if data is None:
            self.sigSelInfo.emit("Nothing to copy — select lines, circles, arcs or points "
                                 "(reference geometry cannot be copied)")
            return False
        SKETCH_CLIPBOARD["data"] = data
        n = sum(len(data[k]) for k in ("segments", "circles", "arcs", "points"))
        if cut:
            sk.remove_geometry([s for s in segs if not s.reference],
                               [c for c in circles if not c.reference],
                               [a for a in arcs if not a.reference], points)
            self._clear_selection(sv)
        self.sigSelInfo.emit(f"{n} element(s) {'cut' if cut else 'copied'} — Ctrl+V / RMB → Paste "
                             "inserts them at the cursor")
        return True

    def _paste(self, sv, sk, at_mm):
        """Start a cursor-following preview of the clipboard."""
        data = SKETCH_CLIPBOARD["data"]
        if data is None:
            self.sigSelInfo.emit("Clipboard is empty"); return False
        self._cursor_mm = tuple(at_mm)
        preview = Sketch(sk.plane, frame=sk.frame)
        sv["paste_preview"] = preview.insert(data)
        self.sigSelInfo.emit("Paste preview — click to place; Esc or right-click to cancel")
        self.update()
        return True

    def _place_paste_preview(self, sv, sk, at_mm):
        data = sv.pop("paste_preview", None)
        if data is None:
            return False
        verts = Sketch.clip_vertices(data)
        x0 = min(v.x for v in verts); y0 = min(v.y for v in verts)
        d = sk.insert(data, at_mm[0]-x0, at_mm[1]-y0)
        self._auto_merge_endpoints(sk)
        self._clear_selection(sv)
        if sv.get("mode") == DTOOL_SELECT:
            idx = [i for i, s in enumerate(sk.segments) if any(s is t for t in d["segments"])]
            sv["_sel_segs"] = idx; sv["sel_seg"] = idx[0] if idx else None
        n = sum(len(d[k]) for k in ("segments", "circles", "arcs", "points"))
        self.sigSelInfo.emit(f"{n} element(s) pasted at ({at_mm[0]:.1f}, {at_mm[1]:.1f})")
        return True

    # ── scissor ────────────────────────────────────────────────────────────────
    def _trim_target(self, sk, px):
        ent = self._curve_entity_at(sk, px)
        if ent is None: return None
        kind, i = ent
        return {"seg": sk.segments, "circle": sk.circles, "arc": sk.arcs}[kind][i]

    def _update_trim_hover(self, sv, px):
        self._trim_hover = None
        sk = self.state.get("active_sketch")
        if sk is None or sv.get("mode") != "draw" or sv.get("draw_tool") != "trim": return
        t = self._trim_target(sk, px)
        if t is not None and not t.reference and sk.text_group_for(t) is None:
            self._trim_hover = sk.trim_preview(t, self.to_mm(px))

    def _trim_at(self, sk, px):
        """Scissor click: cut away the part of the clicked element between its neighbouring
        crossings / points (the whole element if it has none)."""
        t = self._trim_target(sk, px)
        if t is None:
            self.sigSelInfo.emit("Scissor: click on the part of a line, circle or arc to remove")
            return
        ok, msg = sk.trim(t, self.to_mm(px))
        self._trim_hover = None
        self.sigSelInfo.emit(("✂ Scissor: " if ok else "⚠ Scissor: ") + msg)

    def _drawing_step_pending(self, sv):
        return bool(sv.get("wip_pts") or sv.get("rect_p0") is not None
                    or sv.get("circle_ctr") is not None or sv.get("polygon_ctr") is not None
                    or sv.get("ellipse_ctr") is not None
                    or sv.get("arc_ctr") is not None or bool(sv.get("free_pts")))

    def _draw_line(self, sv, sk, mm, px, constr=False):
        v = sk.get_or_merge(mm[0], mm[1], MERGE_TOL)
        wip = sv.setdefault("wip_pts", [])
        # close chain when clicking (snapping onto) the chain's own start (need >= 3 points);
        # the chain's other segments were already added click by click
        if wip and len(wip) >= 3 and v is wip[0]:
            seg = Segment(wip[-1], v, constr)
            sk.segments.append(seg)
            sv["wip_pts"] = []
            self._auto_merge_endpoints(sk)
            self._auto_constraints(sk, seg)
            return
        if wip and wip[-1] is not v:
            seg = Segment(wip[-1], v, constr)
            sk.segments.append(seg)
            self._auto_merge_endpoints(sk)
            self._auto_constraints(sk, seg)
        wip.append(v)

    def _auto_merge_endpoints(self, sk):
        """After adding geometry, merge distinct vertices that sit on exactly the same spot
        (e.g. a new line starting on an existing point). Points joined by a Point→Point
        constraint stay separate so that constraint can still be removed.
        Reference vertices stay separate so their attachments remain removable constraints."""
        linked = {frozenset((c.vertex_move, c.vertex_target))
                  for c in sk.constraints if isinstance(c, CCoincident)}
        text_vertices = sk.text_vertices()
        reference_vertices = sk.reference_vertices()
        merged = True
        while merged:
            merged = False
            verts = list(sk.vertices)
            for i in range(len(verts)):
                for j in range(i+1, len(verts)):
                    va, vb = verts[i], verts[j]
                    if va in text_vertices or vb in text_vertices: continue
                    if va in reference_vertices or vb in reference_vertices: continue
                    if va.locked and vb.locked: continue
                    if frozenset((va, vb)) in linked: continue
                    if math.hypot(va.x-vb.x, va.y-vb.y) <= MERGE_TOL:
                        if vb.locked: va, vb = vb, va
                        sk.replace_vertex(vb, va)   # redirects geometry + constraints
                        merged = True; break
                if merged: break
        degenerate = [s for s in sk.segments if s.v0 is s.v1]
        if degenerate:
            sk.remove_geometry(segs=degenerate)

    def _attach_reference_constraints(self, sk, vertices):
        reference_vertices = sk.reference_vertices()
        references = [vertex for vertex in sk.vertices if vertex in reference_vertices
                      and self._level_reference_available(vertex)]
        curves = [element for element in sk.segments + sk.circles + sk.arcs
                  if element.reference and self._level_reference_available(element)]
        for vertex in sk.vertices:
            if vertex not in vertices or vertex.locked:
                continue
            target = next((point for point in references
                           if math.dist(vertex.xy(), point.xy()) <= MERGE_TOL), None)
            if target is not None:
                constraint = CCoincident(vertex, target)
            else:
                target = next((element for element in curves
                               if dist_to_curve(curve_of(element), vertex.xy()) <= TRIM_TOL), None)
                if target is None:
                    continue
                constraint = CPointOnLine(vertex, target) if isinstance(target, Segment) else \
                    CPointOnCurve(vertex, target)
            self._add_constraint(sk, constraint, describe_constraint(sk, constraint))

    def _report(self, what, result):
        """Show the outcome of a constraint addition in the status bar / side panel."""
        ok, msg = result
        if ok:
            text = f"{what} added" + (f" ({msg})" if msg else "")
        else:
            text = f"⚠ {what} not added: {msg}"
        self.sigSelInfo.emit(text)
        return ok

    def _add_constraint(self, sk, c, what, prefer_lock=(), silent=False):
        res = sk.try_add_constraint(c, prefer_lock)
        return res[0] if silent else self._report(what, res)

    def _auto_constraints(self, sk, new_seg):
        """After adding new_seg: horizontal/vertical and perpendicular-to-neighbour constraints.
        Constraints that would be redundant are skipped automatically."""
        ax = new_seg.axis()
        if ax == 'H':   self._add_constraint(sk, CHorizontal(new_seg), "", silent=True)
        elif ax == 'V': self._add_constraint(sk, CVertical(new_seg), "", silent=True)
        def vec(s): return (s.v1.x - s.v0.x, s.v1.y - s.v0.y)
        vx, vy = vec(new_seg)
        lv = math.hypot(vx, vy)
        for seg in list(sk.segments):
            if seg is new_seg or seg.reference: continue
            if not ({seg.v0, seg.v1} & {new_seg.v0, new_seg.v1}): continue
            ox, oy = vec(seg)
            lo = math.hypot(ox, oy)
            if lv < 1e-9 or lo < 1e-9: continue
            # normalised dot product — zero means perpendicular
            if abs((vx*ox + vy*oy) / (lv * lo)) < 0.01:  # within ~0.6° of perpendicular
                self._add_constraint(sk, CPerpendicular(new_seg, seg), "", silent=True)

    def _draw_rect(self, sv, sk, mm, constr=False):
        rp0=sv.get("rect_p0")
        if rp0 is None:
            sv["rect_p0"]=sk.get_or_merge(mm[0],mm[1],MERGE_TOL)
        else:
            x0,y0=rp0.x,rp0.y; x1,y1=mm
            if abs(x1-x0)<0.01 or abs(y1-y0)<0.01:
                sv["rect_p0"]=None; return
            v0=rp0
            v1=sk.get_or_merge(x1,y0,MERGE_TOL)
            v2=sk.get_or_merge(x1,y1,MERGE_TOL)
            v3=sk.get_or_merge(x0,y1,MERGE_TOL)
            s0=Segment(v0,v1,constr); s1=Segment(v1,v2,constr)
            s2=Segment(v2,v3,constr); s3=Segment(v3,v0,constr)
            sk.segments+=[s0,s1,s2,s3]
            sv["rect_p0"]=None
            # horizontal/vertical sides (corners are then implicitly perpendicular)
            for s in (s0, s2): self._add_constraint(sk, CHorizontal(s), "", silent=True)
            for s in (s1, s3): self._add_constraint(sk, CVertical(s), "", silent=True)

    def _draw_circle(self, sv, sk, mm, constr=False):
        """Centre + radius; matching an enabled reference circle also links its radius."""
        cc=sv.get("circle_ctr")
        if cc is None:
            sv["circle_ctr"]=mm
        else:
            r=math.hypot(mm[0]-cc[0],mm[1]-cc[1])
            if r<0.1: r=1.0
            circle = Circle(sk.get_or_merge(cc[0],cc[1],MERGE_TOL),r,constr)
            target = next((reference for reference in sk.circles
                           if reference.reference and self._level_reference_available(reference)
                           and math.dist(circle.center.xy(), reference.center.xy()) <= MERGE_TOL
                           and abs(circle.radius-reference.radius) <= TRIM_TOL), None)
            sk.circles.append(circle)
            if target is not None:
                constraint = CEqual(circle, target)
                self._add_constraint(sk, constraint, describe_constraint(sk, constraint))
            sv["circle_ctr"]=None

    @staticmethod
    def _ellipse_points(center, major_endpoint, minor_endpoint, count=64):
        cx, cy = center
        ux, uy = major_endpoint[0]-cx, major_endpoint[1]-cy
        major = math.hypot(ux, uy)
        if major < 0.1: return None
        ux, uy = ux/major, uy/major
        nx, ny = -uy, ux
        minor = abs((minor_endpoint[0]-cx)*nx + (minor_endpoint[1]-cy)*ny)
        if minor < 0.1: return None
        return [(cx + major*ux*math.cos(2*math.pi*i/count) +
                 minor*nx*math.sin(2*math.pi*i/count),
                 cy + major*uy*math.cos(2*math.pi*i/count) +
                 minor*ny*math.sin(2*math.pi*i/count)) for i in range(count)]

    def _draw_ellipse(self, sv, sk, mm, constr=False):
        center = sv.get("ellipse_ctr")
        if center is None:
            sv["ellipse_ctr"] = tuple(mm)
            sv["ellipse_axis"] = None
            return
        major_endpoint = sv.get("ellipse_axis")
        if major_endpoint is None:
            if math.dist(center, mm) < 0.1: return
            sv["ellipse_axis"] = tuple(mm)
            return
        cx, cy = center
        major_x, major_y = major_endpoint[0]-cx, major_endpoint[1]-cy
        major_length = math.hypot(major_x, major_y)
        if major_length < 0.1:
            sv["ellipse_ctr"] = None; sv["ellipse_axis"] = None
            return
        normal_x, normal_y = -major_y/major_length, major_x/major_length
        minor_length = abs((mm[0]-cx)*normal_x + (mm[1]-cy)*normal_y)
        sv["ellipse_ctr"] = None
        sv["ellipse_axis"] = None
        if minor_length < 0.1: return
        vertices = [sk.get_or_merge(x, y, MERGE_TOL) for x, y in (
            (cx-major_x, cy-major_y), (cx+major_x, cy+major_y),
            (cx-normal_x*minor_length, cy-normal_y*minor_length),
            (cx+normal_x*minor_length, cy+normal_y*minor_length))]
        sk.ellipses.append(Ellipse(*vertices, construction=constr))

    def _draw_polygon(self, sv, sk, mm, constr=False):
        """Draw a regular polygon from its centre and circumradius."""
        center = sv.get("polygon_ctr")
        if center is None:
            sv["polygon_ctr"] = mm
            return
        radius = math.hypot(mm[0]-center[0], mm[1]-center[1])
        sv["polygon_ctr"] = None
        if radius < 0.1: return
        sides = max(5, min(64, int(sv.get("polygon_sides", 6))))
        vertices = [sk.get_or_merge(
            center[0] + radius*math.cos(2*math.pi*i/sides),
            center[1] + radius*math.sin(2*math.pi*i/sides), MERGE_TOL)
            for i in range(sides)]
        for i, vertex in enumerate(vertices):
            next_vertex = vertices[(i+1) % sides]
            if vertex is not next_vertex:
                sk.segments.append(Segment(vertex, next_vertex, constr))

    def _draw_arc(self, sv, sk, mm, constr=False):
        """Partial circle: click centre, click start (sets radius), click end.
        The arc direction follows the mouse sweep between start and end."""
        ac = sv.get("arc_ctr")
        if ac is None:
            sv["arc_ctr"] = mm; sv["arc_start"] = None; sv["arc_sweep"] = 0.0
            return
        ast = sv.get("arc_start")
        if ast is None:
            if math.hypot(mm[0]-ac[0], mm[1]-ac[1]) <= MERGE_TOL: return
            sv["arc_start"] = mm; sv["arc_sweep"] = 0.0; self._arc_last_ang = None
            return
        r  = math.hypot(ast[0]-ac[0], ast[1]-ac[1])
        a0 = math.atan2(ast[1]-ac[1], ast[0]-ac[0])
        end_snap = self._snap_vtx     # end clicked onto an existing point → use that point
        if end_snap is not None and (sk.text_group_for(end_snap) is not None or
                                     end_snap in sk.reference_vertices()):
            end_snap = None
        sweep = sv.get("arc_sweep", 0.0)
        if abs(sweep) < 1e-3:   # no tracked movement → CCW to the clicked angle
            sweep = (math.atan2(mm[1]-ac[1], mm[0]-ac[0]) - a0) % (2*math.pi)
        sv["arc_ctr"] = None; sv["arc_start"] = None; sv["arc_sweep"] = 0.0
        self._arc_last_ang = None
        if abs(sweep) < 1e-3: return
        prior = set(sk.vertices)
        def drop_new_orphans():
            used = sk.used_vertices()
            sk.vertices = [v for v in sk.vertices if v in prior or v in used]
        vc = sk.get_or_merge(ac[0], ac[1], MERGE_TOL)
        if abs(abs(sweep) - 2*math.pi) < 1e-3:      # full turn → plain circle
            sk.circles.append(Circle(vc, r, constr)); return
        a1 = a0 + sweep
        vs = sk.get_or_merge(ast[0], ast[1], MERGE_TOL)
        ve = end_snap if end_snap is not None and end_snap not in (vc, vs) else \
             sk.get_or_merge(ac[0]+r*math.cos(a1), ac[1]+r*math.sin(a1), MERGE_TOL)
        if vs is ve:                                 # end snapped onto start → circle
            sk.circles.append(Circle(vc, r, constr)); drop_new_orphans(); return
        if vc is vs or vc is ve:
            drop_new_orphans(); return
        if sweep < 0: vs, ve = ve, vs                # store CCW
        sk.arcs.append(Arc(vc, vs, ve, constr))
        self._auto_merge_endpoints(sk)
        sk.solve(prefer_lock=[vc, vs])

    # ── dimension value dialogs ───────────────────────────────────────────────
    @staticmethod
    def circle_dim_dialog(circ, value=None, mode="diameter"):
        """Ask diameter/radius + value. Returns (mode, value) or None."""
        from PyQt5.QtWidgets import QDialog, QDialogButtonBox, QRadioButton
        dlg=QDialog(); dlg.setWindowTitle("Circle Dimension")
        dlg_lay=QVBoxLayout(dlg)
        rb_dia=QRadioButton("Diameter"); rb_rad=QRadioButton("Radius")
        rb_dia.setChecked(mode=="diameter"); rb_rad.setChecked(mode=="radius")
        dlg_lay.addWidget(rb_dia); dlg_lay.addWidget(rb_rad)
        sp=QDoubleSpinBox(); sp.setRange(0.01,10000); sp.setDecimals(2)
        sp.setObjectName("sketchDimension"); sp.setSuffix(" mm")
        sp.setValue(value if value is not None else
                    round(_dimension_measurement(mode, circ)["value"], 2))
        dlg_lay.addWidget(sp)
        def _update_default():
            selected_mode = "diameter" if rb_dia.isChecked() else "radius"
            sp.setValue(round(_dimension_measurement(selected_mode, circ)["value"], 2))
        rb_dia.toggled.connect(_update_default)
        btns=QDialogButtonBox(QDialogButtonBox.Ok|QDialogButtonBox.Cancel)
        btns.accepted.connect(dlg.accept); btns.rejected.connect(dlg.reject)
        dlg_lay.addWidget(btns)
        if not dlg.exec_(): return None
        return ("diameter" if rb_dia.isChecked() else "radius"), sp.value()

    def edit_dimension(self, sk, c):
        """Edit an existing driving dimension (dialog). Reverts if it cannot be satisfied."""
        if isinstance(c, CDistance):
            if not c.driving:
                self.sigSelInfo.emit("Information-only distance (support geometry) — not editable")
                return False
            angle = c.mode == "angle"
            orient = getattr(c, "orient", "D")
            label = {"H": "Horizontal length (mm):", "V": "Vertical length (mm):"}.get(
                orient, "Length (mm):")
            val, ok = QInputDialog.getDouble(None, "Angle" if angle else "Length",
                                             "Angle (°):" if angle else label,
                                             round(c.value, 2),
                                             0.0 if angle or orient in ("H", "V") else 0.01,
                                             180.0 if angle else 10000, 2)
            if not ok: return False
            mode = None
        elif isinstance(c.target, Circle):
            res = self.circle_dim_dialog(c.target, c.value, c.dim_mode)
            if res is None: return False
            mode, val = res
        else:
            label = {"H": "Horizontal distance", "V": "Vertical distance"}.get(
                c.orient, "Radius" if isinstance(c.target, Arc) else "Length")
            val, ok = QInputDialog.getDouble(None, "Dimension", f"{label} (mm):",
                                             round(c.value, 2), 0.01, 10000, 2)
            if not ok: return False
            mode = None
        if sk.set_dimension_value(c, val, mode):
            self.sigSelInfo.emit(f"Dimension set to {val:.2f}"); return True
        self.sigSelInfo.emit(f"⚠ {val:.2f} conflicts with other constraints — value kept")
        return False

    @staticmethod
    def length_dialog(a, b):
        """Ask a length; two points also support horizontal or vertical distance.
        Returns (mode, value, orient) or None."""
        from PyQt5.QtWidgets import QDialog, QDialogButtonBox, QRadioButton
        points = isinstance(a, Vertex) and isinstance(b, Vertex)
        circles = isinstance(a, Circle) and isinstance(b, Circle)
        probe_d = CDistance(a, b, mode="distance")
        probe_h = CDistance(a, b, orient="H") if points else None
        probe_v = CDistance(a, b, orient="V") if points else None
        dlg = QDialog(); dlg.setWindowTitle("Length")
        lay = QVBoxLayout(dlg)
        rb_d = QRadioButton(("Difference between circle radii" if probe_d.circle_relation == "concentric"
                     else "Distance between circle centers") if circles else
                            "Length (lines become parallel)" if isinstance(a, Segment) and isinstance(b, Segment) else
                            "Direct distance (straight line)" if points else "Distance")
        rb_h = QRadioButton("Horizontal distance (ΔX — 0 aligns the points vertically)")
        rb_v = QRadioButton("Vertical distance (ΔY — 0 aligns the points horizontally)")
        lay.addWidget(rb_d)
        if points: lay.addWidget(rb_h); lay.addWidget(rb_v)
        sp = QDoubleSpinBox(); sp.setDecimals(2); lay.addWidget(sp)
        sp.setObjectName("sketchDimension")
        def refresh():
            probe = probe_h if rb_h.isChecked() else probe_v if rb_v.isChecked() else probe_d
            sp.setRange(0.0, 10000.0); sp.setSuffix(" mm"); sp.setValue(round(probe.measure(), 2))
        if points:
            dx, dy = abs(b.x-a.x), abs(b.y-a.y)
            (rb_h if dy <= 0.1*dx else rb_v if dx <= 0.1*dy else rb_d).setChecked(True)
        else:
            rb_d.setChecked(True)
        for rb in (rb_d, rb_h, rb_v): rb.toggled.connect(lambda _: refresh())
        refresh()
        btns = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        btns.accepted.connect(dlg.accept); btns.rejected.connect(dlg.reject); lay.addWidget(btns)
        if not dlg.exec_(): return None
        return "distance", sp.value(), "H" if rb_h.isChecked() else "V" if rb_v.isChecked() else "D"

    @staticmethod
    def text_style_dialog(initial=None, title="Text"):
        """Text content + style dialog. Returns dict or None on cancel."""
        from PyQt5.QtWidgets import QDialog, QDialogButtonBox, QRadioButton
        initial = dict(initial or {})
        dlg = QDialog()
        dlg.setWindowTitle(title)
        lay = QVBoxLayout(dlg)
        text_edit = QLineEdit(initial.get("label", ""))
        text_edit.setPlaceholderText("Text")
        lay.addWidget(QLabel("Text:"))
        lay.addWidget(text_edit)
        row1 = QHBoxLayout()
        font_combo = QComboBox()
        font_combo.addItems(TEXT_FONT_CHOICES)
        font = initial.get("font_family", "Arial")
        font_combo.setCurrentText(font if font in TEXT_FONT_CHOICES else "Arial")
        size_spin = QSpinBox(); size_spin.setRange(1, 400)
        size_spin.setValue(int(round(float(initial.get("font_size", 12.0)))))
        row1.addWidget(QLabel("Font")); row1.addWidget(font_combo)
        row1.addWidget(QLabel("Size")); row1.addWidget(size_spin)
        lay.addLayout(row1)
        row2 = QHBoxLayout()
        cb_bold = QCheckBox("Bold"); cb_bold.setChecked(bool(initial.get("bold", False)))
        cb_italic = QCheckBox("Italic"); cb_italic.setChecked(bool(initial.get("italic", False)))
        cb_underline = QCheckBox("Underline"); cb_underline.setChecked(bool(initial.get("underline", False)))
        row2.addWidget(cb_bold); row2.addWidget(cb_italic); row2.addWidget(cb_underline)
        lay.addLayout(row2)
        row3 = QHBoxLayout()
        rb_left = QRadioButton("Left")
        rb_center = QRadioButton("Center")
        rb_right = QRadioButton("Right")
        align = initial.get("align", "left")
        rb_left.setChecked(align == "left")
        rb_center.setChecked(align == "center")
        rb_right.setChecked(align == "right")
        row3.addWidget(QLabel("Align")); row3.addWidget(rb_left); row3.addWidget(rb_center); row3.addWidget(rb_right)
        lay.addLayout(row3)
        btns = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        btns.accepted.connect(dlg.accept); btns.rejected.connect(dlg.reject)
        lay.addWidget(btns)
        if not dlg.exec_():
            return None
        label = text_edit.text().strip()
        if not label:
            return None
        return {
            "label": label,
            "font_family": font_combo.currentText(),
            "font_size": float(size_spin.value()),
            "bold": cb_bold.isChecked(),
            "italic": cb_italic.isChecked(),
            "underline": cb_underline.isChecked(),
            "align": "right" if rb_right.isChecked() else "center" if rb_center.isChecked() else "left",
        }

    def _draw_point(self, sk, px):
        """Point tool: place a sketch point; snapped crossings / lines get Point-on-Line."""
        mm, segs = self.point_snap(px)
        v = Vertex(mm[0], mm[1]); sk.vertices.append(v); sk.points_free.append(v)
        for s in segs:
            self._add_constraint(sk, CPointOnLine(v, s), "", prefer_lock=[s.v0, s.v1], silent=True)
        names = " × ".join(f"L{sk.segments.index(s)}" for s in segs)
        where = f"at crossing {names}" if len(segs) == 2 else f"on {names}" if segs else \
                f"at ({mm[0]:.1f}, {mm[1]:.1f})"
        self.sigSelInfo.emit(f"Point P{sk.vertices.index(v)} added {where}")

    def _draw_text(self, sk, mm):
        """Open text editing at the clicked location, then place the confirmed label."""
        style = self.text_style_dialog({
            "label": "Text", "font_family": "Arial", "font_size": 24.0,
            "bold": False, "italic": False, "underline": False, "align": "left",
        }, title="Place text")
        if style is None:
            return
        label = style.get("label", "").strip()
        if not label:
            return
        group, added = sk.add_text_label(mm, label, style)
        if group is None or added <= 0:
            self.sigSelInfo.emit("Text tool: nothing added")
            return
        self.sigSelInfo.emit(
            f'Text "{group.label}" added ({added} segment(s)) — drag to move, corner-drag to resize')

    def _constrain_press(self, sv, sk, px, mm, ctrl):
        ctool=sv.get("ctool",CTOOL_NONE)

        if ctool==CTOOL_TANGENT:
            entity=self._near_tangent_entity(sk,px)
            if entity is None: return
            first=sv.get("tangent_first")
            valid=sk.segments+sk.circles+sk.arcs
            if first not in valid:
                sv["tangent_first"]=entity
                self.sigSelInfo.emit("First entity picked — click a line and circle/arc, or two curves")
                self.update(); return
            if entity is first: return
            if isinstance(first,Segment) and isinstance(entity,Segment):
                self.sigSelInfo.emit("Tangential requires a line and circle/arc, or two circles/arcs")
                return
            constraint=CTangential(first,entity)
            if isinstance(first,Segment): prefer_lock=[first.v0,first.v1]
            elif isinstance(first,Circle): prefer_lock=[first.center]
            else: prefer_lock=[first.center,first.v_start]
            self._add_constraint(sk,constraint,describe_constraint(sk,constraint),
                                 prefer_lock=prefer_lock)
            sv["tangent_first"]=None; self.update(); return

        if ctool==CTOOL_ANGLE:
            si=self._near_seg(sk,px)
            if si is None: return
            first=sv.get("angle_first")
            if first is None or first >= len(sk.segments):
                sv["angle_first"]=si
                sv["angle_first_pos"]=tuple(mm) if mm is not None else None
                self.sigSelInfo.emit(f"L{si} picked — click the second line to set the angle")
                self.update(); return
            if si==first: return
            sa,sb=sk.segments[first],sk.segments[si]
            sv["angle_first"]=None
            first_pos=sv.pop("angle_first_pos",None)
            angle_sides=_angle_ray_sides(sa,sb,first_pos,mm) \
                if first_pos is not None and mm is not None else None
            if sv.get("construction"):
                self._add_constraint(sk,CDistance(sa,sb,mode="angle",driving=False,
                                                  angle_sides=angle_sides),
                                     "Angle info")
                self.update(); return
            probe=CDistance(sa,sb,mode="angle",angle_sides=angle_sides)
            value,ok=QInputDialog.getDouble(None,"Angle","Angle (°):",
                                            round(probe.measure(),2),0.0,180.0,2)
            if ok:
                self._add_constraint(sk,CDistance(sa,sb,value,mode="angle",
                                                  angle_sides=angle_sides),"Angle",
                                     prefer_lock=[sa.v0,sa.v1])
            self.update(); return

        if ctool in (CTOOL_LENGTH,CTOOL_DIST):
            # Pick points, lines or circles; diameter/radius is a separate tool.
            ci=self._near_circle(sk,px)
            vi=None if ci is not None else self._near_vtx(sk,px)
            si=None if ci is not None or vi is not None else self._near_seg(sk,px)
            ent=sk.circles[ci] if ci is not None else \
                sk.vertices[vi] if vi is not None else sk.segments[si] if si is not None else None
            if ent is None: return
            first=sv.get("dist_first")
            if first is None or (first not in sk.vertices and first not in sk.segments
                                 and first not in sk.circles):
                sv["dist_first"]=ent
                self.sigSelInfo.emit("First element picked — click a second point, line or circle")
                self.update(); return
            if ent is first: return
            sv["dist_first"]=None
            if sv.get("construction"):
                # support-geometry mode: measurement only, never constrains anything
                c=CDistance(first, ent, driving=False)
                self._add_constraint(sk, c, f"Length info {c.label()}")
                self.update(); return
            res=self.length_dialog(first, ent)
            if res is None: self.update(); return
            mode, val, orient = (tuple(res) + ("D",))[:3]
            c=CDistance(first, ent, val, mode=mode, orient=orient)
            lock=[ent] if isinstance(ent, Vertex) else \
                 [ent.center] if isinstance(ent, Circle) else [ent.v0, ent.v1]
            what={"H": "Horizontal length", "V": "Vertical length"}.get(orient, "Length")
            self._add_constraint(sk, c, what, prefer_lock=lock)
            self.update(); return

        if ctool==CTOOL_FIX:
            vi=self._near_vtx(sk,px)
            if vi is not None:
                v=sk.vertices[vi]
                existing=[c for c in sk.constraints if isinstance(c,CFixed) and c.vertex is v]
                if existing:
                    for c in existing: sk.constraints.remove(c)
                    self.sigSelInfo.emit(f"Fix removed from P{vi}")
                else:
                    self._add_constraint(sk, CFixed(v), f"Fix P{vi}")
                self.update(); return
            # click near origin or axis lines -> fix all vertices on that axis
            ox = self.to_px((0,0))
            origin_thr = 12.0  # px
            axis_thr = 8.0     # px distance to axis line
            if math.hypot(px.x()-ox.x(), px.y()-ox.y()) < origin_thr:
                picked = [v for v in sk.vertices
                          if abs(v.x) < self.snap_mm and abs(v.y) < self.snap_mm]
            elif abs(px.y() - ox.y()) < axis_thr:     # X-axis (y==0 line)
                picked = [v for v in sk.vertices if abs(self.to_px(v.xy()).y() - ox.y()) < axis_thr]
            elif abs(px.x() - ox.x()) < axis_thr:     # Y-axis (x==0 line)
                picked = [v for v in sk.vertices if abs(self.to_px(v.xy()).x() - ox.x()) < axis_thr]
            else:
                return
            n_ok = 0
            reference_vertices = sk.reference_vertices()
            for v in picked:
                if v in reference_vertices: continue
                if not any(isinstance(c,CFixed) and c.vertex is v for c in sk.constraints):
                    n_ok += self._add_constraint(sk, CFixed(v), "", silent=True)
            self.sigSelInfo.emit(f"{n_ok} vertex(es) fixed")
            self.update(); return

        if ctool==CTOOL_DIM:
            # circle radius/diameter
            ci=self._near_circle(sk,px)
            if ci is not None:
                circ=sk.circles[ci]
                existing=next((c for c in sk.constraints if isinstance(c,CDimension)
                               and c.target is circ),None)
                if existing:
                    self.edit_dimension(sk, existing); return
                res=self.circle_dim_dialog(circ)
                if res:
                    c=CDimension(circ, res[1]); c.dim_mode=res[0]
                    self._add_constraint(sk, c, "Circle dimension")
                return
            self.sigSelInfo.emit("Diameter / Radius requires a circle")
            self.update(); return

        if ctool==CTOOL_PERP:
            si=self._near_seg(sk,px)
            if si is None: return
            first=sv.get("sel_seg")
            if first is None:
                sv["sel_seg"]=si
                self.update(); return          # show first-pick highlight
            if si != first:
                sa=sk.segments[first]; sb=sk.segments[si]
                sk.constraints=[c for c in sk.constraints
                                 if not(isinstance(c,CPerpendicular) and
                                        {c.seg_a,c.seg_b}=={sa,sb})]
                self._add_constraint(sk, CPerpendicular(sa,sb), "Perpendicular",
                                     prefer_lock=[sa.v0, sa.v1])
            sv["sel_seg"]=None
            self.update(); return

        if ctool==CTOOL_PTPT:
            # first pick = what moves (a point, or a line); second pick = the target. The
            # target type is detected automatically: point → coincident, line → point on line,
            # circle/arc → point on curve, origin → fixed at (0,0)
            vi=self._near_vtx(sk,px)
            first=sv.get("sel_vtx1"); first_seg=sv.get("sel_seg")
            if first is not None and first >= len(sk.vertices): first=None
            if first_seg is not None and first_seg >= len(sk.segments): first_seg=None
            ox=self.to_px((0,0))
            at_origin = math.hypot(px.x()-ox.x(), px.y()-ox.y()) < 12
            if first is None and first_seg is None:
                if vi is not None:
                    sv["sel_vtx1"]=vi
                    self.sigSelInfo.emit(f"P{vi} picked — click the target point, line, "
                                         "circle/arc or the origin")
                else:
                    si=self._near_seg(sk,px)
                    if si is None: return
                    sv["sel_seg"]=si
                    self.sigSelInfo.emit(f"L{si} picked — click the point the line must pass through")
                self.update(); return
            if first_seg is not None:
                seg=sk.segments[first_seg]
                if vi is None or sk.vertices[vi] in (seg.v0, seg.v1):
                    self.sigSelInfo.emit("Line→Point: click a point that is not an end of the line")
                    return
                vt=sk.vertices[vi]; sv["sel_seg"]=None
                self._add_constraint(sk, CPointOnLine(vt, seg), f"Line→Point L{first_seg}→P{vi}",
                                     prefer_lock=[vt])
                self.update(); return
            vm=sk.vertices[first]
            if vi is not None and vi!=first:
                vt=sk.vertices[vi]
                sk.constraints=[c for c in sk.constraints
                                 if not(isinstance(c,CCoincident) and c.vertex_move is vm)]
                self._add_constraint(sk, CCoincident(vm,vt), f"Point→Point P{first}→P{vi}",
                                     prefer_lock=[vt])
            elif vi is None and at_origin:
                c=CFixed(vm); c.x0=0.0; c.y0=0.0
                self._add_constraint(sk, c, f"Point→Origin P{first}")
            elif vi is None:
                si=self._near_seg(sk,px,exclude_vertex=vm)
                ci=self._near_circle(sk,px) if si is None else None
                ai=self._near_arc(sk,px) if si is None and ci is None else None
                if si is not None:
                    seg=sk.segments[si]
                    sk.constraints=[c for c in sk.constraints if not(
                        isinstance(c,CPointOnLine) and c.vertex is vm and c.seg is seg)]
                    self._add_constraint(sk, CPointOnLine(vm, seg), f"Point→Line P{first}→L{si}",
                                         prefer_lock=[seg.v0, seg.v1])
                elif ci is not None or ai is not None:
                    cu=sk.circles[ci] if ci is not None else sk.arcs[ai]
                    own={cu.center} if ci is not None else {cu.center, cu.v_start, cu.v_end}
                    if vm in own:
                        self.sigSelInfo.emit("Point→Curve: the point already belongs to that curve")
                    else:
                        name=f"C{ci}" if ci is not None else f"A{ai}"
                        lock=[cu.center] if ci is not None else [cu.center, cu.v_start]
                        self._add_constraint(sk, CPointOnCurve(vm, cu),
                                             f"Point→Curve P{first}→{name}", prefer_lock=lock)
                else:
                    self.sigSelInfo.emit("Click a target point, line, circle/arc or the origin")
                    return
            sv["sel_vtx1"]=None; self.update(); return

        if ctool==CTOOL_EQUAL:
            entity = self._near_equal_entity(sk, px)
            if entity is None:
                return
            first = sv.get("equal_first")
            if first is None or first not in sk.segments and first not in sk.circles:
                sv["equal_first"] = entity
                if isinstance(entity, Circle):
                    index = sk.circles.index(entity)
                    self.sigSelInfo.emit(f"C{index} is the reference — click a circle to make equal diameter")
                else:
                    index = sk.segments.index(entity)
                    self.sigSelInfo.emit(f"L{index} is the reference — click a line to make equal length")
                self.update(); return
            if entity is first:
                return
            if isinstance(first, Circle) != isinstance(entity, Circle):
                self.sigSelInfo.emit("Equal requires two lines or two circles")
                return
            sa, sb = first, entity
            sk.constraints=[c for c in sk.constraints
                            if not(isinstance(c,CEqual) and {c.seg_a,c.seg_b}=={sa,sb})]
            if isinstance(sa, Circle):
                name = f"Equal diameter C{sk.circles.index(sa)}=C{sk.circles.index(sb)}"
                prefer_lock = [sa.center]
            else:
                name = f"Equal L{sk.segments.index(sa)}=L{sk.segments.index(sb)}"
                prefer_lock = [sa.v0, sa.v1]
            self._add_constraint(sk, CEqual(sa,sb), name, prefer_lock=prefer_lock)
            sv["equal_first"]=None; self.update(); return

        if ctool==CTOOL_PARA:
            first=sv.get("sel_seg")
            si=self._near_seg(sk,px)
            if first is None:
                if si is None: return
                sv["sel_seg"]=si
                self.sigSelInfo.emit(f"L{si} picked — click the second line to make parallel")
                self.update(); return
            if si is None or si==first: return
            sa,sb=sk.segments[first],sk.segments[si]
            sk.constraints=[c for c in sk.constraints
                            if not(isinstance(c,CParallel) and {c.seg_a,c.seg_b}=={sa,sb})]
            self._add_constraint(sk, CParallel(sa,sb), f"Parallel L{first}||L{si}",
                                 prefer_lock=[sa.v0,sa.v1])
            sv["sel_seg"]=None; self.update(); return

        if ctool==CTOOL_COLLINEAR:
            si=self._near_seg(sk,px)
            if si is None: return
            first=sv.get("sel_seg")
            if first is None:
                sv["sel_seg"]=si
                self.sigSelInfo.emit(f"L{si} picked — click the second line to make collinear")
                self.update(); return
            if si is None or si==first: return
            sa,sb=sk.segments[first],sk.segments[si]
            self._add_constraint(sk,CCollinear(sa,sb),f"Collinear L{first}, L{si}",
                                 prefer_lock=[sa.v0,sa.v1])
            sv["sel_seg"]=None; self.update(); return

        if ctool==CTOOL_SYM:
            ctr=sv.get("_sym_center"); first=sv.get("sel_seg")
            if sv.get("sel_vtx1") is not None:
                first=sk.vertices[sv["sel_vtx1"]]
            si=self._near_seg(sk,px); vi=self._near_vtx(sk,px)
            if ctr is None:
                if si is not None:
                    sv["_sym_center"]=("seg",si); sv["sel_seg"]=None
                    self.sigSelInfo.emit(f"Center L{si} — click first point or line")
                elif vi is not None:
                    sv["_sym_center"]=("vtx",vi); sv["sel_seg"]=None
                    self.sigSelInfo.emit(f"Center P{vi} — click first point or line")
                else: return
                self.update(); return
            center=sk.segments[ctr[1]] if ctr[0]=="seg" else sk.vertices[ctr[1]]
            if si is None and vi is None:
                ci=self._near_circle(sk,px)
                if ci is not None and sk.circles[ci].center in sk.vertices:
                    vi=sk.vertices.index(sk.circles[ci].center)
            entity=sk.vertices[vi] if vi is not None else sk.segments[si] if si is not None else None
            if entity is None or entity is center: return
            if first is None:
                if isinstance(entity, Vertex):
                    sv["sel_vtx1"]=vi
                else:
                    sv["sel_seg"]=si
                self.sigSelInfo.emit(f"P{vi} — click second point" if isinstance(entity, Vertex)
                                     else f"L{si} — click second line")
                self.update(); return
            sa=first if isinstance(first, Vertex) else sk.segments[first]
            if entity is sa: return
            if isinstance(sa, Vertex) != isinstance(entity, Vertex):
                self.sigSelInfo.emit("Symmetric requires two points or two lines")
                return
            prefer_lock=[center.v0,center.v1] if isinstance(center, Segment) else [center]
            constraint=CSymmetric(sa,entity,center)
            self._add_constraint(sk, constraint, describe_constraint(sk, constraint),
                                 prefer_lock=prefer_lock)
            sv["sel_seg"]=None; sv["sel_vtx1"]=None
            sv.pop("_sym_center",None); self.update(); return

    def _can_pick_reference(self, sk, px, thr):
        """Constraint references are a fallback, never an obstruction over editable geometry."""
        if self.state.get("sketch_view_state", {}).get("mode") not in (DTOOL_SELECT, "draw", "constrain"):
            return False
        threshold = max(thr, 12.0)
        point = self.to_mm(px)
        references = sk.reference_vertices()
        if any(v not in references and math.dist(point, v.xy())*self.scale < threshold
               for v in sk.vertices):
            return False
        return not any(not element.reference and
                       dist_to_curve(curve_of(element), point)*self.scale < threshold
                       for element in sk.segments+sk.circles+sk.arcs)

    def _level_reference_available(self, element):
        level = getattr(element, "reference_level", None)
        if level is None:
            return True
        sv = self.state.get("sketch_view_state", {})
        if sv.get("mode") not in (DTOOL_SELECT, "draw", "constrain") and sv.get("mirror_pending") is None:
            return False
        levels = sv.get("underlays", [])
        return any(item["level"] == level and item["visible"] and item["reference"]
                   for item in levels)

    def _near_arc(self, sk, px, thr=12.0):
        """Return index of the arc whose curve is within thr px of px."""
        best_i, best_d = None, thr
        reference_allowed = self._can_pick_reference(sk, px, thr)
        for i, arc in enumerate(sk.arcs):
            if not self._level_reference_available(arc): continue
            if arc.reference and not reference_allowed: continue
            pts = [self.to_px(xy) for xy in arc.tess()]
            d, _nearest, _segment = _projected_polyline_hit(
                (px.x(), px.y()), [(point.x(), point.y()) for point in pts])
            if d < best_d: best_d = d; best_i = i
        return best_i

    def _near_ellipse(self, sk, px, thr=10.0):
        best_i, best_d = None, thr
        for i, ellipse in enumerate(sk.ellipses):
            if ellipse.reference:
                continue
            points = [self.to_px(point) for point in ellipse.tess()]
            if not points:
                continue
            points.append(points[0])
            distance, _nearest, _segment = _projected_polyline_hit(
                (px.x(), px.y()), [(point.x(), point.y()) for point in points])
            if distance < best_d:
                best_i, best_d = i, distance
        return best_i

    def _near_vtx(self, sk, px, thr=10.0):
        reference_vertices = sk.reference_vertices()
        reference_allowed = self._can_pick_reference(sk, px, thr)
        box_vertices = {v for group in sk.text_groups for v in group.box_vertices}
        box_indices = [i for i, vertex in enumerate(sk.vertices) if vertex in box_vertices]
        if box_indices:
            box_points = [self.to_px(sk.vertices[index].xy()) for index in box_indices]
            distance, nearest = _projected_points_hit(
                (px.x(), px.y()), [(point.x(), point.y()) for point in box_points])
            if distance < thr:
                return box_indices[nearest]
        candidates = [i for i, vertex in enumerate(sk.vertices)
                      if vertex not in box_vertices and
                      self._level_reference_available(vertex) and
                      (vertex not in reference_vertices or reference_allowed)]
        if not candidates:
            return None
        projected = [self.to_px(sk.vertices[index].xy()) for index in candidates]
        distance, nearest = _projected_points_hit(
            (px.x(), px.y()), [(point.x(), point.y()) for point in projected])
        return candidates[nearest] if distance < thr else None

    def _near_circle(self, sk, px, thr=12.0):
        """Return index of circle whose circumference is within thr px of px."""
        best_i, best_d = None, thr
        reference_allowed = self._can_pick_reference(sk, px, thr)
        for i, circ in enumerate(sk.circles):
            if not self._level_reference_available(circ): continue
            if circ.reference and not reference_allowed: continue
            cp = self.to_px(circ.center.xy())
            rpx = circ.radius * self.scale
            d, _nearest = _projected_circle_hit(
                (px.x(), px.y()), (cp.x(), cp.y()), rpx)
            if d < best_d: best_d = d; best_i = i
        return best_i

    def _near_seg(self, sk, px, thr=12.0, exclude_vertex=None):
        best_editable_i, best_editable_d = None, thr
        best_reference_i, best_reference_d = None, thr
        for i,seg in enumerate(sk.segments):
            if not self._level_reference_available(seg): continue
            if exclude_vertex is not None and (seg.v0 is exclude_vertex or seg.v1 is exclude_vertex):
                continue
            pp0=self.to_px(seg.v0.xy()); pp1=self.to_px(seg.v1.xy())
            d, _nearest = _projected_segment_hit(
                (px.x(), px.y()), (pp0.x(), pp0.y()), (pp1.x(), pp1.y()))
            if seg.reference:
                if d < best_reference_d:
                    best_reference_i, best_reference_d = i, d
            elif d < best_editable_d:
                best_editable_i, best_editable_d = i, d
        if best_reference_i is None:
            return best_editable_i
        if best_editable_i is None or best_editable_d > best_reference_d + 2.0:
            return best_reference_i
        return best_editable_i

    def _near_equal_entity(self, sk, px, thr=12.0):
        """Pick the closest segment or circle, preferring editable geometry on overlap."""
        best_editable, best_editable_d = None, thr
        best_reference, best_reference_d = None, thr
        for segment in sk.segments:
            if not self._level_reference_available(segment): continue
            p0, p1 = self.to_px(segment.v0.xy()), self.to_px(segment.v1.xy())
            distance, _nearest = _projected_segment_hit(
                (px.x(), px.y()), (p0.x(), p0.y()), (p1.x(), p1.y()))
            if segment.reference:
                if distance < best_reference_d:
                    best_reference, best_reference_d = segment, distance
            elif distance < best_editable_d:
                best_editable, best_editable_d = segment, distance
        for circle in sk.circles:
            if not self._level_reference_available(circle): continue
            center = self.to_px(circle.center.xy())
            distance, _nearest = _projected_circle_hit(
                (px.x(), px.y()), (center.x(), center.y()), circle.radius*self.scale)
            if circle.reference:
                if distance < best_reference_d:
                    best_reference, best_reference_d = circle, distance
            elif distance < best_editable_d:
                best_editable, best_editable_d = circle, distance
        if best_reference is None:
            return best_editable
        if best_editable is None or best_editable_d > best_reference_d + 2.0:
            return best_reference
        return best_editable

    def _near_tangent_entity(self, sk, px, thr=12.0):
        """Pick the nearest segment, circle or arc for a tangent constraint."""
        best_editable, best_editable_d = None, thr
        best_reference, best_reference_d = None, thr
        def consider(entity, distance):
            nonlocal best_editable, best_editable_d, best_reference, best_reference_d
            if not self._level_reference_available(entity):
                return
            if entity.reference:
                if distance < best_reference_d:
                    best_reference, best_reference_d = entity, distance
            elif distance < best_editable_d:
                best_editable, best_editable_d = entity, distance
        for segment in sk.segments:
            p0, p1 = self.to_px(segment.v0.xy()), self.to_px(segment.v1.xy())
            distance, _nearest = _projected_segment_hit(
                (px.x(), px.y()), (p0.x(), p0.y()), (p1.x(), p1.y()))
            consider(segment, distance)
        for circle in sk.circles:
            center = self.to_px(circle.center.xy())
            distance, _nearest = _projected_circle_hit(
                (px.x(), px.y()), (center.x(), center.y()), circle.radius*self.scale)
            consider(circle, distance)
        for arc in sk.arcs:
            points = [self.to_px(point) for point in arc.tess()]
            distance, _nearest, _segment = _projected_polyline_hit(
                (px.x(), px.y()), [(point.x(), point.y()) for point in points])
            consider(arc, distance)
        if best_reference is None:
            return best_editable
        if best_editable is None or best_editable_d > best_reference_d + 2.0:
            return best_reference
        return best_editable

    def _drop_if_orphan(self, sk, *verts):
        used = sk.used_vertices()
        for v in verts:
            if v is not None and v not in used and v in sk.vertices: sk.vertices.remove(v)

    def _abort_drawing_step(self, sv, sk):
        """Abort the drawing action in progress (committed geometry is kept).
        Returns True if something was aborted."""
        wip = sv.get("wip_pts") or []
        if wip:
            sv["wip_pts"] = []; self._drop_if_orphan(sk, wip[0]); return True
        if sv.get("rect_p0") is not None:
            v = sv["rect_p0"]; sv["rect_p0"] = None; self._drop_if_orphan(sk, v); return True
        if sv.get("circle_ctr") is not None:
            sv["circle_ctr"] = None; return True
        if sv.get("polygon_ctr") is not None:
            sv["polygon_ctr"] = None; return True
        if sv.get("ellipse_ctr") is not None:
            sv["ellipse_ctr"] = None; sv["ellipse_axis"] = None; return True
        if sv.get("free_pts"):
            sv["free_pts"] = None; return True
        if sv.get("arc_ctr") is not None:
            sv["arc_ctr"] = None; sv["arc_start"] = None; sv["arc_sweep"] = 0.0
            self._arc_last_ang = None; return True
        return False

    def _has_pending(self, sv):
        """Anything in progress or selected that Esc / RMB should clear first?"""
        return bool(sv.get("wip_pts") or sv.get("rect_p0") or sv.get("circle_ctr")
                    or sv.get("polygon_ctr") is not None or sv.get("ellipse_ctr") is not None
                    or bool(sv.get("free_pts"))
                    or sv.get("paste_preview") is not None
                    or sv.get("arc_ctr") is not None or sv.get("sel_seg") is not None
                    or sv.get("sel_vtx1") is not None or sv.get("sel_curve") is not None
                    or sv.get("_sel_extra")
                    or sv.get("dist_first") is not None
                    or sv.get("equal_first") is not None
                    or sv.get("_sel_segs") or sv.get("ctool", CTOOL_NONE) != CTOOL_NONE)


# ── SketchPanel ───────────────────────────────────────────────────────────────
def tool_group(caption, widgets, bg="#292e36", icon=None, framed=True):
    """A framed group of toolbar widgets with a caption or icon above them."""
    f=QFrame(); f.setObjectName("toolgrp")
    if framed:
        f.setStyleSheet(f"QFrame#toolgrp{{background:{bg};border:1px solid #3b424d;border-radius:4px;}}")
    else:
        f.setStyleSheet("QFrame#toolgrp{background:transparent;border:0;}")
    v=QVBoxLayout(f); v.setContentsMargins(3,1,3,2); v.setSpacing(0)
    if caption or icon:
        cap=QLabel()
        cap.setAlignment(Qt.AlignCenter)
        if icon:
            cap.setPixmap(QIcon(os.path.join(_LOG_DIR, "icons", icon)).pixmap(QSize(24, 24)))
            cap.setToolTip(caption)
            cap.setAccessibleName(caption)
        else:
            cap.setText(caption)
            cap.setStyleSheet("color:#aab2bd;font-size:8pt;background:transparent;")
        v.addWidget(cap)
    h=QHBoxLayout(); h.setContentsMargins(0,0,0,0); h.setSpacing(1)
    for w in widgets: h.addWidget(w)
    v.addLayout(h)
    return f


class ToggleListWidget(QListWidget):
    """List whose selected row is deselected again by clicking it."""
    def mousePressEvent(self, e):
        item = self.itemAt(e.pos())
        was_selected = e.button() == Qt.LeftButton and item is not None and item.isSelected() \
            and item is self.currentItem()
        super().mousePressEvent(e)
        if was_selected:
            self.clearSelection(); self.setCurrentRow(-1)


class ToolbarGroupScroll(QScrollArea):
    def __init__(self, group, parent=None):
        super().__init__(parent)
        self.setFrameShape(QFrame.NoFrame)
        self.setWidgetResizable(True)
        self.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        self.setWidget(group)
        self.setMinimumWidth(120)
        self.setMaximumWidth(max(120, group.sizeHint().width()))
        self.setFixedHeight(group.sizeHint().height() + self.horizontalScrollBar().sizeHint().height())

    def sizeHint(self):
        return QSize(self.maximumWidth(), self.minimumHeight())

    def minimumSizeHint(self):
        return QSize(self.minimumWidth(), self.minimumHeight())


class SketchPanel(QFrame):
    sigAccept      = pyqtSignal()
    sigCancel      = pyqtSignal()
    sigModeChanged = pyqtSignal(str)
    sigToolChanged = pyqtSignal(str)
    sigCtoolChanged= pyqtSignal(str)
    sigDeleteSel   = pyqtSignal()
    sigConstruction= pyqtSignal(bool)
    sigImportGeometry = pyqtSignal()
    sigMirror      = pyqtSignal(str)
    sigConstraintSelected = pyqtSignal(int)   # row in the constraint list (-1 = none)
    sigConstraintRemove   = pyqtSignal(int)
    sigConstraintEdit     = pyqtSignal(int)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFrameShape(QFrame.StyledPanel); self.setMaximumWidth(280)
        self._con_sig = None; self._con_ids = []
        lay=QVBoxLayout(self); lay.setContentsMargins(6,6,6,6); lay.setSpacing(4)
        lay.addWidget(QLabel("<b>Sketch</b>"))
        self.lbl_plane=QLabel("Plane: —"); lay.addWidget(self.lbl_plane)
        lay.addWidget(QLabel("Name:")); self.ed_name=QLineEdit(); lay.addWidget(self.ed_name)
        lay.addWidget(self._sep())
        # Draw / mode / constraint tools live in the main window's sketch toolbar
        # (``toolbar_items``); this panel only shows the sketch status.
        def tbtn(text, tip, checkable=True, css=None, icon=None):
            b=QToolButton(); b.setToolTip(tip); b.setCheckable(checkable)
            if icon:
                b.setIcon(QIcon(os.path.join(_LOG_DIR, "icons", icon)))
                b.setIconSize(QSize(32, 32))
                b.setAccessibleName(text)
                b.setToolButtonStyle(Qt.ToolButtonIconOnly)
            else:
                b.setText(text)
                b.setToolButtonStyle(Qt.ToolButtonTextOnly)
            b.setAutoRaise(True)
            if css: b.setStyleSheet(css)
            return b
        MODE_CSS="QToolButton:checked{background:#3f74c8;color:white;border:1px solid #2a5598;border-radius:3px;}"
        # Modes: Select / Draw / Constrain / Scissor (the trim draw tool) / Delete.
        self.btn_sel=tbtn("Select","Select - Select / drag geometry and dimension labels",
                          css=MODE_CSS, icon="select.png")
        self.btn_sel.clicked.connect(lambda: self.sigModeChanged.emit(DTOOL_SELECT))
        self.btn_draw=tbtn("Draw","Draw - Create geometry with the selected draw tool",
                           css=MODE_CSS, icon="draw.png")
        self.btn_draw.clicked.connect(self._on_draw_clicked)
        self.btn_con=tbtn("Constraint","Constrain - Add constraints with the selected constraint tool",
                          css=MODE_CSS, icon="constraint.png")
        self.btn_con.clicked.connect(lambda: self.sigModeChanged.emit("constrain"))
        self.btn_trim=tbtn("Scissor","Scissor - Cuts the selected geometry",
                           css="QToolButton:checked{background:#c84848;color:white;"
                               "border:1px solid #902828;border-radius:3px;}", icon="scissor.png")
        self.btn_trim.clicked.connect(lambda: self.sigToolChanged.emit("trim"))
        self.btn_del=tbtn("Delete","Delete - Remove the selected geometry (Del)", checkable=False,
                          icon="delete_selected.png")
        self.btn_del.setEnabled(False)
        self.btn_del.clicked.connect(self.sigDeleteSel)
        self.btn_mirror_horizontal = tbtn(
            "Mirror horizontal", "Mirror selected geometry across a horizontal axis",
            checkable=False, icon="mirror_horizontal.png")
        self.btn_mirror_vertical = tbtn(
            "Mirror vertical", "Mirror selected geometry across a vertical axis",
            checkable=False, icon="mirror_vertical.png")
        self.btn_mirror_horizontal.clicked.connect(lambda: self.sigMirror.emit("horizontal"))
        self.btn_mirror_vertical.clicked.connect(lambda: self.sigMirror.emit("vertical"))
        self.btn_mirror_horizontal.setEnabled(False)
        self.btn_mirror_vertical.setEnabled(False)
        draw_btns=[]
        for lbl,val,tip,icon in [("Freehand","freehand",
                             "Freehand drawing", "freehand.png"),
                            ("Line","line","Line",
                             "line.png"),
                            ("Rect","rect","Rectangle","rectangle.png"),
                            ("Circle","circle","Circle - Click the centre",
                             "circle.png"),
                            ("Ellipse","ellipse","Ellipse - Centre, major-axis endpoint, then minor-axis endpoint",
                             "ellipse.png"),
                            ("Polygon","polygon","Polygon - Click the centre, then set its circumradius",
                             "polygon.png"),
                            ("Arc","arc",
                             "Arc - Click the centre, the start point, then the end point",
                             "arc.png"),
                            ("Point","point",
                             "Point", "point.png"),
                            ("Text","text",
                             "Text - Click to open text options",
                             "text.png")]:
            b=tbtn(lbl, tip, icon=icon)
            b.clicked.connect(lambda _,v=val: self.sigToolChanged.emit(v))
            setattr(self,f"btn_{val}",b); draw_btns.append(b)
        self.polygon_sides=6
        self.btn_line.setChecked(True)
        self.btn_constr=tbtn("┄ Support","Support Geometry - Can be used for construction purposes",
                             css="QToolButton:checked{background:#2a4a8a;color:white;"
                                 "border:1px solid #1a3060;border-radius:3px;}",
                             icon="support_geometry.png")
        self.btn_constr.toggled.connect(self.sigConstruction)
        self.btn_import_svg=tbtn("Import SVG/DXF","Import SVG or DXF geometry into the active sketch.",
                     checkable=False, icon="import_svg_dxf.png")
        self.btn_import_svg.clicked.connect(self.sigImportGeometry)
        con_btns=[]
        for lbl,val,tip,icon in [
            ("Length",CTOOL_LENGTH,"Length - Distance between points, lines or circles","length.png"),
            ("Diameter / Radius",CTOOL_DIM,"Diameter or radius - Set a circle dimension","diameter.png"),
            ("Angle",CTOOL_ANGLE,"Angle - Between two lines","angle.png"),
            ("Parallel",CTOOL_PARA,"Parallel - Make two lines parallel","parallel.png"),
            ("Collinear",CTOOL_COLLINEAR,"Collinear - Make two lines lie on the same line","collinear.png"),
            ("Equal",CTOOL_EQUAL,
             "Equal - Click two lines for equal length or two circles for equal diameter","equal.png"),
            ("Fix",CTOOL_FIX,"Fix - Fix a Vertex at its current position.","fix.png"),
            ("Symmetric",CTOOL_SYM,"Symmetric - Click a center line or point, then two points, "
             "lines, or circles (by center)","symmetric.png"),
            ("Perpendicular",CTOOL_PERP,"Perpendicular - Make two lines perpendicular","perpendicular.png"),
            ("Point-to-Point",CTOOL_PTPT,"Point → Point/Line/Circle - The first point "
             "is moved onto the second element","point_to_point.png"),
            ("Tangential",CTOOL_TANGENT,"Tangent - Make a line tangent to a circle or arc, or two "
             "circles / arcs tangent","tangential.png"),
        ]:
            b=tbtn(lbl, tip, icon=icon)
            b.clicked.connect(lambda _,v=val: self.sigCtoolChanged.emit(v))
            setattr(self,f"cbtn_{val}",b); con_btns.append(b)
        self._mode=DTOOL_SELECT; self._tool="line"; self._last_draw_tool="line"
        self.toolbar_items=[   # widgets, str = label, None = separator
            tool_group("", [self.btn_sel, self.btn_draw, self.btn_con, self.btn_trim, self.btn_del,
                            self.btn_mirror_horizontal, self.btn_mirror_vertical],
                       "#292e36", framed=False),
            tool_group("", draw_btns + [self.btn_constr], framed=False),
            tool_group("", con_btns, framed=False)]
        lay.addWidget(QLabel("Constraints:"))
        self.lst_con=ToggleListWidget(); self.lst_con.setMinimumHeight(220)
        self.lst_con.setToolTip("Select to highlight the constrained geometry.\n"
                                "Double-click a dimension to edit its value.")
        self.lst_con.currentRowChanged.connect(self._on_con_row)
        self.lst_con.itemDoubleClicked.connect(
            lambda it: self.sigConstraintEdit.emit(self.lst_con.row(it)))
        lay.addWidget(self.lst_con)
        row=QHBoxLayout()
        self.btn_con_del=QPushButton("🗑 Remove"); self.btn_con_del.setEnabled(False)
        self.btn_con_del.setToolTip("Remove the selected constraint")
        self.btn_con_del.clicked.connect(lambda: self.sigConstraintRemove.emit(self.lst_con.currentRow()))
        self.btn_con_edit=QPushButton("✎ Edit"); self.btn_con_edit.setEnabled(False)
        self.btn_con_edit.setToolTip("Edit the value of the selected dimension")
        self.btn_con_edit.clicked.connect(lambda: self.sigConstraintEdit.emit(self.lst_con.currentRow()))
        row.addWidget(self.btn_con_del); row.addWidget(self.btn_con_edit); lay.addLayout(row)
        lay.addWidget(self._sep())
        self.lbl_issues=QLabel(""); self.lbl_issues.setWordWrap(True)
        self.lbl_issues.setStyleSheet("color:#ff6060;font-size:10px;"); lay.addWidget(self.lbl_issues)
        self.lbl_sel=QLabel(""); self.lbl_sel.setWordWrap(True)
        self.lbl_sel.setStyleSheet("color:#80c8ff;font-size:10px;"); lay.addWidget(self.lbl_sel)
        self.btn_accept=QPushButton("✔ Accept"); self.btn_accept.setEnabled(False)
        self.btn_accept.clicked.connect(self.sigAccept); lay.addWidget(self.btn_accept)
        self.btn_cancel=QPushButton("✖ Cancel"); self.btn_cancel.clicked.connect(self.sigCancel)
        lay.addWidget(self.btn_cancel); lay.addStretch()

    def _sep(self):
        f=QFrame(); f.setFrameShape(QFrame.HLine); f.setFrameShadow(QFrame.Sunken); return f

    def refresh(self, sk):
        if not sk: self.btn_accept.setEnabled(False); self.lbl_issues.setText(""); return
        self.lbl_plane.setText(f"Plane: {sk.plane}")
        self.ed_name.setPlaceholderText(sk.name)
        blocking = sk.blocking_issues(); dof = sk.total_dof()
        if blocking:
            self.lbl_issues.setStyleSheet("color:#ff6060;font-size:10px;")
            self.lbl_issues.setText("\n".join(f"• {i}" for i in sk.open_issues()))
        elif dof > 0:
            self.lbl_issues.setStyleSheet("color:#ffc850;font-size:10px;")
            self.lbl_issues.setText("\n".join(f"• {i}" for i in sk.open_issues()))
        else:
            self.lbl_issues.setStyleSheet("color:#60ff80;font-size:10px;")
            self.lbl_issues.setText("✔ Fully constrained (DOF 0)")
        self.btn_accept.setEnabled(not blocking)
        self._refresh_constraints(sk)

    def _refresh_constraints(self, sk):
        """Rebuild the constraint list only when it changed (keeps the selection)."""
        sig = tuple((id(c), describe_constraint(sk, c)) for c in sk.constraints)
        if sig == self._con_sig: return
        cur = self.lst_con.currentRow()
        cur_id = self._con_ids[cur] if 0 <= cur < len(self._con_ids) else None
        self._con_sig = sig; self._con_ids = [cid for cid, _ in sig]
        self._con_marked = None
        self.lst_con.blockSignals(True)
        self.lst_con.clear()
        for _, text in sig: self.lst_con.addItem(text)
        row = self._con_ids.index(cur_id) if cur_id in self._con_ids else -1
        self.lst_con.setCurrentRow(row)
        self.lst_con.blockSignals(False)
        self._on_con_row(row)

    def mark_constraints(self, constraints):
        """Highlight the list rows of the given constraints (independent of the current row)."""
        marked = frozenset(id(c) for c in constraints)
        if marked == getattr(self, "_con_marked", None): return
        self._con_marked = marked
        first = None
        for row, cid in enumerate(self._con_ids):
            item = self.lst_con.item(row)
            if item is None: continue
            on = cid in marked
            item.setBackground(QColor(120, 80, 20) if on else QColor(0, 0, 0, 0))
            font = item.font(); font.setBold(on); item.setFont(font)
            if on and first is None: first = item
        if first is not None: self.lst_con.scrollToItem(first)

    def _on_con_row(self, row):
        self.btn_con_del.setEnabled(row >= 0)
        self.btn_con_edit.setEnabled(row >= 0 and self.lst_con.item(row) is not None
                                     and self.lst_con.item(row).text().startswith(("📏", "↔", "∠")))
        self.sigConstraintSelected.emit(row)

    def reset_constraints(self):
        self._con_sig = None; self._con_ids = []
        self.lst_con.blockSignals(True); self.lst_con.clear(); self.lst_con.blockSignals(False)
        self.btn_con_del.setEnabled(False); self.btn_con_edit.setEnabled(False)

    def set_mode(self, mode):
        self._mode = mode; self._sync_mode_buttons()

    def _on_draw_clicked(self):
        self.sigModeChanged.emit("draw")
        if self._tool == "trim":            # leaving the Scissor mode → back to the last draw tool
            self.sigToolChanged.emit(self._last_draw_tool)
        self._sync_mode_buttons()

    def _sync_mode_buttons(self):
        trim = self._mode == "draw" and self._tool == "trim"
        self.btn_draw.setChecked(self._mode == "draw" and not trim)
        self.btn_sel.setChecked(self._mode == DTOOL_SELECT)
        self.btn_con.setChecked(self._mode == "constrain")
        self.btn_trim.setChecked(trim)
        for t in ("line","rect","circle","ellipse","polygon","arc","freehand","point","text"):
            getattr(self,f"btn_{t}").setChecked(t == self._tool)

    def set_has_selection(self, has_sel):
        self.btn_del.setEnabled(has_sel)
        self.btn_mirror_horizontal.setEnabled(has_sel)
        self.btn_mirror_vertical.setEnabled(has_sel)

    def set_sel_info(self, text):
        self.lbl_sel.setText(text)

    def set_tool(self, tool):
        self._tool = tool
        if tool != "trim": self._last_draw_tool = tool
        self._sync_mode_buttons()

    def set_construction(self, on):
        self.btn_constr.blockSignals(True); self.btn_constr.setChecked(on)
        self.btn_constr.blockSignals(False)

    def set_ctool(self, ct):
        if ct == CTOOL_DIST: ct=CTOOL_LENGTH
        for t in (CTOOL_LENGTH,CTOOL_DIM,CTOOL_COLLINEAR,CTOOL_ANGLE,CTOOL_PERP,
                  CTOOL_FIX,CTOOL_PTPT,CTOOL_EQUAL,CTOOL_PARA,CTOOL_SYM,CTOOL_TANGENT):
            getattr(self,f"cbtn_{t}").setChecked(t==ct)


