def svg_to_contours(path, text_groups=None):
    """Read SVG geometry in mm; optionally collect text labels and their contour indices."""
    try:
        root = ET.parse(path).getroot()
    except (ET.ParseError, OSError) as ex:
        raise ValueError(f"Could not read SVG: {ex}") from ex
    def number(value, default=0.0):
        match = re.match(r"^\s*([-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?)", value or "")
        return float(match.group(1)) if match else default

    units = {"mm":1.0, "cm":10.0, "in":25.4, "pt":25.4/72,
             "pc":25.4/6, "px":25.4/96}
    viewbox = [number(v) for v in re.split(r"[\s,]+", root.get("viewBox", "").strip()) if v]
    width_attr, height_attr = root.get("width"), root.get("height")
    if len(viewbox) == 4 and viewbox[2] > 0 and viewbox[3] > 0:
        def physical(value, fallback):
            if not value: return fallback
            m = re.match(r"^\s*([-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?)\s*([a-zA-Z]*)", value)
            if not m: return fallback
            return float(m.group(1))*units.get(m.group(2), 25.4/96)
        sx = physical(width_attr, viewbox[2]*25.4/96) / viewbox[2]
        sy = physical(height_attr, viewbox[3]*25.4/96) / viewbox[3]
        scale = min(sx, sy)
        origin_x, origin_y = viewbox[:2]
    else:
        scale = units.get(re.sub(r"^[\d.eE+-]+", "", width_attr or "px"), 25.4/96)
        origin_x = origin_y = 0.0

    def matrix_multiply(a, b):
        return (a[0]*b[0]+a[2]*b[1], a[1]*b[0]+a[3]*b[1],
                a[0]*b[2]+a[2]*b[3], a[1]*b[2]+a[3]*b[3],
                a[0]*b[4]+a[2]*b[5]+a[4], a[1]*b[4]+a[3]*b[5]+a[5])

    def parse_transform(text):
        result = (1, 0, 0, 1, 0, 0)
        for name, args in re.findall(r"([A-Za-z]+)\s*\(([^)]*)\)", text or ""):
            values = [float(x) for x in re.findall(
                r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?", args)]
            op = (1, 0, 0, 1, 0, 0)
            if name == "matrix" and len(values) == 6: op = tuple(values)
            elif name == "translate" and values:
                op = (1, 0, 0, 1, values[0], values[1] if len(values)>1 else 0)
            elif name == "scale" and values:
                op = (values[0], 0, 0, values[1] if len(values)>1 else values[0], 0, 0)
            elif name == "rotate" and values:
                angle = math.radians(values[0]); c, s = math.cos(angle), math.sin(angle)
                op = (c, s, -s, c, 0, 0)
                if len(values) >= 3:
                    cx, cy = values[1:3]
                    op = matrix_multiply((1,0,0,1,cx,cy),
                                         matrix_multiply(op,(1,0,0,1,-cx,-cy)))
            elif name == "skewX" and values: op = (1,0,math.tan(math.radians(values[0])),1,0,0)
            elif name == "skewY" and values: op = (1,math.tan(math.radians(values[0])),0,1,0,0)
            else: raise ValueError(f"Unsupported SVG transform: {name}")
            result = matrix_multiply(result, op)
        return result

    def path_contours(data):
        tokens = re.findall(
            r"[A-Za-z]|[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?", data or "")
        counts = {"M":2,"L":2,"H":1,"V":1,"C":6,"S":4,"Q":4,"T":2,"A":7}
        result, points = [], []
        i, cmd, cur, start, last_ctrl, prev = 0, None, (0.0,0.0), None, None, ""
        def point(x, y, relative):
            return (x+cur[0], y+cur[1]) if relative else (x,y)
        def append(p):
            points.append(p)
        while i < len(tokens):
            if tokens[i].isalpha():
                cmd = tokens[i]; i += 1
                if cmd.upper() == "Z":
                    if points and points[-1] != start: points.append(start)
                    if len(points)>1: result.append(points)
                    points=[]; cur=start if start is not None else cur
                    last_ctrl=None; prev="Z"; cmd=None
                    continue
            if cmd is None or cmd.upper() not in counts:
                raise ValueError("SVG path contains an invalid or incomplete command")
            upper, rel = cmd.upper(), cmd.islower()
            n = counts[upper]
            if i+n > len(tokens) or any(t.isalpha() for t in tokens[i:i+n]):
                raise ValueError("SVG path contains an incomplete command")
            v = [float(x) for x in tokens[i:i+n]]; i += n
            if upper == "M":
                p = point(v[0],v[1],rel)
                if len(points)>1: result.append(points)
                points=[p]; cur=p; start=p
                cmd = "l" if rel else "L"; last_ctrl=None
            elif upper in ("L","H","V"):
                p = point(v[0],v[1],rel) if upper=="L" else (
                    (cur[0]+v[0] if rel else v[0],cur[1]) if upper=="H" else
                    (cur[0],cur[1]+v[0] if rel else v[0]))
                append(p); cur=p; last_ctrl=None
            elif upper in ("C","S","Q","T"):
                if upper == "C":
                    c1=point(v[0],v[1],rel); c2=point(v[2],v[3],rel); end=point(v[4],v[5],rel)
                elif upper == "S":
                    c1=(2*cur[0]-last_ctrl[0],2*cur[1]-last_ctrl[1]) if prev in ("C","S") and last_ctrl else cur
                    c2=point(v[0],v[1],rel); end=point(v[2],v[3],rel)
                elif upper == "Q":
                    c1=point(v[0],v[1],rel); end=point(v[2],v[3],rel); c2=c1
                else:
                    c1=(2*cur[0]-last_ctrl[0],2*cur[1]-last_ctrl[1]) if prev in ("Q","T") and last_ctrl else cur
                    end=point(v[0],v[1],rel); c2=c1
                p0=cur
                for step in range(1,13):
                    t=step/12; u=1-t
                    if upper in ("C","S"):
                        p=(u**3*p0[0]+3*u*u*t*c1[0]+3*u*t*t*c2[0]+t**3*end[0],
                           u**3*p0[1]+3*u*u*t*c1[1]+3*u*t*t*c2[1]+t**3*end[1])
                    else:
                        p=(u*u*p0[0]+2*u*t*c1[0]+t*t*end[0],
                           u*u*p0[1]+2*u*t*c1[1]+t*t*end[1])
                    append(p)
                cur=end; last_ctrl=c2 if upper in ("C","S") else c1
            else:
                rx, ry, rotation, large, sweep, x, y = v
                end=point(x,y,rel); rx,ry=abs(rx),abs(ry)
                if rx == 0 or ry == 0 or end == cur:
                    append(end)
                else:
                    phi=math.radians(rotation%360); co,si=math.cos(phi),math.sin(phi)
                    dx,dy=(cur[0]-end[0])/2,(cur[1]-end[1])/2
                    xp=co*dx+si*dy; yp=-si*dx+co*dy
                    lam=xp*xp/(rx*rx)+yp*yp/(ry*ry)
                    if lam>1: rx*=math.sqrt(lam); ry*=math.sqrt(lam)
                    sign=-1 if bool(large)==bool(sweep) else 1
                    den=rx*rx*yp*yp+ry*ry*xp*xp
                    factor=sign*math.sqrt(max(0,(rx*rx*ry*ry-den)/max(den,1e-30)))
                    cxp=factor*rx*yp/ry; cyp=-factor*ry*xp/rx
                    cx=co*cxp-si*cyp+(cur[0]+end[0])/2
                    cy=si*cxp+co*cyp+(cur[1]+end[1])/2
                    a0=math.atan2((yp-cyp)/ry,(xp-cxp)/rx)
                    a1=math.atan2((-yp-cyp)/ry,(-xp-cxp)/rx)
                    delta=(a1-a0)%(2*math.pi)
                    if not sweep and delta>0: delta-=2*math.pi
                    elif sweep and delta<0: delta+=2*math.pi
                    steps=max(4,int(math.ceil(abs(delta)/(math.pi/24))))
                    for step in range(1,steps+1):
                        a=a0+delta*step/steps
                        append((cx+rx*co*math.cos(a)-ry*si*math.sin(a),
                                cy+rx*si*math.cos(a)+ry*co*math.sin(a)))
                cur=end
                last_ctrl=None
            prev=upper if upper not in ("M",) else "M"
        if len(points)>1: result.append(points)
        return result

    def text_length(value, font_size=16.0, percentage=False):
        match = re.fullmatch(
            r"\s*([-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?)\s*([a-zA-Z%]*)\s*",
            value)
        if not match:
            raise ValueError(f"Unsupported SVG text length: {value!r}. Convert text to paths first.")
        unit = match.group(2)
        factors = {key: factor/(25.4/96) for key, factor in units.items()}
        factors.update({"":1.0, "em":font_size})
        if percentage: factors["%"] = font_size/100
        if unit not in factors:
            raise ValueError(f"Unsupported SVG text unit: {unit!r}. Convert text to paths first.")
        return float(match.group(1))*factors[unit]

    def text_contours(element, properties):
        if len(element):
            raise ValueError("SVG text with tspan/textPath or other child elements is not supported. "
                             "Convert this text to paths first.")
        text = re.sub(r"\s+", " ", element.text or "").strip()
        size = properties["font-size"]
        if not text or size <= 0: return []
        if QApplication.instance() is None:
            raise ValueError("SVG text import requires a running Qt application.")
        font = QFont()
        families = [family.strip().strip("'\"")
                    for family in properties.get("font-family", "serif").split(",")]
        font.setFamilies(families)
        font.setPixelSize(max(1, round(size)))
        weight = properties.get("font-weight", "normal")
        if weight in ("normal", "bold"):
            font.setWeight(QFont.Normal if weight == "normal" else QFont.Bold)
        elif weight.isdigit() and 100 <= int(weight) <= 900:
            weights = [QFont.Thin, QFont.ExtraLight, QFont.Light, QFont.Normal, QFont.Medium,
                       QFont.DemiBold, QFont.Bold, QFont.ExtraBold, QFont.Black]
            font.setWeight(weights[max(0, min(8, round(int(weight)/100)-1))])
        else:
            raise ValueError(f"Unsupported SVG font weight: {weight!r}. Convert text to paths first.")
        font.setItalic(properties.get("font-style") in ("italic", "oblique"))
        ratio = size/font.pixelSize()
        metrics = QFontMetricsF(font)
        x = text_length(element.get("x", "0"), size) + text_length(element.get("dx", "0"), size)
        y = text_length(element.get("y", "0"), size) + text_length(element.get("dy", "0"), size)
        anchor = properties.get("text-anchor", "start")
        if anchor not in ("start", "middle", "end"):
            raise ValueError(f"Unsupported SVG text anchor: {anchor!r}")
        x -= metrics.horizontalAdvance(text)*ratio*{"start":0, "middle":0.5, "end":1}[anchor]
        baseline = properties.get("dominant-baseline", "auto")
        if baseline == "middle": y += metrics.xHeight()*ratio/2
        elif baseline == "central": y += (metrics.ascent()-metrics.descent())*ratio/2
        elif baseline in ("hanging", "text-before-edge", "text-top"): y += metrics.ascent()*ratio
        elif baseline in ("text-after-edge", "text-bottom"): y -= metrics.descent()*ratio
        elif baseline not in ("auto", "alphabetic"):
            raise ValueError(f"Unsupported SVG text baseline: {baseline!r}. Convert text to paths first.")
        outline = QPainterPath()
        outline.addText(0, 0, font, text)
        # Scale before flattening to retain fractional SVG font sizes and separate glyph holes.
        outline = QTransform.fromScale(ratio, ratio).map(outline)
        return [[(point.x()+x, point.y()+y) for point in polygon]
                for polygon in outline.toSubpathPolygons() if len(polygon)>1]

    contours=[]
    def walk(element, parent_matrix, hidden=False, inherited=None):
        style = dict(item.split(":", 1) for item in element.get("style", "").split(";") if ":" in item)
        style = {key.strip(): value.strip() for key, value in style.items()}
        invisible = hidden or style.get("display", element.get("display")) == "none"
        if invisible: return
        properties = dict(inherited or {"font-size":16.0})
        for name in ("font-family", "font-size", "font-weight", "font-style",
                     "text-anchor", "dominant-baseline"):
            value = style.get(name, element.get(name))
            if value is not None and value != "inherit":
                properties[name] = text_length(value, properties["font-size"], percentage=True) if name=="font-size" else value
        matrix=matrix_multiply(parent_matrix,parse_transform(element.get("transform")))
        tag=element.tag.rsplit("}",1)[-1]
        attrs=element.attrib
        made=[]
        if tag=="path": made=path_contours(attrs.get("d",""))
        elif tag=="text": made=text_contours(element, properties)
        elif tag in ("polyline","polygon"):
            vals=[float(x) for x in re.findall(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?",
                                               attrs.get("points",""))]
            pts=list(zip(vals[::2],vals[1::2]))
            if tag=="polygon" and len(pts)>1: pts.append(pts[0])
            if len(pts)>1: made=[pts]
        elif tag=="line":
            made=[[(number(attrs.get("x1")),number(attrs.get("y1"))),
                   (number(attrs.get("x2")),number(attrs.get("y2")))]]
        elif tag in ("rect","circle","ellipse"):
            if tag=="rect":
                x,y=number(attrs.get("x")),number(attrs.get("y"))
                w,h=number(attrs.get("width")),number(attrs.get("height"))
                if w>0 and h>0: made=[[(x,y),(x+w,y),(x+w,y+h),(x,y+h),(x,y)]]
            else:
                cx,cy=number(attrs.get("cx")),number(attrs.get("cy"))
                rx=number(attrs.get("r")) if tag=="circle" else number(attrs.get("rx"))
                ry=rx if tag=="circle" else number(attrs.get("ry"))
                if rx>0 and ry>0:
                    pts=[(cx+rx*math.cos(2*math.pi*i/64),
                          cy+ry*math.sin(2*math.pi*i/64)) for i in range(65)]
                    made=[pts]
        text_indices = []
        for contour in made:
            pts=[]
            for x,y in contour:
                a,b,c,d,e,f=matrix
                pts.append((a*x+c*y+e,b*x+d*y+f))
            if len(pts)>1:
                text_indices.append(len(contours))
                contours.append(pts)
        if tag == "text" and text_indices and text_groups is not None:
            text_groups.append({"label":re.sub(r"\s+", " ", element.text or "").strip(),
                                "contours":text_indices})
        for child in element:
            walk(child,matrix,invisible,properties)
    walk(root,(1,0,0,1,0,0))
    if not contours: raise ValueError("The SVG contains no supported visible geometry")
    flat=[p for contour in contours for p in contour]
    lo_x,hi_x=min(p[0] for p in flat),max(p[0] for p in flat)
    lo_y,hi_y=min(p[1] for p in flat),max(p[1] for p in flat)
    cx,cy=(lo_x+hi_x)/2,(lo_y+hi_y)/2
    converted=[[( (x-cx)*scale, -(y-cy)*scale) for x,y in contour] for contour in contours]
    return converted


def dxf_to_contours(path):
    """Read supported DXF model-space geometry into centered sketch coordinates in mm."""
    try:
        import ezdxf
        from ezdxf.disassemble import recursive_decompose
        from ezdxf.path import make_path
        from ezdxf.units import MM, conversion_factor
    except ImportError as ex:
        raise ValueError("DXF import requires ezdxf. Install it with 'python -m pip install ezdxf'.") from ex
    try:
        document = ezdxf.readfile(path)
    except (ezdxf.DXFError, OSError, UnicodeError) as ex:
        raise ValueError(f"Could not read DXF: {ex}") from ex

    source_units = int(document.header.get("$INSUNITS", 0) or 0)
    try:
        scale = conversion_factor(source_units, MM) if source_units else 1.0
    except (TypeError, ValueError) as ex:
        raise ValueError(f"Unsupported DXF drawing units: {source_units}") from ex

    contours = []
    flattening_distance = 0.02 / scale
    for entity in recursive_decompose(document.modelspace()):
        try:
            points = list(make_path(entity).flattening(distance=flattening_distance))
        except (TypeError, ValueError):
            continue
        if len(points) > 1:
            contours.append([(float(point.x), float(point.y)) for point in points])
    if not contours:
        raise ValueError("The DXF contains no supported model-space geometry")

    flat = [point for contour in contours for point in contour]
    lo_x, hi_x = min(point[0] for point in flat), max(point[0] for point in flat)
    lo_y, hi_y = min(point[1] for point in flat), max(point[1] for point in flat)
    cx, cy = (lo_x + hi_x) / 2, (lo_y + hi_y) / 2
    return [[((x - cx) * scale, -(y - cy) * scale) for x, y in contour]
            for contour in contours]


TEXT_FONT_CHOICES = [
    "Arial", "Arial Black", "Times New Roman", "Gothic", "Impact", "Calibri",
    "Cascadia Code", "Century", "Comic Sans MS", "Fixedsys", "Lucida Handwriting",
    "Stencil", "Wide Latin",
]


def text_contours(text, font_family="Arial", font_size=12.0,
                  bold=False, italic=False, underline=False, align="left"):
    """Text outlines in sketch coordinates (mm), centred vertically around y=0.
    Horizontal anchoring follows align: left, center, right."""
    text = str(text or "").strip()
    if not text:
        return []
    family = font_family if font_family in TEXT_FONT_CHOICES else "Arial"
    font = QFont(family)
    font.setPixelSize(max(1, int(round(float(font_size)))))
    font.setBold(bool(bold))
    font.setItalic(bool(italic))
    metrics = QFontMetricsF(font)
    path = QPainterPath()
    path.addText(0.0, 0.0, font, text)
    rect = path.boundingRect()
    if rect.isEmpty():
        return []
    if align == "right":
        shift_x = -rect.right()
    elif align == "center":
        shift_x = -(rect.left() + rect.right())/2.0
    else:
        shift_x = -rect.left()
    shift_y = -(rect.top() + rect.bottom())/2.0

    contours = []
    for poly in path.toSubpathPolygons(QTransform()):
        pts = []
        for q in poly:
            x = float(q.x()) + shift_x
            y = -(float(q.y()) + shift_y)
            pts.append((x, y))
        if len(pts) > 1:
            if math.hypot(pts[0][0]-pts[-1][0], pts[0][1]-pts[-1][1]) > 1e-9:
                pts.append(pts[0])
            contours.append(pts)

    if underline:
        y_ul = metrics.underlinePos()
        x0, x1 = rect.left() + shift_x, rect.right() + shift_x
        y = -(float(y_ul) + shift_y)
        half_thickness = max(0.5, float(font_size)*0.03)
        contours.append([(x0, y-half_thickness), (x1, y-half_thickness),
                         (x1, y+half_thickness), (x0, y+half_thickness),
                         (x0, y-half_thickness)])
    return contours


def sketch_to_dict(sk):
    """Serialise a sketch (geometry + constraints) to plain JSON-able data."""
    for v in sk.used_vertices():
        if v not in sk.vertices: sk.vertices.append(v)
    vid = {v: i for i, v in enumerate(sk.vertices)}
    sid = {s: i for i, s in enumerate(sk.segments)}
    cid = {c: i for i, c in enumerate(sk.circles)}
    aid = {a: i for i, a in enumerate(sk.arcs)}
    def ref(o):
        if isinstance(o, Vertex):  return {"v": vid[o]}
        if isinstance(o, Segment): return {"s": sid[o]}
        if isinstance(o, Circle):  return {"c": cid[o]}
        if isinstance(o, Arc):     return {"a": aid[o]}
        if isinstance(o, tuple):   return {"tuple": [ref(x) for x in o]}
        if isinstance(o, np.generic): return o.item()
        return o
    cons = []
    for c in sk.constraints:
        d = {k: ref(v) for k, v in c.__dict__.items() if not k.startswith("_")}
        d["__type__"] = type(c).__name__
        cons.append(d)
    return {"name": sk.name, "plane": sk.plane,
            "frame": [[float(x) for x in a] for a in sk.frame],
            "face_rotation": list(sk.face_rotation),
            "vertices": [[v.x, v.y, v.locked] for v in sk.vertices],
            "segments": [[vid[s.v0], vid[s.v1], s.construction, s.reference] for s in sk.segments],
            "circles": [[vid[c.center], c.radius, c.construction, c.reference] for c in sk.circles],
            "arcs": [[vid[a.center], vid[a.v_start], vid[a.v_end], a.construction, a.reference]
                     for a in sk.arcs],
            "ellipses": [[vid[ellipse.major_start], vid[ellipse.major_end],
                          vid[ellipse.minor_start], vid[ellipse.minor_end],
                          ellipse.construction, ellipse.reference]
                         for ellipse in sk.ellipses],
            "points_free": [vid[v] for v in sk.points_free],
            "text_groups": [{"label": group.label,
                             "segments": [sid[s] for s in group.segments],
                             "box_points": [vid[v] for v in group.box_vertices if v in vid],
                             "font_family": group.font_family,
                             "font_size": group.font_size,
                             "bold": group.bold,
                             "italic": group.italic,
                             "underline": group.underline,
                             "align": group.align}
                            for group in sk.text_groups],
            "constraints": cons,
            "reference_boundaries": {
                key: {str(i): element.reference_boundary for i, element in enumerate(elements)
                      if hasattr(element, "reference_boundary")}
                for key, elements in (("segments", sk.segments), ("circles", sk.circles),
                                      ("arcs", sk.arcs))},
            "reference_generated_levels": sk.reference_generated_levels,
            "reference_levels": {
                key: {str(i): element.reference_level for i, element in enumerate(elements)
                      if hasattr(element, "reference_level")}
                for key, elements in (("vertices", sk.vertices), ("segments", sk.segments),
                                      ("circles", sk.circles), ("arcs", sk.arcs),
                                      ("ellipses", sk.ellipses))}}

def sketch_from_dict(d):
    return sketch_fill(Sketch(d["plane"], name=d["name"], frame=d["frame"]), d)

def sketch_fill(sk, d):
    """Replace the geometry and constraints of sketch sk (in place) by those of dict d."""
    sk.face_rotation = tuple(d.get("face_rotation", (1.0, 0.0)))
    sk.reference_generated_levels = list(d.get("reference_generated_levels", []))
    sk.legacy_reference_levels = "reference_levels" not in d
    V = sk.vertices = [Vertex(x, y, locked) for x, y, locked in d["vertices"]]
    sk.segments = [Segment(V[a], V[b], con, ref) for a, b, con, ref in d["segments"]]
    sk.circles  = [Circle(V[c], r, con, ref) for c, r, con, ref in d["circles"]]
    sk.arcs     = [Arc(V[c], V[s], V[e], con, ref) for c, s, e, con, ref in d["arcs"]]
    for key in ("segments", "circles", "arcs"):
        elements = getattr(sk, key)
        for index, boundary in d.get("reference_boundaries", {}).get(key, {}).items():
            elements[int(index)].reference_boundary = boundary
    sk.ellipses = [Ellipse(V[a], V[b], V[c], V[e], con, ref)
                   for a, b, c, e, con, ref in d.get("ellipses", [])]
    for key in ("vertices", "segments", "circles", "arcs", "ellipses"):
        elements = getattr(sk, key)
        for index, level in d.get("reference_levels", {}).get(key, {}).items():
            elements[int(index)].reference_level = level
    sk.points_free = [V[i] for i in d["points_free"]]
    sk.text_groups = []
    for group in d.get("text_groups", []):
        segs = [sk.segments[i] for i in group["segments"]]
        box_pts = [V[i] for i in group.get("box_points", []) if 0 <= i < len(V)]
        if len(box_pts) < 9 and segs:
            box_pts = sk._make_text_box_vertices(segs)
        sk.text_groups.append(SketchText(
            group.get("label", ""), segs,
            box_vertices=box_pts,
            font_family=group.get("font_family", "Arial"),
            font_size=group.get("font_size", 12.0),
            bold=group.get("bold", False),
            italic=group.get("italic", False),
            underline=group.get("underline", False),
            align=group.get("align", "left"),
        ))
    def deref(o):
        if isinstance(o, dict):
            if "v" in o: return V[o["v"]]
            if "s" in o: return sk.segments[o["s"]]
            if "c" in o: return sk.circles[o["c"]]
            if "a" in o: return sk.arcs[o["a"]]
            if "tuple" in o: return tuple(deref(x) for x in o["tuple"])
        return o
    sk.constraints = []
    for cd in d["constraints"]:
        cls = CONSTRAINT_CLASSES[cd["__type__"]]
        c = cls.__new__(cls)
        for k, v in cd.items():
            if k != "__type__": setattr(c, k, deref(v))
        sk.constraints.append(c)
    sk._an_key = None; sk._an = None
    return sk

class History:
    """Snapshot undo / redo. States are strings (JSON); push() only records real changes."""
    def __init__(self, state=None, limit=200):
        self.limit = limit; self.reset(state)
    def reset(self, state):
        self.undo_stack, self.redo_stack, self.cur = [], [], state
    def push(self, state):
        if state == self.cur: return False
        if self.cur is not None:
            self.undo_stack.append(self.cur); del self.undo_stack[:-self.limit]
        self.cur = state; self.redo_stack.clear()
        return True
    def undo(self):
        if not self.undo_stack: return None
        self.redo_stack.append(self.cur); self.cur = self.undo_stack.pop()
        return self.cur
    def redo(self):
        if not self.redo_stack: return None
        self.undo_stack.append(self.cur); self.cur = self.redo_stack.pop()
        return self.cur

def entry_bounds(entry):
    """(min xyz, max xyz) of an entry in world coordinates, or None."""
    if entry["type"] in ("extrusion", "imported"):
        V = np.asarray(entry["solid"][0], float)
        return (V.min(0), V.max(0)) if len(V) else None
    if entry["type"] == "surface":
        origin, u, v, _ = entry["frame"]
        u = np.asarray(u, float) * entry["width"]/2
        v = np.asarray(v, float) * entry["height"]/2
        O = np.asarray(origin, float)
        corners = np.asarray([O-u-v, O+u-v, O+u+v, O-u+v])
        return corners.min(0), corners.max(0)
    if entry["type"] != "sketch": return None
    sk = entry["sketch"]
    pts = [p for pts2, _ in sketch_polylines(sk) for p in pts2] + [v.xy() for v in sk.points_free]
    if not pts: return None
    P = sk.to3d_many(pts)
    return P.min(0), P.max(0)

def _validate_mesh(vertices, triangles):
    """Validate mesh arrays and normalize their vertices and triangle indices."""
    V = np.asarray(vertices, dtype=float)
    T = np.asarray(triangles, dtype=np.int64)
    if V.ndim != 2 or V.shape[1] != 3 or not len(V):
        raise ValueError("The imported file contains no 3-D vertices")
    if T.ndim != 2 or T.shape[1] != 3 or not len(T):
        raise ValueError("The imported file contains no triangles")
    if not np.isfinite(V).all():
        raise ValueError("The imported mesh contains non-finite coordinates")
    if T.min() < 0 or T.max() >= len(V):
        raise ValueError("The imported mesh contains an invalid triangle index")
    return [tuple(map(float, v)) for v in V], [tuple(map(int, t)) for t in T]

def _center_mesh(vertices, triangles):
    """Validate a triangle mesh and center its bounding box at the world origin."""
    vertices, triangles = _validate_mesh(vertices, triangles)
    V = np.asarray(vertices, dtype=float)
    V -= (V.min(axis=0) + V.max(axis=0)) / 2.0
    return [tuple(map(float, v)) for v in V], triangles


def _drawing_view_frame(normal, up_hint):
    """Return a right-handed screen basis for an orthographic viewing direction."""
    n = np.asarray(normal, dtype=float)
    n /= np.linalg.norm(n)
    up = np.asarray(up_hint, dtype=float)
    right = np.cross(up, n)
    if np.linalg.norm(right) < 1e-8:
        up = np.array((0.0, 1.0, 0.0))
        right = np.cross(up, n)
    right /= np.linalg.norm(right)
    up = np.cross(n, right)
    up /= np.linalg.norm(up)
    return right, up, n


